def load_video_data(filename="./res/data/video_data.json"):
    """读取实验视频数据

    支持多种结构：
      { "1": "描述" }
      { "1": {"name": "...", "description": "..."} }
      { 1:   {...} }
    """
    try:
        if os.path.exists(filename):
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if isinstance(data, dict):
                return data
            print(f"[实验视频] {filename} 顶层不是字典，已忽略")
    except Exception as e:
        print(f"[实验视频] 读取 {filename} 失败: {e}")
    return {}


class ExperimentVideoWindow:
    """实验视频窗口（前 N 秒预览）

    设计取舍：
      Tk 原生 PhotoImage 读第 N 帧会从头扫一遍（O(N²)），
      所以大 GIF 加载整段会越来越慢。这里只读前若干秒，
      够看懂实验现象就够了，完整版让用户自己去看。
    """

    VIDEO_DIR = "./res/videos"
    DATA_FILE = "./res/data/video_data.json"

    FRAME_INTERVAL = 80        # 每帧播放间隔(ms)，用来估算预览帧数
    MAX_PREVIEW_SECONDS = 5    # 预览秒数
    BUFFER_SIZE = 4            # 流式缓冲帧数

    def __init__(self, app):
        self.app = app
        self.master = app.root

        # 预览帧数上限：5s / 80ms ≈ 62 帧
        self.MAX_PREVIEW_FRAMES = max(
            1, int(self.MAX_PREVIEW_SECONDS * 1000 / self.FRAME_INTERVAL))

        self.video_data = load_video_data(self.DATA_FILE)
        self.videos = self._scan_videos()

        # 流式播放状态
        self._buffer = deque()
        self._read_idx = 0
        self._eof = False
        self._truncated = False
        self._current_frame = None
        self._play_job = None
        self._read_job = None
        self._playing = False
        self._paused = False
        self._path = None

        self.window = tk.Toplevel(self.master)
        self.window.title("🎬 实验视频")
        self.window.geometry("1000x760")
        self.window.minsize(820, 580)
        try:
            self.window.transient(self.master)
        except Exception:
            pass
        try:
            icon_image = tk.PhotoImage(file='./res/icon/func/experiment.ico')
            self.window.iconphoto(True, icon_image)
        except Exception:
            pass

        self._build_ui()
        self.window.protocol("WM_DELETE_WINDOW", self._on_close)

        if self.videos:
            self.listbox.selection_set(0)
            self._on_select()
        else:
            self._show_empty_hint()

    # ---------------- 扫描 / 数据 ----------------
    def _scan_videos(self):
        result = []
        try:
            if os.path.isdir(self.VIDEO_DIR):
                for fn in os.listdir(self.VIDEO_DIR):
                    if fn.lower().endswith('.gif'):
                        vid = os.path.splitext(fn)[0]
                        result.append((vid, os.path.join(self.VIDEO_DIR, fn)))
        except Exception as e:
            print(f"[实验视频] 扫描 {self.VIDEO_DIR} 失败: {e}")

        def sort_key(item):
            vid = item[0]
            try:
                return (0, int(vid), vid)
            except ValueError:
                return (1, 0, vid)
        result.sort(key=sort_key)
        return result

    def _get_video_info(self, vid):
        info = self.video_data.get(str(vid))
        if info is None:
            try:
                info = self.video_data.get(int(vid))
            except (ValueError, TypeError):
                pass
        if info is None:
            return {"name": f"实验 {vid}", "description": "暂无说明"}
        if isinstance(info, str):
            return {"name": f"实验 {vid}", "description": info}
        if isinstance(info, dict):
            name = (info.get('name') or info.get('title')
                    or info.get('名称') or f"实验 {vid}")
            desc = (info.get('description') or info.get('desc')
                    or info.get('说明') or info.get('描述') or '')
            return {"name": name, "description": desc}
        return {"name": f"实验 {vid}", "description": str(info)}

    # ---------------- UI ----------------
    def _build_ui(self):
        main = tk.Frame(self.window)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        # 左侧列表
        left = tk.LabelFrame(main, text=" 实验列表 ", font=('Unifont', 11))
        left.pack(side=tk.LEFT, fill=tk.Y, padx=(0, 10))
        left.configure(width=240)
        left.pack_propagate(False)

        list_frame = tk.Frame(left)
        list_frame.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)

        scrollbar = tk.Scrollbar(list_frame)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

        self.listbox = tk.Listbox(list_frame, font=('Unifont', 10),
                                  yscrollcommand=scrollbar.set,
                                  selectmode=tk.SINGLE)
        self.listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.config(command=self.listbox.yview)
        self.listbox.bind('<<ListboxSelect>>', lambda e: self._on_select())

        for vid, _ in self.videos:
            info = self._get_video_info(vid)
            self.listbox.insert(tk.END, f"{vid}. {info['name']}")

        # 右侧展示
        right = tk.LabelFrame(main, text=" 实验演示 ", font=('Unifont', 11))
        right.pack(side=tk.RIGHT, fill=tk.BOTH, expand=True)

        self.image_label = tk.Label(right, text="请从左侧选择实验",
                                    font=('Unifont', 12),
                                    bg='#1A1A1A', fg='#888888')
        self.image_label.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)

        # 播放完毕提示（初始为空）
        self.notice_label = tk.Label(
            right, text="", font=('Unifont', 9),
            bg='#F5F7FA', fg='#E67E22',
            anchor='w', justify=tk.LEFT)
        self.notice_label.pack(fill=tk.X, padx=5, pady=(0, 5))

        # 实验信息
        info_frame = tk.LabelFrame(self.window, text=" 实验信息 ",
                                   font=('Unifont', 11))
        info_frame.pack(fill=tk.X, padx=10, pady=(0, 10))

        self.title_label = tk.Label(info_frame, text="",
                                    font=('Unifont', 12), fg='#0066AA',
                                    anchor='w', justify=tk.LEFT)
        self.title_label.pack(fill=tk.X, padx=8, pady=(4, 0))

        self.desc_text = tk.Text(info_frame, height=4, wrap=tk.WORD,
                                 font=('Unifont', 10), bg='#F5F7FA')
        self.desc_text.pack(fill=tk.X, padx=8, pady=(0, 8))
        self.desc_text.config(state=tk.DISABLED)

        # 底部按钮
        bottom = tk.Frame(self.window)
        bottom.pack(fill=tk.X, padx=10, pady=(0, 10))

        self.pause_btn = tk.Button(bottom, text="⏸ 暂停/继续",
                                   font=('Unifont', 10),
                                   command=self._toggle_pause)
        self.pause_btn.pack(side=tk.LEFT, padx=4)

        tk.Button(bottom, text="🔄 重新扫描", font=('Unifont', 10),
                  command=self._reload).pack(side=tk.LEFT, padx=4)

        self.buf_label = tk.Label(bottom, text="",
                                  font=('Unifont', 9), fg='#888888')
        self.buf_label.pack(side=tk.LEFT, padx=12)

        tk.Button(bottom, text="关闭", font=('Unifont', 10), width=10,
                  command=self._on_close).pack(side=tk.RIGHT, padx=4)

    def _show_empty_hint(self):
        self.title_label.config(text="未找到实验视频")
        self._set_desc(
            "请将实验动画（.gif）放入 ./res/videos/ 目录，\n"
            "并在 ./res/data/video_data.json 中按编号提供实验名与说明。")
        self.image_label.config(image='', text="暂无视频")

    def _set_desc(self, text):
        self.desc_text.config(state=tk.NORMAL)
        self.desc_text.delete(1.0, tk.END)
        self.desc_text.insert(tk.END, text)
        self.desc_text.config(state=tk.DISABLED)

    # ---------------- 选择 ----------------
    def _on_select(self):
        sel = self.listbox.curselection()
        if not sel:
            return
        idx = sel[0]
        if idx >= len(self.videos):
            return

        vid, path = self.videos[idx]
        self._path = path

        info = self._get_video_info(vid)
        self.title_label.config(text=f"{vid}. {info['name']}")
        self._set_desc(info['description'])

        self._start_stream(path)

    # ================== 流式播放核心 ==================
    def _start_stream(self, path):
        self._stop_stream()

        try:
            size_mb = os.path.getsize(path) / (1024 * 1024)
        except Exception:
            size_mb = 0
        # 大文件流式播放没问题，只是上限帧数硬性约束
        if size_mb > 200:
            self.image_label.config(
                image='', text=f"GIF 过大 ({size_mb:.0f}MB)\n请到资源文件夹查看")
            return

        self._path = path
        self._read_idx = 0
        self._eof = False
        self._truncated = False
        self._playing = True
        self._paused = False
        self._buffer.clear()
        self._current_frame = None

        self.image_label.config(image='', text="正在加载...")
        self.notice_label.config(text="")
        self.pause_btn.config(text="⏸ 暂停/继续")

        self._read_job = self.image_label.after(1, self._read_loop)
        self._play_job = self.image_label.after(
            self.FRAME_INTERVAL, self._play_loop)

    def _stop_stream(self):
        self._playing = False
        for attr in ('_read_job', '_play_job'):
            job = getattr(self, attr, None)
            if job:
                try:
                    self.image_label.after_cancel(job)
                except Exception:
                    pass
                setattr(self, attr, None)

        self._buffer.clear()
        self._current_frame = None
        try:
            self.image_label.config(image='')
            self.image_label.image = None
        except Exception:
            pass

    # ---------- 读流水线 ----------
    def _read_loop(self):
        if not self._playing or self._paused or self._eof:
            return

        # 达到预览帧数上限：停止读取，标记为截断
        if self._read_idx >= self.MAX_PREVIEW_FRAMES:
            self._eof = True
            self._truncated = True
            self._update_buf_label()
            return

        # 缓冲满：稍后再来
        if len(self._buffer) >= self.BUFFER_SIZE:
            self._read_job = self.image_label.after(15, self._read_loop)
            return

        try:
            frame = tk.PhotoImage(
                file=self._path,
                format=f"gif -index {self._read_idx}")
            self._buffer.append(frame)
            self._read_idx += 1
        except tk.TclError:
            # 自然读完（GIF 本身不足预览长度）
            self._eof = True
            self._truncated = False
            self._update_buf_label()
            return
        except Exception as e:
            print(f"[实验视频] 读第 {self._read_idx} 帧异常: {e}")
            self._eof = True
            self._truncated = False
            return

        self._update_buf_label()
        self._read_job = self.image_label.after(1, self._read_loop)

    # ---------- 播流水线 ----------
    def _play_loop(self):
        if not self._playing or self._paused:
            return

        if self._buffer:
            self._current_frame = self._buffer.popleft()
            try:
                self.image_label.config(image=self._current_frame, text='')
                self.image_label.image = self._current_frame
            except tk.TclError:
                return
            self._update_buf_label()
            self._play_job = self.image_label.after(
                self.FRAME_INTERVAL, self._play_loop)

        elif self._eof:
            # 缓冲空 + 读完 → 播放结束
            self._finish_playback(self._truncated)
        else:
            # 缓冲暂时空，读还没跟上，稍等
            self._play_job = self.image_label.after(15, self._play_loop)

    def _finish_playback(self, truncated):
        """播放结束：停住，保留最后一帧，显示提示"""
        self._playing = False
        if self._play_job:
            try:
                self.image_label.after_cancel(self._play_job)
            except Exception:
                pass
            self._play_job = None
        if self._read_job:
            try:
                self.image_label.after_cancel(self._read_job)
            except Exception:
                pass
            self._read_job = None

        if truncated:
            self.notice_label.config(
                text=(f"⏸ 仅预览前 {self.MAX_PREVIEW_SECONDS} 秒。"
                      f"完整视频请到 ./res/videos/ 文件夹自行观看。"),
                fg='#E67E22')
        else:
            self.notice_label.config(
                text=(f"✓ 播放完毕（共 {self._read_idx} 帧）。"
                      f"如需再看，点击左侧重新选择。"),
                fg='#27AE60')

        # 暂停按钮变成"重播"
        self.pause_btn.config(text="↻ 重播")
        self._update_buf_label()

    def _update_buf_label(self):
        if not self._playing and not self._read_idx:
            self.buf_label.config(text="")
            return
        state = '结束' if self._eof else '读取中'
        self.buf_label.config(
            text=f"已读 {self._read_idx}/{self.MAX_PREVIEW_FRAMES} 帧 "
                 f"| 缓冲 {len(self._buffer)} | {state}")

    # ---------------- 控制 ----------------
    def _toggle_pause(self):
        # 已经播放完了 → 点这个按钮就当"重播"
        if not self._playing:
            if self._path:
                self._start_stream(self._path)
            return

        self._paused = not self._paused
        if not self._paused:
            self._read_job = self.image_label.after(1, self._read_loop)
            self._play_job = self.image_label.after(
                self.FRAME_INTERVAL, self._play_loop)

    def _reload(self):
        self._stop_stream()
        self.video_data = load_video_data(self.DATA_FILE)
        self.videos = self._scan_videos()

        self.listbox.delete(0, tk.END)
        for vid, _ in self.videos:
            info = self._get_video_info(vid)
            self.listbox.insert(tk.END, f"{vid}. {info['name']}")

        self._path = None
        self.image_label.config(image='', text="请从左侧选择实验")
        self.title_label.config(text="")
        self._set_desc("")
        self.notice_label.config(text="")
        self.buf_label.config(text="")
        self.pause_btn.config(text="⏸ 暂停/继续")

        if self.videos:
            self.listbox.selection_set(0)
            self._on_select()
        else:
            self._show_empty_hint()

    def _on_close(self):
        self._stop_stream()
        try:
            self.window.destroy()
        except Exception:
            pass

def load_language_packs(lang_dir="./res/language"):
    """扫描语言包目录，返回 {文件名: 语言包字典}

    每个语言包字典:
      language : 语言代码（缺省时取文件名去 .json）
      direction: 'left' / 'right' / 'up'（其他值回退为 'left'）
      elements : {元素符号: 该语言下的名称}
    """
    packs = {}
    try:
        if not os.path.isdir(lang_dir):
            return packs
        for filename in os.listdir(lang_dir):
            if not filename.lower().endswith('.json'):
                continue
            filepath = os.path.join(lang_dir, filename)
            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                if not isinstance(data, dict):
                    continue
                direction = str(data.get('direction', 'left')).strip().lower()
                if direction not in ('left', 'right', 'up'):
                    direction = 'left'
                packs[filename] = {
                    'language': str(data.get('language',
                                             os.path.splitext(filename)[0])),
                    'direction': direction,
                    'elements': data.get('elements', {}) or {},
                }
            except Exception as e:
                print(f"[多语言周期表] 读取 {filename} 失败: {e}")
    except Exception as e:
        print(f"[多语言周期表] 扫描 {lang_dir} 失败: {e}")
    return packs


class MultiLangPeriodicTableWindow:
    """多语言元素周期表窗口

    根据语言包里的 direction 字段决定整表的显示方式：
      left  -> 原始布局
      right -> 整表水平镜像（列反转）
      up    -> 先水平镜像，再逆时针旋转 90°（等价于矩阵转置）
    """

    # 与主表相同的 9×18 布局
    LAYOUT = [
        ["H",  "", "",  "",  "",  "",  "",  "",  "",  "",  "",  "",  "",  "",  "",  "",  "", "He"],
        ["Li", "Be", "",  "",  "",  "",  "",  "",  "",  "",  "",  "", "B",  "C",  "N",  "O",  "F",  "Ne"],
        ["Na", "Mg", "",  "",  "",  "",  "",  "",  "",  "",  "",  "", "Al", "Si", "P",  "S",  "Cl", "Ar"],
        ["K",  "Ca", "Sc", "Ti", "V",  "Cr", "Mn", "Fe", "Co", "Ni", "Cu", "Zn", "Ga", "Ge", "As", "Se", "Br", "Kr"],
        ["Rb", "Sr", "Y",  "Zr", "Nb", "Mo", "Tc", "Ru", "Rh", "Pd", "Ag", "Cd", "In", "Sn", "Sb", "Te", "I",  "Xe"],
        ["Cs", "Ba", "",  "Hf", "Ta", "W",  "Re", "Os", "Ir", "Pt", "Au", "Hg", "Tl", "Pb", "Bi", "Po", "At", "Rn"],
        ["Fr", "Ra", "",  "Rf", "Db", "Sg", "Bh", "Hs", "Mt", "Ds", "Rg", "Cn", "Nh", "Fl", "Mc", "Lv", "Ts", "Og"],
        ["",  "",  "La", "Ce", "Pr", "Nd", "Pm", "Sm", "Eu", "Gd", "Tb", "Dy", "Ho", "Er", "Tm", "Yb", "Lu", ""],
        ["",  "",  "Ac", "Th", "Pa", "U",  "Np", "Pu", "Am", "Cm", "Bk", "Cf", "Es", "Fm", "Md", "No", "Lr", ""],
    ]

    CELL_SIZE = 58
    PADDING = 26

    CATEGORY_COLORS = {
        "碱金属":   "#FF8080", "碱土金属": "#FFA380",
        "过渡金属": "#FFC680", "后过渡金属": "#FFE680",
        "类金属":   "#CCD980", "非金属":   "#80CC80",
        "卤素":     "#80B3CC", "稀有气体": "#8099CC",
        "镧系":     "#B380CC", "锕系":     "#CC80B3",
        "未知":     "#D9D9D9",
    }

    def __init__(self, app):
        self.app = app
        self.master = app.root
        self.lang_dir = "./res/language"

        self.window = tk.Toplevel(self.master)
        self.window.title("🌐 多语言周期表")
        self.window.geometry("1180x780")
        self.window.minsize(760, 520)
        try:
            self.window.transient(self.master)
        except Exception:
            pass

        try:
            icon_image = tk.PhotoImage(file='./res/icon/func/change.ico')
            self.window.iconphoto(True, icon_image)
        except Exception:
            pass

        # 深色配色
        self.bg = '#15192A'
        self.text_primary = '#FFFFFF'
        self.text_secondary = '#D6E6FF'
        self.hint_color = '#7A8A99'

        # 加载语言包
        self.packs = load_language_packs(self.lang_dir)

        self._build_ui()

        if self.packs:
            self.lang_var.set(sorted(self.packs.keys())[0])
            self._render()
        else:
            self._render_empty_hint()

    # ---------------- UI ----------------
    def _build_ui(self):
        top = tk.Frame(self.window, bg=self.bg)
        top.pack(fill=tk.X, padx=12, pady=(10, 6))

        tk.Label(top, text="语言包:", font=('Unifont', 11),
                 bg=self.bg, fg=self.text_primary).pack(side=tk.LEFT)

        self.lang_var = tk.StringVar()
        self.lang_combo = ttk.Combobox(
            top, textvariable=self.lang_var,
            values=sorted(self.packs.keys()),
            state='readonly', width=28, font=('Unifont', 10))
        self.lang_combo.pack(side=tk.LEFT, padx=8)
        self.lang_combo.bind('<<ComboboxSelected>>', lambda e: self._render())

        tk.Button(top, text="🔄 重新扫描", font=('Unifont', 9),
                  command=self._rescan_packs).pack(side=tk.LEFT, padx=4)

        self.direction_label = tk.Label(
            top, text="", font=('Unifont', 10),
            bg=self.bg, fg=self.hint_color)
        self.direction_label.pack(side=tk.LEFT, padx=18)

        canvas_frame = tk.Frame(self.window, bg=self.bg)
        canvas_frame.pack(fill=tk.BOTH, expand=True, padx=12, pady=(0, 6))

        h_scroll = tk.Scrollbar(canvas_frame, orient=tk.HORIZONTAL)
        v_scroll = tk.Scrollbar(canvas_frame, orient=tk.VERTICAL)

        self.canvas = tk.Canvas(canvas_frame, bg=self.bg,
                                highlightthickness=0,
                                xscrollcommand=h_scroll.set,
                                yscrollcommand=v_scroll.set)
        h_scroll.config(command=self.canvas.xview)
        v_scroll.config(command=self.canvas.yview)

        self.canvas.grid(row=0, column=0, sticky='nsew')
        v_scroll.grid(row=0, column=1, sticky='ns')
        h_scroll.grid(row=1, column=0, sticky='ew')
        canvas_frame.grid_rowconfigure(0, weight=1)
        canvas_frame.grid_columnconfigure(0, weight=1)

        bottom = tk.Frame(self.window, bg=self.bg)
        bottom.pack(fill=tk.X, padx=12, pady=(0, 10))

        self.info_label = tk.Label(
            bottom, text="点击任一元素查看详情",
            font=('Unifont', 10), bg=self.bg, fg=self.hint_color,
            anchor='w')
        self.info_label.pack(fill=tk.X)

    # ---------------- 事件 ----------------
    def _rescan_packs(self):
        self.packs = load_language_packs(self.lang_dir)
        self.lang_combo['values'] = sorted(self.packs.keys())
        if self.packs:
            if self.lang_var.get() not in self.packs:
                self.lang_var.set(sorted(self.packs.keys())[0])
            self._render()
        else:
            self._render_empty_hint()

    def _render_empty_hint(self):
        self.canvas.delete('all')
        self.direction_label.config(text="")
        self.canvas.create_text(
            400, 200,
            text=("未在 ./res/language/ 找到任何语言包\n"
                  "请将 .json 语言包放入该目录后点击「重新扫描」"),
            fill=self.hint_color, font=('Unifont', 12), justify='center')

    # ---------------- 渲染 ----------------
    def _render(self):
        canvas = self.canvas
        canvas.delete('all')

        selected = self.lang_var.get()
        pack = self.packs.get(selected)
        if not pack:
            self._render_empty_hint()
            return

        direction = pack['direction']
        elements = pack['elements']

        dir_display = {
            'left':  '正常 (left)',
            'right': '整表镜像 (right)',
            'up':    '镜像 + 逆时针旋转 90° (up)',
        }.get(direction, direction)
        self.direction_label.config(
            text=f"书写方向: {dir_display}    ·    语言代码: {pack['language']}")

        rows = len(self.LAYOUT)
        cols = max(len(r) for r in self.LAYOUT)

        # up 方向行列互换
        if direction == 'up':
            grid_w, grid_h = rows, cols
        else:
            grid_w, grid_h = cols, rows

        cell = self.CELL_SIZE
        pad = self.PADDING
        canvas_w = grid_w * cell + 2 * pad
        canvas_h = grid_h * cell + 2 * pad
        canvas.config(scrollregion=(0, 0, canvas_w, canvas_h))

        # 坐标变换
        def transform(c, r):
            if direction == 'right':
                return cols - 1 - c, r          # 整表水平镜像
            if direction == 'up':
                return r, c                     # 镜像 + 逆时针 90° == 转置
            return c, r

        for r, row in enumerate(self.LAYOUT):
            for c, symbol in enumerate(row):
                if not symbol:
                    continue

                gx, gy = transform(c, r)
                x1 = pad + gx * cell
                y1 = pad + gy * cell
                x2 = x1 + cell
                y2 = y1 + cell

                info = self.app.elements.get(symbol, {})
                cat = info.get('category', '未知')
                fill = self.CATEGORY_COLORS.get(cat, '#4A90E2')

                tag = f"cell_{symbol}"

                canvas.create_rectangle(
                    x1 + 2, y1 + 2, x2 - 2, y2 - 2,
                    fill=fill, outline='#1A1A1A', width=2, tags=(tag,))

                name = elements.get(symbol, symbol)
                canvas.create_text(
                    (x1 + x2) / 2, y1 + cell * 0.36,
                    text=name, font=('Unifont', 12),
                    fill=self.text_primary, tags=(tag,))

                canvas.create_text(
                    (x1 + x2) / 2, y1 + cell * 0.72,
                    text=symbol, font=('Unifont', 9),
                    fill=self.text_secondary, tags=(tag,))

                canvas.tag_bind(tag, '<Button-1>',
                                lambda e, s=symbol: self._on_cell_click(s))

        canvas.create_text(
            canvas_w / 2, 12,
            text=f"多语言周期表 · {selected}",
            font=('Unifont', 11), fill=self.hint_color, anchor='n')

    def _on_cell_click(self, symbol):
        selected = self.lang_var.get()
        pack = self.packs.get(selected)
        if not pack:
            return
        translated = pack['elements'].get(symbol, '（无翻译）')
        info = self.app.elements.get(symbol, {})
        local_name = info.get('name', '?')
        number = info.get('number', '?')

        self.info_label.config(
            text=(f"符号: {symbol}    |    原子序数: {number}    |    "
                  f"应用内置名: {local_name}    |    {selected}: {translated}"),
            fg='#4A90E2')

