def load_bubble_data(path=_BUBBLE_JSON):
    """加载元素诗句数据；失败返回 fallback"""
    try:
        if os.path.exists(path):
            with open(path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if isinstance(data, dict) and data:
                print(f"[诗句] 已加载 {len(data)} 条元素诗句")
                return data
        print(f"[诗句] 未找到 {path}，使用内置 fallback")
    except Exception as e:
        print(f"[诗句] 加载 {path} 失败：{e}，使用内置 fallback")
    return dict(_FALLBACK_BUBBLE)


