class ScreensaverBGM:
    """屏保背景音乐播放器（MCI 主 + winsound 兜底）"""

    _counter = 0

    def __init__(self):
        ScreensaverBGM._counter += 1
        self.alias = f"ssbgm{ScreensaverBGM._counter}"   # 去掉下划线
        self.opened = False
        self.is_windows = (os.name == 'nt')
        self.use_fallback = False
        self.fallback_playing = False
        self._fallback_path = None        # ★ 关键：__init__ 就初始化

    # ---------- 内部 ----------
    def _mci(self, cmd):
        """返回 (错误码, 错误描述)。0 表示成功。"""
        if not self.is_windows:
            return 0, ""
        try:
            buf = ctypes.create_unicode_buffer(512)
            err = ctypes.windll.winmm.mciSendStringW(cmd, buf, 511, 0)
            if err != 0:
                err_buf = ctypes.create_unicode_buffer(512)
                try:
                    ctypes.windll.winmm.mciGetErrorStringW(err, err_buf, 511)
                    msg = err_buf.value
                except Exception:
                    msg = ""
                return err, msg
            return 0, buf.value
        except Exception as e:
            return -1, str(e)

    @staticmethod
    def _to_short_path(path):
        if os.name != 'nt':
            return path
        try:
            fn = ctypes.windll.kernel32.GetShortPathNameW
            fn.argtypes = [ctypes.c_wchar_p, ctypes.c_wchar_p, ctypes.c_uint]
            buf = ctypes.create_unicode_buffer(1024)
            if fn(path, buf, 1024):
                return buf.value
        except Exception:
            pass
        return path

    def _prepare_safe_path(self, path):
        """复制到无中文目录，规避 MCI 对路径的挑剔"""
        try:
            safe_dir = os.path.join(tempfile.gettempdir(), "PeriodicTable_BGM")
            os.makedirs(safe_dir, exist_ok=True)
            ext = os.path.splitext(path)[1] or ".wav"
            safe_path = os.path.join(safe_dir, f"screensaver_bgm{ext}")
            if not (os.path.exists(safe_path) and
                    os.path.getsize(safe_path) == os.path.getsize(path)):
                shutil.copy2(path, safe_path)
            return safe_path
        except Exception as e:
            print(f"[BGM] 复制到临时目录失败: {e}")
            return path

    # ---------- 公开 API ----------
    def open(self, path):
        if not self.is_windows:
            return False
        if not os.path.exists(path):
            print(f"[BGM] 文件不存在: {path}")
            return False

        safe_path = self._prepare_safe_path(path)
        # ★ 无论 MCI 成败，先记住 fallback 路径
        self._fallback_path = safe_path
        print(f"[BGM] 工作文件: {safe_path}")

        short = self._to_short_path(safe_path)

        attempts = [
            f'open "{short}" type waveaudio alias {self.alias}',
            f'open "{short}" alias {self.alias}',
        ]
        for cmd in attempts:
            err, msg = self._mci(cmd)
            if err == 0:
                self.opened = True
                print(f"[BGM] MCI open 成功")
                return True
            else:
                print(f"[BGM] MCI open 尝试失败: err={err} msg={msg}")

        print("[BGM] MCI 全部失败，将回退到 winsound")
        self.use_fallback = True
        return True

    def set_volume(self, volume):
        """volume: 0~1000（仅 MCI 生效，winsound 忽略）"""
        if self.use_fallback or not self.opened:
            return
        v = max(0, min(1000, int(volume)))
        err, msg = self._mci(f"setaudio {self.alias} volume to {v}")
        if err != 0:
            print(f"[BGM] setaudio 失败: {err} {msg}")

    def play_loop(self):
        # 优先 MCI，试两种写法
        if self.opened and not self.use_fallback:
            for cmd in (
                f'play {self.alias} repeat',
                f'play {self.alias}',
            ):
                err, msg = self._mci(cmd)
                if err == 0:
                    print(f"[BGM] MCI play 成功: {cmd}")
                    return
                print(f"[BGM] MCI play 尝试失败: err={err} msg={msg}")
            self.use_fallback = True

        # 回退 winsound（无音量控制）
        if self.use_fallback and self._fallback_path:
            try:
                import winsound
                winsound.PlaySound(
                    self._fallback_path,
                    winsound.SND_FILENAME | winsound.SND_ASYNC | winsound.SND_LOOP
                )
                self.fallback_playing = True
                print("[BGM] winsound 循环播放中（无音量控制）")
            except Exception as e:
                print(f"[BGM] winsound 播放失败: {e}")

    def stop(self):
        if self.opened:
            self._mci(f"stop {self.alias}")
        if self.fallback_playing:
            try:
                import winsound
                winsound.PlaySound(None, winsound.SND_PURGE)
                self.fallback_playing = False
            except Exception:
                pass

    def close(self):
        if self.opened:
            self._mci(f"close {self.alias}")
            self.opened = False

