def _load_acp_json(path, fallback):
    """读取音体美联动的 JSON 数据，失败时返回 fallback"""
    try:
        if os.path.exists(path):
            with open(path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if isinstance(data, dict):
                return data
        print(f"[音体美联动] 数据文件不存在，使用内置数据: {path}")
    except Exception as e:
        print(f"[音体美联动] 读取 {path} 失败，使用内置数据: {e}")
    return fallback

def _safe_builtin(name, friendly_name=None):
    """安全获取内置函数；打包后缺失时返回占位函数，不会崩溃"""
    fn = getattr(builtins, name, None)
    if fn is not None:
        return fn

    display = friendly_name or name

    def _missing(*args, **kwargs):
        raise RuntimeError(
            f"当前运行环境缺少内置函数 '{display}'（{name}）。\n"
            f"这通常是因为打包时裁剪了 site 模块。"
        )
    return _missing

class ArtsChemistryWindow:
    """音体美与化学跨学科联动工具（数据从 JSON 加载）"""

    def __init__(self, master):
        self.master = master

        # ---- 数据加载 ----
        music_data = _load_acp_json(_ACP_MUSIC_JSON, _FALLBACK_MUSIC)
        pe_data    = _load_acp_json(_ACP_PE_JSON,    _FALLBACK_PE)
        art_data   = _load_acp_json(_ACP_ART_JSON,   _FALLBACK_ART)

        # 拆成实例属性，方便方法里引用
        self.NOTE_FREQS     = music_data.get('note_freqs', {})
        self.PENTATONIC     = music_data.get('pentatonic', [])
        self.PENTA_NAMES    = music_data.get('penta_names', [])
        self.SPECTRUM_LINES = music_data.get('spectrum_lines', {})

