    def _sport_show_element(self):
        sym = self.sport_elem_var.get()
        info = self.SPORT_ELEMENT_NOTES.get(sym, "暂无数据")
        self._set_text(self.sport_elem_out, info)

    def _sport_calc(self):
        try:
            w = float(self.sport_weight.get())
            t = float(self.sport_duration.get())
        except ValueError:
            self._set_text(self.sport_output, "请输入有效的数字")
            return

        intensity = self.sport_intensity.get()
        vo2_rate = self.SPORT_INTENSITY_RATES.get(intensity, 25.0)
        total_vo2_mL = vo2_rate * w * t
        total_vo2_L  = total_vo2_mL / 1000

        energy_kJ = total_vo2_L * 20.9
        energy_kcal = energy_kJ / 4.184

        glucose_mol = total_vo2_L / 134.4
        atp_mol = glucose_mol * 30
        lactate_mol = glucose_mol * 2 * 0.20
        lactate_g = lactate_mol * 90.08

        txt = (
            f"【运动参数】\n"
            f"  体重：{w:.1f} kg  时长：{t:.1f} min  强度：{intensity}\n\n"
            f"【能量代谢】\n"
            f"  耗氧量 VO₂：{total_vo2_L:.2f} L  ({total_vo2_mL:.0f} mL)\n"
            f"  释放能量：{energy_kJ:.1f} kJ  ≈  {energy_kcal:.1f} kcal\n\n"
            f"【化学计量估算】\n"
            f"  葡萄糖消耗：{glucose_mol*180.16:.2f} g  ({glucose_mol:.4f} mol)\n"
            f"  ATP 生成：约 {atp_mol:.3f} mol\n"
            f"  乳酸生成（按 20% 无氧供能估算）：{lactate_g:.2f} g\n\n"
            f"  反应式：C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + 能量"
        )
        self._set_text(self.sport_output, txt)

