    def _art_show_pigment(self):
        name = self.art_pigment_var.get()
        info = self.PIGMENTS.get(name)
        if not info:
            self._set_text(self.art_pigment_out, "暂无数据")
            return
        txt = (
            f"【{name}】\n\n"
            f"  化学式：  {info.get('化学式', '—')}\n"
            f"  颜色：    {info.get('颜色', '—')}\n"
            f"  来源：    {info.get('来源', '—')}\n"
            f"  化学特性：{info.get('特性', '—')}\n"
            f"  主要用途：{info.get('用途', '—')}"
        )
        self._set_text(self.art_pigment_out, txt)

    def _art_simulate_degrade(self):
        pig = self.degrade_pigment_var.get()
        cond = self.degrade_cond_var.get()
        rule = self.DEGRADE_RULES.get(f"{pig}|{cond}")

        if rule:
            txt = f"【{pig} × {cond}】\n\n{rule}"
        else:
            txt = (
                f"【{pig} × {cond}】\n\n"
                "该组合暂无详细化学记录。\n"
                "可以在 JSON 文件的 degrade_rules 里补充 "
                f"\"{pig}|{cond}\" 键。"
            )
        self._set_text(self.degrade_out, txt)

    # ==================================================================
    # 工具
    # ==================================================================
    @staticmethod
    def _set_text(widget, text):
        widget.config(state=tk.NORMAL)
        widget.delete(1.0, tk.END)
        widget.insert(tk.END, text)
        widget.config(state=tk.DISABLED)

