# 🌍 世界时间查看器（含夏令时，纯标准库）
# ======================================================================

# -------- 夏令时规则工具 --------
_DST_NONE  = None
_DST_EU    = "EU"      # 3月最后周日 ~ 10月最后周日
_DST_US    = "US"      # 3月第二周日 ~ 11月第一周日
_DST_AU    = "AU"      # 10月第一周日 ~ 次年 4月第一周日
_DST_NZ    = "NZ"      # 9月最后周日 ~ 次年 4月第一周日
_DST_IRAN  = "IRAN"    # 3/22 ~ 9/22
_DST_CL    = "CL"      # 9月第一周日 ~ 次年 4月第一周日


def _nth_weekday(year, month, weekday, n):
    """返回某年某月第 n 个 weekday（0=周一, 6=周日）

    n=5 表示最后一个；若该月不足 n 个，则回退到最后一个。
    """
    first = datetime.date(year, month, 1)
    offset = (weekday - first.weekday()) % 7
    day = 1 + offset + (n - 1) * 7

    # 计算该月最后一天
    if month == 12:
        last_day = 31
    else:
        last_day = (datetime.date(year, month + 1, 1)
                    - datetime.timedelta(days=1)).day

    if day > last_day:
        day -= 7
    return datetime.date(year, month, day)


def _is_dst(dst_rule, now_utc):
    """根据规则判断当前（UTC时刻）是否处于夏令时"""
    if dst_rule is None:
        return False

    y = now_utc.year
    today = now_utc.date()

    if dst_rule == _DST_EU:
        start = _nth_weekday(y, 3, 6, 5)   # 3月最后一个周日
        end   = _nth_weekday(y, 10, 6, 5)  # 10月最后一个周日
        return start <= today < end

    if dst_rule == _DST_US:
        start = _nth_weekday(y, 3, 6, 2)   # 3月第二个周日
        end   = _nth_weekday(y, 11, 6, 1)  # 11月第一个周日
        return start <= today < end

    if dst_rule == _DST_AU:
        start = _nth_weekday(y, 10, 6, 1)  # 10月第一个周日
        end   = _nth_weekday(y, 4, 6, 1)   # 4月第一个周日
        # 南半球：跨年判断
        if today >= start:
            return True
        if today < end:
            return True
        return False

    if dst_rule == _DST_NZ:
        start = _nth_weekday(y, 9, 6, 5)   # 9月最后一个周日
        end   = _nth_weekday(y, 4, 6, 1)   # 4月第一个周日
        if today >= start:
            return True
        if today < end:
            return True
        return False

    if dst_rule == _DST_CL:
        start = _nth_weekday(y, 9, 6, 1)   # 9月第一个周日
        end   = _nth_weekday(y, 4, 6, 1)   # 4月第一个周日
        if today >= start:
            return True
        if today < end:
            return True
        return False

    if dst_rule == _DST_IRAN:
        start = datetime.date(y, 3, 22)
        end   = datetime.date(y, 9, 22)
        return start <= today < end

    return False


