# 11. 命令行参数解析（无用）
# ----------------------------------------------------------------------
def parse_args():
    parser = argparse.ArgumentParser(description="Useless Machine Simulator")
    parser.add_argument("--cycles", type=int, default=5, help="Number of cycles to run")
    parser.add_argument("--seed", type=int, default=None, help="Random seed")
    parser.add_argument("--verbose", action="store_true", help="Increase verbosity")
    return parser.parse_args()


# ----------------------------------------------------------------------
# 12. 主程序入口
# ----------------------------------------------------------------------
def main2():
    args = parse_args()
    if args.seed is not None:
        random.seed(args.seed)
    if args.verbose:
        logging.basicConfig(level=logging.DEBUG)
    else:
        logging.basicConfig(level=logging.INFO)

    print("=" * 60)
    print("   WELCOME TO THE USELESS MACHINE SIMULATOR")
    print("   (This program does absolutely nothing useful)")
    print("=" * 60)

    # Create the machine and run it
    machine = UselessMachine()
    machine.start(cycles=args.cycles)

    # Perform some completely useless operations after stopping
    print("\nPerforming post-mortem useless calculations...")
    for i in range(3):
        val = useless_calculation(i * 10)
        print(f"Useless calculation {i}: {val}")
    s = useless_string_manipulation("Hello, Useless World!")
    print(f"Transformed string: {s}")
    path = useless_file_operation()
    print(f"Created and deleted file: {path}")
    packet_hex = useless_network_simulation()
    print(f"Simulated packet hex: {packet_hex[:40]}...")

    print("\nThank you for wasting time with this useless program.")
    print("Goodbye!")

class MinesweeperGame:
    """32x32 点阵扫雷"""
    def __init__(self, master):
        self.master = master
        self.master.title("扫雷 - 32x32 点阵")
        self.master.resizable(False, False)
        self.master.protocol("WM_DELETE_WINDOW", self.on_closing)

        self.GRID_SIZE = 32
        self.CELL_SIZE = 20
        self.WIDTH = self.GRID_SIZE * self.CELL_SIZE
        self.HEIGHT = self.GRID_SIZE * self.CELL_SIZE
        self.MINE_COUNT = 99  # 固定雷数

        self.board = [[0]*self.GRID_SIZE for _ in range(self.GRID_SIZE)]  # 0=未翻开, 1-8=数字, -1=地雷
        self.revealed = [[False]*self.GRID_SIZE for _ in range(self.GRID_SIZE)]
        self.flagged = [[False]*self.GRID_SIZE for _ in range(self.GRID_SIZE)]
        self.game_over = False
        self.first_click = True

        self.create_widgets()
        self.bind_keys()
        self.reset_game()

    def create_widgets(self):
        # 顶部信息栏
        info_frame = tk.Frame(self.master, bg='black')
        info_frame.pack(fill=tk.X)
        self.mine_label = tk.Label(info_frame, text=f"💣 {self.MINE_COUNT}", fg='white', bg='black',
                                   font=FONT_NORMAL)
        self.mine_label.pack(side=tk.LEFT, padx=10, pady=5)
        self.status_label = tk.Label(info_frame, text="游戏中", fg='lightgreen', bg='black',
                                     font=FONT_NORMAL)
        self.status_label.pack(side=tk.LEFT, padx=20, pady=5)
        btn_frame = tk.Frame(info_frame, bg='black')
        btn_frame.pack(side=tk.RIGHT, padx=10, pady=5)
        self.reset_btn = tk.Button(btn_frame, text="重置", command=self.reset_game, font=FONT_SMALL)
        self.reset_btn.pack(side=tk.LEFT, padx=2)

        self.canvas = tk.Canvas(self.master, width=self.WIDTH, height=self.HEIGHT,
                                bg='black', highlightthickness=0)
        self.canvas.pack()

        # 绑定鼠标事件
        self.canvas.bind("<Button-1>", self.left_click)
        self.canvas.bind("<Button-3>", self.right_click)

    def bind_keys(self):
        self.master.bind("r", lambda e: self.reset_game())
        self.master.bind("R", lambda e: self.reset_game())

    def reset_game(self):
        # 重置状态
        self.board = [[0]*self.GRID_SIZE for _ in range(self.GRID_SIZE)]
        self.revealed = [[False]*self.GRID_SIZE for _ in range(self.GRID_SIZE)]
        self.flagged = [[False]*self.GRID_SIZE for _ in range(self.GRID_SIZE)]
        self.game_over = False
        self.first_click = True
        self.mine_label.config(text=f"💣 {self.MINE_COUNT}")
        self.status_label.config(text="游戏中", fg='lightgreen')
        self.draw()

    def place_mines(self, safe_x, safe_y):
        # 在确保第一次点击位置安全的前提下布雷
        import random
        placed = 0
        while placed < self.MINE_COUNT:
            x = random.randint(0, self.GRID_SIZE-1)
            y = random.randint(0, self.GRID_SIZE-1)
            if (x, y) != (safe_x, safe_y) and self.board[y][x] != -1:
                self.board[y][x] = -1
                placed += 1
        # 计算数字
        for y in range(self.GRID_SIZE):
            for x in range(self.GRID_SIZE):
                if self.board[y][x] == -1:
                    continue
                count = 0
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < self.GRID_SIZE and 0 <= nx < self.GRID_SIZE and self.board[ny][nx] == -1:
                            count += 1
                self.board[y][x] = count

    def left_click(self, event):
        if self.game_over:
            return
        x = event.x // self.CELL_SIZE
        y = event.y // self.CELL_SIZE
        if not (0 <= x < self.GRID_SIZE and 0 <= y < self.GRID_SIZE):
            return
        if self.flagged[y][x]:
            return
        if self.first_click:
            self.place_mines(x, y)
            self.first_click = False
        self.reveal(x, y)

    def right_click(self, event):
        if self.game_over:
            return
        x = event.x // self.CELL_SIZE
        y = event.y // self.CELL_SIZE
        if not (0 <= x < self.GRID_SIZE and 0 <= y < self.GRID_SIZE):
            return
        if self.revealed[y][x]:
            return
        self.flagged[y][x] = not self.flagged[y][x]
        # 更新剩余雷数显示
        flag_count = sum(1 for row in self.flagged for f in row if f)
        self.mine_label.config(text=f"💣 {self.MINE_COUNT - flag_count}")
        self.draw()

    def reveal(self, x, y):
        if self.revealed[y][x] or self.flagged[y][x]:
            return
        self.revealed[y][x] = True
        if self.board[y][x] == -1:  # 踩雷
            self.game_over = True
            self.status_label.config(text="游戏结束 💥", fg='red')
            self.draw()
            return
        # 如果是空格（0），自动展开相邻格子
        if self.board[y][x] == 0:
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < self.GRID_SIZE and 0 <= nx < self.GRID_SIZE and not self.revealed[ny][nx]:
                        self.reveal(nx, ny)
        self.draw()
        # 检查胜利
        if self.check_win():
            self.game_over = True
            self.status_label.config(text="你赢了！ 🎉", fg='gold')
            self.draw()

    def check_win(self):
        for y in range(self.GRID_SIZE):
            for x in range(self.GRID_SIZE):
                if self.board[y][x] != -1 and not self.revealed[y][x]:
                    return False
        return True

    def draw(self):
        self.canvas.delete("all")
        for y in range(self.GRID_SIZE):
            for x in range(self.GRID_SIZE):
                x1 = x * self.CELL_SIZE
                y1 = y * self.CELL_SIZE
                x2 = x1 + self.CELL_SIZE
                y2 = y1 + self.CELL_SIZE
                if self.revealed[y][x]:
                    # 已翻开
                    if self.board[y][x] == -1:
                        self.canvas.create_rectangle(x1, y1, x2, y2, fill='red', outline='gray')
                        self.canvas.create_text(x1+self.CELL_SIZE//2, y1+self.CELL_SIZE//2,
                                                text='💣', font=FONT_SMALL)
                    else:
                        color = 'white' if (x+y)%2==0 else '#cccccc'
                        self.canvas.create_rectangle(x1, y1, x2, y2, fill=color, outline='gray')
                        if self.board[y][x] > 0:
                            num_colors = ['', 'blue', 'green', 'red', 'darkblue', 'darkred', 'cyan', 'black', 'gray']
                            self.canvas.create_text(x1+self.CELL_SIZE//2, y1+self.CELL_SIZE//2,
                                                    text=str(self.board[y][x]),
                                                    fill=num_colors[self.board[y][x]], font=FONT_NORMAL)
                else:
                    # 未翻开
                    if self.flagged[y][x]:
                        self.canvas.create_rectangle(x1, y1, x2, y2, fill='yellow', outline='gray')
                        self.canvas.create_text(x1+self.CELL_SIZE//2, y1+self.CELL_SIZE//2,
                                                text='🚩', font=FONT_SMALL)
                    else:
                        self.canvas.create_rectangle(x1, y1, x2, y2, fill='#666', outline='gray')
        # 网格线
        for i in range(self.GRID_SIZE+1):
            self.canvas.create_line(i*self.CELL_SIZE, 0, i*self.CELL_SIZE, self.HEIGHT, fill='#444')
            self.canvas.create_line(0, i*self.CELL_SIZE, self.WIDTH, i*self.CELL_SIZE, fill='#444')

    def on_closing(self):
        self.master.destroy()

class AvoidWhiteBlockGame:
    """32x32 点阵别踩白块（4列）"""
    def __init__(self, master):
        self.master = master
        self.master.title("别踩白块 - 32x32 点阵")
        self.master.resizable(False, False)
        self.master.protocol("WM_DELETE_WINDOW", self.on_closing)

        self.COLS = 4
        self.CELL_SIZE = 20
        self.WIDTH = 32 * self.CELL_SIZE          # 640
        self.HEIGHT = 32 * self.CELL_SIZE         # 640
        self.COL_WIDTH = self.WIDTH // self.COLS  # 160
        self.BLOCK_HEIGHT = 2  # 黑块高度为2格

        self.falling_blocks = []  # 每个元素 (col, row) 表示黑块顶部行
        self.score = 0
        self.game_over = False
        self.paused = False
        self.speed = 200  # 毫秒/步
        self.after_id = None
        self.last_row = -1  # 防止连续相同列

        self.create_widgets()
        self.bind_keys()
        self.start_game()

    def create_widgets(self):
        info_frame = tk.Frame(self.master, bg='black')
        info_frame.pack(fill=tk.X)
        self.score_label = tk.Label(info_frame, text="得分: 0", fg='white', bg='black',
                                    font=FONT_NORMAL)
        self.score_label.pack(side=tk.LEFT, padx=10, pady=5)
        self.status_label = tk.Label(info_frame, text="游戏中", fg='lightgreen', bg='black',
                                     font=FONT_NORMAL)
        self.status_label.pack(side=tk.LEFT, padx=20, pady=5)
        btn_frame = tk.Frame(info_frame, bg='black')
        btn_frame.pack(side=tk.RIGHT, padx=10, pady=5)
        self.reset_btn = tk.Button(btn_frame, text="重置", command=self.reset_game, font=FONT_SMALL)
        self.reset_btn.pack(side=tk.LEFT, padx=2)
        self.pause_btn = tk.Button(btn_frame, text="暂停", command=self.toggle_pause, font=FONT_SMALL)
        self.pause_btn.pack(side=tk.LEFT, padx=2)

        self.canvas = tk.Canvas(self.master, width=self.WIDTH, height=self.HEIGHT,
                                bg='black', highlightthickness=0)
        self.canvas.pack()
        self.canvas.bind("<Button-1>", self.on_click)

    def bind_keys(self):
        self.master.bind("r", lambda e: self.reset_game())
        self.master.bind("R", lambda e: self.reset_game())
        self.master.bind("<space>", lambda e: self.toggle_pause())
        self.master.bind("p", lambda e: self.toggle_pause())
        self.master.bind("P", lambda e: self.toggle_pause())

    def reset_game(self):
        if self.after_id:
            self.master.after_cancel(self.after_id)
            self.after_id = None
        self.falling_blocks = []
        self.score = 0
        self.game_over = False
        self.paused = False
        self.speed = 200
        self.last_row = -1
        self.update_score()
        self.status_label.config(text="游戏中", fg='lightgreen')
        self.pause_btn.config(text="暂停")
        self.start_game()

    def toggle_pause(self):
        if self.game_over:
            return
        self.paused = not self.paused
        if self.paused:
            self.status_label.config(text="暂停", fg='orange')
            self.pause_btn.config(text="继续")
            if self.after_id:
                self.master.after_cancel(self.after_id)
                self.after_id = None
        else:
            self.status_label.config(text="游戏中", fg='lightgreen')
            self.pause_btn.config(text="暂停")
            self.start_game()

    def start_game(self):
        if not self.game_over and not self.paused:
            self.update_blocks()
            self.draw()
            self.after_id = self.master.after(self.speed, self.start_game)

    def update_blocks(self):
        # 移动现有黑块向下
        new_blocks = []
        for col, row in self.falling_blocks:
            row += 1
            if row < 32 - self.BLOCK_HEIGHT + 1:
                new_blocks.append((col, row))
            else:
                # 黑块移出底部，游戏结束
                self.end_game()
                return
        self.falling_blocks = new_blocks

        # 生成新黑块（每步生成一个）
        import random
        col = random.randint(0, self.COLS-1)
        # 避免连续相同列
        if col == self.last_row:
            col = (col + 1) % self.COLS
        self.falling_blocks.append((col, 0))
        self.last_row = col
        # 加速
        if self.score % 10 == 0 and self.speed > 80:
            self.speed = max(80, self.speed - 5)

    def draw(self):
        self.canvas.delete("all")
        # 绘制竖线（列分隔线）
        for i in range(self.COLS + 1):
            x = i * self.COL_WIDTH
            self.canvas.create_line(x, 0, x, self.HEIGHT, fill='#444')
        # 绘制横线（行分隔线）
        for i in range(33):
            y = i * self.CELL_SIZE
            self.canvas.create_line(0, y, self.WIDTH, y, fill='#444')
        # 绘制黑块
        for col, row in self.falling_blocks:
            x1 = col * self.COL_WIDTH
            y1 = row * self.CELL_SIZE
            x2 = x1 + self.COL_WIDTH
            y2 = y1 + self.BLOCK_HEIGHT * self.CELL_SIZE
            self.canvas.create_rectangle(x1, y1, x2, y2, fill='black', outline='gray')
        # 显示得分
        self.canvas.create_text(self.WIDTH//2, 20, text=f"得分: {self.score}",
                                fill='white', font=FONT_NORMAL)
        
    def on_click(self, event):
        if self.game_over or self.paused:
            return
        x, y = event.x, event.y
        col = x // self.COL_WIDTH
        row = y // self.CELL_SIZE
        # 检查点击位置是否在黑块上
        hit = False
        for i, (c, r) in enumerate(self.falling_blocks):
            if c == col and r <= row < r + self.BLOCK_HEIGHT:
                hit = True
                # 移除该黑块（得分）
                del self.falling_blocks[i]
                self.score += 1
                self.update_score()
                self.draw()
                break
        if not hit:
            # 点击白块，游戏结束
            self.end_game()

    def update_score(self):
        self.score_label.config(text=f"得分: {self.score}")

    def end_game(self):
        self.game_over = True
        self.status_label.config(text="游戏结束", fg='red')
        self.pause_btn.config(state=tk.DISABLED)
        if self.after_id:
            self.master.after_cancel(self.after_id)
            self.after_id = None
        self.draw()
        self.canvas.create_text(self.WIDTH//2, self.HEIGHT//2,
                                text=f"GAME OVER\n得分: {self.score}",
                                fill='red', font=FONT_TITLE, justify=tk.CENTER)

    def on_closing(self):
        if self.after_id:
            self.master.after_cancel(self.after_id)
        self.master.destroy()

# ----------------------------------------------------------------------
# 2D 向量与辅助函数
# ----------------------------------------------------------------------
class Vector2:
    __slots__ = ('x', 'y')
    def __init__(self, x: float = 0.0, y: float = 0.0):
        self.x = x
        self.y = y

    def __add__(self, other: 'Vector2') -> 'Vector2':
        return Vector2(self.x + other.x, self.y + other.y)
    def __sub__(self, other: 'Vector2') -> 'Vector2':
        return Vector2(self.x - other.x, self.y - other.y)
    def __mul__(self, scalar: float) -> 'Vector2':
        return Vector2(self.x * scalar, self.y * scalar)
    def __rmul__(self, scalar: float) -> 'Vector2':
        return Vector2(self.x * scalar, self.y * scalar)
    def __truediv__(self, scalar: float) -> 'Vector2':
        return Vector2(self.x / scalar, self.y / scalar)
    def __neg__(self) -> 'Vector2':
        return Vector2(-self.x, -self.y)
    def dot(self, other: 'Vector2') -> float:
        return self.x * other.x + self.y * other.y
    def cross(self, other: 'Vector2') -> float:
        return self.x * other.y - self.y * other.x
    def length_sq(self) -> float:
        return self.x*self.x + self.y*self.y
    def length(self) -> float:
        return math.sqrt(self.length_sq())
    def normalize(self) -> 'Vector2':
        l = self.length()
        if l == 0:
            return Vector2(0, 0)
        return Vector2(self.x / l, self.y / l)
    def copy(self) -> 'Vector2':
        return Vector2(self.x, self.y)

def rotate_vector(v: Vector2, angle: float) -> Vector2:
    c, s = math.cos(angle), math.sin(angle)
    return Vector2(v.x*c - v.y*s, v.x*s + v.y*c)

def clamp(value: float, minv: float, maxv: float) -> float:
    return max(minv, min(value, maxv))

# ----------------------------------------------------------------------
# 刚体形状 (圆、多边形/矩形)
# ----------------------------------------------------------------------
class Shape:
    pass

@dataclass
class Circle(Shape):
    radius: float

class Polygon(Shape):
    def __init__(self, vertices: List[Vector2]):
        self.vertices = vertices
        self.normals = self._compute_normals()
    def _compute_normals(self) -> List[Vector2]:
        normals = []
        for i in range(len(self.vertices)):
            a = self.vertices[i]
            b = self.vertices[(i+1) % len(self.vertices)]
            edge = b - a
            normal = Vector2(edge.y, -edge.x).normalize()
            normals.append(normal)
        return normals

def rectangle_polygon(half_width: float, half_height: float) -> Polygon:
    return Polygon([
        Vector2(-half_width, -half_height),
        Vector2( half_width, -half_height),
        Vector2( half_width,  half_height),
        Vector2(-half_width,  half_height)
    ])

# ----------------------------------------------------------------------
# 刚体 (支持旋转)
# ----------------------------------------------------------------------
class RigidBody:
    def __init__(self, pos: Vector2, shape: Shape, mass: float = 1.0,
                 restitution: float = 0.6, friction: float = 0.3,
                 dynamic: bool = True, color: str = None):
        self.pos = pos
        self.shape = shape
        self.mass = mass
        self.inv_mass = 0.0 if not dynamic else (1.0 / mass)
        self.restitution = restitution
        self.friction = friction
        self.dynamic = dynamic

        self.vel = Vector2(0, 0)
        self.acc = Vector2(0, 0)
        self.angle = 0.0
        self.ang_vel = 0.0
        self.ang_acc = 0.0

        self.inertia = self._compute_inertia()
        self.inv_inertia = 0.0 if not dynamic else (1.0 / self.inertia)
        self.color = color if color else self._random_color()

    def _compute_inertia(self) -> float:
        if not self.dynamic:
            return 0.0
        if isinstance(self.shape, Circle):
            return 0.5 * self.mass * self.shape.radius ** 2
        elif isinstance(self.shape, Polygon):
            w = self._get_width()
            h = self._get_height()
            return self.mass * (w*w + h*h) / 12.0
        return 0.0

    def _get_width(self) -> float:
        if isinstance(self.shape, Polygon):
            xs = [v.x for v in self.shape.vertices]
            return max(xs) - min(xs)
        return 0.0

    def _get_height(self) -> float:
        if isinstance(self.shape, Polygon):
            ys = [v.y for v in self.shape.vertices]
            return max(ys) - min(ys)
        return 0.0

    @staticmethod
    def _random_color():
        return '#{:02x}{:02x}{:02x}'.format(
            random.randint(80, 220),
            random.randint(80, 220),
            random.randint(80, 220)
        )

    def world_vertices(self) -> List[Vector2]:
        if isinstance(self.shape, Circle):
            return []
        verts = []
        for v in self.shape.vertices:
            rotated = rotate_vector(v, self.angle)
            verts.append(self.pos + rotated)
        return verts

    def get_axes(self) -> List[Vector2]:
        if isinstance(self.shape, Polygon):
            return [rotate_vector(n, self.angle) for n in self.shape.normals]
        return []

# ----------------------------------------------------------------------
# 粒子 (用于流体/特效)
# ----------------------------------------------------------------------
class Particle:
    def __init__(self, pos: Vector2, vel: Vector2 = None, radius: float = 3.0,
                 mass: float = 0.1, color: str = '#3399FF'):
        self.pos = pos
        self.vel = vel if vel else Vector2(0, 0)
        self.radius = radius
        self.mass = mass
        self.inv_mass = 1.0 / mass
        self.color = color
        self.life = 1.0
        self.is_fluid = True

    def kinetic_energy(self) -> float:
        return 0.5 * self.mass * self.vel.length_sq()

# ----------------------------------------------------------------------
# 软体 (质量-弹簧网络)
# ----------------------------------------------------------------------
class SoftBody:
    def __init__(self, pos: Vector2, radius: float, node_count: int = 12,
                 stiffness: float = 200.0, damping: float = 1.0,
                 mass_per_node: float = 0.2, color: str = '#FF66CC'):
        self.nodes: List[Particle] = []
        self.springs: List[Tuple[int, int, float, float]] = []
        self.pos = pos
        self.radius = radius
        self.stiffness = stiffness
        self.damping = damping
        self.color = color
        angle_step = 2 * math.pi / node_count
        for i in range(node_count):
            angle = i * angle_step
            offset = Vector2(math.cos(angle), math.sin(angle)) * radius
            node = Particle(pos + offset, mass=mass_per_node, radius=3.0, color=color)
            self.nodes.append(node)
        for i in range(node_count):
            j = (i+1) % node_count
            rest_len = (self.nodes[i].pos - self.nodes[j].pos).length()
            self.springs.append((i, j, rest_len, stiffness))
        for i in range(node_count):
            j = (i+node_count//2) % node_count
            rest_len = (self.nodes[i].pos - self.nodes[j].pos).length()
            self.springs.append((i, j, rest_len, stiffness * 0.8))

    def update_springs(self, dt: float):
        for i, j, rest_len, k in self.springs:
            p1, p2 = self.nodes[i], self.nodes[j]
            delta = p2.pos - p1.pos
            dist = delta.length()
            if dist < 1e-6:
                continue
            force_mag = -k * (dist - rest_len)
            rel_vel = p2.vel - p1.vel
            damp_force = -self.damping * (rel_vel.dot(delta) / dist)
            total_force = force_mag + damp_force
            direction = delta / dist
            f = direction * total_force
            p1.vel = p1.vel - f * p1.inv_mass * dt
            p2.vel = p2.vel + f * p2.inv_mass * dt

    def update(self, dt: float, gravity: Vector2, drag: float):
        for node in self.nodes:
            node.vel = node.vel + gravity * dt
            node.vel = node.vel * (1 - drag * dt)
            node.pos = node.pos + node.vel * dt
        self.update_springs(dt)

    def draw(self, canvas):
        for i, j, _, _ in self.springs:
            p1, p2 = self.nodes[i].pos, self.nodes[j].pos
            canvas.create_line(p1.x, p1.y, p2.x, p2.y, fill=self.color, width=1)
        for node in self.nodes:
            r = node.radius
            canvas.create_oval(node.pos.x - r, node.pos.y - r,
                               node.pos.x + r, node.pos.y + r,
                               fill=node.color, outline='purple')

# ----------------------------------------------------------------------
# 关节系统 (方向修正: 锚点局部坐标转换正确)
# ----------------------------------------------------------------------
class Joint:
    def __init__(self, body_a: RigidBody, body_b: RigidBody):
        self.body_a = body_a
        self.body_b = body_b

class DistanceJoint(Joint):
    def __init__(self, body_a: RigidBody, body_b: RigidBody,
                 anchor_a: Vector2, anchor_b: Vector2, distance: float = None):
        super().__init__(body_a, body_b)
        self.anchor_a = anchor_a
        self.anchor_b = anchor_b
        if distance is None:
            world_a = body_a.pos + rotate_vector(anchor_a, body_a.angle)
            world_b = body_b.pos + rotate_vector(anchor_b, body_b.angle)
            distance = (world_b - world_a).length()
        self.distance = distance

    def solve(self, iterations: int = 1):
        world_a = self.body_a.pos + rotate_vector(self.anchor_a, self.body_a.angle)
        world_b = self.body_b.pos + rotate_vector(self.anchor_b, self.body_b.angle)
        delta = world_b - world_a
        current_dist = delta.length()
        if current_dist < 1e-6:
            return
        correction = (current_dist - self.distance) / current_dist
        inv_mass_sum = self.body_a.inv_mass + self.body_b.inv_mass
        if inv_mass_sum == 0:
            return
        correction *= 0.5
        impulse = delta * (correction / inv_mass_sum)
        self.body_a.pos = self.body_a.pos - impulse * self.body_a.inv_mass
        self.body_b.pos = self.body_b.pos + impulse * self.body_b.inv_mass

class RevoluteJoint(Joint):
    def __init__(self, body_a: RigidBody, body_b: RigidBody, anchor: Vector2):
        super().__init__(body_a, body_b)
        self.anchor_world = anchor

    def solve(self, iterations: int = 1):
        r_a = self.anchor_world - self.body_a.pos
        r_b = self.anchor_world - self.body_b.pos
        delta = (self.body_b.pos + r_b) - (self.body_a.pos + r_a)
        inv_mass_sum = self.body_a.inv_mass + self.body_b.inv_mass
        if inv_mass_sum == 0:
            return
        correction = delta * (0.8 / inv_mass_sum)
        self.body_a.pos = self.body_a.pos - correction * self.body_a.inv_mass
        self.body_b.pos = self.body_b.pos + correction * self.body_b.inv_mass

# ----------------------------------------------------------------------
# 力场系统 (方向已统一为从场指向物体或反之)
# ----------------------------------------------------------------------
class ForceField:
    def apply(self, obj, dt: float) -> Vector2:
        return Vector2(0, 0)

class RadialForceField(ForceField):
    def __init__(self, center: Vector2, strength: float, radius: float = 200.0, attractive: bool = True):
        self.center = center
        self.strength = strength
        self.radius = radius
        self.attractive = attractive
    def apply(self, obj, dt: float) -> Vector2:
        delta = obj.pos - self.center
        dist = delta.length()
        if dist < 1e-6 or dist > self.radius:
            return Vector2(0, 0)
        magnitude = self.strength / (dist * dist + 1.0)
        if not self.attractive:
            magnitude = -magnitude
        direction = delta / dist
        return direction * magnitude

class VortexForceField(ForceField):
    def __init__(self, center: Vector2, strength: float, radius: float = 200.0):
        self.center = center
        self.strength = strength
        self.radius = radius
    def apply(self, obj, dt: float) -> Vector2:
        delta = obj.pos - self.center
        dist = delta.length()
        if dist > self.radius or dist < 1e-6:
            return Vector2(0, 0)
        perp = Vector2(-delta.y, delta.x).normalize()
        magnitude = self.strength * (1 - dist / self.radius)
        return perp * magnitude

class WindForceField(ForceField):
    def __init__(self, direction: Vector2, strength: float, noise: float = 0.5):
        self.direction = direction.normalize()
        self.strength = strength
        self.noise = noise
    def apply(self, obj, dt: float) -> Vector2:
        noise_vec = Vector2(random.uniform(-self.noise, self.noise),
                            random.uniform(-self.noise, self.noise))
        force = self.direction * self.strength + noise_vec
        return force

# ----------------------------------------------------------------------
# 光学引擎：光线投射与渲染
# ----------------------------------------------------------------------
class Ray:
    def __init__(self, origin: Vector2, direction: Vector2, max_dist: float = 1000.0):
        self.origin = origin
        self.direction = direction.normalize()
        self.max_dist = max_dist

class OpticsEngine:
    def __init__(self, world_ref: 'World'):
        self.world = world_ref
        self.light_sources = []  # 每个光源: (position, intensity, color)
        self.rays = []           # 存储待绘制的光线线段
        self.enabled = True

    def add_point_light(self, pos: Vector2, intensity: float = 1.0, color: str = 'yellow'):
        self.light_sources.append((pos, intensity, color))

    def cast_ray(self, ray: Ray) -> Tuple[Vector2, Optional[Any], float]:
        """返回(击中点, 击中物体, 距离)"""
        closest_dist = ray.max_dist
        hit_point = ray.origin + ray.direction * ray.max_dist
        hit_obj = None
        # 遍历所有刚体（包括静态）
        for body in self.world.bodies:
            # 只考虑凸形状，简化为圆形和矩形
            if isinstance(body.shape, Circle):
                # 圆与射线相交
                oc = ray.origin - body.pos
                a = ray.direction.dot(ray.direction)
                b = 2.0 * oc.dot(ray.direction)
                c = oc.dot(oc) - body.shape.radius**2
                disc = b*b - 4*a*c
                if disc >= 0:
                    t = (-b - math.sqrt(disc)) / (2*a)
                    if 0 < t < closest_dist:
                        closest_dist = t
                        hit_point = ray.origin + ray.direction * t
                        hit_obj = body
            elif isinstance(body.shape, Polygon):
                # 射线与多边形碰撞：遍历所有边
                verts = body.world_vertices()
                for i in range(len(verts)):
                    a = verts[i]
                    b = verts[(i+1)%len(verts)]
                    # 线段与射线交点
                    p = ray.origin
                    r = ray.direction
                    q = a
                    s = b - a
                    rxs = r.cross(s)
                    if abs(rxs) < 1e-8:
                        continue
                    t = (q - p).cross(s) / rxs
                    u = (q - p).cross(r) / rxs
                    if 0 <= t < closest_dist and 0 <= u <= 1:
                        closest_dist = t
                        hit_point = ray.origin + ray.direction * t
                        hit_obj = body
        # 粒子对光线透明，忽略
        # 软体节点也忽略，简化
        return hit_point, hit_obj, closest_dist

    def update_rays_from_lights(self):
        """从每个光源向所有方向发射光线（简化为8个方向）"""
        self.rays.clear()
        if not self.enabled:
            return
        for light_pos, intensity, color in self.light_sources:
            # 发射8条光线，角度间隔45度
            for ang in range(0, 360, 45):
                rad = math.radians(ang)
                dir_vec = Vector2(math.cos(rad), math.sin(rad))
                ray = Ray(light_pos, dir_vec, max_dist=600)
                hit_point, hit_obj, dist = self.cast_ray(ray)
                if hit_obj is not None:
                    self.rays.append((light_pos, hit_point, color, intensity))
                else:
                    # 没击中，画到边界
                    end = light_pos + dir_vec * ray.max_dist
                    self.rays.append((light_pos, end, color, intensity*0.3))

    def draw(self, canvas):
        for start, end, color, intensity in self.rays:
            # 根据强度调整亮度
            alpha = min(255, int(255 * intensity))
            hex_color = color if color.startswith('#') else self._color_name_to_hex(color)
            canvas.create_line(start.x, start.y, end.x, end.y,
                               fill=hex_color, width=2, stipple='gray50' if intensity<0.5 else '')

    @staticmethod
    def _color_name_to_hex(name):
        colors = {'yellow': '#FFFF00', 'red': '#FF0000', 'green': '#00FF00', 'blue': '#0000FF'}
        return colors.get(name, '#FFFF00')

# ----------------------------------------------------------------------
# 声学引擎：基于碰撞事件播放声音 (使用 winsound 和线程)
# ----------------------------------------------------------------------
class AudioEngine:
    def __init__(self):
        self.enabled = True
        self.last_sound_time = {}  # 用于限制同一物体对的声音频率
        self.min_interval = 0.05   # 最小间隔(秒)

    def play_collision_sound(self, obj_a, obj_b, relative_velocity: float, restitution: float):
        if not self.enabled:
            return
        # 避免短时间内重复播放
        key = (id(obj_a), id(obj_b)) if id(obj_a) < id(obj_b) else (id(obj_b), id(obj_a))
        now = time.time()
        if key in self.last_sound_time and now - self.last_sound_time[key] < self.min_interval:
            return
        self.last_sound_time[key] = now

        # 根据相对速度和恢复系数映射频率：速度越大频率越高，恢复系数影响音色
        freq = int(300 + min(800, abs(relative_velocity) * 5) * restitution)
        freq = clamp(freq, 200, 2000)
        duration = int(50 + min(200, abs(relative_velocity) * 2))
        # 使用线程播放，避免阻塞主循环
        threading.Thread(target=self._beep, args=(freq, duration), daemon=True).start()

    def _beep(self, freq, duration):
        try:
            winsound.Beep(freq, duration)
        except Exception:
            pass  # 非Windows系统忽略

# ----------------------------------------------------------------------
# 物理世界 (集成所有子系统)
# ----------------------------------------------------------------------
world_width = 1000
world_height = 700

class World:
    def __init__(self, gravity: Vector2 = Vector2(0, 500), drag: float = 0.005):
        self.bodies: List[RigidBody] = []
        self.particles: List[Particle] = []
        self.soft_bodies: List[SoftBody] = []
        self.joints: List[Joint] = []
        self.force_fields: List[ForceField] = []

        self.gravity = gravity
        self.drag = drag
        self.ang_drag = 0.01
        self.iterations = 10
        self.dt = 1 / 60.0

        # SPH 参数
        self.sph_enabled = True
        self.sph_pressure_stiffness = 200.0
        self.sph_rest_density = 1.0
        self.sph_viscosity = 0.1
        self.sph_kernel_radius = 20.0

        # 性能统计
        self.frame_count = 0
        self.last_time = time.time()
        self.fps = 0

        # 光学与声学引擎
        self.optics = OpticsEngine(self)
        self.audio = AudioEngine()

        # 添加默认光源
        self.optics.add_point_light(Vector2(world_width/2, 50), intensity=0.8, color='yellow')
        self.optics.add_point_light(Vector2(200, 300), intensity=0.5, color='red')

    def add_body(self, body: RigidBody):
        self.bodies.append(body)

    def add_particle(self, particle: Particle):
        self.particles.append(particle)

    def add_soft_body(self, soft: SoftBody):
        self.soft_bodies.append(soft)

    def add_joint(self, joint: Joint):
        self.joints.append(joint)

    def add_force_field(self, field: ForceField):
        self.force_fields.append(field)

    # ----------------- SPH 流体 -----------------
    def update_sph(self, dt: float):
        if not self.sph_enabled:
            return
        n = len(self.particles)
        if n == 0:
            return
        densities = [0.0] * n
        pressures = [0.0] * n
        for i in range(n):
            rho = 0.0
            pi = self.particles[i]
            for j in range(n):
                if i == j:
                    continue
                pj = self.particles[j]
                delta = pi.pos - pj.pos
                dist = delta.length()
                if dist < self.sph_kernel_radius:
                    w = max(0, 1 - dist / self.sph_kernel_radius)
                    rho += pj.mass * w
            densities[i] = max(rho, 0.01)
            pressures[i] = self.sph_pressure_stiffness * (densities[i] - self.sph_rest_density)
        for i in range(n):
            pi = self.particles[i]
            force = Vector2(0, 0)
            for j in range(n):
                if i == j:
                    continue
                pj = self.particles[j]
                delta = pi.pos - pj.pos
                dist = delta.length()
                if dist < self.sph_kernel_radius:
                    w_prime = -1.0 / (self.sph_kernel_radius * dist + 1e-6)
                    pressure_force = -(pressures[i] + pressures[j]) / (2 * densities[j]) * w_prime
                    force += (delta / dist) * pressure_force * pj.mass
                    rel_vel = pj.vel - pi.vel
                    visc = self.sph_viscosity * rel_vel.dot(delta) / (dist * dist + 1e-6) * w_prime
                    force += rel_vel * visc * pj.mass
            pi.vel += force * dt

    # ----------------- 力场应用 -----------------
    def apply_force_fields(self, dt: float):
        for field in self.force_fields:
            for b in self.bodies:
                if b.dynamic:
                    f = field.apply(b, dt)
                    b.vel += f * b.inv_mass * dt
            for p in self.particles:
                f = field.apply(p, dt)
                p.vel += f * p.inv_mass * dt
            for soft in self.soft_bodies:
                for node in soft.nodes:
                    f = field.apply(node, dt)
                    node.vel += f * node.inv_mass * dt

    # ----------------- 碰撞检测与响应 (刚体间) 修正法向方向 -----------------
    @dataclass
    class Contact:
        point: Vector2
        normal: Vector2
        penetration: float

    @dataclass
    class Collision:
        body_a: RigidBody
        body_b: RigidBody
        contact: 'World.Contact'

    def circle_circle(self, a: RigidBody, b: RigidBody) -> Optional['World.Contact']:
        if not isinstance(a.shape, Circle) or not isinstance(b.shape, Circle):
            return None
        delta = b.pos - a.pos
        dist = delta.length()
        rad_sum = a.shape.radius + b.shape.radius
        if dist >= rad_sum:
            return None
        penetration = rad_sum - dist
        normal = delta / dist if dist > 1e-6 else Vector2(1,0)
        # 修正：法向从 a 指向 b
        point = a.pos + normal * (a.shape.radius - penetration * 0.5)
        return self.Contact(point, normal, penetration)

    def circle_polygon(self, circle_body: RigidBody, poly_body: RigidBody) -> Optional['World.Contact']:
        if not isinstance(circle_body.shape, Circle) or not isinstance(poly_body.shape, Polygon):
            return None
        circle = circle_body.shape
        local_center = circle_body.pos - poly_body.pos
        local_center = rotate_vector(local_center, -poly_body.angle)
        vertices = poly_body.shape.vertices
        closest_dist_sq = float('inf')
        closest_point = None
        for v in vertices:
            delta = local_center - v
            dist_sq = delta.length_sq()
            if dist_sq < closest_dist_sq:
                closest_dist_sq = dist_sq
                closest_point = v
        for i in range(len(vertices)):
            a = vertices[i]
            bv = vertices[(i+1) % len(vertices)]
            ab = bv - a
            t = (local_center - a).dot(ab) / max(ab.dot(ab), 1e-8)
            t = clamp(t, 0, 1)
            edge_point = a + ab * t
            delta = local_center - edge_point
            dist_sq = delta.length_sq()
            if dist_sq < closest_dist_sq:
                closest_dist_sq = dist_sq
                closest_point = edge_point
        if closest_point is None:
            return None
        delta_local = local_center - closest_point
        dist = math.sqrt(closest_dist_sq)
        if dist >= circle.radius:
            return None
        penetration = circle.radius - dist
        normal_local = delta_local / dist if dist > 1e-6 else Vector2(0, -1)
        normal_world = rotate_vector(normal_local, poly_body.angle)
        # 修正：确保法向从圆形指向多边形
        # 圆形为 a，多边形为 b，法向应该从 a 指向 b
        # 当前 normal_world 是从多边形最近点指向圆心，需要反向
        normal_world = -normal_world
        point_local = closest_point
        point_world = poly_body.pos + rotate_vector(point_local, poly_body.angle)
        return self.Contact(point_world, normal_world, penetration)

    def polygon_polygon(self, a: RigidBody, b: RigidBody) -> Optional['World.Contact']:
        if not isinstance(a.shape, Polygon) or not isinstance(b.shape, Polygon):
            return None
        axes = a.get_axes() + b.get_axes()
        min_penetration = float('inf')
        best_axis = None
        def project(poly: RigidBody, axis: Vector2):
            min_proj = float('inf')
            max_proj = -float('inf')
            for v in poly.world_vertices():
                proj = v.dot(axis)
                if proj < min_proj: min_proj = proj
                if proj > max_proj: max_proj = proj
            return min_proj, max_proj
        for axis in axes:
            l = axis.length()
            if l < 1e-8: continue
            axis = axis / l
            min1, max1 = project(a, axis)
            min2, max2 = project(b, axis)
            if max1 < min2 or max2 < min1:
                return None
            overlap = min(max1, max2) - max(min1, min2)
            if overlap < min_penetration:
                min_penetration = overlap
                best_axis = axis
        if best_axis is None:
            return None
        # 确保法向从 a 指向 b
        center_dir = b.pos - a.pos
        if center_dir.dot(best_axis) < 0:
            best_axis = -best_axis
        closest_dist_sq = float('inf')
        contact_point = None
        for v1 in a.world_vertices():
            for v2 in b.world_vertices():
                delta = v2 - v1
                dist_sq = delta.length_sq()
                if dist_sq < closest_dist_sq:
                    closest_dist_sq = dist_sq
                    contact_point = (v1 + v2) * 0.5
        if contact_point is None:
            contact_point = (a.pos + b.pos) * 0.5
        return self.Contact(contact_point, best_axis, min_penetration)

    def dispatch_collision(self, a: RigidBody, b: RigidBody) -> Optional['World.Collision']:
        shape_a = type(a.shape)
        shape_b = type(b.shape)
        contact = None
        if shape_a is Circle and shape_b is Circle:
            contact = self.circle_circle(a, b)
        elif shape_a is Circle and shape_b is Polygon:
            contact = self.circle_polygon(a, b)
        elif shape_a is Polygon and shape_b is Circle:
            c = self.circle_polygon(b, a)
            if c:
                # 交换时法向取反
                contact = self.Contact(c.point, -c.normal, c.penetration)
        elif shape_a is Polygon and shape_b is Polygon:
            contact = self.polygon_polygon(a, b)
        if contact:
            return self.Collision(a, b, contact)
        return None

    def resolve_collision(self, coll: 'World.Collision'):
        a, b = coll.body_a, coll.body_b
        c = coll.contact
        n = c.normal
        # 位置修正
        if a.inv_mass + b.inv_mass > 0:
            correction = max(c.penetration - 0.01, 0.0)
            percent = 0.8
            correction_vec = n * correction * percent
            total_inv_mass = a.inv_mass + b.inv_mass
            if a.dynamic:
                a.pos = a.pos - correction_vec * (a.inv_mass / total_inv_mass)
            if b.dynamic:
                b.pos = b.pos + correction_vec * (b.inv_mass / total_inv_mass)
        # 相对速度
        r_a = c.point - a.pos
        r_b = c.point - b.pos
        v_a = a.vel + Vector2(-a.ang_vel * r_a.y, a.ang_vel * r_a.x)
        v_b = b.vel + Vector2(-b.ang_vel * r_b.y, b.ang_vel * r_b.x)
        v_rel = v_b - v_a
        vel_along_n = v_rel.dot(n)
        if vel_along_n > 0:
            return
        # 冲量计算
        e = min(a.restitution, b.restitution)
        numerator = -(1 + e) * vel_along_n
        r_a_cross_n = r_a.cross(n)
        r_b_cross_n = r_b.cross(n)
        denominator = a.inv_mass + b.inv_mass + (r_a_cross_n*r_a_cross_n)*a.inv_inertia + (r_b_cross_n*r_b_cross_n)*b.inv_inertia
        impulse_mag = numerator / max(denominator, 1e-8)
        impulse_n = n * impulse_mag
        if a.dynamic:
            a.vel = a.vel - impulse_n * a.inv_mass
            a.ang_vel = a.ang_vel - r_a.cross(impulse_n) * a.inv_inertia
        if b.dynamic:
            b.vel = b.vel + impulse_n * b.inv_mass
            b.ang_vel = b.ang_vel + r_b.cross(impulse_n) * b.inv_inertia
        # 摩擦
        t = v_rel - n * vel_along_n
        if t.length_sq() > 1e-6:
            t = t.normalize()
            numerator_t = -v_rel.dot(t)
            r_a_cross_t = r_a.cross(t)
            r_b_cross_t = r_b.cross(t)
            denominator_t = a.inv_mass + b.inv_mass + (r_a_cross_t*r_a_cross_t)*a.inv_inertia + (r_b_cross_t*r_b_cross_t)*b.inv_inertia
            jt = numerator_t / max(denominator_t, 1e-8)
            mu = math.sqrt(a.friction * b.friction)
            max_jt = impulse_mag * mu
            jt = clamp(jt, -max_jt, max_jt)
            impulse_t = t * jt
            if a.dynamic:
                a.vel = a.vel - impulse_t * a.inv_mass
                a.ang_vel = a.ang_vel - r_a.cross(impulse_t) * a.inv_inertia
            if b.dynamic:
                b.vel = b.vel + impulse_t * b.inv_mass
                b.ang_vel = b.ang_vel + r_b.cross(impulse_t) * b.inv_inertia

        # 播放碰撞声音 (相对速度大小)
        rel_speed = abs(vel_along_n)
        self.audio.play_collision_sound(a, b, rel_speed, e)

    # ----------------- 刚体-粒子碰撞 -----------------
    def closest_point_on_polygon(self, point: Vector2, body: RigidBody) -> Vector2:
        local_pt = point - body.pos
        local_pt = rotate_vector(local_pt, -body.angle)
        vertices = body.shape.vertices
        closest = vertices[0].copy()
        min_dist = (local_pt - vertices[0]).length_sq()
        for v in vertices:
            d = (local_pt - v).length_sq()
            if d < min_dist:
                min_dist = d
                closest = v
        for i in range(len(vertices)):
            a = vertices[i]
            b = vertices[(i+1)%len(vertices)]
            ab = b - a
            t = (local_pt - a).dot(ab) / max(ab.dot(ab), 1e-8)
            t = clamp(t, 0, 1)
            edge_pt = a + ab * t
            d = (local_pt - edge_pt).length_sq()
            if d < min_dist:
                min_dist = d
                closest = edge_pt
        return body.pos + rotate_vector(closest, body.angle)

    def handle_particle_collisions(self):
        for p in self.particles:
            for b in self.bodies:
                if not b.dynamic:
                    continue
                if isinstance(b.shape, Circle):
                    delta = p.pos - b.pos
                    dist = delta.length()
                    min_dist = b.shape.radius + p.radius
                    if dist < min_dist:
                        normal = delta / dist if dist > 0 else Vector2(1,0)
                        p.pos = b.pos + normal * (min_dist + 0.01)
                        rel_speed = p.vel.dot(normal) - b.vel.dot(normal)
                        p.vel = p.vel - normal * (1 + b.restitution) * p.vel.dot(normal)
                        self.audio.play_collision_sound(p, b, abs(rel_speed), b.restitution)
                elif isinstance(b.shape, Polygon):
                    closest = self.closest_point_on_polygon(p.pos, b)
                    delta = p.pos - closest
                    dist = delta.length()
                    if dist < p.radius:
                        normal = delta / dist if dist > 0 else Vector2(0, -1)
                        p.pos = closest + normal * p.radius
                        rel_speed = p.vel.dot(normal) - b.vel.dot(normal)
                        p.vel = p.vel - normal * (1 + b.restitution) * p.vel.dot(normal)
                        self.audio.play_collision_sound(p, b, abs(rel_speed), b.restitution)
            # 边界碰撞也发出声音（简化）
            margin = p.radius
            if p.pos.x - margin < 0 or p.pos.x + margin > world_width or p.pos.y - margin < 0 or p.pos.y + margin > world_height:
                self.audio.play_collision_sound(p, None, 50, 0.5)

    def handle_softbody_collisions(self):
        for soft in self.soft_bodies:
            for node in soft.nodes:
                for b in self.bodies:
                    if not b.dynamic:
                        continue
                    if isinstance(b.shape, Circle):
                        delta = node.pos - b.pos
                        dist = delta.length()
                        min_dist = b.shape.radius + node.radius
                        if dist < min_dist:
                            normal = delta / dist if dist > 0 else Vector2(1,0)
                            node.pos = b.pos + normal * (min_dist + 0.01)
                            rel_speed = node.vel.dot(normal) - b.vel.dot(normal)
                            node.vel = node.vel - normal * (1 + b.restitution) * node.vel.dot(normal)
                            self.audio.play_collision_sound(node, b, abs(rel_speed), b.restitution)
                    elif isinstance(b.shape, Polygon):
                        closest = self.closest_point_on_polygon(node.pos, b)
                        delta = node.pos - closest
                        dist = delta.length()
                        if dist < node.radius:
                            normal = delta / dist if dist > 0 else Vector2(0, -1)
                            node.pos = closest + normal * node.radius
                            rel_speed = node.vel.dot(normal) - b.vel.dot(normal)
                            node.vel = node.vel - normal * (1 + b.restitution) * node.vel.dot(normal)
                            self.audio.play_collision_sound(node, b, abs(rel_speed), b.restitution)

    # ----------------- 主更新循环 -----------------
    def step(self, dt: float):
        # 1. 应用力场
        self.apply_force_fields(dt)
        # 2. 更新刚体
        for b in self.bodies:
            if b.dynamic:
                drag_acc = b.vel * (-self.drag / max(b.mass, 0.01))
                b.acc = self.gravity + drag_acc
                b.vel = b.vel + b.acc * dt
                b.ang_vel = b.ang_vel * (1 - self.ang_drag)
                b.pos = b.pos + b.vel * dt
                b.angle += b.ang_vel * dt
        # 3. 更新粒子
        for p in self.particles:
            p.vel = p.vel + self.gravity * dt
            p.vel = p.vel * (1 - self.drag * dt)
            p.pos = p.pos + p.vel * dt
        # 4. 更新软体
        for soft in self.soft_bodies:
            soft.update(dt, self.gravity, self.drag)
        # 5. SPH
        self.update_sph(dt)
        # 6. 刚体碰撞
        for _ in range(self.iterations):
            collisions = []
            n = len(self.bodies)
            for i in range(n):
                for j in range(i+1, n):
                    coll = self.dispatch_collision(self.bodies[i], self.bodies[j])
                    if coll:
                        collisions.append(coll)
            if not collisions:
                break
            for coll in collisions:
                self.resolve_collision(coll)
        # 7. 粒子与刚体碰撞
        self.handle_particle_collisions()
        # 8. 软体节点碰撞
        self.handle_softbody_collisions()
        # 9. 关节求解
        for _ in range(self.iterations):
            for joint in self.joints:
                if isinstance(joint, DistanceJoint):
                    joint.solve()
                elif isinstance(joint, RevoluteJoint):
                    joint.solve()
        # 10. 边界约束
        margin = 10
        for b in self.bodies:
            if not b.dynamic:
                continue
            if isinstance(b.shape, Circle):
                hw = b.shape.radius
                hh = b.shape.radius
            else:
                hw = b._get_width() / 2
                hh = b._get_height() / 2
            if b.pos.x - hw < margin:
                b.pos.x = margin + hw
                b.vel.x = -b.vel.x * b.restitution
                self.audio.play_collision_sound(b, None, abs(b.vel.x), b.restitution)
            if b.pos.x + hw > world_width - margin:
                b.pos.x = world_width - margin - hw
                b.vel.x = -b.vel.x * b.restitution
                self.audio.play_collision_sound(b, None, abs(b.vel.x), b.restitution)
            if b.pos.y - hh < margin:
                b.pos.y = margin + hh
                b.vel.y = -b.vel.y * b.restitution
                self.audio.play_collision_sound(b, None, abs(b.vel.y), b.restitution)
            if b.pos.y + hh > world_height - margin:
                b.pos.y = world_height - margin - hh
                b.vel.y = -b.vel.y * b.restitution
                self.audio.play_collision_sound(b, None, abs(b.vel.y), b.restitution)

        # 更新光学光线
        self.optics.update_rays_from_lights()

        # 性能统计
        self.frame_count += 1
        now = time.time()
        if now - self.last_time >= 1.0:
            self.fps = self.frame_count
            self.frame_count = 0
            self.last_time = now

# ----------------------------------------------------------------------
# Tkinter 可视化主程序 (整合光学绘制)
# ----------------------------------------------------------------------
class PhysicsApp:
    def __init__(self, root):
        self.root = root
        self.root.title("终极物理引擎 + 光学 + 声学")
        self.canvas = tk.Canvas(root, width=world_width, height=world_height,
                                bg='black', highlightthickness=0)  # 黑背景凸显光线
        self.canvas.pack()

        frame = tk.Frame(root)
        frame.pack(fill=tk.X, padx=5, pady=5)

        tk.Button(frame, text="清除所有动态物体", command=self.clear_all).pack(side=tk.LEFT, padx=5)
        tk.Button(frame, text="随机刚体圆形", command=lambda: self.add_random_body('circle')).pack(side=tk.LEFT, padx=5)
        tk.Button(frame, text="随机刚体矩形", command=lambda: self.add_random_body('rect')).pack(side=tk.LEFT, padx=5)
        tk.Button(frame, text="添加软体", command=self.add_softbody).pack(side=tk.LEFT, padx=5)
        tk.Button(frame, text="添加粒子群", command=self.add_particle_swarm).pack(side=tk.LEFT, padx=5)
        tk.Button(frame, text="切换力场", command=self.toggle_force_fields).pack(side=tk.LEFT, padx=5)
        tk.Button(frame, text="切换光学", command=self.toggle_optics).pack(side=tk.LEFT, padx=5)
        tk.Button(frame, text="切换声音", command=self.toggle_audio).pack(side=tk.LEFT, padx=5)
        tk.Button(frame, text="暂停/运行", command=self.toggle_run).pack(side=tk.LEFT, padx=5)

        self.info_label = tk.Label(root, text="", font=('Unifont', 10), fg='white', bg='black')
        self.info_label.pack(side=tk.BOTTOM, fill=tk.X)

        self.world = World(gravity=Vector2(0, 600), drag=0.005)
        self._init_scene()
        self.running = True
        self.dt = 1/60.0

        self.canvas.bind("<Button-1>", lambda e: self.create_body(e.x, e.y, 'circle'))
        self.canvas.bind("<Button-3>", lambda e: self.create_body(e.x, e.y, 'rect'))
        self.animate()

    def _init_scene(self):
        # 地面
        ground = RigidBody(pos=Vector2(world_width/2, world_height-20),
                           shape=rectangle_polygon(world_width/2, 20),
                           mass=0, restitution=0.5, friction=0.5, dynamic=False,
                           color='#8B5A2B')
        self.world.add_body(ground)
        # 左右墙
        left = RigidBody(pos=Vector2(15, world_height/2),
                         shape=rectangle_polygon(15, world_height/2),
                         mass=0, dynamic=False, color='#AAAAAA')
        self.world.add_body(left)
        right = RigidBody(pos=Vector2(world_width-15, world_height/2),
                          shape=rectangle_polygon(15, world_height/2),
                          mass=0, dynamic=False, color='#AAAAAA')
        self.world.add_body(right)

        # 演示刚体
        box = RigidBody(pos=Vector2(400, 500), shape=rectangle_polygon(30, 30),
                        mass=2.0, restitution=0.7, friction=0.4)
        box.vel = Vector2(80, 0)
        box.ang_vel = 1.2
        self.world.add_body(box)

        ball = RigidBody(pos=Vector2(600, 300), shape=Circle(25),
                         mass=1.5, restitution=0.8, friction=0.3)
        ball.vel = Vector2(-60, 100)
        self.world.add_body(ball)

        # 软体
        soft = SoftBody(pos=Vector2(800, 200), radius=50, node_count=12,
                        stiffness=150, damping=0.8, mass_per_node=0.15, color='#FF88CC')
        self.world.add_soft_body(soft)

        # 关节
        box2 = RigidBody(pos=Vector2(200, 300), shape=Circle(20),
                         mass=1.0, restitution=0.6, dynamic=True)
        box2.vel = Vector2(100, -50)
        self.world.add_body(box2)
        joint = DistanceJoint(box, box2, anchor_a=Vector2(0,0), anchor_b=Vector2(0,0), distance=150)
        self.world.add_joint(joint)

        # 力场
        self.radial_field = RadialForceField(center=Vector2(world_width/2, world_height/2),
                                             strength=3000, radius=250, attractive=True)
        self.vortex_field = VortexForceField(center=Vector2(world_width/2, world_height/2),
                                             strength=200, radius=200)
        self.wind_field = WindForceField(direction=Vector2(1, 0), strength=50, noise=30)
        self.force_fields_enabled = True
        self.world.add_force_field(self.radial_field)
        self.world.add_force_field(self.vortex_field)
        self.world.add_force_field(self.wind_field)

    def clear_all(self):
        self.world.bodies = [b for b in self.world.bodies if not b.dynamic]
        self.world.particles.clear()
        self.world.soft_bodies.clear()
        self.world.joints.clear()

    def add_random_body(self, typ: str):
        x = random.uniform(100, world_width-100)
        y = random.uniform(80, world_height-150)
        if typ == 'circle':
            radius = random.uniform(12, 28)
            shape = Circle(radius)
            mass = radius / 10.0
            body = RigidBody(pos=Vector2(x, y), shape=shape, mass=mass,
                             restitution=random.uniform(0.5,0.9), friction=random.uniform(0.2,0.6))
            body.vel = Vector2(random.uniform(-150,150), random.uniform(-50,100))
        else:
            w = random.uniform(20,45)
            h = random.uniform(20,45)
            shape = rectangle_polygon(w/2, h/2)
            mass = (w*h)/500.0
            body = RigidBody(pos=Vector2(x, y), shape=shape, mass=mass,
                             restitution=random.uniform(0.4,0.8), friction=random.uniform(0.3,0.7))
            body.vel = Vector2(random.uniform(-150,150), random.uniform(-50,100))
            body.ang_vel = random.uniform(-2,2)
        self.world.add_body(body)

    def add_softbody(self):
        x = random.uniform(100, world_width-100)
        y = random.uniform(100, world_height-100)
        soft = SoftBody(pos=Vector2(x, y), radius=random.uniform(40,70),
                        node_count=random.choice([8,12,16]),
                        stiffness=random.uniform(100,250), damping=0.8,
                        mass_per_node=0.1, color='#FF88CC')
        self.world.add_soft_body(soft)

    def add_particle_swarm(self):
        cx = random.uniform(200, world_width-200)
        cy = random.uniform(100, world_height-200)
        for _ in range(80):
            angle = random.uniform(0, 2*math.pi)
            rad = random.uniform(0, 40)
            x = cx + math.cos(angle)*rad
            y = cy + math.sin(angle)*rad
            p = Particle(pos=Vector2(x, y),
                         vel=Vector2(random.uniform(-20,20), random.uniform(-20,20)),
                         radius=3, mass=0.1, color='#3399FF')
            self.world.add_particle(p)

    def create_body(self, x, y, typ: str):
        x = max(20, min(world_width-20, x))
        y = max(20, min(world_height-20, y))
        if typ == 'circle':
            body = RigidBody(pos=Vector2(x, y), shape=Circle(15),
                             mass=1.0, restitution=0.75, friction=0.4)
        else:
            body = RigidBody(pos=Vector2(x, y), shape=rectangle_polygon(20,20),
                             mass=1.2, restitution=0.65, friction=0.5)
        body.vel = Vector2(random.uniform(-80,80), -150)
        self.world.add_body(body)

    def toggle_force_fields(self):
        self.force_fields_enabled = not self.force_fields_enabled
        if not self.force_fields_enabled:
            self.world.force_fields.clear()
        else:
            self.world.force_fields = [self.radial_field, self.vortex_field, self.wind_field]

    def toggle_optics(self):
        self.world.optics.enabled = not self.world.optics.enabled

    def toggle_audio(self):
        self.world.audio.enabled = not self.world.audio.enabled

    def toggle_run(self):
        self.running = not self.running

    def draw(self):
        self.canvas.delete("all")
        # 绘制光学光线 (先绘制光线，再绘制物体，使光线在半透明效果下可见)
        if self.world.optics.enabled:
            self.world.optics.draw(self.canvas)

        # 绘制刚体
        for b in self.world.bodies:
            if isinstance(b.shape, Circle):
                r = b.shape.radius
                self.canvas.create_oval(b.pos.x - r, b.pos.y - r,
                                        b.pos.x + r, b.pos.y + r,
                                        fill=b.color, outline='white', width=1.5)
            elif isinstance(b.shape, Polygon):
                verts = b.world_vertices()
                if verts:
                    coords = []
                    for v in verts:
                        coords.extend([v.x, v.y])
                    self.canvas.create_polygon(coords, fill=b.color, outline='white', width=1.5)
        # 绘制粒子
        for p in self.world.particles:
            r = p.radius
            self.canvas.create_oval(p.pos.x - r, p.pos.y - r,
                                    p.pos.x + r, p.pos.y + r,
                                    fill=p.color, outline='')
        # 绘制软体
        for soft in self.world.soft_bodies:
            soft.draw(self.canvas)
        # 绘制关节
        for joint in self.world.joints:
            if isinstance(joint, DistanceJoint):
                pa = joint.body_a.pos + rotate_vector(joint.anchor_a, joint.body_a.angle)
                pb = joint.body_b.pos + rotate_vector(joint.anchor_b, joint.body_b.angle)
                self.canvas.create_line(pa.x, pa.y, pb.x, pb.y, fill='red', width=2, dash=(4,2))
            elif isinstance(joint, RevoluteJoint):
                self.canvas.create_oval(joint.anchor_world.x-3, joint.anchor_world.y-3,
                                        joint.anchor_world.x+3, joint.anchor_world.y+3,
                                        fill='yellow', outline='orange')
        # 性能信息
        obj_count = len(self.world.bodies) + len(self.world.particles) + sum(len(s.nodes) for s in self.world.soft_bodies)
        self.info_label.config(text=f"FPS: {self.world.fps}  |  物体: {obj_count}  |  刚体: {len(self.world.bodies)} 粒子: {len(self.world.particles)} 软体节点: {sum(len(s.nodes) for s in self.world.soft_bodies)} | 光学: {'开' if self.world.optics.enabled else '关'} 声音: {'开' if self.world.audio.enabled else '关'}")
        # 力场指示器
        if self.force_fields_enabled:
            self.canvas.create_oval(self.radial_field.center.x-250, self.radial_field.center.y-250,
                                    self.radial_field.center.x+250, self.radial_field.center.y+250,
                                    outline='green', dash=(5,5), width=1)

    def animate(self):
        if self.running:
            mx, my = self.canvas.winfo_pointerx() - self.canvas.winfo_rootx(), self.canvas.winfo_pointery() - self.canvas.winfo_rooty()
            if 0 <= mx <= world_width and 0 <= my <= world_height:
                self.radial_field.center = Vector2(mx, my)
                self.vortex_field.center = Vector2(mx, my)
            self.world.step(self.dt)
            self.draw()
        self.root.after(16, self.animate)

