# -------------------- 化学分子类（依赖物理引擎） --------------------
class Molecule:
    """表示一个分子，由原子（RigidBody）和键（DistanceJoint）组成"""
    def __init__(self, world: 'World', template_name: str, center: Vector2, scale: float = 1.0, vel: Vector2 = None):
        self.world = world
        self.template = template_name
        self.atoms = []          # 存储 RigidBody 对象
        self.bonds = []          # 存储 DistanceJoint 对象
        self.center = center
        self.scale = scale
        self.vel = vel if vel else Vector2(0, 0)
        self._build_from_template(template_name, center, scale)
        self._apply_initial_velocity()
        self._alive = True

    def _build_from_template(self, template_name, center, scale):
        template = MOLECULE_TEMPLATES[template_name]
        atom_symbols = template['atoms']
        bond_indices = template['bonds']
        # 计算原子位置（根据形状）
        positions = self._compute_atom_positions(template, scale)
        # 创建原子
        for i, (symbol, pos) in enumerate(zip(atom_symbols, positions)):
            props = ATOM_PROPS.get(symbol, {'color': '#AAAAAA', 'radius': 15, 'mass': 10.0})
            radius = props['radius'] * scale
            mass = props['mass'] * scale
            body = RigidBody(
                pos=center + pos,
                shape=Circle(radius),
                mass=mass,
                restitution=0.4,
                friction=0.3,
                dynamic=True,
                color=props['color']
            )
            # 存储元素符号用于识别
            body.element = symbol
            body.molecule_ref = self
            self.world.add_body(body)
            self.atoms.append(body)
        # 创建键（DistanceJoint）
        for i, j in bond_indices:
            # 锚点取原子局部坐标（相对于原子中心）
            anchor_a = self.atoms[i].pos - center  # 原子初始位置相对分子中心的偏移
            anchor_b = self.atoms[j].pos - center
            # 注意：分子整体移动时，原子位置会变化，但锚点应相对于原子本身，所以使用局部偏移（0,0）？
            # 更稳健：在joint中直接使用原子位置，但DistanceJoint设计为锚点固定的，需要随原子移动。
            # 这里我们使用原子当前位置作为锚点（但DistanceJoint的锚点是相对于body的偏移，我们让锚点为零，即连接质心？）
            # 简单处理：将anchor设为 (0,0)，即关节连接两个body的质心。
            joint = DistanceJoint(
                body_a=self.atoms[i],
                body_b=self.atoms[j],
                anchor_a=Vector2(0, 0),
                anchor_b=Vector2(0, 0),
                distance=(self.atoms[i].pos - self.atoms[j].pos).length()
            )
            self.world.add_joint(joint)
            self.bonds.append(joint)

    def _compute_atom_positions(self, template, scale):
        """根据分子形状计算原子相对中心的位置（单位：像素）"""
        n = len(template['atoms'])
        shape = template.get('shape', 'linear')
        length = template.get('length', 30) * scale
        positions = []
        if shape == 'linear':
            # 线性分子：均匀分布在x轴上
            if n == 2:
                positions = [Vector2(-length/2, 0), Vector2(length/2, 0)]
            elif n == 3:
                positions = [Vector2(-length, 0), Vector2(0, 0), Vector2(length, 0)]
            else:
                # 默认均匀分布
                positions = [Vector2((i - (n-1)/2) * length/(n-1), 0) for i in range(n)]
        elif shape == 'bent':
            # V形，如H2O
            angle = math.radians(template.get('angle', 104.5))
            half_angle = angle / 2
            l = length
            # 中心原子在原点
            positions = [Vector2(0, 0)]  # 中心原子（通常是O）
            # 两个H在两侧
            positions.append(Vector2(l * math.sin(half_angle), -l * math.cos(half_angle)))
            positions.append(Vector2(-l * math.sin(half_angle), -l * math.cos(half_angle)))
            # 如果原子数不是3，则按需调整（这里仅支持3）
        elif shape == 'trigonal':
            # 三角锥（如NH3），N在原点，三个H在下方
            l = length
            angle_down = math.radians(109.5)  # 近似
            for i in range(3):
                theta = 2 * math.pi * i / 3
                x = l * math.sin(angle_down) * math.cos(theta)
                y = l * math.cos(angle_down)
                z = l * math.sin(angle_down) * math.sin(theta)  # 3D投影到2D简化
                # 这里简单采用平面三角形
                positions.append(Vector2(l * math.cos(theta), l * math.sin(theta)))
            # 将中心原子放在原点
            positions.insert(0, Vector2(0, 0))
        elif shape == 'tetrahedral':
            # 正四面体（CH4），C在原点，H在四个顶点
            # 使用2D投影（一个H在屏幕上方，三个在下方呈三角形）
            l = length
            # 上方H
            positions.append(Vector2(0, -l))
            # 下方三个H
            for i in range(3):
                theta = 2 * math.pi * i / 3
                x = l * 0.816 * math.cos(theta)  # sqrt(2/3) ~ 0.816
                y = l * 0.577  # 1/3
                positions.append(Vector2(x, y))
            positions.insert(0, Vector2(0, 0))
        else:
            # 默认随机散射
            for i in range(n):
                angle = 2 * math.pi * i / n
                r = length * 0.6
                positions.append(Vector2(r * math.cos(angle), r * math.sin(angle)))
        # 保证位置数量与原子数一致
        while len(positions) < n:
            positions.append(Vector2(0, 0))
        return positions[:n]

    def _apply_initial_velocity(self):
        """给分子整体一个速度"""
        for atom in self.atoms:
            atom.vel = self.vel

    def remove_from_world(self):
        """从物理世界中移除该分子"""
        for joint in self.bonds:
            if joint in self.world.joints:
                self.world.joints.remove(joint)
        for body in self.atoms:
            if body in self.world.bodies:
                self.world.bodies.remove(body)
        self._alive = False

    def get_center(self):
        """计算分子质心（平均位置）"""
        if not self.atoms:
            return Vector2(0, 0)
        x = sum(a.pos.x for a in self.atoms) / len(self.atoms)
        y = sum(a.pos.y for a in self.atoms) / len(self.atoms)
        return Vector2(x, y)

    def get_bond_energy(self):
        """计算该分子的总键能（根据当前键类型）"""
        total = 0.0
        for joint in self.bonds:
            a, b = joint.body_a, joint.body_b
            # 获取元素符号
            elem_a = getattr(a, 'element', '?')
            elem_b = getattr(b, 'element', '?')
            # 构造键名（按字母顺序）
            if elem_a > elem_b:
                elem_a, elem_b = elem_b, elem_a
            bond_key = f"{elem_a}-{elem_b}"
            energy = BOND_ENERGIES.get(bond_key, 0)
            total += energy
        return total

# -------------------- 化学模拟实验室窗口 --------------------
class ChemistryLabWindow(tk.Toplevel):
    def __init__(self, master):
        super().__init__(master)
        self.title("化学模拟实验室 - 基于物理引擎")
        self.geometry("1200x750")
        self.resizable(False, False)
        self.protocol("WM_DELETE_WINDOW", self.close)

        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/experiment.ico')
            self.iconphoto(True, icon_image)
        except:
            pass

        # 物理世界
        self.world = World(gravity=Vector2(0, 0), drag=0.01)  # 无重力，有轻微阻尼
        self.world.dt = 1/60.0
        self.running = True

        # 分子列表
        self.molecules = []

        # 画布
        canvas_frame = tk.Frame(self)
        canvas_frame.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        self.canvas = tk.Canvas(canvas_frame, width=900, height=700, bg='#1a1a2e', highlightthickness=0)
        self.canvas.pack(fill=tk.BOTH, expand=True)

        # 控制面板（右侧）
        control_frame = tk.Frame(self, width=280, bg='#2d2d44')
        control_frame.pack(side=tk.RIGHT, fill=tk.Y)
        control_frame.pack_propagate(False)

        # 标题
        tk.Label(control_frame, text="化学模拟实验室", font=('Unifont', 14), bg='#2d2d44', fg='white').pack(pady=10)

        # 分子选择
        mol_frame = tk.LabelFrame(control_frame, text="添加分子", bg='#2d2d44', fg='white', font=('Arial', 10))
        mol_frame.pack(fill=tk.X, padx=10, pady=5)

        tk.Label(mol_frame, text="分子类型:", font='Unifont', bg='#2d2d44', fg='white').pack(anchor=tk.W)
        self.mol_var = tk.StringVar(value='H2')
        mol_menu = ttk.Combobox(mol_frame, textvariable=self.mol_var, values=list(MOLECULE_TEMPLATES.keys()), state='readonly', width=15)
        mol_menu.pack(pady=2)

        tk.Label(mol_frame, text="数量:", font='Unifont', bg='#2d2d44', fg='white').pack(anchor=tk.W)
        self.count_var = tk.IntVar(value=1)
        tk.Spinbox(mol_frame, from_=1, to=10, textvariable=self.count_var, width=5).pack(pady=2)

        tk.Button(mol_frame, text="生成分子", font='Unifont', command=self.spawn_molecules, bg='#4CAF50', fg='white').pack(pady=5)

        # 反应控制
        react_frame = tk.LabelFrame(control_frame, text="反应控制", bg='#2d2d44', fg='white', font=('Unifont', 10))
        react_frame.pack(fill=tk.X, padx=10, pady=5)

        tk.Button(react_frame, text="触发反应（碰撞检测）", font='Unifont', command=self.force_reaction_check, bg='#FF9800', fg='white').pack(pady=5)
        tk.Button(react_frame, text="清空所有分子", font='Unifont', command=self.clear_molecules, bg='#f44336', fg='white').pack(pady=5)

        # 信息显示
        info_frame = tk.LabelFrame(control_frame, text="能量信息", bg='#2d2d44', fg='white', font=('Unifont', 10))
        info_frame.pack(fill=tk.X, padx=10, pady=5)

        self.info_text = tk.Text(info_frame, height=8, bg='#1a1a2e', fg='#00ffcc', font=('Unifont', 9), wrap=tk.WORD)
        self.info_text.pack(fill=tk.X, pady=5)

        # 控制按钮
        btn_frame = tk.Frame(control_frame, bg='#2d2d44')
        btn_frame.pack(fill=tk.X, padx=10, pady=10)
        self.pause_btn = tk.Button(btn_frame, text="⏸ 暂停", font='Unifont', command=self.toggle_pause, bg='#2196F3', fg='white')
        self.pause_btn.pack(side=tk.LEFT, padx=5)

        tk.Button(btn_frame, text="❌ 关闭", font='Unifont', command=self.close, bg='#9E9E9E', fg='white').pack(side=tk.RIGHT, padx=5)

        # 默认添加一些分子
        self.spawn_molecules_initial()

        # 启动动画
        self.animate()

    def spawn_molecules_initial(self):
        """启动时生成一些分子"""
        templates = ['H2', 'O2', 'N2', 'Cl2']
        for i, tmpl in enumerate(templates):
            for j in range(2):
                x = 150 + i * 150 + j * 40
                y = 200 + j * 80
                self._spawn_molecule(tmpl, Vector2(x, y), scale=0.8, vel=Vector2(random.uniform(-30,30), random.uniform(-30,30)))

    def spawn_molecules(self):
        """根据用户选择生成分子"""
        template = self.mol_var.get()
        count = self.count_var.get()
        for _ in range(count):
            x = random.randint(100, 800)
            y = random.randint(100, 600)
            vel = Vector2(random.uniform(-50, 50), random.uniform(-50, 50))
            self._spawn_molecule(template, Vector2(x, y), scale=0.8, vel=vel)

    def _spawn_molecule(self, template_name, pos, scale=0.8, vel=None):
        """内部生成分子"""
        mol = Molecule(self.world, template_name, pos, scale=scale, vel=vel)
        self.molecules.append(mol)
        return mol

    def clear_molecules(self):
        """移除所有分子"""
        for mol in self.molecules[:]:
            mol.remove_from_world()
        self.molecules.clear()
        self.update_info()

    def force_reaction_check(self):
        """手动触发反应检测"""
        self.check_and_perform_reactions()

    def toggle_pause(self):
        self.running = not self.running
        self.pause_btn.config(text="▶ 继续" if not self.running else "⏸ 暂停")

    def close(self):
        self.running = False
        self.destroy()

    def animate(self):
        """动画循环"""
        if self.running:
            # 执行物理步骤
            self.world.step(self.world.dt)

            # 检测反应
            self.check_and_perform_reactions()

            # 绘制
            self.draw()
            self.update_info()

        self.after(16, self.animate)  # ~60 FPS

    def check_and_perform_reactions(self):
        """遍历分子对，检查是否满足反应条件"""
        # 收集存活分子
        alive = [m for m in self.molecules if m._alive]
        n = len(alive)
        for i in range(n):
            for j in range(i+1, n):
                mol_a = alive[i]
                mol_b = alive[j]
                # 判断是否发生反应（基于规则）
                for rule in REACTION_RULES:
                    if rule['trigger'](mol_a, mol_b):
                        # 执行反应：删除反应物，生成产物
                        self.perform_reaction(mol_a, mol_b, rule)
                        # 一次碰撞仅触发一个反应，然后跳出循环
                        return

    def perform_reaction(self, mol_a, mol_b, rule):
        """执行反应，删除反应物，生成产物分子"""
        # 计算反应中心位置（取两分子质心平均）
        center = (mol_a.get_center() + mol_b.get_center()) * 0.5
        # 移除反应物
        mol_a.remove_from_world()
        mol_b.remove_from_world()
        # 从列表中移除
        if mol_a in self.molecules:
            self.molecules.remove(mol_a)
        if mol_b in self.molecules:
            self.molecules.remove(mol_b)

        # 根据化学计量比生成产物
        products = rule['products']
        stoich = rule['stoich']  # (coef_a, coef_b, coef_prod)
        # 确定生成数量（简化：固定生成 stoich[2] 个产物分子，但实际需要考虑系数）
        # 这里简单生成一个产物分子（系数为1），如果有多个产物类型，可扩展
        prod_template = products[0]  # 只取第一个产物
        # 生成产物分子（随机位置在中心附近）
        for _ in range(stoich[2]):  # 生成 stoich[2] 个产物分子
            offset = Vector2(random.uniform(-50,50), random.uniform(-50,50))
            pos = center + offset
            vel = Vector2(random.uniform(-20,20), random.uniform(-20,20))
            self._spawn_molecule(prod_template, pos, scale=0.8, vel=vel)

    def draw(self):
        """在画布上绘制物理世界"""
        self.canvas.delete("all")

        # 绘制原子
        for body in self.world.bodies:
            if isinstance(body.shape, Circle):
                r = body.shape.radius
                x, y = body.pos.x, body.pos.y
                color = body.color if hasattr(body, 'color') else '#AAAAAA'
                self.canvas.create_oval(x-r, y-r, x+r, y+r, fill=color, outline='white', width=1)
                # 显示元素符号
                elem = getattr(body, 'element', '')
                if elem:
                    self.canvas.create_text(x, y, text=elem, fill='black', font=('Arial', 8, 'bold'))

        # 绘制键（DistanceJoint）
        for joint in self.world.joints:
            if isinstance(joint, DistanceJoint):
                # 计算世界坐标下的锚点位置
                pa = joint.body_a.pos + rotate_vector(joint.anchor_a, joint.body_a.angle)
                pb = joint.body_b.pos + rotate_vector(joint.anchor_b, joint.body_b.angle)
                self.canvas.create_line(pa.x, pa.y, pb.x, pb.y, fill='#FFD700', width=2)

        # 绘制边界（指示模拟区域）
        self.canvas.create_rectangle(10, 10, 890, 690, outline='#444466', width=2, dash=(5,5))

    def update_info(self):
        """更新能量信息"""
        # 计算总键能
        total_energy = 0.0
        mol_count = 0
        for mol in self.molecules:
            if mol._alive:
                total_energy += mol.get_bond_energy()
                mol_count += 1

        info = f"分子总数: {mol_count}\n"
        info += f"总键能: {total_energy:.1f} kJ/mol\n"
        info += f"原子总数: {len(self.world.bodies)}\n"
        info += f"键总数: {len(self.world.joints)}\n"
        info += f"模拟状态: {'运行中' if self.running else '暂停'}"
        self.info_text.delete(1.0, tk.END)
        self.info_text.insert(tk.END, info)

class SnakeGame:
    def __init__(self, master):
        self.master = master
        self.master.title("贪吃蛇 - 32x32 黑白点阵")
        self.master.resizable(False, False)
        self.master.protocol("WM_DELETE_WINDOW", self.on_closing)

        self.GRID_SIZE = 32
        self.CELL_SIZE = 20
        self.WIDTH = self.GRID_SIZE * self.CELL_SIZE
        self.HEIGHT = self.GRID_SIZE * self.CELL_SIZE

        self.snake = []
        self.direction = (1, 0)
        self.next_direction = (1, 0)
        self.food = None
        self.score = 0
        self.game_over = False
        self.paused = False
        self.after_id = None

        self.create_widgets()
        self.init_game()
        self.bind_keys()
        self.start_game()

    def create_widgets(self):
        # 顶部信息栏
        info_frame = tk.Frame(self.master, bg='black')
        info_frame.pack(fill=tk.X)
        self.score_label = tk.Label(info_frame, text="得分: 0", fg='white', bg='black',
                                    font=FONT_NORMAL)
        self.score_label.pack(side=tk.LEFT, padx=10, pady=5)
        self.status_label = tk.Label(info_frame, text="游戏中", fg='lightgreen', bg='black',
                                     font=FONT_NORMAL)
        self.status_label.pack(side=tk.LEFT, padx=20, pady=5)

        btn_frame = tk.Frame(info_frame, bg='black')
        btn_frame.pack(side=tk.RIGHT, padx=10, pady=5)
        self.pause_btn = tk.Button(btn_frame, text="暂停", command=self.toggle_pause, font=FONT_SMALL)
        self.pause_btn.pack(side=tk.LEFT, padx=2)
        self.reset_btn = tk.Button(btn_frame, text="重置", command=self.reset_game, font=FONT_SMALL)
        self.reset_btn.pack(side=tk.LEFT, padx=2)

        self.canvas = tk.Canvas(self.master, width=self.WIDTH, height=self.HEIGHT,
                                bg='black', highlightthickness=0)
        self.canvas.pack()

        tip_label = tk.Label(self.master, text="方向键控制 | 空格暂停/继续 | R重置",
                             font=FONT_SMALL, fg='gray')
        tip_label.pack(pady=5)

    def init_game(self):
        center = self.GRID_SIZE // 2
        self.snake = [(center, center), (center-1, center), (center-2, center)]
        self.direction = (1, 0)
        self.next_direction = (1, 0)
        self.score = 0
        self.game_over = False
        self.paused = False
        self.update_score()
        self.status_label.config(text="游戏中", fg='lightgreen')
        self.pause_btn.config(text="暂停")
        self.generate_food()
        self.draw()

    def generate_food(self):
        import random
        while True:
            x = random.randint(0, self.GRID_SIZE-1)
            y = random.randint(0, self.GRID_SIZE-1)
            if (x, y) not in self.snake:
                self.food = (x, y)
                break

    def bind_keys(self):
        self.master.bind("<Up>", lambda e: self.change_direction(0, -1))
        self.master.bind("<Down>", lambda e: self.change_direction(0, 1))
        self.master.bind("<Left>", lambda e: self.change_direction(-1, 0))
        self.master.bind("<Right>", lambda e: self.change_direction(1, 0))
        self.master.bind("<space>", lambda e: self.toggle_pause())
        self.master.bind("r", lambda e: self.reset_game())
        self.master.bind("R", lambda e: self.reset_game())

    def change_direction(self, dx, dy):
        if self.game_over or self.paused:
            return
        if (dx, dy) != (-self.direction[0], -self.direction[1]):
            self.next_direction = (dx, dy)

    def move(self):
        if self.game_over or self.paused:
            return
        self.direction = self.next_direction
        head = self.snake[0]
        new_head = (head[0] + self.direction[0], head[1] + self.direction[1])

        if new_head == self.food:
            self.snake.insert(0, new_head)
            self.score += 1
            self.update_score()
            self.generate_food()
        else:
            self.snake.insert(0, new_head)
            self.snake.pop()
            if new_head in self.snake[1:]:
                self.end_game()
                return

        if (new_head[0] < 0 or new_head[0] >= self.GRID_SIZE or
            new_head[1] < 0 or new_head[1] >= self.GRID_SIZE):
            self.end_game()
            return

        self.draw()

    def draw(self):
        self.canvas.delete("all")
        # 蛇身白色
        for seg in self.snake:
            x1 = seg[0] * self.CELL_SIZE
            y1 = seg[1] * self.CELL_SIZE
            x2 = x1 + self.CELL_SIZE
            y2 = y1 + self.CELL_SIZE
            self.canvas.create_rectangle(x1, y1, x2, y2, fill='white', outline='gray')
        # 食物白色带黑边
        if self.food:
            fx = self.food[0] * self.CELL_SIZE
            fy = self.food[1] * self.CELL_SIZE
            self.canvas.create_rectangle(fx, fy, fx+self.CELL_SIZE, fy+self.CELL_SIZE,
                                         fill='white', outline='black', width=2)
        # 网格线
        for i in range(self.GRID_SIZE):
            self.canvas.create_line(i*self.CELL_SIZE, 0, i*self.CELL_SIZE, self.HEIGHT, fill='#333')
            self.canvas.create_line(0, i*self.CELL_SIZE, self.WIDTH, i*self.CELL_SIZE, fill='#333')

    def update_score(self):
        self.score_label.config(text=f"得分: {self.score}")

    def toggle_pause(self):
        if self.game_over:
            return
        self.paused = not self.paused
        if self.paused:
            self.status_label.config(text="暂停", fg='orange')
            self.pause_btn.config(text="继续")
            if self.after_id:
                self.master.after_cancel(self.after_id)
                self.after_id = None
        else:
            self.status_label.config(text="游戏中", fg='lightgreen')
            self.pause_btn.config(text="暂停")
            self.start_game()

    def reset_game(self):
        if self.after_id:
            self.master.after_cancel(self.after_id)
            self.after_id = None
        self.init_game()
        self.start_game()

    def end_game(self):
        self.game_over = True
        self.status_label.config(text="游戏结束", fg='red')
        self.pause_btn.config(state=tk.DISABLED)
        self.canvas.create_text(self.WIDTH//2, self.HEIGHT//2,
                                text=f"GAME OVER\n得分: {self.score}",
                                fill='red', font=FONT_TITLE, justify=tk.CENTER)

    def start_game(self):
        if not self.game_over and not self.paused:
            self.move()
            self.after_id = self.master.after(150, self.start_game)

    def on_closing(self):
        if self.after_id:
            self.master.after_cancel(self.after_id)
        self.master.destroy()


# ================== 俄罗斯方块（32x32 黑白点阵） ==================
class TetrisGame:
    def __init__(self, master):
        self.master = master
        self.master.title("俄罗斯方块 - 32x32 黑白点阵")
        self.master.resizable(False, False)
        self.master.protocol("WM_DELETE_WINDOW", self.on_closing)

        # 游戏区域 20x20 格子（占 32x32 中部，四周留边显示信息）
        self.BOARD_W = 20
        self.BOARD_H = 20
        self.CELL_SIZE = 16          # 每个格子16像素，20*16=320，居中显示
        self.OFFSET_X = (32 - self.BOARD_W) * self.CELL_SIZE // 2
        self.OFFSET_Y = (32 - self.BOARD_H) * self.CELL_SIZE // 2
        self.WIDTH = 32 * self.CELL_SIZE
        self.HEIGHT = 32 * self.CELL_SIZE

        # 经典形状 (相对坐标)
        self.SHAPES = [
            [(0,1),(1,0),(1,1),(2,1)],   # T
            [(0,1),(1,1),(2,0),(2,1)],   # L
            [(0,0),(1,0),(2,0),(2,1)],   # J
            [(1,0),(1,1),(2,1),(2,2)],   # Z
            [(0,1),(0,2),(1,0),(1,1)],   # S
            [(0,0),(0,1),(1,0),(1,1)],   # O
            [(0,0),(1,0),(2,0),(3,0)]    # I
        ]
        self.SHAPE_COLOR = 'white'       # 统一白色

        self.board = [[0]*self.BOARD_W for _ in range(self.BOARD_H)]
        self.current_piece = None
        self.current_shape_idx = 0
        self.current_x = self.BOARD_W//2 - 2
        self.current_y = 0
        self.score = 0
        self.lines_cleared = 0
        self.game_over = False
        self.paused = False
        self.fall_interval = 500
        self.after_id = None

        self.create_widgets()
        self.new_piece()
        self.bind_keys()
        self.start_game()

    def create_widgets(self):
        # 顶部信息栏（白色字体）
        info_frame = tk.Frame(self.master, bg='black')
        info_frame.pack(fill=tk.X)
        self.score_label = tk.Label(info_frame, text="得分: 0", fg='white', bg='black', font=FONT_NORMAL)
        self.score_label.pack(side=tk.LEFT, padx=10, pady=5)
        self.status_label = tk.Label(info_frame, text="游戏中", fg='lightgreen', bg='black', font=FONT_NORMAL)
        self.status_label.pack(side=tk.LEFT, padx=20, pady=5)

        btn_frame = tk.Frame(info_frame, bg='black')
        btn_frame.pack(side=tk.RIGHT, padx=10, pady=5)
        self.pause_btn = tk.Button(btn_frame, text="暂停", command=self.toggle_pause, font=FONT_SMALL)
        self.pause_btn.pack(side=tk.LEFT, padx=2)
        self.reset_btn = tk.Button(btn_frame, text="重置", command=self.reset_game, font=FONT_SMALL)
        self.reset_btn.pack(side=tk.LEFT, padx=2)

        self.canvas = tk.Canvas(self.master, width=self.WIDTH, height=self.HEIGHT,
                                bg='black', highlightthickness=0)
        self.canvas.pack()

        tip_label = tk.Label(self.master, text="← → 移动 | ↑ 旋转 | 空格硬到底 | P暂停 | R重置",
                             font=FONT_SMALL, fg='gray')
        tip_label.pack(pady=5)

    def new_piece(self):
        import random
        self.current_shape_idx = random.randint(0, len(self.SHAPES)-1)
        self.current_piece = [list(x) for x in self.SHAPES[self.current_shape_idx]]
        self.current_x = self.BOARD_W//2 - 2
        self.current_y = 0
        if self.collision():
            self.game_over = True
            self.status_label.config(text="游戏结束", fg='red')
            self.pause_btn.config(state=tk.DISABLED)
            if self.after_id:
                self.master.after_cancel(self.after_id)
            self.draw()
            self.canvas.create_text(self.WIDTH//2, self.HEIGHT//2,
                                    text="GAME OVER", fill='red', font=FONT_TITLE)

    def collision(self):
        for x, y in self.current_piece:
            board_x = self.current_x + x
            board_y = self.current_y + y
            if (board_x < 0 or board_x >= self.BOARD_W or
                board_y >= self.BOARD_H or
                (board_y >= 0 and self.board[board_y][board_x] != 0)):
                return True
        return False

    def rotate_piece(self):
        # 旋转 (x,y) -> (-y, x)
        rotated = [(-y, x) for x, y in self.current_piece]
        # 尝试踢墙
        old_piece = self.current_piece
        self.current_piece = rotated
        if self.collision():
            # 尝试向左/右微移
            for dx in [-1, 1, -2, 2]:
                self.current_x += dx
                if not self.collision():
                    self.draw()
                    return
                self.current_x -= dx
            # 还原
            self.current_piece = old_piece
        else:
            self.draw()

    def move(self, dx, dy):
        self.current_x += dx
        self.current_y += dy
        if self.collision():
            self.current_x -= dx
            self.current_y -= dy
            if dy == 1:  # 向下移动失败 -> 固定
                self.fix_piece()
                return False
            return False
        self.draw()
        return True

    def hard_drop(self):
        while self.move(0, 1):
            pass

    def fix_piece(self):
        for x, y in self.current_piece:
            board_x = self.current_x + x
            board_y = self.current_y + y
            if 0 <= board_y < self.BOARD_H and 0 <= board_x < self.BOARD_W:
                self.board[board_y][board_x] = 1
        self.clear_lines()
        self.new_piece()
        self.draw()

    def clear_lines(self):
        lines = 0
        for row in range(self.BOARD_H-1, -1, -1):
            if all(self.board[row][col] != 0 for col in range(self.BOARD_W)):
                del self.board[row]
                self.board.insert(0, [0]*self.BOARD_W)
                lines += 1
        if lines > 0:
            self.lines_cleared += lines
            self.score += [0, 100, 300, 600, 1000][lines] if lines <=4 else 1000
            self.update_score()
            # 下落速度随分数增加
            self.fall_interval = max(100, 500 - (self.score // 500)*30)

    def update_score(self):
        self.score_label.config(text=f"得分: {self.score}")

    def draw(self):
        self.canvas.delete("all")
        # 绘制已固定的方块
        for row in range(self.BOARD_H):
            for col in range(self.BOARD_W):
                if self.board[row][col]:
                    x1 = self.OFFSET_X + col * self.CELL_SIZE
                    y1 = self.OFFSET_Y + row * self.CELL_SIZE
                    x2 = x1 + self.CELL_SIZE
                    y2 = y1 + self.CELL_SIZE
                    self.canvas.create_rectangle(x1, y1, x2, y2, fill='white', outline='gray')
        # 绘制当前下落方块
        if self.current_piece:
            for x, y in self.current_piece:
                board_x = self.current_x + x
                board_y = self.current_y + y
                if board_y >= 0:
                    x1 = self.OFFSET_X + board_x * self.CELL_SIZE
                    y1 = self.OFFSET_Y + board_y * self.CELL_SIZE
                    x2 = x1 + self.CELL_SIZE
                    y2 = y1 + self.CELL_SIZE
                    self.canvas.create_rectangle(x1, y1, x2, y2, fill='white', outline='gray')
        # 绘制网格线（整个 32x32 区域）
        for i in range(33):
            line_x = i * self.CELL_SIZE
            line_y = i * self.CELL_SIZE
            self.canvas.create_line(line_x, 0, line_x, self.HEIGHT, fill='#333')
            self.canvas.create_line(0, line_y, self.WIDTH, line_y, fill='#333')

    def bind_keys(self):
        self.master.bind("<Left>", lambda e: self.move(-1, 0))
        self.master.bind("<Right>", lambda e: self.move(1, 0))
        self.master.bind("<Down>", lambda e: self.move(0, 1))
        self.master.bind("<Up>", lambda e: self.rotate_piece())
        self.master.bind("<space>", lambda e: self.hard_drop())
        self.master.bind("p", lambda e: self.toggle_pause())
        self.master.bind("P", lambda e: self.toggle_pause())
        self.master.bind("r", lambda e: self.reset_game())
        self.master.bind("R", lambda e: self.reset_game())

    def toggle_pause(self):
        if self.game_over:
            return
        self.paused = not self.paused
        if self.paused:
            self.status_label.config(text="暂停", fg='orange')
            self.pause_btn.config(text="继续")
            if self.after_id:
                self.master.after_cancel(self.after_id)
        else:
            self.status_label.config(text="游戏中", fg='lightgreen')
            self.pause_btn.config(text="暂停")
            self.start_game()

    def reset_game(self):
        if self.after_id:
            self.master.after_cancel(self.after_id)
        self.board = [[0]*self.BOARD_W for _ in range(self.BOARD_H)]
        self.score = 0
        self.lines_cleared = 0
        self.game_over = False
        self.paused = False
        self.fall_interval = 500
        self.update_score()
        self.new_piece()
        self.draw()
        self.start_game()

    def start_game(self):
        if not self.game_over and not self.paused:
            self.move(0, 1)
            self.after_id = self.master.after(self.fall_interval, self.start_game)

    def on_closing(self):
        if self.after_id:
            self.master.after_cancel(self.after_id)
        self.master.destroy()


# ================== 乒乓球（32x32 黑白点阵，双人对战） ==================
class PongGame:
    def __init__(self, master):
        self.master = master
        self.master.title("乒乓球 - 32x32 黑白点阵")
        self.master.resizable(False, False)
        self.master.protocol("WM_DELETE_WINDOW", self.on_closing)

        self.GRID_SIZE = 32
        self.CELL_SIZE = 20
        self.WIDTH = self.GRID_SIZE * self.CELL_SIZE
        self.HEIGHT = self.GRID_SIZE * self.CELL_SIZE

        # 乒乓球参数（在点阵中）
        self.BALL = [self.GRID_SIZE//2, self.GRID_SIZE//2]
        self.BALL_VEL = [1, 1]          # 每帧移动1格
        self.PADDLE_LEFT = self.GRID_SIZE//2
        self.PADDLE_RIGHT = self.GRID_SIZE//2
        self.PADDLE_HEIGHT = 3           # 球拍高度为3个点
        self.LEFT_SCORE = 0
        self.RIGHT_SCORE = 0
        self.game_over = False
        self.paused = False
        self.after_id = None

        self.create_widgets()
        self.bind_keys()
        self.start_game()

    def create_widgets(self):
        info_frame = tk.Frame(self.master, bg='black')
        info_frame.pack(fill=tk.X)
        self.score_label = tk.Label(info_frame, text="0 : 0", fg='white', bg='black', font=FONT_NORMAL)
        self.score_label.pack(side=tk.LEFT, padx=10, pady=5)
        self.status_label = tk.Label(info_frame, text="游戏中", fg='lightgreen', bg='black', font=FONT_NORMAL)
        self.status_label.pack(side=tk.LEFT, padx=20, pady=5)

        btn_frame = tk.Frame(info_frame, bg='black')
        btn_frame.pack(side=tk.RIGHT, padx=10, pady=5)
        self.pause_btn = tk.Button(btn_frame, text="暂停", command=self.toggle_pause, font=FONT_SMALL)
        self.pause_btn.pack(side=tk.LEFT, padx=2)
        self.reset_btn = tk.Button(btn_frame, text="重置", command=self.reset_game, font=FONT_SMALL)
        self.reset_btn.pack(side=tk.LEFT, padx=2)

        self.canvas = tk.Canvas(self.master, width=self.WIDTH, height=self.HEIGHT,
                                bg='black', highlightthickness=0)
        self.canvas.pack()

        tip_label = tk.Label(self.master, text="左拍: W/S | 右拍: ↑/↓ | 空格暂停 | R重置",
                             font=FONT_SMALL, fg='gray')
        tip_label.pack(pady=5)

    def bind_keys(self):
        self.master.bind("w", lambda e: self.move_paddle('left', -1))
        self.master.bind("s", lambda e: self.move_paddle('left', 1))
        self.master.bind("<Up>", lambda e: self.move_paddle('right', -1))
        self.master.bind("<Down>", lambda e: self.move_paddle('right', 1))
        self.master.bind("<space>", lambda e: self.toggle_pause())
        self.master.bind("r", lambda e: self.reset_game())
        self.master.bind("R", lambda e: self.reset_game())

    def move_paddle(self, side, delta):
        if self.paused or self.game_over:
            return
        if side == 'left':
            new = self.PADDLE_LEFT + delta
            if 0 <= new <= self.GRID_SIZE - self.PADDLE_HEIGHT:
                self.PADDLE_LEFT = new
        else:
            new = self.PADDLE_RIGHT + delta
            if 0 <= new <= self.GRID_SIZE - self.PADDLE_HEIGHT:
                self.PADDLE_RIGHT = new

    def update_physics(self):
        if self.paused or self.game_over:
            return

        # 移动球
        self.BALL[0] += self.BALL_VEL[0]
        self.BALL[1] += self.BALL_VEL[1]

        # 上下边界碰撞
        if self.BALL[1] <= 0 or self.BALL[1] >= self.GRID_SIZE-1:
            self.BALL_VEL[1] = -self.BALL_VEL[1]

        # 左拍碰撞（球在 x=2 列）
        if self.BALL[0] == 2 and self.PADDLE_LEFT <= self.BALL[1] <= self.PADDLE_LEFT+self.PADDLE_HEIGHT-1:
            self.BALL_VEL[0] = -self.BALL_VEL[0]
            # 根据碰撞偏移改变Y方向（增加趣味）
            hit_pos = (self.BALL[1] - self.PADDLE_LEFT) / self.PADDLE_HEIGHT
            self.BALL_VEL[1] = 1 if hit_pos > 0.5 else -1

        # 右拍碰撞（球在 x=29 列）
        if self.BALL[0] == self.GRID_SIZE-3 and self.PADDLE_RIGHT <= self.BALL[1] <= self.PADDLE_RIGHT+self.PADDLE_HEIGHT-1:
            self.BALL_VEL[0] = -self.BALL_VEL[0]
            hit_pos = (self.BALL[1] - self.PADDLE_RIGHT) / self.PADDLE_HEIGHT
            self.BALL_VEL[1] = 1 if hit_pos > 0.5 else -1

        # 得分判断（超出左边界或右边界）
        if self.BALL[0] < 0:
            self.RIGHT_SCORE += 1
            self.update_score()
            self.reset_ball()
        elif self.BALL[0] >= self.GRID_SIZE:
            self.LEFT_SCORE += 1
            self.update_score()
            self.reset_ball()

        self.draw()

    def reset_ball(self):
        self.BALL = [self.GRID_SIZE//2, self.GRID_SIZE//2]
        import random
        self.BALL_VEL = [1 if random.random()>0.5 else -1,
                         1 if random.random()>0.5 else -1]

    def update_score(self):
        self.score_label.config(text=f"{self.LEFT_SCORE} : {self.RIGHT_SCORE}")

    def draw(self):
        self.canvas.delete("all")
        # 绘制中央虚线（垂直）
        for i in range(0, self.GRID_SIZE, 2):
            self.canvas.create_rectangle(self.GRID_SIZE//2 * self.CELL_SIZE, i*self.CELL_SIZE,
                                         (self.GRID_SIZE//2+1)*self.CELL_SIZE, (i+1)*self.CELL_SIZE,
                                         fill='white')
        # 绘制左拍（垂直条）
        for i in range(self.PADDLE_HEIGHT):
            y = (self.PADDLE_LEFT + i) * self.CELL_SIZE
            self.canvas.create_rectangle(1*self.CELL_SIZE, y,
                                         2*self.CELL_SIZE, y+self.CELL_SIZE,
                                         fill='white')
        # 绘制右拍
        for i in range(self.PADDLE_HEIGHT):
            y = (self.PADDLE_RIGHT + i) * self.CELL_SIZE
            self.canvas.create_rectangle((self.GRID_SIZE-2)*self.CELL_SIZE, y,
                                         (self.GRID_SIZE-1)*self.CELL_SIZE, y+self.CELL_SIZE,
                                         fill='white')
        # 绘制球
        bx = self.BALL[0] * self.CELL_SIZE
        by = self.BALL[1] * self.CELL_SIZE
        self.canvas.create_rectangle(bx, by, bx+self.CELL_SIZE, by+self.CELL_SIZE, fill='white')
        # 绘制网格线
        for i in range(self.GRID_SIZE+1):
            line = i * self.CELL_SIZE
            self.canvas.create_line(line, 0, line, self.HEIGHT, fill='#333')
            self.canvas.create_line(0, line, self.WIDTH, line, fill='#333')

    def toggle_pause(self):
        if self.game_over:
            return
        self.paused = not self.paused
        if self.paused:
            self.status_label.config(text="暂停", fg='orange')
            self.pause_btn.config(text="继续")
            if self.after_id:
                self.master.after_cancel(self.after_id)
        else:
            self.status_label.config(text="游戏中", fg='lightgreen')
            self.pause_btn.config(text="暂停")
            self.start_game()

    def reset_game(self):
        if self.after_id:
            self.master.after_cancel(self.after_id)
        self.BALL = [self.GRID_SIZE//2, self.GRID_SIZE//2]
        self.BALL_VEL = [1, 1]
        self.PADDLE_LEFT = self.GRID_SIZE//2
        self.PADDLE_RIGHT = self.GRID_SIZE//2
        self.LEFT_SCORE = 0
        self.RIGHT_SCORE = 0
        self.game_over = False
        self.paused = False
        self.update_score()
        self.status_label.config(text="游戏中", fg='lightgreen')
        self.pause_btn.config(text="暂停")
        self.start_game()

    def start_game(self):
        if not self.game_over and not self.paused:
            self.update_physics()
            self.after_id = self.master.after(50, self.start_game)   # 约20FPS

    def on_closing(self):
        if self.after_id:
            self.master.after_cancel(self.after_id)
        self.master.destroy()

class NVLReader:
    """基于 ZIP 的 NVL 小说阅读器（固定左侧600x800封面，字体统一为 Unifont）"""
    def __init__(self, master):
        self.master = master
        master.title("NVL 小说阅读器")
        self.current_zip = None
        self.chapters = []
        self.chapter_index = -1
        self.book_info = {}

        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/note.ico')
            master.iconphoto(True, icon_image)
        except:
            #raise
            pass

        self.create_widgets()
        self.create_menu()

    def create_menu(self):
        menubar = tk.Menu(self.master)
        file_menu = tk.Menu(menubar, tearoff=0)
        file_menu.add_command(label="打开", command=self.open_file)
        file_menu.add_separator()
        file_menu.add_command(label="退出", command=self.master.quit)
        menubar.add_cascade(label="文件", menu=file_menu)
        self.master.config(menu=menubar)

    def create_widgets(self):
        # 顶部书籍信息区
        info_frame = tk.Frame(self.master)
        info_frame.pack(fill=tk.X, padx=10, pady=5)

        self.title_label = tk.Label(info_frame, text="未打开文件", font=("Unifont", 16))
        self.title_label.pack(anchor=tk.W)

        self.author_label = tk.Label(info_frame, text="", font=("Unifont", 10))
        self.author_label.pack(anchor=tk.W)

        self.subtitle_label = tk.Label(info_frame, text="", font=("Unifont", 10, "italic"))
        self.subtitle_label.pack(anchor=tk.W)

        self.desc_label = tk.Label(info_frame, text="", font=("Unifont", 9), wraplength=600, justify=tk.LEFT)
        self.desc_label.pack(anchor=tk.W, fill=tk.X)

        # 中间区域：左侧封面（600宽） + 右侧正文
        middle_frame = tk.Frame(self.master)
        middle_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)

        # 左侧封面区域，固定宽度600，高度由图片自然撑开
        left_frame = tk.Frame(middle_frame)
        left_frame.pack(side=tk.LEFT, padx=(0,10))
        self.cover_label = tk.Label(left_frame, bg="#f0f0f0", font=("Unifont", 10))
        self.cover_label.pack()

        # 右侧区域（章节选择 + 文本阅读）
        right_frame = tk.Frame(middle_frame)
        right_frame.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        chap_frame = tk.Frame(right_frame)
        chap_frame.pack(fill=tk.X, pady=(0,5))
        tk.Label(chap_frame, text="章节:", font=("Unifont", 10)).pack(side=tk.LEFT)
        self.chapter_var = tk.StringVar()
        self.chapter_combo = ttk.Combobox(chap_frame, textvariable=self.chapter_var,
                                          state="readonly", width=50)
        self.chapter_combo.pack(side=tk.LEFT, padx=5)
        self.chapter_combo.bind("<<ComboboxSelected>>", self.on_chapter_selected)

        # 文本区 + 滚动条
        text_frame = tk.Frame(right_frame)
        text_frame.pack(fill=tk.BOTH, expand=True)
        self.text_widget = tk.Text(text_frame, wrap=tk.WORD, font=("Unifont", 12))
        self.scrollbar = tk.Scrollbar(text_frame, command=self.text_widget.yview)
        self.text_widget.config(yscrollcommand=self.scrollbar.set)
        self.text_widget.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        self.scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

        # 底部翻页按钮
        bottom_frame = tk.Frame(self.master)
        bottom_frame.pack(fill=tk.X, padx=10, pady=5)
        self.prev_btn = tk.Button(bottom_frame, text="上一章", command=self.prev_chapter, state=tk.DISABLED,
                                  font=("Unifont", 10))
        self.prev_btn.pack(side=tk.LEFT, padx=5)
        self.next_btn = tk.Button(bottom_frame, text="下一章", command=self.next_chapter, state=tk.DISABLED,
                                  font=("Unifont", 10))
        self.next_btn.pack(side=tk.LEFT, padx=5)

    def open_file(self):
        filename = filedialog.askopenfilename(filetypes=[("NVL files", "*.nvl"), ("All files", "*.*")])
        if not filename:
            return
        if self.current_zip:
            self.current_zip.close()
        try:
            self.load_zip(filename)
        except Exception as e:
            messagebox.showerror("错误", f"无法打开文件：{e}")

    def load_zip(self, zip_path):
        self.current_zip = zipfile.ZipFile(zip_path, 'r')

        # 读取 data.json
        try:
            with self.current_zip.open('data.json') as f:
                data = json.load(f)
            self.book_info = data
        except KeyError:
            self.book_info = {"title": "未知标题", "author": "未知作者", "subtitle": "", "description": ""}
        except Exception as e:
            raise RuntimeError(f"解析 data.json 失败: {e}")

        self.title_label.config(text=self.book_info.get("title", "无标题"))
        self.author_label.config(text=f"作者：{self.book_info.get('author', '未知')}")
        self.subtitle_label.config(text=self.book_info.get("subtitle", ""))
        self.desc_label.config(text=f"简介：{self.book_info.get('description', '')}")
        self.master.title(f"NVL 阅读器 - {self.book_info.get('title', '未知')}")

        # 加载封面
        self.load_cover()

        # 加载章节列表
        namelist = self.current_zip.namelist()
        txt_files = [name for name in namelist if name.startswith('texts/') and name.endswith('.txt')]
        if not txt_files:
            raise RuntimeError("未找到任何章节文件（texts/*.txt）")

        def sort_key(fname):
            base = os.path.basename(fname)
            num_str = os.path.splitext(base)[0]
            try:
                return int(num_str)
            except ValueError:
                return 0
        txt_files.sort(key=sort_key)
        self.chapters = txt_files

        chapter_names = [os.path.splitext(os.path.basename(ch))[0] for ch in self.chapters]
        self.chapter_combo['values'] = chapter_names
        self.chapter_index = 0
        self.chapter_combo.current(0)
        self.load_chapter_content(self.chapters[0])
        self.update_buttons()

    def load_cover(self):
        """加载封面图，尺寸为600x800（原始尺寸）"""
        try:
            cover_data = self.current_zip.read('images/cover.gif')
            self.cover_img = tk.PhotoImage(data=cover_data)
            self.cover_label.config(image=self.cover_img, text='')
        except KeyError:
            # 无封面时显示默认文字，并设置一个占位尺寸
            self.cover_label.config(text="默认封面\n(无封面图)", font=("Unifont", 12), width=30, height=40)
        except Exception as e:
            self.cover_label.config(text=f"封面加载失败\n{e}", font=("Unifont", 10))

    def load_chapter_content(self, chapter_path):
        try:
            with self.current_zip.open(chapter_path) as f:
                content = f.read().decode('utf-8')
        except Exception as e:
            content = f"无法读取章节内容：{e}"
        self.text_widget.delete(1.0, tk.END)
        self.text_widget.insert(tk.END, content)
        self.text_widget.see(1.0)

    def on_chapter_selected(self, event=None):
        idx = self.chapter_combo.current()
        if 0 <= idx < len(self.chapters):
            self.chapter_index = idx
            self.load_chapter_content(self.chapters[idx])
            self.update_buttons()

    def prev_chapter(self):
        if self.chapter_index > 0:
            self.chapter_index -= 1
            self.chapter_combo.current(self.chapter_index)
            self.load_chapter_content(self.chapters[self.chapter_index])
            self.update_buttons()

    def next_chapter(self):
        if self.chapter_index < len(self.chapters) - 1:
            self.chapter_index += 1
            self.chapter_combo.current(self.chapter_index)
            self.load_chapter_content(self.chapters[self.chapter_index])
            self.update_buttons()

    def update_buttons(self):
        if self.chapter_index <= 0:
            self.prev_btn.config(state=tk.DISABLED)
        else:
            self.prev_btn.config(state=tk.NORMAL)

        if self.chapter_index >= len(self.chapters) - 1:
            self.next_btn.config(state=tk.DISABLED)
        else:
            self.next_btn.config(state=tk.NORMAL)

class Scoreboard:
    """计分板类"""
    
    def __init__(self):
        self.teams = []  # 存储队伍信息
        self.current_round = 1
        self.max_rounds = 10
        self.game_type = "标准"  # 标准、淘汰赛、循环赛
        
    def add_team(self, name, color="#FFA8A8"):
        """添加队伍"""
        team = {
            'name': name,
            'score': 0,
            'color': color,
            'wins': 0,
            'losses': 0,
            'draws': 0,
            'history': []  # 历史得分记录
        }
        self.teams.append(team)
        return len(self.teams) - 1  # 返回队伍索引
    
    def remove_team(self, index):
        """移除队伍"""
        if 0 <= index < len(self.teams):
            return self.teams.pop(index)
        return None
    
    def update_score(self, team_index, delta):
        """更新队伍分数"""
        if 0 <= team_index < len(self.teams):
            self.teams[team_index]['score'] += delta
            self.teams[team_index]['history'].append({
                'round': self.current_round,
                'delta': delta,
                'total': self.teams[team_index]['score']
            })
            return True
        return False
    
    def set_score(self, team_index, value):
        """设置队伍分数"""
        if 0 <= team_index < len(self.teams):
            old_score = self.teams[team_index]['score']
            delta = value - old_score
            self.teams[team_index]['score'] = value
            self.teams[team_index]['history'].append({
                'round': self.current_round,
                'delta': delta,
                'total': value
            })
            return True
        return False
    
    def record_match(self, team1_idx, team2_idx, result):
        """记录比赛结果
        result: 'win1', 'win2', 'draw'
        """
        if result == 'win1':
            self.teams[team1_idx]['wins'] += 1
            self.teams[team2_idx]['losses'] += 1
        elif result == 'win2':
            self.teams[team1_idx]['losses'] += 1
            self.teams[team2_idx]['wins'] += 1
        elif result == 'draw':
            self.teams[team1_idx]['draws'] += 1
            self.teams[team2_idx]['draws'] += 1
    
    def next_round(self):
        """进入下一轮"""
        self.current_round += 1
        return self.current_round
    
    def reset_scores(self):
        """重置所有分数"""
        for team in self.teams:
            team['score'] = 0
            team['wins'] = 0
            team['losses'] = 0
            team['draws'] = 0
            team['history'] = []
        self.current_round = 1
    
    def get_rankings(self):
        """获取排名"""
        # 按分数降序排序
        sorted_teams = sorted(enumerate(self.teams), 
                             key=lambda x: x[1]['score'], 
                             reverse=True)
        return sorted_teams
    
    def get_team_stats(self, team_index):
        """获取队伍统计信息"""
        if 0 <= team_index < len(self.teams):
            team = self.teams[team_index]
            total_matches = team['wins'] + team['losses'] + team['draws']
            win_rate = (team['wins'] / total_matches * 100) if total_matches > 0 else 0
            return {
                'total_matches': total_matches,
                'win_rate': win_rate,
                'avg_score': team['score'] / self.current_round if self.current_round > 0 else 0
            }
        return None

# ------------------ 无用的全局常量 ------------------
THE_ANSWER_TO_EVERYTHING = 42
PI_APPROXIMATION = 3.141592653589793
NOTHINGNESS = None
USELESS_LIST = [i for i in range(100) if i % 2 == 0 and i % 3 != 0]

# ------------------ 无用的装饰器 ------------------
def verbose_decorator(func):
    """一个只会打印废话的装饰器"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        print("[系统] 正在调用函数: {}".format(func.__name__))
        print("[系统] 参数检查中... 一切正常（尽管没什么好检查的）")
        result = func(*args, **kwargs)
        print("[系统] 函数执行完毕，结果已上传至虚空云")
        return result
    return wrapper

# ------------------ 无用的工具函数 ------------------
def heavy_computation(x):
    """执行一系列毫无意义的浮点运算"""
    y = x ** 2.71828
    for _ in range(10):
        y = (y + PI_APPROXIMATION) / 2.0
        y = y * 0.999999
    return y

def reverse_string_twice(s):
    """把字符串反转两次，等同于原字符串，但中间打印进度"""
    print("  反转第一阶段...")
    s1 = s[::-1]
    print("  反转第二阶段（撤销）...")
    s2 = s1[::-1]
    return s2

def generate_random_noise():
    """生成随机噪声字符串，但最终丢弃"""
    noise = ""
    for _ in range(5):
        noise += chr(random.randint(65, 90))
    return noise

# ------------------ 无用的类 ------------------
class QuantumOscillator:
    """模拟一个量子振荡器，但实际上只是改变内部数字"""
    def __init__(self, frequency=1.0):
        self.frequency = frequency
        self._state = 0.0

    def oscillate(self, steps=1):
        for _ in range(steps):
            self._state = (self._state + self.frequency) % THE_ANSWER_TO_EVERYTHING

    def read_state(self):
        return self._state

class RecursiveCounter:
    """递归计数器：用递归计算一个简单的结果，导致大量函数调用"""
    def __init__(self, limit=5):
        self.limit = limit

    def count(self, n=None):
        if n is None:
            n = self.limit
        if n <= 0:
            return 0
        else:
            return 1 + self.count(n - 1)

# ------------------ 主要“逻辑” ------------------
@verbose_decorator
def analyze_meaning(input_value):
    """分析输入值的宇宙意义（结果总是 42 的变体）"""
    temp = heavy_computation(input_value)
    temp = int(temp) % 100
    if temp in USELESS_LIST:
        meaning = THE_ANSWER_TO_EVERYTHING
    else:
        meaning = THE_ANSWER_TO_EVERYTHING - 1
    # 随机决定是否增加噪声
    if random.random() > 0.5:
        noise = generate_random_noise()
        meaning = meaning + len(noise) % 3
    return meaning

def fake_main():
    """伪主函数，执行一系列无意义的任务"""
    print("=" * 50)
    print("宇宙回响分析系统初始化...")
    print("正在加载无用的模块...")
    time.sleep(0.1)  # 假装在加载

    # 创建几个无用的对象
    osc = QuantumOscillator(frequency=0.618)
    counter = RecursiveCounter(limit=8)

    # 执行振荡（但不使用结果）
    osc.oscillate(steps=100)
    _ = osc.read_state()

    # 递归计数（也不使用结果）
    recursive_result = counter.count()
    print(f"[调试] 递归计数结果：{recursive_result} （完全没有用）")

    # 生成一个测试字符串
    test_str = "整活代码示例"
    reversed_twice = reverse_string_twice(test_str)
    print(f"[验证] 反转两次后的字符串：{reversed_twice} （果然没变）")

    # 分析几个随机数字的“意义”
    print("\n开始进行无意义的分析：")
    for i in range(5):
        dummy_input = random.randint(0, 100)
        meaning = analyze_meaning(dummy_input)
        print(f"  输入 {dummy_input:3d} 的宇宙意义 → {meaning} （其实都一样）")

    # 最后的无用循环
    accumulator = 0
    for j in range(10):
        accumulator += j
        accumulator %= THE_ANSWER_TO_EVERYTHING
    # 什么都不做，只是让累加器存在

    print("\n分析完成。系统即将关闭。")
    print("最终结论：这段代码没有任何实际作用。")
    print("=" * 50)

fake_main()

