def check_unifont_system():
    """检查系统字体目录中是否有Unifont"""
    
    system = platform.system()
    unifont_files = []
    
    # 定义Unifont可能的文件名
    possible_files = [
        "unifont.ttf",
        "unifont.otf",
        "Unifont.ttf",
        "Unifont.otf",
        "GNUUnifont.ttf",
        "unifont-*.ttf",
        "unifont-*.otf"
    ]
    
    # 根据操作系统确定字体目录
    if system == "Windows":
        font_dirs = [
            os.path.join(os.environ['WINDIR'], 'Fonts'),
            os.path.join(os.environ['LOCALAPPDATA'], 'Microsoft', 'Windows', 'Fonts')
        ]
    elif system == "Darwin":  # macOS
        font_dirs = [
            '/Library/Fonts',
            '/System/Library/Fonts',
            os.path.expanduser('~/Library/Fonts')
        ]
    else:  # Linux/Unix
        font_dirs = [
            '/usr/share/fonts',
            '/usr/local/share/fonts',
            os.path.expanduser('~/.fonts'),
            os.path.expanduser('~/.local/share/fonts')
        ]
    
    # 检查字体目录
    for font_dir in font_dirs:
        if os.path.exists(font_dir):
            try:
                for root, dirs, files in os.walk(font_dir):
                    for file in files:
                        if 'unifont' in file.lower():
                            full_path = os.path.join(root, file)
                            unifont_files.append(full_path)
            except (PermissionError, OSError):
                continue
    
    return unifont_files

def start_screensaver(self, event=None):
    """启动屏保"""
    print("启动屏保")
    ScreensaverWindow(self.root)

class ScreensaverWindow:
    """屏保窗口类"""
    
    def __init__(self, parent):
        self.parent = parent
        self.screensaver_window = None
        self.image_label = None
        self.animation_id = None
        self._bgm = None
        
        self.create_screensaver()
    
    def create_screensaver(self):
        """创建屏保窗口"""
        # 创建全屏无边框窗口
        self.screensaver_window = tk.Toplevel(self.parent)
        
        # 先设置全屏，再设置override-redirect
        self.screensaver_window.attributes('-fullscreen', True)  # 先设置全屏
        self.screensaver_window.overrideredirect(True)  # 再设置无边框
        self.screensaver_window.attributes('-topmost', True)  # 置顶
        self.screensaver_window.configure(bg='black')  # 黑色背景
        
        # 绑定退出事件
        self.screensaver_window.bind('<Any-KeyPress>', self.exit_screensaver)
        self.screensaver_window.bind('<Button-1>', self.exit_screensaver)  # 鼠标点击

        self._start_bgm()

        # 加载和显示图片
        self.load_screensaver_image()
        
        # 显示提示信息
        self.show_exit_hint()

    # ---------- 背景音乐 ----------
    def _start_bgm(self):
        """启动屏保背景音乐（循环，音量 30%）"""
        try:
            path = os.path.abspath("./res/sound/screen.wav")
            bgm = ScreensaverBGM()
            if bgm.open(path):
                bgm.set_volume(300)   # ← 音量，0~1000，改这里调大小
                bgm.play_loop()
                self._bgm = bgm
            else:
                self._bgm = None
        except Exception as e:
            print(f"[屏保] 背景音乐启动失败: {e}")
            self._bgm = None

    def _stop_bgm(self):
        """停止并释放背景音乐"""
        if self._bgm is not None:
            try:
                self._bgm.stop()
                self._bgm.close()
            except Exception as e:
                print(f"[屏保] 停止背景音乐失败: {e}")
            self._bgm = None
    
    def load_screensaver_image(self):
        """加载屏保图片"""
        try:
            image_path = "./res/images/unimportant/screen.gif"
            
            if os.path.exists(image_path):
                # 尝试加载GIF图片
                self.screensaver_image = tk.PhotoImage(file=image_path)
                
                # 获取屏幕尺寸
                screen_width = self.screensaver_window.winfo_screenwidth()
                screen_height = self.screensaver_window.winfo_screenheight()
                
                # 创建图片标签并居中显示
                self.image_label = tk.Label(self.screensaver_window, 
                                          image=self.screensaver_image, 
                                          bg='black')
                self.image_label.place(relx=0.5, rely=0.5, anchor=tk.CENTER)
                
            else:
                # 如果图片不存在，显示备用屏保
                self.show_fallback_display()
                
        except Exception as e:
            print(f"加载屏保图片失败: {e}")
            # 如果GIF加载失败，显示备用屏保
            self.show_fallback_display()
    
    def show_fallback_display(self):
        """显示备用屏保内容"""
        # 创建化学相关的屏保显示
        screen_width = self.screensaver_window.winfo_screenwidth()
        screen_height = self.screensaver_window.winfo_screenheight()
        
        # 创建画布
        canvas = tk.Canvas(self.screensaver_window, bg='black', 
                          highlightthickness=0)
        canvas.pack(fill=tk.BOTH, expand=True)
        
        # 显示化学元素周期表符号
        elements = ["H", "He", "Li", "Be", "B", "C", "N", "O", "F", "Ne",
                   "Na", "Mg", "Al", "Si", "P", "S", "Cl", "Ar"]
        
        # 在屏幕上随机显示元素符号
        import random
        for i in range(50):
            element = random.choice(elements)
            x = random.randint(50, screen_width - 50)
            y = random.randint(50, screen_height - 50)
            size = random.randint(20, 40)
            color = random.choice(['#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4', 
                                 '#FFEAA7', '#DDA0DD', '#98D8C8'])
            
            canvas.create_text(x, y, text=element, 
                             font=('Unifont', size),
                             fill=color)
        
        # 显示程序信息
        canvas.create_text(screen_width // 2, 50,
                         text="元素周期表屏保",
                         font=('Unifont', 24),
                         fill='white')
        
        # 显示提示文字
        canvas.create_text(screen_width // 2, screen_height - 50,
                         text="按下鼠标退出屏保\n字符画",
                         font=('Unifont', 16),
                         fill='white')
        
        # 显示版本信息
        canvas.create_text(screen_width // 2, screen_height - 100,
                         text="Version 1.4.0 Beta | © 2026 Sive-Nioo Studios",
                         font=('Unifont', 12),
                         fill='gray')
    
    def show_exit_hint(self):
        """显示退出提示"""
        screen_width = self.screensaver_window.winfo_screenwidth()
        screen_height = self.screensaver_window.winfo_screenheight()
        
        hint_label = tk.Label(self.screensaver_window,
                            text="按下鼠标退出屏保\n由创作者制作的艺术作品",
                            font=('Unifont', 16),
                            fg='white',
                            bg='black')
        hint_label.place(relx=0.5, rely=0.95, anchor=tk.CENTER)
    
    def exit_screensaver(self, event=None):
        """退出屏保"""
        self._stop_bgm()

        if self.animation_id:
            try:
                self.screensaver_window.after_cancel(self.animation_id)
            except Exception:
                pass

        if self.screensaver_window:
            try:
                self.screensaver_window.destroy()
            except Exception:
                pass

        print("退出屏保")

class LanChatServer:
    """局域网聊天服务器"""
    
    def __init__(self, user_manager, port=8888):
        self.user_manager = user_manager
        self.port = port
        self.server_socket = None
        self.clients = {}
        self.is_running = False
        self.messages = []
        self.host_username = None
        
    def start_server(self, username):
        """启动服务器"""
        try:
            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.server_socket.bind(('0.0.0.0', self.port))
            self.server_socket.listen(5)
            self.is_running = True
            self.host_username = username
            
            # 添加欢迎消息
            welcome_msg = {
                'type': 'system',
                'username': '系统',
                'message': f'讨论区已创建！主机: {username}',
                'timestamp': datetime.datetime.now().strftime('%H:%M:%S')
            }
            self.messages.append(welcome_msg)
            
            # 启动接受客户端线程
            accept_thread = threading.Thread(target=self.accept_clients)
            accept_thread.daemon = True
            accept_thread.start()
            
            return True, f"讨论区启动成功！端口: {self.port}"
            
        except Exception as e:
            return False, f"启动失败: {str(e)}"
    
    def accept_clients(self):
        """接受客户端连接"""
        while self.is_running:
            try:
                client_socket, address = self.server_socket.accept()
                client_thread = threading.Thread(target=self.handle_client, args=(client_socket, address))
                client_thread.daemon = True
                client_thread.start()
            except:
                break
    
    def handle_client(self, client_socket, address):
        """处理客户端连接"""
        username = None
        try:
            # 接收用户名
            data = client_socket.recv(1024).decode('utf-8')
            join_data = json.loads(data)
            username = join_data.get('username', '未知用户')
            
            # 发送历史消息
            history_msg = {
                'type': 'history',
                'messages': self.messages[-50:]  # 最近50条消息
            }
            client_socket.send(json.dumps(history_msg).encode('utf-8'))
            
            # 添加到客户端列表
            self.clients[username] = {
                'socket': client_socket,
                'address': address,
                'join_time': datetime.datetime.now()
            }
            
            # 广播用户加入消息
            join_msg = {
                'type': 'system',
                'username': '系统',
                'message': f'{username} 加入了讨论区',
                'timestamp': datetime.datetime.now().strftime('%H:%M:%S')
            }
            self.broadcast_message(join_msg)
            self.messages.append(join_msg)
            
            # 接收消息循环
            while self.is_running:
                data = client_socket.recv(1024).decode('utf-8')
                if not data:
                    break
                    
                message_data = json.loads(data)
                self.process_client_message(username, message_data)
                
        except Exception as e:
            print(f"客户端处理错误: {e}")
        finally:
            if username and username in self.clients:
                del self.clients[username]
                # 广播用户离开消息
                if self.is_running:
                    leave_msg = {
                        'type': 'system',
                        'username': '系统',
                        'message': f'{username} 离开了讨论区',
                        'timestamp': datetime.datetime.now().strftime('%H:%M:%S')
                    }
                    self.broadcast_message(leave_msg)
                    self.messages.append(leave_msg)
            
            client_socket.close()
    
    def process_client_message(self, username, message_data):
        """处理客户端消息"""
        if message_data['type'] == 'chat':
            chat_msg = {
                'type': 'chat',
                'username': username,
                'message': message_data['message'],
                'timestamp': datetime.datetime.now().strftime('%H:%M:%S')
            }
            self.messages.append(chat_msg)
            self.broadcast_message(chat_msg)
    
    def broadcast_message(self, message_data):
        """广播消息给所有客户端"""
        disconnected_clients = []
        for username, client_info in self.clients.items():
            try:
                client_info['socket'].send(json.dumps(message_data).encode('utf-8'))
            except:
                disconnected_clients.append(username)
        
        # 移除断开连接的客户端
        for username in disconnected_clients:
            if username in self.clients:
                del self.clients[username]
    
    def send_message(self, message):
        """主机发送消息"""
        if self.is_running:
            chat_msg = {
                'type': 'chat',
                'username': self.host_username,
                'message': message,
                'timestamp': datetime.datetime.now().strftime('%H:%M:%S')
            }
            self.messages.append(chat_msg)
            self.broadcast_message(chat_msg)
    
    def stop_server(self):
        """停止服务器"""
        self.is_running = False
        # 广播关闭消息
        if hasattr(self, 'clients'):
            shutdown_msg = {
                'type': 'system',
                'username': '系统',
                'message': '讨论区已关闭',
                'timestamp': datetime.datetime.now().strftime('%H:%M:%S')
            }
            self.broadcast_message(shutdown_msg)
            
            # 关闭所有客户端连接
            for client_info in self.clients.values():
                try:
                    client_info['socket'].close()
                except:
                    pass
        
        if self.server_socket:
            try:
                self.server_socket.close()
            except:
                pass

class LanChatClient:
    """局域网聊天客户端"""
    
    def __init__(self, user_manager, message_callback=None):
        self.user_manager = user_manager
        self.message_callback = message_callback
        self.client_socket = None
        self.is_connected = False
        self.receive_thread = None
        
    def connect_to_server(self, host, port=8888, username=None):
        """连接到服务器"""
        try:
            self.client_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.client_socket.connect((host, port))
            self.is_connected = True
            
            # 发送用户信息
            join_data = {
                'type': 'join',
                'username': username or self.user_manager.current_user or '匿名用户'
            }
            self.client_socket.send(json.dumps(join_data).encode('utf-8'))
            
            # 启动接收消息线程
            self.receive_thread = threading.Thread(target=self.receive_messages)
            self.receive_thread.daemon = True
            self.receive_thread.start()
            
            return True, "连接成功！"
            
        except Exception as e:
            return False, f"连接失败: {str(e)}"
    
    def receive_messages(self):
        """接收服务器消息"""
        while self.is_connected:
            try:
                data = self.client_socket.recv(1024).decode('utf-8')
                if not data:
                    break
                    
                message_data = json.loads(data)
                if self.message_callback:
                    self.message_callback(message_data)
                    
            except Exception as e:
                if self.is_connected:  # 只有在连接状态时才回调错误
                    error_msg = {
                        'type': 'error',
                        'message': f'连接断开: {str(e)}'
                    }
                    if self.message_callback:
                        self.message_callback(error_msg)
                break
        
        self.is_connected = False
    
    def send_message(self, message):
        """发送消息到服务器"""
        if self.is_connected and self.client_socket:
            try:
                message_data = {
                    'type': 'chat',
                    'message': message
                }
                self.client_socket.send(json.dumps(message_data).encode('utf-8'))
                return True
            except Exception as e:
                return False
        return False
    
    def disconnect(self):
        """断开连接"""
        self.is_connected = False
        if self.client_socket:
            try:
                self.client_socket.close()
            except:
                pass

class LanDiscussionWindow:
    """局域网讨论区窗口"""
    
    def __init__(self, parent, user_manager):
        self.parent = parent
        self.user_manager = user_manager
        self.server = LanChatServer(user_manager)
        self.client = LanChatClient(user_manager, self.on_message_received)
        self.is_host = False
        
        self.window = tk.Toplevel(parent)
        self.window.title("化学讨论区 - 局域网")
        self.window.geometry("800x670")
        self.center_window()
        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/chart.ico')
            self.window.iconphoto(True, icon_image)

        except:
            pass
        
        self.create_widgets()
        self.window.protocol("WM_DELETE_WINDOW", self.on_close)
    
    def center_window(self):
        self.window.update_idletasks()
        width = self.window.winfo_width()
