        msg_frame = tk.LabelFrame(main_frame, text=" 讨论内容 ", 
                                font=('Unifont', 11),
                                relief=tk.GROOVE, bd=2)
        msg_frame.pack(fill='both', expand=True, pady=(0, 15))
        
        self.message_text = tk.Text(msg_frame, wrap=tk.WORD,
                                  font=('Unifont', 10),
                                  bg='#F8F9FA')
