class FavoritesWindow:
    """收藏元素窗口"""
    
    def __init__(self, parent, user_manager, app):
        self.parent = parent
        self.user_manager = user_manager
        self.app = app
        
        self.window = tk.Toplevel(parent)
        self.window.title("我的收藏")
        self.window.geometry("500x400")
        self.window.resizable(True, True)
        
        self.center_window()
        self.create_widgets()
    
    def center_window(self):
        """窗口居中"""
        self.window.update_idletasks()
        width = self.window.winfo_width()
        height = self.window.winfo_height()
        x = (self.window.winfo_screenwidth() // 2) - (width // 2)
        y = (self.window.winfo_screenheight() // 2) - (height // 2)
        self.window.geometry(f'{width}x{height}+{x}+{y}')
    
    def create_widgets(self):
        """创建界面组件"""
        main_frame = tk.Frame(self.window)
        main_frame.pack(fill='both', expand=True, padx=20, pady=20)
        
        # 标题
        title_label = tk.Label(main_frame, text="我的收藏元素", 
                              font=('Unifont', 16))
        title_label.pack(pady=(0, 15))
        
        favorites = self.user_manager.get_favorites()
        
        if not favorites:
            # 没有收藏
            empty_label = tk.Label(main_frame, text="暂无收藏元素",
                                 font=('Unifont', 12),
                                 fg='gray')
            empty_label.pack(expand=True)
        else:
            # 创建滚动框架
            canvas = tk.Canvas(main_frame)
            scrollbar = tk.Scrollbar(main_frame, orient=tk.VERTICAL, command=canvas.yview)
            scrollable_frame = tk.Frame(canvas)
            
            scrollable_frame.bind(
                "<Configure>",
                lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
            )
            
            canvas.create_window((0, 0), window=scrollable_frame, anchor="nw")
            canvas.configure(yscrollcommand=scrollbar.set)
            
            canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
            scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
            
            # 显示收藏元素
            for i, symbol in enumerate(favorites):
                if symbol in self.app.elements:
                    element_data = self.app.elements[symbol]
                    self.create_favorite_item(scrollable_frame, symbol, element_data, i)
    
    def create_favorite_item(self, parent, symbol, element_data, index):
        """创建收藏元素项"""
        item_frame = tk.Frame(parent, relief=tk.RAISED, bd=1)
        item_frame.pack(fill=tk.X, padx=5, pady=2)
        
        # 元素信息
        info_text = f"{symbol} - {element_data['name']} (原子序数: {element_data['number']})"
        info_label = tk.Label(item_frame, text=info_text,
                            font=('Unifont', 10))
        info_label.pack(side=tk.LEFT, padx=5, pady=5)
        
        # 查看按钮
        view_btn = tk.Button(item_frame, text="查看",
                           command=lambda s=symbol: self.view_element(s),
                           font=('Unifont', 8))
        view_btn.pack(side=tk.RIGHT, padx=2)
        
        # 取消收藏按钮
        remove_btn = tk.Button(item_frame, text="取消收藏",
                             command=lambda s=symbol: self.remove_favorite(s),
                             font=('Unifont', 8))
        remove_btn.pack(side=tk.RIGHT, padx=2)
    
    def view_element(self, symbol):
        """查看元素详情"""
        # 模拟点击元素按钮
        if symbol in self.app.element_buttons:
            self.app.element_buttons[symbol].show_info()
    
    def remove_favorite(self, symbol):
        """取消收藏"""
        self.user_manager.remove_favorite(symbol)
        messagebox.showinfo("成功", f"已取消收藏 {symbol}")
        self.window.destroy()
        # 重新打开窗口刷新列表
        FavoritesWindow(self.parent, self.user_manager, self.app)

class PluginManager:
    """插件管理器

    支持多个插件目录：
    - ./plugins/          （相对路径，随程序走）
    - C:/pt/plugins/      （固定路径，用户可放自己的插件）
    """

    def __init__(self, app):
        self.app = app
        self.plugins = {}                # {plugin_name: 绝对路径}
        self.loaded_plugins = {}

        # 多目录支持：列表里每个目录都会被扫描
        self.plugins_dirs = [
            "./plugins",
            "C:/pt/plugins/",
        ]

        # 确保所有插件目录都存在
        for d in self.plugins_dirs:
            try:
                if not os.path.exists(d):
                    os.makedirs(d, exist_ok=True)
                    print(f"[PluginManager] 已创建插件目录: {d}")
            except Exception as e:
                print(f"[PluginManager] 创建插件目录 {d} 失败: {e}")

    # 兼容旧代码里可能引用到的 self.plugins_dir
    @property
    def plugins_dir(self):
        return self.plugins_dirs[0]

    def discover_plugins(self):
        """发现所有插件目录里的可用插件

        扫描顺序：先 ./plugins，后 C:/pt/plugins/
        同名插件后扫描到的会覆盖前面的（即 C:/pt/plugins/ 优先）。
        """
        self.plugins = {}

        for d in self.plugins_dirs:
            if not os.path.exists(d):
                continue

            try:
                for item in os.listdir(d):
                    full_path = os.path.join(d, item)

                    # 只识别 .py 文件，且不是私有/包文件
                    if (item.endswith('.py')
                            and not item.startswith('_')
                            and os.path.isfile(full_path)):

                        plugin_name = item[:-3]  # 去掉 .py

                        # 后扫描的目录覆盖先扫描的目录，实现优先级
                        self.plugins[plugin_name] = full_path
            except Exception as e:
                print(f"[PluginManager] 扫描目录 {d} 失败: {e}")

        return self.plugins
    
    def load_plugin(self, plugin_name):
        """加载插件"""
        if plugin_name not in self.plugins:
            return False, f"插件 {plugin_name} 不存在"
        
        try:
            # 动态导入插件
            spec = importlib.util.spec_from_file_location(plugin_name, self.plugins[plugin_name])
            plugin_module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(plugin_module)
            
            # 检查插件类
            plugin_class = None
            for name, obj in inspect.getmembers(plugin_module):
                if (inspect.isclass(obj) and 
                    hasattr(obj, 'is_plugin') and 
                    obj.is_plugin):
                    plugin_class = obj
                    break
            
            if not plugin_class:
                return False, f"插件 {plugin_name} 没有找到有效的插件类"
            
            # 实例化插件
            plugin_instance = plugin_class(self.app)
            self.loaded_plugins[plugin_name] = plugin_instance
            
            # 调用插件的初始化方法
            if hasattr(plugin_instance, 'initialize'):
                plugin_instance.initialize()
            
            return True, f"插件 {plugin_name} 加载成功"
            
        except Exception as e:
            return False, f"加载插件 {plugin_name} 失败: {str(e)}"
    
    def unload_plugin(self, plugin_name):
        """卸载插件"""
        if plugin_name in self.loaded_plugins:
            plugin_instance = self.loaded_plugins[plugin_name]
            
            # 调用插件的清理方法
            if hasattr(plugin_instance, 'cleanup'):
                plugin_instance.cleanup()
            
            del self.loaded_plugins[plugin_name]
            return True, f"插件 {plugin_name} 卸载成功"
        
        return False, f"插件 {plugin_name} 未加载"
    
    def get_plugin_info(self, plugin_name):
        """获取插件信息"""
        if plugin_name in self.loaded_plugins:
            plugin_instance = self.loaded_plugins[plugin_name]
            info = {
                'name': plugin_name,
                'loaded': True
            }
            
            # 获取插件元数据
            if hasattr(plugin_instance, 'get_metadata'):
                info.update(plugin_instance.get_metadata())
            else:
                info.update({
                    'description': '无描述',
                    'version': '1.0.0',
                    'author': '未知作者'
                })
            
            return info
        else:
            return {
                'name': plugin_name,
                'loaded': False,
                'description': '插件未加载',
                'version': '未知',
                'author': '未知'
            }
    
    def get_all_plugins_info(self):
        """获取所有插件信息"""
        plugins_info = {}
        
        # 已加载的插件
        for plugin_name in self.loaded_plugins:
            plugins_info[plugin_name] = self.get_plugin_info(plugin_name)
        
        # 未加载但可用的插件
        for plugin_name in self.plugins:
            if plugin_name not in self.loaded_plugins:
                plugins_info[plugin_name] = {
                    'name': plugin_name,
                    'loaded': False,
                    'description': '插件可用但未加载',
                    'version': '未知',
                    'author': '未知'
                }
        
        return plugins_info
    
    def call_plugin_method(self, plugin_name, method_name, *args, **kwargs):
        """调用插件方法"""
        if plugin_name in self.loaded_plugins:
            plugin_instance = self.loaded_plugins[plugin_name]
            if hasattr(plugin_instance, method_name):
                method = getattr(plugin_instance, method_name)
                return method(*args, **kwargs)
        
        return None

class ActivationSystem:
    """激活系统"""
    def __init__(self):
        self.correct_key = "B09E7-A6C9C-3F7D8-E4A2B-1C3D5-E6F7A-8B000"
        self.key_file = "C:/res/res/data/password.txt"
        self.activated = False
        
    def check_activation(self):
        """检查激活状态"""
        # 确保目录存在
        os.makedirs(os.path.dirname(self.key_file), exist_ok=True)
        
        # 检查密钥文件是否存在
        if os.path.exists(self.key_file):
            try:
                with open(self.key_file, 'r', encoding='utf-8') as f:
                    stored_key = f.read().strip()
                    if stored_key == self.correct_key:
                        self.activated = True
                        return True
            except:
                pass
        return False
    
    def save_key(self, key):
        """保存密钥到文件"""
        try:
            with open(self.key_file, 'w', encoding='utf-8') as f:
                f.write(key)
            return True
        except:
            return False
    
