    def change_theme(self):
        """切换深浅色模式，只改变背景色（以及标签文字颜色以便识别）"""
        theme = self.theme_var.get()
        if theme == "dark":
            bg = "#2b2b2b"      # 深灰色背景
            fg = "white"        # 标签文字颜色
        else:
            bg = "#f0f0f0"      # 浅灰色（与原默认背景协调）
            fg = "black"

        # 主框架背景
        self.main_frame.config(bg=bg)
        # 状态栏
        self.status_bar.config(bg=bg, fg=fg)

        # 递归修改 main_frame 下所有 Frame / LabelFrame / Label
        self._apply_theme_to_widgets(self.main_frame, bg, fg)

    def _apply_theme_to_widgets(self, widget, bg, fg):
        """递归修改 widget 及其子控件的背景和文字颜色"""
        # 处理当前控件
        if isinstance(widget, (tk.Frame, tk.LabelFrame)):
            widget.config(bg=bg)
        if isinstance(widget, (tk.Label, tk.LabelFrame)):
            widget.config(bg=bg, fg=fg)
        # 递归处理子控件
        for child in widget.winfo_children():
            self._apply_theme_to_widgets(child, bg, fg)

    def bind_shortcuts(self):
        """绑定全局快捷键"""
        # 使用更可靠的绑定方式
        self.root.bind_all('<Control-KeyPress-h>', self.open_help_file)
        self.root.bind_all('<Control-KeyPress-H>', self.open_help_file)
        
        self.root.bind_all('<Control-KeyPress-q>', self.quit_program)
        self.root.bind_all('<Control-KeyPress-Q>', self.quit_program)
        
