    def show_exit_dialog(self):
        """显示现代化无边框退出对话框（矩形设计）"""
        # 创建无边框对话框
        exit_window = tk.Toplevel(self.root)
        exit_window.overrideredirect(True)  # 无边框
        exit_window.attributes('-topmost', True)  # 置顶
        
        # 设置窗口大小和位置（居中）
        dialog_width = 500  # 恢复为500
        dialog_height = 400  # 恢复为400
        screen_width = exit_window.winfo_screenwidth()
        screen_height = exit_window.winfo_screenheight()
        x = (screen_width - dialog_width) // 2
        y = (screen_height - dialog_height) // 2
        exit_window.geometry(f"{dialog_width}x{dialog_height}+{x}+{y}")
        
        # 设置主背景色
        exit_window.configure(bg='#0A1A2F')
        
        # 创建窗口边框
        self.create_exit_border(exit_window)
        
        # 创建对话框内容
        self.create_exit_content(exit_window)
        
        # 绑定键盘事件
        self.bind_exit_events(exit_window)
        
        # 显示窗口
        exit_window.deiconify()
        
        # 让取消按钮获得焦点
        if hasattr(self, 'exit_cancel_button'):
            self.exit_cancel_button.focus_set()

