    def bind_exit_events(self, window):
        """绑定退出对话框事件"""
        # 绑定ESC键取消
        window.bind('<Escape>', lambda e: self.exit_cancel_button.invoke())
        
        # 绑定回车键退出
        window.bind('<Return>', lambda e: self.exit_cancel_button.master.winfo_children()[1].invoke())
        
        # 绑定点击窗口外部关闭
        def on_focus_out(e):
            if window.focus_get() is None:
                self.exit_cancel_button.invoke()
        
        window.bind('<FocusOut>', on_focus_out)

    def animate_exit_close(self, window, exit_program=False):
        """动画化关闭退出对话框"""
        # 收缩动画效果
        def shrink_animation():
            try:
                width = window.winfo_width()
                height = window.winfo_height()
                x = window.winfo_x()
                y = window.winfo_y()
                
                if width > 50:
                    # 计算新的尺寸和位置
                    new_width = max(50, width - 40)
                    new_height = max(30, height - 30)
                    new_x = x + (width - new_width) // 2
                    new_y = y + (height - new_height) // 2
                    
                    window.geometry(f"{new_width}x{new_height}+{new_x}+{new_y}")
                    window.after(20, shrink_animation)
                else:
                    window.destroy()
                    if exit_program:
                        # 完全退出程序
                        winsound.PlaySound('./res/sound/status/end.wav', winsound.SND_FILENAME)
                        
                        self.root.quit()
                        self.root.destroy()
            except tk.TclError:
                # 如果窗口已被销毁，直接退出
                if exit_program:
                    self.root.quit()
                    self.root.destroy()
        
        # 开始收缩动画
        shrink_animation()
        
    def quit_program(self, event=None):
        """Ctrl+Q: 退出程序"""
        """退出程序 - 显示美化退出界面"""
        print("快捷键 Ctrl+Q 被触发")
        self.show_exit_dialog()

