    def load_today_history(self, month, day):
        """加载今天的历史事件"""
        try:
            history_file = "./res/data/history_data.txt"
            
            if not os.path.exists(history_file):
                return []
            
            today_events = []
            with open(history_file, 'r', encoding='utf-8') as file:
                for line in file:
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue
                    
                    # 解析日期和事件，格式如："1月1日 1801年意大利天文学家皮亚齐发现第一颗小行星谷神星"
                    # 查找第一个空格的位置来分割日期和事件
                    space_index = line.find(' ')
                    if space_index > 0:
                        date_part = line[:space_index].strip()
                        event = line[space_index:].strip()
                        
                        # 检查是否匹配今天的日期
                        if self.is_date_match(date_part, month, day):
                            today_events.append(event)
            
            return today_events
            
        except Exception as e:
            messagebox.showerror("错误", f"加载历史数据失败: {str(e)}")
            return []

    def is_date_match(self, date_str, target_month, target_day):
        """检查日期字符串是否匹配目标月日"""
        try:
            # 格式："1月1日" 或 "01月01日"
            date_str = date_str.replace(' ', '')
            
            if '月' in date_str and '日' in date_str:
                # 提取月份和日期
                month_end = date_str.find('月')
                day_start = month_end + 1
                day_end = date_str.find('日')
                
                if month_end > 0 and day_end > day_start:
                    event_month = int(date_str[:month_end])
                    event_day = int(date_str[day_start:day_end])
                    return event_month == target_month and event_day == target_day
            
        except:
            pass
        
        return False

    def show_history_today(self):
        """显示历史上的今天 - 自动识别当前日期"""
        history_window = tk.Toplevel(self.root)
        history_window.title("历史上的今天")
        history_window.geometry("800x600")
        history_window.resizable(True, True)

        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/history.ico')
            history_window.iconphoto(True, icon_image)
        except:
            pass
        
        # 居中显示
        history_window.transient(self.root)
        history_window.grab_set()
        
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 400
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 300
        history_window.geometry(f"+{x}+{y}")
        
        # 创建主框架
        main_frame = tk.Frame(history_window)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=20, pady=20)
        
        # 标题
        title_label = tk.Label(main_frame, text="历史上的今天", 
                          font=('Unifont', 16))
        title_label.pack(pady=(0, 15))
        
        # 获取当前日期
        today = datetime.datetime.now()
        month = today.month
        day = today.day
        date_str = today.strftime("%Y年%m月%d日")
        
        date_label = tk.Label(main_frame, text=f"今天是：{date_str} ({month}月{day}日)", 
                         font=('Unifont', 12),
                         fg='blue')
        date_label.pack(pady=(0, 10))
        
        # 创建内容框架
        content_frame = tk.Frame(main_frame)
        content_frame.pack(fill=tk.BOTH, expand=True)
        
        # 创建文本框和滚动条
        text_frame = tk.Frame(content_frame)
        text_frame.pack(fill=tk.BOTH, expand=True)
        
        text_widget = tk.Text(text_frame, wrap=tk.WORD, font=('Unifont', 11))
        scrollbar = tk.Scrollbar(text_frame, orient=tk.VERTICAL, command=text_widget.yview)
        text_widget.configure(yscrollcommand=scrollbar.set)
        
        text_widget.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        # 加载并显示今天的历史事件
        today_events = self.load_today_history(month, day)
        
        if today_events:
            # 插入标题
            text_widget.insert(tk.END, f"{month}月{day}日 - 历史上的今天\n\n", 'title')
            text_widget.tag_configure('title', font=('Unifont', 14), 
                                 foreground='darkblue', justify=tk.CENTER)
            
            # 插入历史事件
            for i, event in enumerate(today_events, 1):
                text_widget.insert(tk.END, f"{i}. {event}\n\n")
            
            # 显示事件数量
            count_label = tk.Label(main_frame, text=f"共找到 {len(today_events)} 个历史事件", 
                              font=('Unifont', 10), fg='green')
            count_label.pack(pady=(5, 0))
        else:
            text_widget.insert(tk.END, f"暂未找到{month}月{day}日的化学史事件\n\n")
            text_widget.insert(tk.END, "历史上的今天数据文件可能还未包含今天日期的记录。")
        
        text_widget.config(state=tk.DISABLED)  # 设置为只读
    
        # 关闭按钮
        close_button = tk.Button(main_frame, text="关闭", 
                            command=history_window.destroy,
                            font=('Unifont', 10), width=10)
        close_button.pack(pady=10)

    def open_help(self, event=None):
        """打开帮助HTML文件"""
        help_file = "./res/help.html"
    
        if help_file:
            try:
                # 使用默认浏览器打开帮助文件
                webbrowser.open('file://' + os.path.abspath(help_file))
            except Exception as e:
                print("找不到帮助文件")

    def create_menu_bar(self):
        menubar = tk.Menu(self.root)
        self.root.config(menu=menubar)

        # ---------- 周年纪念菜单（仅在 9.19 - 9.23 出现） ----------
        if self.is_anniversary_period():
            anniversary_menu = tk.Menu(menubar, tearoff=0)
            menubar.add_cascade(label="🎂 周年", menu=anniversary_menu)
            anniversary_menu.add_command(
                label="回到最初 · v0.8.0 纪念版",
                command=self.launch_legacy_version
            )
            anniversary_menu.add_separator()
            anniversary_menu.add_command(
                label="关于纪念版",
                command=lambda: messagebox.showinfo(
                    "周年纪念版",
                    "{datetime.datetime.now().year - 2025}年前的今天，第一行代码被敲下。\n\n"
                    "这是 2025-09-21 发布的 v0.8.0 初版，\n"
                    "以字符串形式完整内嵌于主程序，逐字未改。\n\n"
                    f"感谢你陪它走过第{datetime.datetime.now().year - 2025}年 ❤️"
                )
            )
        
        # ---------- 始终显示的核心菜单 ----------
        core_menu = tk.Menu(menubar, tearoff=0)
        menubar.add_cascade(label="菜单", menu=core_menu)
        
        # 关于 -> 始终可用
        core_menu.add_command(label="关于", command=self.show_about)
        
        # 激活/已激活状态
        if not self.activated:
            core_menu.add_command(label="激活程序", command=self.activate_program)
        else:
            core_menu.add_command(label="✅ 已激活", state=tk.DISABLED)
        
        # 退出 -> 始终可用
        core_menu.add_separator()
        core_menu.add_command(label="退出", command=self.quit_program)
        
        # ---------- 扩展功能（仅激活后显示） ----------
        if self.activated:
            self._build_full_menus(menubar)

    def activate_program(self):
        """弹出激活窗口，成功后切换为完整版"""
        win = self.activation_system.show_activation_window(self.root)
        self.root.wait_window(win)
        if self.activation_system.activated:
            self.activated = True
            messagebox.showinfo("成功", "已激活，所有功能已解锁！")
            # 重建菜单（切换为完整版）
            self.root.config(menu="")          # 清空当前菜单
            self.create_menu_bar()             # 重新创建（此时 activated 为 True，会显示完整菜单）
            # 更新状态栏提示
            self.status_bar.config(text="已激活 - 所有功能可用")
        else:
            messagebox.showwarning("失败", "激活未成功，请重试。")

    def refresh_menu(self):
        self.root.config(menu="")
        self.create_menu_bar()

