    def is_anniversary_period(self):
        """判断当前是否在周年纪念期（每年 9 月 12 日 - 9 月 30 日）"""
        today = datetime.datetime.now()
        return today.month == 9 and 12 <= today.day <= 30

    def launch_legacy_version(self):
        """启动内嵌的 v1.0.0 纪念版

        与旧方案不同：不再用 subprocess 启动（打包后会变成重启 exe），
        而是把纪念版源码写到临时文件、用 importlib 作为模块导入，
        再用 Toplevel 承载纪念版界面，同进程运行，关闭后清理临时文件。
        """
        import importlib.util

        try:
            cache_dir = os.path.join(tempfile.gettempdir(), "PeriodicTable_Legacy")
            os.makedirs(cache_dir, exist_ok=True)

            # ---- 清理上一次可能残留的临时文件 ----
            try:
                for fname in os.listdir(cache_dir):
                    if fname.startswith("periodic_table_v1_") and fname.endswith(".py"):
                        try:
                            os.remove(os.path.join(cache_dir, fname))
                        except Exception:
                            pass
            except Exception:
                pass

            # ---- 1) 写临时文件 ----
            ts = int(time.time() * 1000)
            legacy_path = os.path.join(cache_dir, f"periodic_table_v1_{ts}.py")
            with open(legacy_path, "w", encoding="utf-8") as f:
                f.write(LEGACY_V1_SOURCE)

            # ---- 2) 作为模块导入 ----
            module_name = f"_legacy_v1_{ts}"
            spec = importlib.util.spec_from_file_location(module_name, legacy_path)
            module = importlib.util.module_from_spec(spec)
            sys.modules[module_name] = module
            spec.loader.exec_module(module)   # 此时 __name__ != "__main__"，所以不会自动 main()

            # ---- 3) 用 Toplevel 承载纪念版界面 ----
            legacy_root = tk.Toplevel(self.root)
            legacy_root.title("📦 元素周期表 v0.8.0（一周年纪念版）")
            try:
                legacy_root.transient(self.root)
            except Exception:
                pass

            # 位置：错开主窗口，不挡视线
            try:
                px = self.root.winfo_x() + 60
                py = self.root.winfo_y() + 60
                legacy_root.geometry(f"+{px}+{py}")
            except Exception:
                pass

            # 直接复用纪念版里的 PeriodicTableApp 类
            legacy_app = module.PeriodicTableApp(legacy_root)

            # 创建完 APP 后，把它自动设置的窗口标题恢复为"纪念版"
            try:
                legacy_root.title("📦 元素周期表 v0.8.0（一周年纪念版）")
            except Exception:
                pass

            # ---- 4) 关闭时清理 ----
            def _cleanup():
                # 关闭窗口
                try:
                    if legacy_root.winfo_exists():
                        legacy_root.destroy()
                except Exception:
                    pass
                # 从模块缓存移除
                try:
                    sys.modules.pop(module_name, None)
                except Exception:
                    pass
                # 删除临时文件
                try:
                    if os.path.exists(legacy_path):
                        os.remove(legacy_path)
                except Exception:
                    pass

            legacy_root.protocol("WM_DELETE_WINDOW", _cleanup)

            # 保存引用，避免被 gc 回收（也方便以后需要主动关闭）
            self._legacy_window = legacy_root
            self._legacy_cleanup = _cleanup

            # ---- 5) 音效 ----
            try:
                winsound.PlaySound('./res/sound/status/start.wav',
                                   winsound.SND_FILENAME | winsound.SND_ASYNC)
            except Exception:
                pass

        except Exception as e:
            import traceback
            traceback.print_exc()
            messagebox.showerror("启动纪念版失败", f"{e}")
