    def parse_discovery_year(self, year_str):
        """解析发现年份字符串

        支持格式: "古代" / "1774" / "1774年" / "公元前3000年" / "约1774年"
        返回: 年份整数（公元前为负数）；无法解析时返回 None
        """
        if not year_str or year_str == '未知':
            return None

        year_str = str(year_str).strip()

        # 处理"古代/史前/远古/上古"
        if any(k in year_str for k in ['古代', '史前', '远古', '上古']):
            return -3000

        cleaned = year_str.replace('年', '').replace('约', '').strip()

        # 处理"公元前"
        if '公元前' in cleaned or 'BC' in cleaned.upper():
            cleaned = cleaned.replace('公元前', '')
            cleaned = re.sub(r'[Bb][Cc]', '', cleaned).strip()
            nums = re.findall(r'\d+', cleaned)
            if nums:
                return -int(nums[0])

        # 普通年份
        nums = re.findall(r'\d+', cleaned)
        if nums:
            try:
                return int(nums[0])
            except ValueError:
                return None
        return None


    def on_discovery_year_change(self, value):
        """滑块年份改变时更新显示"""
        try:
            year = int(float(value))
        except (ValueError, TypeError):
            return
        self.update_discovery_display(year)


    def update_discovery_display(self, current_year):
        """根据当前年份更新周期表各元素的显示状态"""
        # 更新年份显示
        if current_year < 0:
            year_text = f"公元前 {abs(current_year)} 年"
        else:
            year_text = f"公元 {current_year} 年"
        self.discovery_year_var.set(year_text)

        # 类别颜色（与主周期表一致）
        category_colors = {
            "碱金属": "#FF8080",
            "碱土金属": "#FFA380",
            "过渡金属": "#FFC680",
            "后过渡金属": "#FFE680",
            "类金属": "#CCD980",
            "非金属": "#80CC80",
            "卤素": "#80B3CC",
            "稀有气体": "#8099CC",
            "镧系": "#B380CC",
            "锕系": "#CC80B3",
            "未知": "#D9D9D9"
        }

        discovered_count = 0
        undiscovered_count = 0
        unknown_count = 0

        for symbol, label in self.discovery_element_labels.items():
            element_data = self.elements.get(symbol)
            if not element_data:
                continue

            discovery_year = self.parse_discovery_year(element_data.get('discovery', ''))

            if discovery_year is None:
                # 数据未知，用中性灰
                label.config(bg='#E0E0E0', fg='#888888')
                unknown_count += 1
                continue

            if current_year >= discovery_year:
                # 已发现：类别颜色
                color = category_colors.get(element_data.get('category', ''), "#E0E0E0")
                label.config(bg=color, fg='black')
                discovered_count += 1
            else:
                # 未发现：暗淡灰色
                label.config(bg='#CCCCCC', fg='#999999')
                undiscovered_count += 1

        stats_text = f"已发现: {discovered_count} | 未发现: {undiscovered_count}"
        if unknown_count > 0:
            stats_text += f" | 数据未知: {unknown_count}"
        self.discovery_stats_var.set(stats_text)


    def toggle_discovery_play(self, btn, year_scale):
        """切换自动播放"""
        if self.discovery_playing:
            self.discovery_playing = False
            btn.config(text="▶ 播放", bg='#4CAF50')
        else:
            self.discovery_playing = True
            btn.config(text="⏸ 暂停", bg='#FF9800')
            self.auto_play_discovery(year_scale)


    def auto_play_discovery(self, year_scale):
        """自动播放动画：根据年代调整速度"""
        if not self.discovery_playing:
            return
        try:
            if not year_scale.winfo_exists():
                self.discovery_playing = False
                return

            current = year_scale.get()
            if current >= 2030:
                self.discovery_playing = False
                return

            # 古代跳得快，近代跳得慢
            if current < 0:
                step = 50       # 公元前
            elif current < 1600:
                step = 20       # 中世纪
            elif current < 1800:
                step = 5        # 18 世纪
            elif current < 1900:
                step = 2        # 19 世纪
            else:
                step = 1        # 20 世纪以后

            year_scale.set(current + step)
            # 20ms 一次，几十秒即可跑完整个化学史
            year_scale.after(40, lambda: self.auto_play_discovery(year_scale))
        except tk.TclError:
            self.discovery_playing = False


    def show_discovery_element_info(self, symbol):
        """点击元素时弹出发现信息"""
        if symbol not in self.elements:
            return
        e = self.elements[symbol]
        info = (
            f"元素: {symbol} - {e.get('name', '未知')}\n"
            f"原子序数: {e.get('number', '?')}\n"
            f"类别: {e.get('category', '未知')}\n"
            f"────────────────\n"
            f"发现年份: {e.get('discovery', '未知')}\n"
            f"发现者: {e.get('discoverer', '未知')}"
        )
        messagebox.showinfo(f"{symbol} - {e.get('name', '')}", info)


    def close_discovery_demo(self, window):
        """关闭发现演示窗口"""
        self.discovery_playing = False
        try:
            window.destroy()
        except:
            pass
        self.discovery_demo_window = None

