        def update_display(index):
            """更新右侧显示"""
            if index < 0 or index >= len(compounds):
                return

            comp = compounds[index]
            # 更新文字信息
            info_vars['chinese'].set(comp['chinese'])
            info_vars['pinyin'].set(comp['pinyin'])
            info_vars['english'].set(comp['english'])

            # 加载图片
            image_path = os.path.join("./res/images/molecules", comp['english'].lower() + ".gif")
            if not os.path.exists(image_path):
                # 尝试使用绝对路径（基于当前文件所在目录）
                base_dir = os.path.dirname(os.path.abspath(__file__))
                image_path = os.path.join(base_dir, "res/images/molecules", comp['english'].lower() + ".gif")

            try:
                if os.path.exists(image_path):
                    photo = tk.PhotoImage(file=image_path)
                    # 缩放图片以适应显示区域（可选）
                    # 这里直接显示原图，若需要缩放可调整
                    current_photo[0] = photo
                    image_label.config(image=photo, text="")
                    status_label.config(text=f"加载成功: {os.path.basename(image_path)}", fg='green')
                else:
                    # 图片不存在，显示占位符
                    image_label.config(image='', text=f"图片未找到\n{comp['english']}.gif", font=('Unifont', 14), fg='red')
                    status_label.config(text=f"图片文件不存在: {comp['english']}.gif", fg='red')
            except Exception as e:
                image_label.config(image='', text=f"加载失败\n{str(e)}", font=('Unifont', 12), fg='red')
                status_label.config(text=f"加载错误: {str(e)}", fg='red')

        # 绑定列表选择事件
        def on_select(event):
            selection = listbox.curselection()
            if selection:
                update_display(selection[0])

        listbox.bind('<<ListboxSelect>>', on_select)

        # 默认选择第一项
        if compounds:
            listbox.selection_set(0)
            listbox.see(0)
            update_display(0)

        # 关闭按钮
        tk.Button(win, text="关闭", command=win.destroy, font=('Unifont', 10), width=10).pack(pady=10)

