    def load_cross_politics_data(self, filename="./res/data/politics_data.json"):
        """从 JSON 文件加载政治跨学科数据（键为标题，值为内容）"""
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if isinstance(data, dict):
                return data
            else:
                return {}
        except FileNotFoundError:
            # 返回示例数据，方便测试
            return {
                "人民代表大会制度": "我国根本政治制度，保障人民当家作主。",
                "民主集中制": "民主基础上的集中和集中指导下的民主相结合。",
                "国体与政体": "国体决定政体，政体体现国体。我国国体是人民民主专政，政体是人民代表大会制度。",
            }
        except Exception as e:
            print(f"加载政治数据出错: {e}")
            return {}

