    def _build_calendar_tab(self, parent):
        """跨纪元换算（公元、干支、帝王年号、民国）及时间轴缩放"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入公元年份（如 2026）:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.cal_year = tk.Entry(main, width=15, font=('Unifont', 10))
        self.cal_year.pack(pady=5)
        self.cal_year.insert(0, "2026")

        tk.Button(main, text="换算", command=self._convert_year, font=('Unifont', 9)).pack(pady=5)

        self.cal_result = tk.Text(main, height=10, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
        self.cal_result.pack(fill=tk.BOTH, expand=True, pady=5)

        # 内置年号表（示例，仅部分）
        self._reign_years = {
            "唐": {"贞观": (627, 649), "开元": (713, 741)},
            "宋": {"太平兴国": (976, 984), "元祐": (1086, 1094)},
            "明": {"洪武": (1368, 1398), "永乐": (1403, 1424)},
            "清": {"康熙": (1662, 1722), "乾隆": (1736, 1795)},
        }
        # 干支表（简化）
        self._ganzhi = ["甲子", "乙丑", "丙寅", "丁卯", "戊辰", "己巳", "庚午", "辛未", "壬申", "癸酉",
                        "甲戌", "乙亥", "丙子", "丁丑", "戊寅", "己卯", "庚辰", "辛巳", "壬午", "癸未",
                        "甲申", "乙酉", "丙戌", "丁亥", "戊子", "己丑", "庚寅", "辛卯", "壬辰", "癸巳",
                        "甲午", "乙未", "丙申", "丁酉", "戊戌", "己亥", "庚子", "辛丑", "壬寅", "癸卯",
                        "甲辰", "乙巳", "丙午", "丁未", "戊申", "己酉", "庚戌", "辛亥", "壬子", "癸丑",
                        "甲寅", "乙卯", "丙辰", "丁巳", "戊午", "己未", "庚申", "辛酉", "壬戌", "癸亥"]

    def _convert_year(self):
        try:
            year = int(self.cal_year.get().strip())
        except:
            return
        self.cal_result.delete(1.0, tk.END)
        # 干支
        ganzhi = self._ganzhi[(year - 4) % 60]  # 公元4年为甲子
        self.cal_result.insert(tk.END, f"干支：{ganzhi}\n")
        # 民国纪年（1912年为民国元年）
        if year >= 1912:
            min_guo = year - 1911
            self.cal_result.insert(tk.END, f"民国：民国{min_guo}年\n")
        # 中国帝王年号（查找）
        found = False
        for dynasty, reigns in self._reign_years.items():
            for reign, (start, end) in reigns.items():
                if start <= year <= end:
                    self.cal_result.insert(tk.END, f"中国纪年：{dynasty} {reign} {year-start+1}年\n")
                    found = True
        if not found:
            self.cal_result.insert(tk.END, "未匹配到具体年号。\n")
        # 时间轴缩放模拟（用文字表示）
        self.cal_result.insert(tk.END, "\n时间轴缩放示意：\n")
        if year < 0:
            scale = "公元前"
        else:
            scale = "公元后"
        self.cal_result.insert(tk.END, f"{scale} {abs(year)} 年\n")
        self.cal_result.insert(tk.END, "（可缩放至分钟或世纪，此功能需加载更详细数据）\n")

    def _build_geography_tab(self, parent):
        """地名沿革追踪（显示古今地名对应）"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入古代地名（如 南京）:", font=('Unifont', 10)).pack(anchor=tk.W)
