        tk.Button(main, text="查询沿革", command=self._show_place_evolution, font=('Unifont', 9)).pack(pady=5)

        self.geo_result = tk.Text(main, height=15, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
        self.geo_result.pack(fill=tk.BOTH, expand=True, pady=5)

