    def _show_place_evolution(self):
        place = self.geo_input.get().strip()
        if place not in self._place_evolution:
            self.geo_result.delete(1.0, tk.END)
            self.geo_result.insert(tk.END, "未找到该地名的沿革数据。")
            return
        data = self._place_evolution[place]
        self.geo_result.delete(1.0, tk.END)
        self.geo_result.insert(tk.END, f"【{place}】的历代名称演变：\n")
        for name, dynasty, time in data:
            self.geo_result.insert(tk.END, f"{name}（{dynasty}，{time}）\n")
        # 叠加地图模拟（文字说明）
        self.geo_result.insert(tk.END, "\n（古地图叠加功能需加载GIS数据，此处仅示意）\n")

    def _build_history_graph_tab(self, parent):
        """历史人物关系动态图谱"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入人物（如 苏轼）:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.hist_graph_input = tk.Entry(main, width=30, font=('Unifont', 10))
        self.hist_graph_input.pack(pady=5)
        self.hist_graph_input.insert(0, "苏轼")

        tk.Button(main, text="绘制关系图", command=self._draw_historical_graph, font=('Unifont', 9)).pack(pady=5)

        self.hist_graph_canvas = tk.Canvas(main, bg='white', relief=tk.SUNKEN, bd=2)
        self.hist_graph_canvas.pack(fill=tk.BOTH, expand=True, pady=5)

        # 内置历史人物关系（示例）
        self._historical_graph = {
            "苏轼": {"师从": ["欧阳修"], "政敌": ["王安石"], "兄弟": ["苏辙"], "学生": ["黄庭坚", "秦观", "晁补之", "张耒"]},
            "欧阳修": {"学生": ["苏轼"], "政敌": ["王安石"]},
            "王安石": {"政敌": ["苏轼", "欧阳修"]},
        }

    def _draw_historical_graph(self):
        person = self.hist_graph_input.get().strip()
        if person not in self._historical_graph:
            self.hist_graph_canvas.delete("all")
            self.hist_graph_canvas.create_text(300, 150, text="未找到该人物", font=('Unifont', 14))
            return
        data = self._historical_graph[person]
        self.hist_graph_canvas.delete("all")
        center_x, center_y = 300, 150
        self.hist_graph_canvas.create_oval(center_x-30, center_y-20, center_x+30, center_y+20, fill='lightblue')
        self.hist_graph_canvas.create_text(center_x, center_y, text=person, font=('Unifont', 10))
        colors = ['red', 'green', 'blue', 'orange']
        y_offset = 50
        for idx, (rel, targets) in enumerate(data.items()):
            y = center_y + y_offset + idx*40
            self.hist_graph_canvas.create_text(center_x-80, y, text=rel+":", anchor=tk.E, font=('Unifont', 9))
            for j, target in enumerate(targets):
                tx = center_x + j*60 + 20
                self.hist_graph_canvas.create_line(center_x, center_y, tx, y, fill=colors[idx%len(colors)], width=2)
                self.hist_graph_canvas.create_oval(tx-15, y-10, tx+15, y+10, fill='lightyellow')
                self.hist_graph_canvas.create_text(tx, y, text=target, font=('Unifont', 8))

    def _build_causal_tab(self, parent):
        """事件因果链（鱼骨图/树状图模拟）"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入历史事件（如 安史之乱）:", font=('Unifont', 10)).pack(anchor=tk.W)
