    def show_cross_history(self):
        """重做：历史研究工具台（原功能变为“相关资料”选项卡）"""
        # 加载跨学科历史数据（如果有）
        data = self.load_cross_history_data()
        if not data:
            messagebox.showwarning("提示", "未找到跨学科历史数据，请检查文件。")

        # 创建主窗口
        win = tk.Toplevel(self.root)
        win.title("历史研究工具台")
        win.geometry("1100x800")
        win.resizable(True, True)
        win.transient(self.root)
        win.grab_set()
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 550
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 400
        win.geometry(f"+{x}+{y}")

        try:
            icon_image = tk.PhotoImage(file='./res/icon/func/subject.ico')
            win.iconphoto(True, icon_image)
        except:
            pass

        # 主 Notebook
        notebook = ttk.Notebook(win)
        notebook.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)

        # ----- 选项卡1：相关资料（原功能） -----
        tab_data = tk.Frame(notebook)
        notebook.add(tab_data, text="📚 相关资料")
        if data:
            left_frame = tk.Frame(tab_data, width=200)
            left_frame.pack(side=tk.LEFT, fill=tk.Y, padx=(0, 10))
            left_frame.pack_propagate(False)
            right_frame = tk.Frame(tab_data)
            right_frame.pack(side=tk.RIGHT, fill=tk.BOTH, expand=True)
            listbox = tk.Listbox(left_frame, font=('Unifont', 11), height=20)
            listbox.pack(fill=tk.BOTH, expand=True)
            titles = sorted(data.keys())
            for title in titles:
                listbox.insert(tk.END, title)
            if listbox.size() > 0:
                listbox.selection_set(0)
            text_widget = tk.Text(right_frame, wrap=tk.WORD, font=('Unifont', 11))
            scrollbar = tk.Scrollbar(right_frame, orient=tk.VERTICAL, command=text_widget.yview)
            text_widget.configure(yscrollcommand=scrollbar.set)
            text_widget.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
            scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

            def display_content(event=None):
                sel = listbox.curselection()
                if sel:
                    idx = sel[0]
                    title = listbox.get(idx)
                    content = data.get(title, "暂无内容")
                    text_widget.config(state=tk.NORMAL)
                    text_widget.delete(1.0, tk.END)
                    text_widget.insert(tk.END, f"【{title}】\n\n")
                    text_widget.insert(tk.END, content)
                    text_widget.config(state=tk.DISABLED)
            listbox.bind('<<ListboxSelect>>', display_content)
            display_content()
        else:
            tk.Label(tab_data, text="暂无历史相关资料", font=('Unifont', 14), fg='gray').place(relx=0.5, rely=0.5, anchor=tk.CENTER)

        # ----- 选项卡2：跨纪元换算与时间轴 -----
        tab_calendar = tk.Frame(notebook)
        notebook.add(tab_calendar, text="📅 纪元换算")
        self._build_calendar_tab(tab_calendar)

        # ----- 选项卡3：历史地理（地名沿革） -----
        tab_geo = tk.Frame(notebook)
        notebook.add(tab_geo, text="🗺️ 地名沿革")
        self._build_geography_tab(tab_geo)

        # ----- 选项卡4：人物关系图谱 -----
        tab_graph = tk.Frame(notebook)
        notebook.add(tab_graph, text="👥 人物关系")
        self._build_history_graph_tab(tab_graph)

        # ----- 选项卡5：事件因果链 -----
        tab_causal = tk.Frame(notebook)
        notebook.add(tab_causal, text="🔗 事件因果链")
        self._build_causal_tab(tab_causal)

        # ----- 选项卡6：同时代性对比 -----
        tab_sync = tk.Frame(notebook)
        notebook.add(tab_sync, text="🌍 同时代性对比")
        self._build_synchronicity_tab(tab_sync)

        # ----- 选项卡7：史料对勘与避讳字识别 -----
        tab_source = tk.Frame(notebook)
        notebook.add(tab_source, text="📜 史料考据")
        self._build_source_criticism_tab(tab_source)

        # ----- 选项卡8：史学观点切换 -----
        tab_historiography = tk.Frame(notebook)
        notebook.add(tab_historiography, text="📖 史学观点")
        self._build_historiography_tab(tab_historiography)

        # ----- 底部关闭按钮 -----
        close_btn = tk.Button(win, text="关闭", command=win.destroy,
                              font=('Unifont', 10), width=10)
        close_btn.pack(pady=10)

