        self.concept_input = tk.Entry(main, width=30, font=('Unifont', 10))
        self.concept_input.pack(pady=5)
        self.concept_input.insert(0, "商品")

        tk.Button(main, text="生成思维导图", command=self._show_concept_map, font=('Unifont', 9)).pack(pady=5)

