    def _build_answer_layers_tab(self, parent):
        """标准答案分层对照（原理层、材料层、结论层）"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入学生答案:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.answer_input = tk.Text(main, height=6, font=('Unifont', 10), wrap=tk.WORD)
        self.answer_input.pack(fill=tk.X, pady=5)
        self.answer_input.insert(tk.END, "我国是人民民主专政的国家，政府要依法行政，所以要加强监管，保护人民利益。")

        tk.Label(main, text="标准答案（分层）:", font=('Unifont', 9)).pack(anchor=tk.W)
        self.standard_input = tk.Text(main, height=6, font=('Unifont', 9), wrap=tk.WORD)
        self.standard_input.pack(fill=tk.X, pady=5)
        self.standard_input.insert(tk.END, "【原理层】我国是人民民主专政的社会主义国家，政府要坚持对人民负责。\n【材料层】当前监管领域存在漏洞。\n【结论层】政府应依法行政，加强监管，保障人民群众合法权益。")

        tk.Button(main, text="对照分析", command=self._compare_layers, font=('Unifont', 9)).pack(pady=5)

        self.layer_result = tk.Text(main, height=10, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
        self.layer_result.pack(fill=tk.BOTH, expand=True, pady=5)

    def _compare_layers(self):
        student = self.answer_input.get(1.0, tk.END).strip()
        standard = self.standard_input.get(1.0, tk.END).strip()
        if not student or not standard:
            return
        self.layer_result.delete(1.0, tk.END)
        # 简单匹配
        layers = {"原理层": [], "材料层": [], "结论层": []}
        for line in standard.split('\n'):
            for key in layers.keys():
                if key in line:
                    layers[key].append(line)
        matched = []
        for key, texts in layers.items():
            for t in texts:
                if any(word in student for word in t.split()):
                    matched.append(key)
                    break
        if matched:
            self.layer_result.insert(tk.END, f"匹配到的层级：{', '.join(matched)}\n")
        else:
            self.layer_result.insert(tk.END, "未匹配到任何层级。")
        missing = set(layers.keys()) - set(matched)
        if missing:
            self.layer_result.insert(tk.END, f"缺失层级：{', '.join(missing)}\n")

