    def _build_projection_tab(self, parent):
        """简单投影转换（经纬度转平面坐标，演示墨卡托投影）"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入经度 (度):", font=('Unifont', 10)).pack(anchor=tk.W)
        self.lon_entry = tk.Entry(main, width=15, font=('Unifont', 10))
        self.lon_entry.pack(pady=5)
        self.lon_entry.insert(0, "116.4")

        tk.Label(main, text="输入纬度 (度):", font=('Unifont', 10)).pack(anchor=tk.W)
        self.lat_entry = tk.Entry(main, width=15, font=('Unifont', 10))
        self.lat_entry.pack(pady=5)
        self.lat_entry.insert(0, "39.9")

        tk.Button(main, text="转换为平面坐标 (墨卡托)", command=self._convert_coords, font=('Unifont', 9)).pack(pady=5)

        self.proj_result = tk.Text(main, height=10, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
        self.proj_result.pack(fill=tk.BOTH, expand=True, pady=5)

    def _convert_coords(self):
        try:
            lon = float(self.lon_entry.get())
            lat = float(self.lat_entry.get())
        except:
            return
        # 墨卡托投影（简化，单位：弧度的正切）
        import math
        R = 6371000  # 地球半径（米）
        x = R * math.radians(lon)
        y = R * math.log(math.tan(math.pi/4 + math.radians(lat)/2))
        self.proj_result.delete(1.0, tk.END)
        self.proj_result.insert(tk.END, f"经纬度: ({lon:.2f}°, {lat:.2f}°)\n")
        self.proj_result.insert(tk.END, f"墨卡托平面坐标: x = {x:.2f} m, y = {y:.2f} m\n")
        self.proj_result.insert(tk.END, "\n注：此为演示投影，实际应用需考虑椭球体参数和投影分带。")

    def _build_profile_tab(self, parent):
        """根据高程数据绘制地形剖面"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入高程数据（用空格分隔，单位:米）:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.elevation_input = tk.Text(main, height=4, font=('Unifont', 10), wrap=tk.WORD)
        self.elevation_input.pack(fill=tk.X, pady=5)
        self.elevation_input.insert(tk.END, "50 120 180 300 450 520 480 350 200 80")

        tk.Button(main, text="绘制剖面", command=self._draw_profile, font=('Unifont', 9)).pack(pady=5)

        self.profile_canvas = tk.Canvas(main, bg='white', relief=tk.SUNKEN, bd=2)
        self.profile_canvas.pack(fill=tk.BOTH, expand=True, pady=5)

    def _draw_profile(self):
        data = self.elevation_input.get(1.0, tk.END).strip().split()
        if not data:
            return
        try:
            elems = [float(x) for x in data]
        except:
            return
        canvas = self.profile_canvas
        canvas.delete("all")
        w = canvas.winfo_width()
        h = canvas.winfo_height()
        if w <= 1 or h <= 1:
            canvas.after(100, self._draw_profile)
            return
        margin = 40
        plot_w = w - 2*margin
        plot_h = h - 2*margin
        max_e = max(elems)
        min_e = min(elems)
        if max_e == min_e:
            max_e += 1
        points = []
        for i, e in enumerate(elems):
            x = margin + (i / (len(elems)-1)) * plot_w if len(elems)>1 else margin+plot_w/2
            y = h - margin - ((e - min_e) / (max_e - min_e)) * plot_h
            points.append((x, y))
        # 绘制折线
        if len(points) > 1:
            for i in range(len(points)-1):
                canvas.create_line(points[i][0], points[i][1], points[i+1][0], points[i+1][1], fill='blue', width=2)
        # 填充下方（模拟面积）
        for i in range(len(points)-1):
            canvas.create_polygon(points[i][0], h-margin, points[i][0], points[i][1],
                                  points[i+1][0], points[i+1][1], points[i+1][0], h-margin,
                                  fill='lightblue', outline='')
        # 坐标轴标签
        canvas.create_text(margin-10, h-margin, text=f"{min_e:.0f}m", font=('Unifont', 8))
