    def _build_climate_tab(self, parent):
        """根据气温和降水数据查询气候类型"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入最热月均温 (°C):", font=('Unifont', 10)).pack(anchor=tk.W)
        self.temp_hot = tk.Entry(main, width=10, font=('Unifont', 10))
        self.temp_hot.pack(pady=5)
        self.temp_hot.insert(0, "28")

        tk.Label(main, text="输入最冷月均温 (°C):", font=('Unifont', 10)).pack(anchor=tk.W)
        self.temp_cold = tk.Entry(main, width=10, font=('Unifont', 10))
        self.temp_cold.pack(pady=5)
        self.temp_cold.insert(0, "5")

        tk.Label(main, text="输入年降水量 (mm):", font=('Unifont', 10)).pack(anchor=tk.W)
        self.precip = tk.Entry(main, width=10, font=('Unifont', 10))
        self.precip.pack(pady=5)
        self.precip.insert(0, "800")

        tk.Button(main, text="分类", command=self._classify_climate, font=('Unifont', 9)).pack(pady=5)

        self.climate_result = tk.Text(main, height=10, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
        self.climate_result.pack(fill=tk.BOTH, expand=True, pady=5)

    def _classify_climate(self):
        try:
            th = float(self.temp_hot.get())
            tc = float(self.temp_cold.get())
            p = float(self.precip.get())
        except:
            return
        self.climate_result.delete(1.0, tk.END)
        # 简化分类
        if th < 10:
            climate = "极地气候 (EF/ET)"
        elif tc > 18:
            climate = "热带气候 (A)"
            if p < 1000:
                climate += " - 热带干草原"
            else:
                climate += " - 热带雨林或季风"
        elif tc > 0:
            if th > 22 and p < 500:
                climate = "干旱气候 (B)"
            elif th > 22:
                climate = "温暖湿润 (C)"
            else:
                climate = "温带气候 (D)"
        else:
            climate = "寒带气候 (D或E)"
        self.climate_result.insert(tk.END, f"输入: 最热月 {th}°C, 最冷月 {tc}°C, 年降水 {p} mm\n")
        self.climate_result.insert(tk.END, f"推测气候类型: {climate}\n")
        self.climate_result.insert(tk.END, "\n（此为简化版，实际需考虑降水季节分布等因素）")

    def _build_population_tab(self, parent):
        """人口密度计算并显示简单柱状图"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入区域数据（区域名 人口 面积(km²)，每行一个）:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.pop_data = tk.Text(main, height=6, font=('Unifont', 10), wrap=tk.WORD)
        self.pop_data.pack(fill=tk.X, pady=5)
        self.pop_data.insert(tk.END, "北京 2189 16410\n上海 2487 6340\n广州 1868 7434")

        tk.Button(main, text="计算密度", command=self._show_pop_density, font=('Unifont', 9)).pack(pady=5)

        self.pop_result = tk.Text(main, height=8, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
        self.pop_result.pack(fill=tk.X, pady=5)

        self.pop_canvas = tk.Canvas(main, bg='white', relief=tk.SUNKEN, bd=2)
