    def _show_pop_density(self):
        data = self.pop_data.get(1.0, tk.END).strip().split('\n')
        if not data:
            return
        regions = []
        densities = []
        max_d = 0
        for line in data:
            parts = line.split()
            if len(parts) >= 3:
                name = parts[0]
                pop = float(parts[1])
                area = float(parts[2])
                if area > 0:
                    d = pop / area
                    densities.append(d)
                    regions.append(name)
                    if d > max_d:
                        max_d = d
        if not densities:
            return
        # 文本结果
        self.pop_result.delete(1.0, tk.END)
        for i, name in enumerate(regions):
            self.pop_result.insert(tk.END, f"{name}: {densities[i]:.2f} 人/km²\n")
        # 柱状图
        canvas = self.pop_canvas
        canvas.delete("all")
        w = canvas.winfo_width()
        h = canvas.winfo_height()
        if w <= 1 or h <= 1:
            canvas.after(100, self._show_pop_density)
            return
        margin = 50
        plot_w = w - 2*margin
        plot_h = h - 2*margin
        n = len(densities)
        bar_width = plot_w / n * 0.7
        for i, d in enumerate(densities):
            x = margin + i * (plot_w / n) + (plot_w / n - bar_width)/2
            height = (d / max_d) * plot_h if max_d > 0 else 0
            canvas.create_rectangle(x, h - margin - height, x + bar_width, h - margin, fill='skyblue', outline='black')
            canvas.create_text(x + bar_width/2, h - margin + 15, text=regions[i], font=('Unifont', 8))
        canvas.create_text(margin-10, h-margin, text="0", font=('Unifont', 8))
        canvas.create_text(margin-10, margin, text=f"{max_d:.1f}", font=('Unifont', 8))

    def _build_timezone_tab(self, parent):
        """时区与区时计算"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入城市或时区（如 UTC+8）:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.tz_input = tk.Entry(main, width=30, font=('Unifont', 10))
        self.tz_input.pack(pady=5)
        self.tz_input.insert(0, "UTC+8")

        tk.Label(main, text="输入日期时间 (可选, 格式 YYYY-MM-DD HH:MM):", font=('Unifont', 9)).pack(anchor=tk.W)
        self.tz_datetime = tk.Entry(main, width=30, font=('Unifont', 9))
        self.tz_datetime.pack(pady=5)
        self.tz_datetime.insert(0, "2026-07-26 14:30")

        tk.Button(main, text="计算区时", command=self._calc_timezone, font=('Unifont', 9)).pack(pady=5)

        self.tz_result = tk.Text(main, height=10, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
        self.tz_result.pack(fill=tk.BOTH, expand=True, pady=5)

    def _calc_timezone(self):
        tz_str = self.tz_input.get().strip().upper()
        try:
            if tz_str.startswith("UTC"):
                sign = 1 if '+' in tz_str else -1 if '-' in tz_str else 0
                if sign != 0:
                    offset = float(tz_str.split(tz_str[3])[1].replace(':', '.'))
                else:
                    offset = 0
            else:
                # 固定城市映射（示例）
                city_tz = {"北京": 8, "东京": 9, "伦敦": 0, "纽约": -5, "悉尼": 10}
                offset = city_tz.get(tz_str, 0)
        except:
            self.tz_result.delete(1.0, tk.END)
            self.tz_result.insert(tk.END, "时区格式错误，请使用如 UTC+8 或城市名。")
            return
        dt_str = self.tz_datetime.get().strip()
        if dt_str:
            try:
                import datetime
                dt = datetime.datetime.strptime(dt_str, "%Y-%m-%d %H:%M")
                # 计算UTC时间
                utc = dt - datetime.timedelta(hours=offset)
                self.tz_result.delete(1.0, tk.END)
                self.tz_result.insert(tk.END, f"本地时间: {dt_str} (UTC{offset:+g})\n")
                self.tz_result.insert(tk.END, f"UTC时间: {utc.strftime('%Y-%m-%d %H:%M')}\n")
                # 其他时区示例
                for city, off in [("纽约", -5), ("伦敦", 0), ("悉尼", 10)]:
                    if off != offset:
                        other = utc + datetime.timedelta(hours=off)
                        self.tz_result.insert(tk.END, f"{city} (UTC{off:+g}): {other.strftime('%Y-%m-%d %H:%M')}\n")
            except:
                self.tz_result.delete(1.0, tk.END)
                self.tz_result.insert(tk.END, "日期时间格式错误。")
        else:
            self.tz_result.delete(1.0, tk.END)
            self.tz_result.insert(tk.END, f"当前时区 UTC{offset:+g}")

    def _build_river_tab(self, parent):
        """模拟河流流域分析（简单数字高程模型）"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入DEM（数字高程，用空格分隔行，行用换行分隔）:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.dem_input = tk.Text(main, height=6, font=('Unifont', 10), wrap=tk.WORD)
        self.dem_input.pack(fill=tk.X, pady=5)
        self.dem_input.insert(tk.END, "20 19 18\n17 16 15\n14 13 12")

        tk.Button(main, text="分析流向", command=self._analyze_river, font=('Unifont', 9)).pack(pady=5)

        self.river_result = tk.Text(main, height=10, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
        self.river_result.pack(fill=tk.BOTH, expand=True, pady=5)

    def _analyze_river(self):
        data = self.dem_input.get(1.0, tk.END).strip()
        rows = [list(map(float, line.split())) for line in data.split('\n') if line.strip()]
        if not rows:
            return
        self.river_result.delete(1.0, tk.END)
        # 简单示例：找最低点作为汇水口
        flat = [val for row in rows for val in row]
        min_val = min(flat)
        self.river_result.insert(tk.END, f"最低点高程: {min_val}\n")
        # 模拟流向（每个格点流向相邻最低格点）
        self.river_result.insert(tk.END, "流向箭头（模拟）:\n")
        for i, row in enumerate(rows):
            line = []
            for j, val in enumerate(row):
                # 检查8邻域最低
                neighbors = []
                for di in (-1,0,1):
                    for dj in (-1,0,1):
                        if di==0 and dj==0: continue
                        ni, nj = i+di, j+dj
                        if 0 <= ni < len(rows) and 0 <= nj < len(row):
                            neighbors.append((rows[ni][nj], ni, nj))
                if neighbors:
                    min_nei = min(neighbors, key=lambda x: x[0])
                    if min_nei[0] < val:
                        # 方向指示（简化）
                        if min_nei[1] < i and min_nei[2] == j:
                            line.append("↑")
                        elif min_nei[1] > i and min_nei[2] == j:
                            line.append("↓")
                        elif min_nei[1] == i and min_nei[2] < j:
                            line.append("←")
                        elif min_nei[1] == i and min_nei[2] > j:
                            line.append("→")
                        else:
                            line.append("↗")
                    else:
                        line.append("•")
                else:
                    line.append("•")
            self.river_result.insert(tk.END, " ".join(line) + "\n")
        self.river_result.insert(tk.END, "\n（流向箭头指向相邻最低点，'•'表示局部低点）")

    def _build_region_compare_tab(self, parent):
        """区域对比（面积、人口、GDP等）"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入区域数据（区域名 人口 面积 GDP，用空格分隔，每行一个）:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.region_data = tk.Text(main, height=6, font=('Unifont', 10), wrap=tk.WORD)
        self.region_data.pack(fill=tk.X, pady=5)
        self.region_data.insert(tk.END, "北京 2189 16410 41610\n上海 2487 6340 47220\n广州 1868 7434 30300")

        tk.Label(main, text="选择对比指标:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.compare_indicator = tk.StringVar(value="人口")
        indicators = ["人口", "面积", "GDP"]
        for ind in indicators:
            tk.Radiobutton(main, text=ind, variable=self.compare_indicator, value=ind, font=('Unifont', 9)).pack(anchor=tk.W, padx=20)

        tk.Button(main, text="绘制对比", command=self._draw_region_compare, font=('Unifont', 9)).pack(pady=5)

        self.compare_canvas = tk.Canvas(main, bg='white', relief=tk.SUNKEN, bd=2)
        self.compare_canvas.pack(fill=tk.BOTH, expand=True, pady=5)

    def _draw_region_compare(self):
        data = self.region_data.get(1.0, tk.END).strip().split('\n')
        if not data:
            return
        regions = []
        values = []
        for line in data:
            parts = line.split()
            if len(parts) >= 4:
                name = parts[0]
                pop = float(parts[1])
                area = float(parts[2])
                gdp = float(parts[3])
                regions.append(name)
                ind = self.compare_indicator.get()
                if ind == "人口":
                    values.append(pop)
                elif ind == "面积":
                    values.append(area)
                else:
                    values.append(gdp)
        if not values:
            return
        canvas = self.compare_canvas
        canvas.delete("all")
        w = canvas.winfo_width()
        h = canvas.winfo_height()
        if w <= 1 or h <= 1:
            canvas.after(100, self._draw_region_compare)
            return
        margin = 50
        plot_w = w - 2*margin
        plot_h = h - 2*margin
        max_v = max(values) if values else 1
        n = len(values)
        bar_width = plot_w / n * 0.7
        for i, v in enumerate(values):
            x = margin + i * (plot_w / n) + (plot_w / n - bar_width)/2
            height = (v / max_v) * plot_h if max_v > 0 else 0
            canvas.create_rectangle(x, h - margin - height, x + bar_width, h - margin, fill='orange', outline='black')
            canvas.create_text(x + bar_width/2, h - margin + 15, text=regions[i], font=('Unifont', 8))
            canvas.create_text(x + bar_width/2, h - margin - height - 5, text=f"{v:.1f}", font=('Unifont', 8))
        canvas.create_text(margin-10, h-margin, text="0", font=('Unifont', 8))
        canvas.create_text(margin-10, margin, text=f"{max_v:.1f}", font=('Unifont', 8))
        canvas.create_text(w//2, 20, text=f"{self.compare_indicator.get()}对比", font=('Unifont', 10))

