    # ---------- 序列编辑与分析选项卡 ----------
    def _build_sequence_editor(self, parent):
        """构建序列编辑与分析界面"""
        main_frame = tk.Frame(parent)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        # 输入区
        tk.Label(main_frame, text="输入DNA序列（5'→3'，仅含ACGT）:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.seq_input = tk.Text(main_frame, height=8, font=('Unifont', 10), wrap=tk.WORD)
        self.seq_input.pack(fill=tk.X, pady=5)
        self.seq_input.insert(tk.END, "ATGCGTACGTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAG")

        # 按钮行
        btn_frame = tk.Frame(main_frame)
        btn_frame.pack(fill=tk.X, pady=5)
        tk.Button(btn_frame, text="反向互补", command=self._seq_reverse_complement, font=('Unifont', 9)).pack(side=tk.LEFT, padx=2)
        tk.Button(btn_frame, text="翻译为蛋白质", command=self._seq_translate, font=('Unifont', 9)).pack(side=tk.LEFT, padx=2)
        tk.Button(btn_frame, text="GC含量", command=self._seq_gc_content, font=('Unifont', 9)).pack(side=tk.LEFT, padx=2)
        tk.Button(btn_frame, text="清空", command=lambda: self.seq_input.delete(1.0, tk.END), font=('Unifont', 9)).pack(side=tk.LEFT, padx=2)

        # 结果显示
        tk.Label(main_frame, text="结果:", font=('Unifont', 10)).pack(anchor=tk.W, pady=(10,0))
        self.seq_result = tk.Text(main_frame, height=8, font=('Unifont', 10), wrap=tk.WORD, bg='#f0f0f0')
        self.seq_result.pack(fill=tk.BOTH, expand=True, pady=5)
        self.seq_result.config(state=tk.DISABLED)

    def _seq_reverse_complement(self):
        seq = self.seq_input.get(1.0, tk.END).strip().upper()
        if not seq:
            return
        comp = {'A':'T','T':'A','G':'C','C':'G'}
        rc = ''.join(comp.get(ch, 'N') for ch in reversed(seq))
        self._show_seq_result(f"反向互补序列:\n{rc}")

    def _seq_translate(self):
        seq = self.seq_input.get(1.0, tk.END).strip().upper()
        if not seq:
            return
        # 标准遗传密码表
        codon_table = {
            'ATA':'I', 'ATC':'I', 'ATT':'I', 'ATG':'M',
            'ACA':'T', 'ACC':'T', 'ACG':'T', 'ACT':'T',
            'AAC':'N', 'AAT':'N', 'AAA':'K', 'AAG':'K',
            'AGC':'S', 'AGT':'S', 'AGA':'R', 'AGG':'R',
            'CTA':'L', 'CTC':'L', 'CTG':'L', 'CTT':'L',
            'CCA':'P', 'CCC':'P', 'CCG':'P', 'CCT':'P',
            'CAC':'H', 'CAT':'H', 'CAA':'Q', 'CAG':'Q',
            'CGA':'R', 'CGC':'R', 'CGG':'R', 'CGT':'R',
            'GTA':'V', 'GTC':'V', 'GTG':'V', 'GTT':'V',
            'GCA':'A', 'GCC':'A', 'GCG':'A', 'GCT':'A',
            'GAC':'D', 'GAT':'D', 'GAA':'E', 'GAG':'E',
            'GGA':'G', 'GGC':'G', 'GGG':'G', 'GGT':'G',
            'TCA':'S', 'TCC':'S', 'TCG':'S', 'TCT':'S',
            'TTC':'F', 'TTT':'F', 'TTA':'L', 'TTG':'L',
            'TAC':'Y', 'TAT':'Y', 'TAA':'*', 'TAG':'*',
            'TGC':'C', 'TGT':'C', 'TGA':'*', 'TGG':'W',
        }
        protein = []
        for i in range(0, len(seq)-2, 3):
            codon = seq[i:i+3]
            protein.append(codon_table.get(codon, 'X'))
        self._show_seq_result(f"翻译结果（标准遗传密码）:\n{''.join(protein)}")

    def _seq_gc_content(self):
        seq = self.seq_input.get(1.0, tk.END).strip().upper()
        if not seq:
            return
        gc = (seq.count('G') + seq.count('C')) / len(seq) * 100
        self._show_seq_result(f"序列长度: {len(seq)} bp\nGC含量: {gc:.2f}%")

    def _show_seq_result(self, text):
        self.seq_result.config(state=tk.NORMAL)
        self.seq_result.delete(1.0, tk.END)
        self.seq_result.insert(tk.END, text)
        self.seq_result.config(state=tk.DISABLED)

    # ---------- 序列比对选项卡 ----------
    def _build_alignment_tab(self, parent):
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="序列1 (5'→3'):", font=('Unifont', 10)).pack(anchor=tk.W)
        self.align_seq1 = tk.Text(main, height=4, font=('Unifont', 10), wrap=tk.WORD)
        self.align_seq1.pack(fill=tk.X, pady=5)
        self.align_seq1.insert(tk.END, "ATGCGTACGTAGCTAGCTAGCTAGCTAGCTAG")

        tk.Label(main, text="序列2 (5'→3'):", font=('Unifont', 10)).pack(anchor=tk.W)
        self.align_seq2 = tk.Text(main, height=4, font=('Unifont', 10), wrap=tk.WORD)
        self.align_seq2.pack(fill=tk.X, pady=5)
        self.align_seq2.insert(tk.END, "ATGCGTACGTAGCTAGCTAGCTAGCTAGCTAG")

        btn_frame = tk.Frame(main)
        btn_frame.pack(pady=5)
        tk.Button(btn_frame, text="全局比对 (Needleman-Wunsch)", command=self._do_global_alignment, font=('Unifont', 9)).pack(side=tk.LEFT, padx=2)

        tk.Label(main, text="比对结果:", font=('Unifont', 10)).pack(anchor=tk.W, pady=(10,0))
        self.align_result = tk.Text(main, height=8, font=('Unifont', 10), wrap=tk.WORD, bg='#f0f0f0')
        self.align_result.pack(fill=tk.BOTH, expand=True, pady=5)
        self.align_result.config(state=tk.DISABLED)

    def _do_global_alignment(self):
        seq1 = self.align_seq1.get(1.0, tk.END).strip().upper().replace(' ', '')
        seq2 = self.align_seq2.get(1.0, tk.END).strip().upper().replace(' ', '')
        if not seq1 or not seq2:
            return
        # Needleman-Wunsch 算法 (简单实现)
        gap_penalty = -1
        match_score = 1
        mismatch_score = -1

        m, n = len(seq1), len(seq2)
        dp = [[0]*(n+1) for _ in range(m+1)]
        for i in range(m+1):
            dp[i][0] = i * gap_penalty
        for j in range(n+1):
            dp[0][j] = j * gap_penalty

        for i in range(1, m+1):
            for j in range(1, n+1):
                score = match_score if seq1[i-1] == seq2[j-1] else mismatch_score
                dp[i][j] = max(
                    dp[i-1][j-1] + score,
                    dp[i-1][j] + gap_penalty,
                    dp[i][j-1] + gap_penalty
                )

        # 回溯
        align1, align2 = [], []
        i, j = m, n
        while i > 0 or j > 0:
            if i > 0 and j > 0 and dp[i][j] == dp[i-1][j-1] + (match_score if seq1[i-1] == seq2[j-1] else mismatch_score):
                align1.append(seq1[i-1])
                align2.append(seq2[j-1])
                i -= 1; j -= 1
            elif i > 0 and dp[i][j] == dp[i-1][j] + gap_penalty:
                align1.append(seq1[i-1])
                align2.append('-')
                i -= 1
            else:
                align1.append('-')
                align2.append(seq2[j-1])
                j -= 1

        align1 = ''.join(reversed(align1))
        align2 = ''.join(reversed(align2))

        # 显示结果
        self.align_result.config(state=tk.NORMAL)
        self.align_result.delete(1.0, tk.END)
        self.align_result.insert(tk.END, f"比对得分: {dp[m][n]}\n\n")
        self.align_result.insert(tk.END, f"序列1: {align1}\n")
        self.align_result.insert(tk.END, f"序列2: {align2}\n")
        # 标注匹配
        match_line = ''
        for a, b in zip(align1, align2):
            if a == b and a != '-':
                match_line += '|'
            else:
                match_line += ' '
        self.align_result.insert(tk.END, f"        {match_line}\n")
        self.align_result.config(state=tk.DISABLED)

    # ---------- ORF查找选项卡 ----------
    def _build_orf_tab(self, parent):
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入DNA序列（5'→3'）:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.orf_seq = tk.Text(main, height=6, font=('Unifont', 10), wrap=tk.WORD)
        self.orf_seq.pack(fill=tk.X, pady=5)
        self.orf_seq.insert(tk.END, "ATGCGTACGTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAG")

        param_frame = tk.Frame(main)
        param_frame.pack(fill=tk.X, pady=5)
        tk.Label(param_frame, text="起始密码子（逗号分隔）:", font=('Unifont', 9)).pack(side=tk.LEFT)
        self.start_codons_var = tk.StringVar(value="ATG")
        tk.Entry(param_frame, textvariable=self.start_codons_var, width=15, font=('Unifont', 9)).pack(side=tk.LEFT, padx=5)
        tk.Label(param_frame, text="最小长度 (aa):", font=('Unifont', 9)).pack(side=tk.LEFT, padx=(10,0))
        self.min_length_var = tk.IntVar(value=10)
        tk.Spinbox(param_frame, from_=5, to=100, textvariable=self.min_length_var, width=5).pack(side=tk.LEFT, padx=5)

        tk.Button(main, text="查找ORF", command=self._find_orfs, font=('Unifont', 9)).pack(pady=5)

        tk.Label(main, text="ORF列表:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.orf_result = tk.Text(main, height=8, font=('Unifont', 10), wrap=tk.WORD, bg='#f0f0f0')
        self.orf_result.pack(fill=tk.BOTH, expand=True, pady=5)
        self.orf_result.config(state=tk.DISABLED)

    def _find_orfs(self):
        seq = self.orf_seq.get(1.0, tk.END).strip().upper().replace(' ', '')
        if not seq:
            return
        start_codons = [c.strip().upper() for c in self.start_codons_var.get().split(',') if c.strip()]
        min_len = self.min_length_var.get()
        orfs = []
        for i in range(len(seq)):
            for start in start_codons:
                if seq.startswith(start, i):
                    # 从 i 开始找终止密码子（TAA, TAG, TGA）
                    for j in range(i+3, len(seq)-2, 3):
                        codon = seq[j:j+3]
                        if codon in ('TAA', 'TAG', 'TGA'):
                            aa_len = (j - i)//3
                            if aa_len >= min_len:
                                orfs.append((i, j+3, aa_len, seq[i:j+3]))
                            break
                    break  # 只找第一个起始密码子
        self.orf_result.config(state=tk.NORMAL)
        self.orf_result.delete(1.0, tk.END)
        if orfs:
            self.orf_result.insert(tk.END, f"找到 {len(orfs)} 个ORF (最小长度 {min_len} aa)\n\n")
            for idx, (start, end, aa_len, orf_seq) in enumerate(orfs, 1):
                self.orf_result.insert(tk.END, f"ORF {idx}: {start+1}..{end} ({aa_len} aa)\n")
                self.orf_result.insert(tk.END, f"序列: {orf_seq}\n\n")
        else:
            self.orf_result.insert(tk.END, "未找到符合条件的ORF。")
        self.orf_result.config(state=tk.DISABLED)

    # ---------- 引物设计选项卡 ----------
    def _build_primer_tab(self, parent):
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入目标DNA序列（用于设计引物）:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.primer_seq = tk.Text(main, height=6, font=('Unifont', 10), wrap=tk.WORD)
        self.primer_seq.pack(fill=tk.X, pady=5)
        self.primer_seq.insert(tk.END, "ATGCGTACGTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAGCTAG")

        tk.Label(main, text="引物长度 (bp):", font=('Unifont', 9)).pack(anchor=tk.W)
        self.primer_len_var = tk.IntVar(value=20)
        tk.Spinbox(main, from_=15, to=30, textvariable=self.primer_len_var, width=5).pack(anchor=tk.W, pady=5)

        tk.Button(main, text="设计引物 (简单保守区域)", command=self._design_primers, font=('Unifont', 9)).pack(pady=5)

        tk.Label(main, text="引物结果:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.primer_result = tk.Text(main, height=8, font=('Unifont', 10), wrap=tk.WORD, bg='#f0f0f0')
        self.primer_result.pack(fill=tk.BOTH, expand=True, pady=5)
        self.primer_result.config(state=tk.DISABLED)

    def _design_primers(self):
        seq = self.primer_seq.get(1.0, tk.END).strip().upper().replace(' ', '')
        if len(seq) < 40:
            self._show_primer_result("序列太短，无法设计引物。")
            return
        length = self.primer_len_var.get()
        # 简单策略：取5'端和3'端保守区域
        forward = seq[:length]
        reverse = seq[-length:]
        # 反向互补
        comp = {'A':'T','T':'A','G':'C','C':'G'}
        reverse_rc = ''.join(comp.get(ch, 'N') for ch in reversed(reverse))
        # 检查GC含量
        def gc_percent(s):
            return (s.count('G') + s.count('C')) / len(s) * 100
        f_gc = gc_percent(forward)
        r_gc = gc_percent(reverse_rc)
        result = f"正向引物 (5'→3'): {forward} (GC: {f_gc:.1f}%)\n"
        result += f"反向引物 (5'→3'): {reverse_rc} (GC: {r_gc:.1f}%)\n"
        result += f"Tm估算 (简单): {self._tm_estimate(forward)} °C / {self._tm_estimate(reverse_rc)} °C\n"
        self._show_primer_result(result)

    def _tm_estimate(self, seq):
        # 简单 Tm 估算（Wallace法则）：2*(A+T) + 4*(G+C)
        at = seq.count('A') + seq.count('T')
        gc = seq.count('G') + seq.count('C')
        return 2*at + 4*gc

    def _show_primer_result(self, text):
        self.primer_result.config(state=tk.NORMAL)
        self.primer_result.delete(1.0, tk.END)
        self.primer_result.insert(tk.END, text)
        self.primer_result.config(state=tk.DISABLED)

    def load_cross_physics_data(self, filename="./res/data/physics_data.json"):
        """从 JSON 文件加载化学与物理跨学科数据"""
        try:
            import json
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if isinstance(data, dict):
                return data
            else:
                messagebox.showerror("错误", "JSON 数据格式应为字典")
                return {}
        except FileNotFoundError:
            messagebox.showerror("错误", f"找不到跨学科物理数据文件 {filename}")
            return {}
        except json.JSONDecodeError as e:
            messagebox.showerror("错误", f"JSON 解析错误: {e}")
            return {}
        except Exception as e:
            messagebox.showerror("错误", f"读取数据时出错: {e}")
            return {}

