    def _build_fdm_tab(self, parent):
        """构建1D热传导有限差分求解器"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        # 参数设置框架
        param_frame = tk.LabelFrame(main, text=" 参数设置 ", font=('Unifont', 10))
