    def _generate_mesh(self):
        try:
            L = self.mesh_L.get()
            N = self.mesh_N.get()
        except:
            return
        dx = L / N
        nodes = [i * dx for i in range(N+1)]
        self.mesh_result.delete(1.0, tk.END)
        self.mesh_result.insert(tk.END, f"节点数: {N+1}, 单元数: {N}\n")
        self.mesh_result.insert(tk.END, "节点坐标:\n")
        for i, x in enumerate(nodes):
            self.mesh_result.insert(tk.END, f"节点 {i}: x = {x:.4f}\n")
        self.mesh_result.insert(tk.END, f"\n边界条件:\n左边界: {self.mesh_bc_left.get()}\n右边界: {self.mesh_bc_right.get()}")

    def _build_cfl_tab(self, parent):
        """演示CFL条件与自适应时间步长"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        param_frame = tk.LabelFrame(main, text=" 参数 ", font=('Unifont', 10))
        param_frame.pack(fill=tk.X, pady=5)

        row = 0
        tk.Label(param_frame, text="扩散系数 α:", font=('Unifont', 9)).grid(row=row, column=0, sticky=tk.W, padx=5)
        self.cfl_alpha = tk.DoubleVar(value=0.01)
        tk.Entry(param_frame, textvariable=self.cfl_alpha, width=8).grid(row=row, column=1, padx=5)

        tk.Label(param_frame, text="空间步长 dx:", font=('Unifont', 9)).grid(row=row, column=2, sticky=tk.W, padx=5)
        self.cfl_dx = tk.DoubleVar(value=0.05)
        tk.Entry(param_frame, textvariable=self.cfl_dx, width=8).grid(row=row, column=3, padx=5)

        tk.Label(param_frame, text="CFL数 (r):", font=('Unifont', 9)).grid(row=row, column=4, sticky=tk.W, padx=5)
        self.cfl_r = tk.DoubleVar(value=0.4)
        tk.Entry(param_frame, textvariable=self.cfl_r, width=8).grid(row=row, column=5, padx=5)

        tk.Button(param_frame, text="计算稳定时间步长", command=self._compute_cfl, font=('Unifont', 9)).grid(row=row, column=6, padx=5)

        # 结果显示
        self.cfl_result = tk.Text(main, height=8, font=('Unifont', 10), wrap=tk.WORD, bg='#f0f0f0')
        self.cfl_result.pack(fill=tk.BOTH, expand=True, pady=10)

    def _compute_cfl(self):
        try:
            alpha = self.cfl_alpha.get()
            dx = self.cfl_dx.get()
            r = self.cfl_r.get()
        except:
            return
        dt_stable = r * dx * dx / alpha
        self.cfl_result.delete(1.0, tk.END)
        self.cfl_result.insert(tk.END, f"稳定时间步长 (显式欧拉) 计算:\n")
        self.cfl_result.insert(tk.END, f"α = {alpha}\n")
        self.cfl_result.insert(tk.END, f"dx = {dx}\n")
        self.cfl_result.insert(tk.END, f"CFL数 r = {r}\n")
        self.cfl_result.insert(tk.END, f"dt_max = {dt_stable:.6f} s\n")
        self.cfl_result.insert(tk.END, f"自适应策略: dt = min(dt_max, 用户设定值)\n")
        self.cfl_result.insert(tk.END, f"若 r > 0.5，模拟可能不稳定，建议降低 r 或减小 dx。")

    def load_cross_english_data(self, filename="./res/data/english_data.json"):
        """从 JSON 文件加载化学与英语跨学科数据"""
        try:
            import json
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if isinstance(data, dict):
                return data
            else:
                messagebox.showerror("错误", "JSON 数据格式应为字典")
                return {}
        except FileNotFoundError:
            messagebox.showerror("错误", f"找不到跨学科英语数据文件 {filename}")
            return {}
        except json.JSONDecodeError as e:
            messagebox.showerror("错误", f"JSON 解析错误: {e}")
            return {}
        except Exception as e:
            messagebox.showerror("错误", f"读取数据时出错: {e}")
            return {}

    def _build_inflection_tab(self, parent):
        """智能词形变化：动词时态、名词复数、比较级"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入单词:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.inflect_word = tk.Entry(main, width=30, font=('Unifont', 10))
        self.inflect_word.pack(pady=5)
        self.inflect_word.insert(0, "sing")

        tk.Label(main, text="词性 (verb/noun/adj):", font=('Unifont', 9)).pack(anchor=tk.W)
        self.inflect_pos = tk.Entry(main, width=15, font=('Unifont', 9))
        self.inflect_pos.pack(pady=5)
        self.inflect_pos.insert(0, "verb")

        tk.Button(main, text="生成词形", command=self._inflect_word, font=('Unifont', 9)).pack(pady=5)

        self.inflect_result = tk.Text(main, height=12, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
        self.inflect_result.pack(fill=tk.BOTH, expand=True, pady=5)

        # 内置不规则动词表（简化）
        self._irregular_verbs = {
            "sing": {"past": "sang", "pp": "sung", "ing": "singing", "s": "sings"},
            "go": {"past": "went", "pp": "gone", "ing": "going", "s": "goes"},
            "eat": {"past": "ate", "pp": "eaten", "ing": "eating", "s": "eats"},
            "write": {"past": "wrote", "pp": "written", "ing": "writing", "s": "writes"},
            "read": {"past": "read", "pp": "read", "ing": "reading", "s": "reads"},
            "take": {"past": "took", "pp": "taken", "ing": "taking", "s": "takes"},
        }
        # 名词复数不规则
        self._irregular_plurals = {
            "child": "children", "man": "men", "woman": "women", "foot": "feet",
            "tooth": "teeth", "mouse": "mice", "criterion": "criteria", "analysis": "analyses",
        }
        # 形容词比较级不规则
        self._irregular_comparative = {
            "good": {"comp": "better", "sup": "best"},
            "bad": {"comp": "worse", "sup": "worst"},
            "far": {"comp": "farther/further", "sup": "farthest/furthest"},
        }

    def _inflect_word(self):
        word = self.inflect_word.get().strip().lower()
        pos = self.inflect_pos.get().strip().lower()
        if not word:
            return
        self.inflect_result.delete(1.0, tk.END)
        if pos == "verb":
            if word in self._irregular_verbs:
                data = self._irregular_verbs[word]
                self.inflect_result.insert(tk.END, f"动词 {word} 的词形变化:\n")
                self.inflect_result.insert(tk.END, f"第三人称单数: {data['s']}\n")
                self.inflect_result.insert(tk.END, f"过去式: {data['past']}\n")
                self.inflect_result.insert(tk.END, f"过去分词: {data['pp']}\n")
                self.inflect_result.insert(tk.END, f"现在分词: {data['ing']}\n")
            else:
                # 规则变化
                self.inflect_result.insert(tk.END, f"规则动词 {word} 的词形:\n")
                self.inflect_result.insert(tk.END, f"第三人称单数: {word + ('es' if word.endswith(('s','sh','ch','x','z')) else 's')}\n")
                self.inflect_result.insert(tk.END, f"过去式: {word + ('ed' if not word.endswith('e') else 'd')}\n")
                self.inflect_result.insert(tk.END, f"过去分词: {word + ('ed' if not word.endswith('e') else 'd')}\n")
                self.inflect_result.insert(tk.END, f"现在分词: {word + ('ing' if not word.endswith('e') else word[:-1]+'ing')}\n")
        elif pos == "noun":
            if word in self._irregular_plurals:
                self.inflect_result.insert(tk.END, f"名词 {word} 的复数: {self._irregular_plurals[word]}\n")
            else:
                # 规则
                if word.endswith(('s','x','z','sh','ch')):
                    plural = word + "es"
                elif word.endswith('y') and len(word)>1 and word[-2] not in 'aeiou':
                    plural = word[:-1] + "ies"
                else:
                    plural = word + "s"
                self.inflect_result.insert(tk.END, f"名词 {word} 的复数: {plural}\n")
        elif pos == "adj":
            if word in self._irregular_comparative:
                data = self._irregular_comparative[word]
                self.inflect_result.insert(tk.END, f"形容词 {word} 的比较级: {data['comp']}\n")
                self.inflect_result.insert(tk.END, f"最高级: {data['sup']}\n")
            else:
                # 规则
                if len(word) >= 2 and word[-1] == 'y' and word[-2] not in 'aeiou':
                    comp = word[:-1] + "ier"
                    sup = word[:-1] + "iest"
                elif len(word) >= 2 and word[-1] in 'aeiou' and word[-2] in 'bcdfghjklmnpqrstvwxyz':
                    comp = word + word[-1] + "er"
                    sup = word + word[-1] + "est"
                else:
                    comp = word + "er" if len(word) < 4 else "more " + word
                    sup = word + "est" if len(word) < 4 else "most " + word
                self.inflect_result.insert(tk.END, f"形容词 {word} 的比较级: {comp}\n")
                self.inflect_result.insert(tk.END, f"最高级: {sup}\n")
        else:
            self.inflect_result.insert(tk.END, "暂不支持该词性。")

    def _build_article_tab(self, parent):
        """冠词（a/an/the）与介词（in/on/at）校验"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入英文短语或句子:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.article_input = tk.Text(main, height=6, font=('Unifont', 10), wrap=tk.WORD)
        self.article_input.pack(fill=tk.X, pady=5)
        self.article_input.insert(tk.END, "I have ___ apple and ___ orange.")

        tk.Button(main, text="校验冠词/介词", command=self._check_articles, font=('Unifont', 9)).pack(pady=5)

        self.article_result = tk.Text(main, height=12, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
        self.article_result.pack(fill=tk.BOTH, expand=True, pady=5)

        # 常见可数/不可数名词（示例）
        self._countable = set(["apple", "orange", "cat", "book", "idea", "car"])
        self._uncountable = set(["water", "rice", "information", "furniture", "advice", "music"])

    def _check_articles(self):
        text = self.article_input.get(1.0, tk.END).strip()
        if not text:
            return
        self.article_result.delete(1.0, tk.END)
        # 简单识别 ___ 占位符
        import re
        parts = re.split(r'(___)', text)
        for i, part in enumerate(parts):
            if part == "___":
                # 查看后面的词
                next_word = ""
                if i+1 < len(parts):
                    next_word = parts[i+1].strip().split()[0].lower() if parts[i+1].strip() else ""
                if next_word:
                    if next_word in self._uncountable:
                        article = "some"  # 或零冠词
                    elif next_word in self._countable:
                        if next_word[0] in 'aeiou':
                            article = "an"
                        else:
                            article = "a"
                    else:
                        article = "a/an"
                    self.article_result.insert(tk.END, f"建议冠词: {article} {next_word}\n")
            else:
                # 检测介词（简化）
                words = part.split()
                for j, w in enumerate(words):
                    if w.lower() in ["in", "on", "at"]:
                        context = " ".join(words[max(0,j-2):j+3])
                        self.article_result.insert(tk.END, f"介词 '{w}' 出现于: {context}\n")
                        # 简单提示
                        if w == "in":
                            self.article_result.insert(tk.END, "  in 用于大地方、时间段、年份等\n")
                        elif w == "on":
                            self.article_result.insert(tk.END, "  on 用于具体日期、表面、设备等\n")
                        elif w == "at":
                            self.article_result.insert(tk.END, "  at 用于具体时间点、小地点、节日等\n")
        if self.article_result.get(1.0, tk.END).strip() == "":
            self.article_result.insert(tk.END, "未检测到需要校正的冠词或介词。")

    def _build_syntax_tab(self, parent):
        """简单句法结构解析（SVO, 定语从句等）"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入英语句子:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.syntax_input = tk.Entry(main, width=60, font=('Unifont', 10))
        self.syntax_input.pack(pady=5)
        self.syntax_input.insert(0, "The cat ate the fish.")

        tk.Button(main, text="解析结构", command=self._parse_syntax, font=('Unifont', 9)).pack(pady=5)

        self.syntax_result = tk.Text(main, height=15, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
        self.syntax_result.pack(fill=tk.BOTH, expand=True, pady=5)

        # 简单词性标注（仅示例）
        self._pos_tags = {
            "the": "DET", "a": "DET", "an": "DET",
            "cat": "NOUN", "fish": "NOUN", "dog": "NOUN",
            "ate": "VERB", "chased": "VERB", "barked": "VERB",
            "quickly": "ADV", "very": "ADV",
            "happy": "ADJ", "big": "ADJ",
        }

    def _parse_syntax(self):
        sent = self.syntax_input.get().strip()
        if not sent:
            return
        self.syntax_result.delete(1.0, tk.END)
        words = sent.split()
        # 简单标注
        tagged = []
        for w in words:
            w_clean = w.strip('.,!?')
            tag = self._pos_tags.get(w_clean.lower(), "UNK")
            tagged.append((w, tag))
        self.syntax_result.insert(tk.END, "词性标注:\n")
        for w, tag in tagged:
            self.syntax_result.insert(tk.END, f"{w} ({tag}) ")
        self.syntax_result.insert(tk.END, "\n\n")
        # 试图找主语、谓语、宾语（简单位置）
        if len(tagged) >= 3:
            # 通常第一个名词短语做主语，第一个动词做谓语，后面名词做宾语
            subj = ""
            verb = ""
            obj = ""
            for w, tag in tagged:
                if tag == "NOUN" and not subj:
                    subj = w
                elif tag == "VERB" and not verb:
                    verb = w
                elif tag == "NOUN" and subj and verb and not obj:
                    obj = w
            self.syntax_result.insert(tk.END, f"主语: {subj}\n")
            self.syntax_result.insert(tk.END, f"谓语: {verb}\n")
            self.syntax_result.insert(tk.END, f"宾语: {obj}\n")
        else:
            self.syntax_result.insert(tk.END, "句子太短，无法完整解析SVO。")

    def _build_editing_tab(self, parent):
        """写作润色：拼写、语法、标点、语用 + 可读性"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入待润色的文本:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.edit_input = tk.Text(main, height=8, font=('Unifont', 10), wrap=tk.WORD)
        self.edit_input.pack(fill=tk.X, pady=5)
        self.edit_input.insert(tk.END, "He open the door and go to school quickly.")

        tk.Button(main, text="润色检查", command=self._edit_text, font=('Unifont', 9)).pack(pady=5)

        self.edit_result = tk.Text(main, height=15, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
        self.edit_result.pack(fill=tk.BOTH, expand=True, pady=5)

        # 内置拼写字典（基础）
        self._spell_dict = {"open", "door", "go", "school", "quickly", "he", "the", "to", "and", "cat", "dog", "happy"}

    def _edit_text(self):
        text = self.edit_input.get(1.0, tk.END).strip()
        if not text:
            return
        self.edit_result.delete(1.0, tk.END)
        # 1. 拼写检查
        words = text.split()
        misspelled = []
        for w in words:
            w_clean = w.strip('.,!?').lower()
            if w_clean not in self._spell_dict and len(w_clean) > 1:
                misspelled.append(w_clean)
        if misspelled:
            self.edit_result.insert(tk.END, f"拼写疑似错误: {', '.join(misspelled)}\n")
        # 2. 语法检查（简单主谓一致/时态）
        if "open" in text and "he" in text.lower():
            self.edit_result.insert(tk.END, "语法提示: 'he open' 应为 'he opens' (第三人称单数)\n")
        if "go" in text and "he" in text.lower():
            self.edit_result.insert(tk.END, "语法提示: 'he go' 应为 'he goes' (第三人称单数)\n")
        # 3. 标点
        if not text.endswith(('.', '!', '?')):
            self.edit_result.insert(tk.END, "标点提示: 句子应以句号/问号/感叹号结尾。\n")
        # 4. 语用（中式英语）
        if "open the light" in text.lower():
            self.edit_result.insert(tk.END, "语用建议: 'open the light' 应为 'turn on the light'\n")
        # 5. 可读性 (Flesch Reading Ease)
        total_words = len(words)
        total_sentences = max(1, text.count('.') + text.count('!') + text.count('?'))
        total_syllables = sum(self._count_syllables(w) for w in words)
        if total_words > 0:
            flesch = 206.835 - 1.015 * (total_words / total_sentences) - 84.6 * (total_syllables / total_words)
            self.edit_result.insert(tk.END, f"\n可读性 (Flesch Reading Ease): {flesch:.2f}\n")
            if flesch >= 80:
                self.edit_result.insert(tk.END, "  非常易读，适合小学生。\n")
            elif flesch >= 60:
                self.edit_result.insert(tk.END, "  易读，适合初中生。\n")
            elif flesch >= 40:
                self.edit_result.insert(tk.END, "  中等难度，适合高中生。\n")
            else:
                self.edit_result.insert(tk.END, "  较难，适合大学生或以上。\n")

    def _count_syllables(self, word):
        """简单音节计数（仅用于演示）"""
        word = word.lower()
        vowels = 'aeiou'
        count = 0
        last_was_vowel = False
        for ch in word:
            if ch in vowels:
                if not last_was_vowel:
                    count += 1
                last_was_vowel = True
            else:
                last_was_vowel = False
        return max(1, count)

    def _build_phonetics_tab(self, parent):
        """音标显示、音节划分、连读弱读模拟"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入单词或句子:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.phon_input = tk.Entry(main, width=50, font=('Unifont', 10))
        self.phon_input.pack(pady=5)
        self.phon_input.insert(0, "interesting")

        tk.Button(main, text="显示音标/音节", command=self._show_phonetics, font=('Unifont', 9)).pack(pady=5)

        self.phon_result = tk.Text(main, height=12, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
        self.phon_result.pack(fill=tk.BOTH, expand=True, pady=5)

        # 简化音标映射（仅示例）
        self._ipa_map = {
            "interesting": "/ˈɪntrəstɪŋ/",
            "apple": "/ˈæpəl/",
            "cat": "/kæt/",
            "dog": "/dɔːɡ/",
            "school": "/skuːl/",
        }

    def _show_phonetics(self):
        word = self.phon_input.get().strip()
        if not word:
            return
        self.phon_result.delete(1.0, tk.END)
        # 音标
        ipa = self._ipa_map.get(word, "/未知/")
        self.phon_result.insert(tk.END, f"音标: {ipa}\n")
        # 音节划分（简单）
        syllables = self._split_syllables(word)
        self.phon_result.insert(tk.END, f"音节划分: {'·'.join(syllables)}\n")
        # 连读弱读模拟（固定句子示例）
        if " " in word:
            self.phon_result.insert(tk.END, "\n连读/弱读模拟:\n")
            self.phon_result.insert(tk.END, "快速语流中，'to' 读作 /tə/，'and' 读作 /ən/。\n")
            self.phon_result.insert(tk.END, "例如: 'going to school' → /ˈɡoʊɪŋ tə skuːl/\n")

    def _split_syllables(self, word):
        """简单音节划分（仅演示）"""
        # 近似，实际需更复杂规则
        return [word[i:i+2] for i in range(0, len(word), 2)] if len(word) > 4 else [word]

