    def load_cross_math_data(self, filename="./res/data/math_data.json"):
        """从 JSON 文件加载化学与数学跨学科数据"""
        try:
            import json
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if isinstance(data, dict):
                return data
            else:
                messagebox.showerror("错误", "JSON 数据格式应为字典")
                return {}
        except FileNotFoundError:
            messagebox.showerror("错误", f"找不到跨学科数学数据文件 {filename}")
            return {}
        except json.JSONDecodeError as e:
            messagebox.showerror("错误", f"JSON 解析错误: {e}")
            return {}
        except Exception as e:
            messagebox.showerror("错误", f"读取数据时出错: {e}")
            return {}

