        # 使用 Notebook 内部子选项卡
        inner = ttk.Notebook(main)
        inner.pack(fill=tk.BOTH, expand=True)

        # ---- 子选项卡：矩阵运算 ----
        mat_frame = tk.Frame(inner)
        inner.add(mat_frame, text="矩阵运算")

        tk.Label(mat_frame, text="输入矩阵 A (行用分号分隔，列用空格):", font=('Unifont', 10)).pack(anchor=tk.W)
        self.mat_A = tk.Text(mat_frame, height=5, font=('Unifont', 9))
        self.mat_A.pack(fill=tk.X, pady=5)
