    # ---------- 矩阵运算辅助函数 ----------
    def _parse_matrix(self, text_widget):
        """从Text控件解析矩阵为列表的列表"""
        lines = text_widget.get(1.0, tk.END).strip().split('\n')
        matrix = []
        for line in lines:
            if line.strip():
                row = [float(x) for x in line.split()]
                matrix.append(row)
        return matrix

    def _mat_add(self):
        A = self._parse_matrix(self.mat_A)
        B = self._parse_matrix(self.mat_B)
        if not A or not B:
            return
        if len(A) != len(B) or len(A[0]) != len(B[0]):
            self.mat_result.delete(1.0, tk.END)
            self.mat_result.insert(tk.END, "矩阵维度不匹配")
            return
        C = [[A[i][j] + B[i][j] for j in range(len(A[0]))] for i in range(len(A))]
        self._show_matrix(C)

    def _mat_mul(self):
        A = self._parse_matrix(self.mat_A)
        B = self._parse_matrix(self.mat_B)
        if not A or not B:
            return
        if len(A[0]) != len(B):
            self.mat_result.delete(1.0, tk.END)
            self.mat_result.insert(tk.END, "矩阵维度不匹配 (A列 != B行)")
            return
        C = [[sum(A[i][k]*B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]
        self._show_matrix(C)

    def _mat_inv(self):
        A = self._parse_matrix(self.mat_A)
        if not A or len(A) != len(A[0]):
            self.mat_result.delete(1.0, tk.END)
            self.mat_result.insert(tk.END, "矩阵非方阵")
            return
        # 使用高斯-约当消元法求逆
        n = len(A)
        # 增广矩阵 [A | I]
        aug = [A[i][:] + [1 if i==j else 0 for j in range(n)] for i in range(n)]
        for i in range(n):
            # 选主元
            pivot = aug[i][i]
            if abs(pivot) < 1e-12:
                self.mat_result.delete(1.0, tk.END)
                self.mat_result.insert(tk.END, "矩阵奇异，无法求逆")
                return
            # 归一化
            for j in range(2*n):
                aug[i][j] /= pivot
            # 消去其他行
            for k in range(n):
                if k != i:
                    factor = aug[k][i]
                    for j in range(2*n):
                        aug[k][j] -= factor * aug[i][j]
        inv = [row[n:] for row in aug]
        self._show_matrix(inv)

    def _mat_det(self):
        A = self._parse_matrix(self.mat_A)
        if not A or len(A) != len(A[0]):
            self.mat_result.delete(1.0, tk.END)
            self.mat_result.insert(tk.END, "非方阵")
            return
        # 高斯消元求行列式
        n = len(A)
        det = 1.0
        M = [row[:] for row in A]
        for i in range(n):
            # 选主元
            pivot = M[i][i]
            if abs(pivot) < 1e-12:
                self.mat_result.delete(1.0, tk.END)
                self.mat_result.insert(tk.END, "行列式为零或接近零")
                return
            det *= pivot
            for j in range(i+1, n):
                factor = M[j][i] / pivot
                for k in range(i, n):
                    M[j][k] -= factor * M[i][k]
        self.mat_result.delete(1.0, tk.END)
        self.mat_result.insert(tk.END, f"行列式 = {det}")

    def _mat_solve(self):
        # 解 A x = b, 其中 b 是 B 的第一列（如果B是列向量）
        A = self._parse_matrix(self.mat_A)
        B = self._parse_matrix(self.mat_B)
        if not A or not B:
            return
        if len(A) != len(A[0]) or len(B[0]) != 1:
            self.mat_result.delete(1.0, tk.END)
            self.mat_result.insert(tk.END, "需要方阵 A 且 B 为列向量")
            return
        b = [row[0] for row in B]
        # 高斯消元
        n = len(A)
        aug = [A[i][:] + [b[i]] for i in range(n)]
        for i in range(n):
            pivot = aug[i][i]
            if abs(pivot) < 1e-12:
                self.mat_result.delete(1.0, tk.END)
                self.mat_result.insert(tk.END, "奇异矩阵")
                return
            for j in range(i+1, n):
                factor = aug[j][i] / pivot
                for k in range(i, n+1):
                    aug[j][k] -= factor * aug[i][k]
        x = [0]*n
        for i in range(n-1, -1, -1):
            x[i] = aug[i][n] / aug[i][i]
            for j in range(i-1, -1, -1):
                aug[j][n] -= aug[j][i] * x[i]
        self._show_matrix([x])

    def _show_matrix(self, M):
        self.mat_result.delete(1.0, tk.END)
        for row in M:
            self.mat_result.insert(tk.END, " ".join(f"{v:.6g}" for v in row) + "\n")

    # ---------- ODE 求解器 ----------
    def _ode_rk4(self):
        try:
            f_str = self.ode_func.get().strip()
            x0 = self.ode_x0.get()
            y0 = self.ode_y0.get()
            xn = self.ode_xn.get()
            steps = self.ode_steps.get()
        except:
            return
        h = (xn - x0) / steps
        x, y = x0, y0
        result = [(x, y)]
        # 解析函数
        ns = {'x': x, 'y': y, 'math': math}
        for _ in range(steps):
            # RK4
            ns['x'] = x; ns['y'] = y
            k1 = eval(f_str, {"__builtins__": {}}, ns)
            ns['x'] = x + h/2; ns['y'] = y + h*k1/2
            k2 = eval(f_str, {"__builtins__": {}}, ns)
            ns['x'] = x + h/2; ns['y'] = y + h*k2/2
            k3 = eval(f_str, {"__builtins__": {}}, ns)
            ns['x'] = x + h; ns['y'] = y + h*k3
            k4 = eval(f_str, {"__builtins__": {}}, ns)
            y = y + h/6 * (k1 + 2*k2 + 2*k3 + k4)
            x += h
            result.append((x, y))
        self.ode_result.delete(1.0, tk.END)
        self.ode_result.insert(tk.END, "x\ty\n")
        for xv, yv in result:
            self.ode_result.insert(tk.END, f"{xv:.4f}\t{yv:.6f}\n")

    # ---------- 优化（梯度下降） ----------
    def _opt_gradient(self):
        try:
            f_str = self.opt_func.get().strip()
            x0 = self.opt_x0.get()
            lr = self.opt_lr.get()
            iters = self.opt_iters.get()
        except:
            return
        x = x0
        ns = {'x': x, 'math': math}
        # 数值梯度 (中心差分)
        eps = 1e-6
        for _ in range(iters):
            ns['x'] = x + eps
            f1 = eval(f_str, {"__builtins__": {}}, ns)
            ns['x'] = x - eps
            f2 = eval(f_str, {"__builtins__": {}}, ns)
            grad = (f1 - f2) / (2*eps)
            x -= lr * grad
            if abs(grad) < 1e-8:
                break
        self.opt_result.delete(1.0, tk.END)
        self.opt_result.insert(tk.END, f"最优解 x = {x:.8f}\n")
        ns['x'] = x
        f_min = eval(f_str, {"__builtins__": {}}, ns)
        self.opt_result.insert(tk.END, f"最小值 f(x) = {f_min:.8f}")

    # ---------- 插值（拉格朗日） ----------
    def _interp_lagrange(self):
        data = self.interp_data.get(1.0, tk.END).strip().split('\n')
        points = []
        for line in data:
            if line.strip():
                x, y = map(float, line.split())
                points.append((x, y))
        if not points:
            return
        x_target = self.interp_x.get()
        n = len(points)
        result = 0.0
        for i in range(n):
            term = points[i][1]
            for j in range(n):
                if i != j:
                    term *= (x_target - points[j][0]) / (points[i][0] - points[j][0])
            result += term
        self.interp_result.delete(1.0, tk.END)
        self.interp_result.insert(tk.END, f"插值点 x = {x_target} 处 y = {result:.8f}")

    # ---------- FFT 演示 ----------
    def _fft_demo(self):
        # 简单实现 DFT（不优化），仅演示
        data = self.interp_data.get(1.0, tk.END).strip().split('\n')
        vals = []
        for line in data:
            if line.strip():
                _, y = map(float, line.split())
                vals.append(y)
        if not vals:
            return
        N = len(vals)
        # DFT
        real = [0.0]*N
        imag = [0.0]*N
        for k in range(N):
            for n in range(N):
                angle = 2*math.pi*k*n/N
                real[k] += vals[n] * math.cos(angle)
                imag[k] -= vals[n] * math.sin(angle)
        self.interp_result.delete(1.0, tk.END)
        self.interp_result.insert(tk.END, "DFT 幅度谱:\n")
        for k in range(N):
            amp = math.sqrt(real[k]**2 + imag[k]**2)
            self.interp_result.insert(tk.END, f"k={k}: {amp:.4f}\n")

    def _build_plot_tab(self, parent):
        """构建科学绘图：函数图、参数方程、隐函数、等高线、向量场"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        # 绘图类型选择
        type_frame = tk.Frame(main)
        type_frame.pack(fill=tk.X, pady=5)
        tk.Label(type_frame, text="绘图类型:", font=('Unifont', 10)).pack(side=tk.LEFT)
        self.plot_type = tk.StringVar(value="function")
        types = [("函数图", "function"), ("参数方程", "parametric"), ("隐函数", "implicit"),
                 ("等高线", "contour"), ("向量场", "vector")]
        for text, val in types:
            tk.Radiobutton(type_frame, text=text, variable=self.plot_type, value=val,
                           font=('Unifont', 9)).pack(side=tk.LEFT, padx=5)

        # 输入区域
        input_frame = tk.Frame(main)
        input_frame.pack(fill=tk.X, pady=5)

        tk.Label(input_frame, text="表达式 (变量 x, y):", font=('Unifont', 9)).pack(anchor=tk.W)
        self.plot_expr = tk.Entry(input_frame, width=60, font=('Unifont', 9))
        self.plot_expr.pack(pady=2)
        self.plot_expr.insert(0, "sin(x)")

        tk.Label(input_frame, text="x 范围 (min,max):", font=('Unifont', 9)).pack(anchor=tk.W)
        self.plot_xrange = tk.Entry(input_frame, width=30, font=('Unifont', 9))
        self.plot_xrange.pack(pady=2)
        self.plot_xrange.insert(0, "-6.28, 6.28")

        tk.Label(input_frame, text="y 范围 (min,max) (可选):", font=('Unifont', 9)).pack(anchor=tk.W)
        self.plot_yrange = tk.Entry(input_frame, width=30, font=('Unifont', 9))
        self.plot_yrange.pack(pady=2)
        self.plot_yrange.insert(0, "-2, 2")

        tk.Button(main, text="绘制", command=self._draw_plot, font=('Unifont', 9)).pack(pady=5)

        # 绘图画布
        self.plot_canvas = tk.Canvas(main, bg='white', relief=tk.SUNKEN, bd=2)
        self.plot_canvas.pack(fill=tk.BOTH, expand=True, pady=5)

    def _draw_plot(self):
        canvas = self.plot_canvas
        canvas.delete("all")
        w = canvas.winfo_width()
        h = canvas.winfo_height()
        if w <= 1 or h <= 1:
            canvas.after(100, self._draw_plot)
            return

        plot_type = self.plot_type.get()
        expr_str = self.plot_expr.get().strip()
        try:
            x_min, x_max = map(float, self.plot_xrange.get().split(','))
        except:
            x_min, x_max = -6.28, 6.28
        try:
            y_min, y_max = map(float, self.plot_yrange.get().split(','))
        except:
            y_min, y_max = -2, 2

        margin = 40
        plot_w = w - 2*margin
        plot_h = h - 2*margin

        # 绘制坐标轴
        canvas.create_line(margin, margin, margin, h-margin, fill='black')
        canvas.create_line(margin, h-margin, w-margin, h-margin, fill='black')
        canvas.create_text(margin-5, h-margin, text=f"{x_min:.1f}", font=('Unifont', 8))
        canvas.create_text(w-margin, h-margin+5, text=f"{x_max:.1f}", font=('Unifont', 8))
        canvas.create_text(margin-5, margin, text=f"{y_max:.1f}", font=('Unifont', 8))
        canvas.create_text(margin-5, h-margin, text=f"{y_min:.1f}", font=('Unifont', 8))

        ns = {'x': 0, 'y': 0, 'math': math}
        if plot_type == "function":
            # 绘制 y = f(x)
            points = []
            for i in range(plot_w):
                x_val = x_min + (i / plot_w) * (x_max - x_min)
                ns['x'] = x_val
                try:
                    y_val = eval(expr_str, {"__builtins__": {}}, ns)
                except:
                    y_val = 0
                if y_min <= y_val <= y_max:
                    px = margin + i
                    py = h - margin - ( (y_val - y_min) / (y_max - y_min) * plot_h )
                    points.append((px, py))
            if len(points) > 1:
                for i in range(len(points)-1):
                    canvas.create_line(points[i][0], points[i][1], points[i+1][0], points[i+1][1], fill='red', width=2)
        elif plot_type == "parametric":
            # 参数方程 x = f(t), y = g(t) 格式: "cos(t), sin(t)"
            parts = expr_str.split(',')
            if len(parts) != 2:
                return
            f_t, g_t = parts[0].strip(), parts[1].strip()
            # t 范围默认 0-2pi
            t_min, t_max = 0, 2*math.pi
            points = []
            steps = 200
            for i in range(steps+1):
                t = t_min + (i/steps)*(t_max-t_min)
                ns['t'] = t
                try:
                    x_val = eval(f_t, {"__builtins__": {}}, ns)
                    y_val = eval(g_t, {"__builtins__": {}}, ns)
                except:
                    continue
                if x_min <= x_val <= x_max and y_min <= y_val <= y_max:
                    px = margin + ( (x_val - x_min) / (x_max - x_min) * plot_w )
                    py = h - margin - ( (y_val - y_min) / (y_max - y_min) * plot_h )
                    points.append((px, py))
            if len(points) > 1:
                for i in range(len(points)-1):
                    canvas.create_line(points[i][0], points[i][1], points[i+1][0], points[i+1][1], fill='blue', width=2)
        elif plot_type == "implicit":
            # 隐函数 f(x,y)=0 简单网格搜索
            step = 0.02
            found = False
            for x in range(0, plot_w, 2):
                x_val = x_min + (x / plot_w) * (x_max - x_min)
                for y in range(0, plot_h, 2):
                    y_val = y_min + (y / plot_h) * (y_max - y_min)
                    ns['x'] = x_val; ns['y'] = y_val
                    try:
                        val = eval(expr_str, {"__builtins__": {}}, ns)
                    except:
                        val = 0
                    if abs(val) < 0.05:
                        canvas.create_oval(margin+x-1, h-margin-y-1, margin+x+1, h-margin-y+1, fill='green')
                        found = True
            if not found:
                canvas.create_text(w//2, h//2, text="未找到隐函数曲线", font=('Unifont', 10))
        elif plot_type == "contour":
            # 等高线 f(x,y)=c (简单绘制几条)
            levels = [-2, -1, 0, 1, 2]
            step = 0.02
            for level in levels:
                for x in range(0, plot_w, 2):
                    x_val = x_min + (x / plot_w) * (x_max - x_min)
                    for y in range(0, plot_h, 2):
                        y_val = y_min + (y / plot_h) * (y_max - y_min)
                        ns['x'] = x_val; ns['y'] = y_val
                        try:
                            val = eval(expr_str, {"__builtins__": {}}, ns)
                        except:
                            val = 0
                        if abs(val - level) < 0.05:
                            canvas.create_oval(margin+x-1, h-margin-y-1, margin+x+1, h-margin-y+1, fill='purple')
        elif plot_type == "vector":
            # 向量场: 表达式为 "u(x,y), v(x,y)" 格式
            parts = expr_str.split(',')
            if len(parts) != 2:
                return
            u_str, v_str = parts[0].strip(), parts[1].strip()
            step = (x_max - x_min) / 10
            for x in range(0, plot_w, 20):
                x_val = x_min + (x / plot_w) * (x_max - x_min)
                for y in range(0, plot_h, 20):
                    y_val = y_min + (y / plot_h) * (y_max - y_min)
                    ns['x'] = x_val; ns['y'] = y_val
                    try:
                        u = eval(u_str, {"__builtins__": {}}, ns)
                        v = eval(v_str, {"__builtins__": {}}, ns)
                    except:
                        continue
                    # 归一化长度
                    mag = math.hypot(u, v)
                    if mag > 1e-6:
                        u /= mag; v /= mag
                    px = margin + x
                    py = h - margin - y
                    canvas.create_line(px, py, px + u*15, py - v*15, fill='orange', width=2, arrow=tk.LAST)

    def _build_precision_tab(self, parent):
        """多精度算术（使用 decimal 和 fractions）"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入表达式 (支持 + - * / **, 可包含函数):", font=('Unifont', 10)).pack(anchor=tk.W)
        self.prec_expr = tk.Entry(main, width=60, font=('Unifont', 9))
        self.prec_expr.pack(pady=5)
        self.prec_expr.insert(0, "2**100")

        tk.Label(main, text="精度 (小数位数):", font=('Unifont', 9)).pack(anchor=tk.W)
        self.prec_digits = tk.IntVar(value=50)
        tk.Spinbox(main, from_=10, to=200, textvariable=self.prec_digits, width=8).pack(anchor=tk.W, pady=5)

        tk.Button(main, text="计算 (Decimal)", command=self._prec_calc, font=('Unifont', 9)).pack(pady=5)

        self.prec_result = tk.Text(main, height=10, font=('Unifont', 9), bg='#f0f0f0')
        self.prec_result.pack(fill=tk.BOTH, expand=True, pady=5)

    def _prec_calc(self):
        from decimal import Decimal, getcontext
        expr = self.prec_expr.get().strip()
        digits = self.prec_digits.get()
        getcontext().prec = digits
        try:
            # 安全替换 math 函数
            ns = {'math': math, 'Decimal': Decimal}
            # 将普通数字转为 Decimal
            result = eval(expr, {"__builtins__": {}}, ns)
            self.prec_result.delete(1.0, tk.END)
            self.prec_result.insert(tk.END, f"结果: {result}")
        except Exception as e:
            self.prec_result.delete(1.0, tk.END)
            self.prec_result.insert(tk.END, f"错误: {e}")

    def _build_repl_tab(self, parent):
        """交互式 Python 数学环境（支持变量保持）"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        # 命令输入
        cmd_frame = tk.Frame(main)
        cmd_frame.pack(fill=tk.X, pady=5)
        tk.Label(cmd_frame, text=">>> ", font=('Unifont', 10)).pack(side=tk.LEFT)
        self.repl_entry = tk.Entry(cmd_frame, font=('Unifont', 10))
        self.repl_entry.pack(side=tk.LEFT, fill=tk.X, expand=True)
        self.repl_entry.bind('<Return>', self._repl_execute)

        # 输出区域
        self.repl_output = tk.Text(main, height=20, font=('Unifont', 9), bg='black', fg='lightgreen', wrap=tk.WORD)
        self.repl_output.pack(fill=tk.BOTH, expand=True, pady=5)
        self.repl_output.insert(tk.END, "交互式数学环境 (支持 math 库, 变量保留)\n")
        self.repl_output.insert(tk.END, "输入 help 查看帮助\n")

        # 环境命名空间
        self.repl_namespace = {'math': math, '__builtins__': {}}

    def _repl_execute(self, event=None):
        cmd = self.repl_entry.get().strip()
        self.repl_entry.delete(0, tk.END)
        if not cmd:
            return
        self.repl_output.insert(tk.END, f">>> {cmd}\n")
        if cmd == "help":
            self.repl_output.insert(tk.END, "可用: 任意Python表达式, math库函数, 变量 x, y, z 等\n")
            self.repl_output.see(tk.END)
            return
        try:
            result = eval(cmd, {"__builtins__": {}}, self.repl_namespace)
            if result is not None:
                self.repl_output.insert(tk.END, f"{result}\n")
        except Exception as e:
            self.repl_output.insert(tk.END, f"错误: {e}\n")
        self.repl_output.see(tk.END)

