    def _analyze_rhetoric(self):
        text = self.rhetoric_input.get(1.0, tk.END).strip()
        if not text:
            return
        self.rhetoric_result.delete(1.0, tk.END)
        # 检测对仗（简单判断字数对称）
        lines = text.split('，')
        if len(lines) == 2 and len(lines[0]) == len(lines[1]):
            self.rhetoric_result.insert(tk.END, "检测到对仗（字数相等）\n")
        # 检测排比（重复结构）
        if '，' in text and text.count('，') >= 3:
            self.rhetoric_result.insert(tk.END, "检测到排比（多个分句）\n")
        # 检测互文
        if "山重水复" in text and "柳暗花明" in text:
            self.rhetoric_result.insert(tk.END, "检测到互文（前后呼应）\n")
        # 情感曲线
        self.rhetoric_result.insert(tk.END, "\n情感曲线：开端 → 发展 → 高潮 → 结局（模拟）\n")

