        self.compare_a.pack(fill=tk.X, pady=5)
        self.compare_a.insert(tk.END, "春天来了，万物复苏。")

        tk.Label(main, text="文本 B:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.compare_b = tk.Text(main, height=6, font=('Unifont', 10), wrap=tk.WORD)
        self.compare_b.pack(fill=tk.X, pady=5)
        self.compare_b.insert(tk.END, "春回大地，万象更新。")

        tk.Button(main, text="对比分析", command=self._compare_texts, font=('Unifont', 9)).pack(pady=5)

        self.compare_result = tk.Text(main, height=12, font=('Unifont', 10), bg='#f0f0f0', wrap=tk.WORD)
