    def _compare_texts(self):
        text_a = self.compare_a.get(1.0, tk.END).strip()
        text_b = self.compare_b.get(1.0, tk.END).strip()
        if not text_a or not text_b:
            return
        self.compare_result.delete(1.0, tk.END)
        # 长度
        len_a = len(text_a)
        len_b = len(text_b)
        self.compare_result.insert(tk.END, f"文本A长度：{len_a} 字\n文本B长度：{len_b} 字\n")
        # 词汇密度（简单用去重字/总字数）
        unique_a = len(set(text_a))
        unique_b = len(set(text_b))
        self.compare_result.insert(tk.END, f"文本A词汇密度：{unique_a/len_a:.2f}\n")
        self.compare_result.insert(tk.END, f"文本B词汇密度：{unique_b/len_b:.2f}\n")
        # 句式（标点统计）
        punct_a = text_a.count('，') + text_a.count('。')
        punct_b = text_b.count('，') + text_b.count('。')
        self.compare_result.insert(tk.END, f"文本A标点数量：{punct_a}\n")
        self.compare_result.insert(tk.END, f"文本B标点数量：{punct_b}\n")

