    def _check_poem(self):
        text = self.poem_input.get(1.0, tk.END).strip()
        lines = [line.strip() for line in text.split('\n') if line.strip()]
        if not lines:
            return
        self.poem_result.delete(1.0, tk.END)
        # 校验每句平仄
        for idx, line in enumerate(lines):
            self.poem_result.insert(tk.END, f"第{idx+1}句：{line}\n")
            tones = []
            for char in line:
                if char in self._tone_table:
                    tones.append(self._tone_table[char])
                else:
                    tones.append('?')
            self.poem_result.insert(tk.END, f"平仄：{' '.join(tones)}\n")
        # 押韵检测（检查最后一句尾字）
        if len(lines) >= 2:
            last_char = lines[-1][-1]
            second_last = lines[-2][-1] if len(lines) >= 2 else ""
            if last_char == second_last:
                self.poem_result.insert(tk.END, "检测到押韵（尾字相同）\n")
            else:
                self.poem_result.insert(tk.END, "尾字不同，可能不押韵。\n")

    def _build_graph_tab(self, parent):
        """人物关系图谱（简单知识图谱）"""
        main = tk.Frame(parent)
        main.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        tk.Label(main, text="输入人物（如 苏轼）:", font=('Unifont', 10)).pack(anchor=tk.W)
        self.graph_person = tk.Entry(main, width=30, font=('Unifont', 10))
        self.graph_person.pack(pady=5)
        self.graph_person.insert(0, "苏轼")

        tk.Button(main, text="绘制关系图", command=self._draw_graph, font=('Unifont', 9)).pack(pady=5)

        self.graph_canvas = tk.Canvas(main, bg='white', relief=tk.SUNKEN, bd=2)
        self.graph_canvas.pack(fill=tk.BOTH, expand=True, pady=5)

        # 内置人物关系数据
        self._graph_data = {
            "苏轼": {
                "师从": ["欧阳修"],
                "政敌": ["王安石"],
                "兄弟": ["苏辙"],
                "地点": ["黄州", "儋州"],
                "作品": ["赤壁赋", "水调歌头"]
            },
            "欧阳修": {
                "学生": ["苏轼"],
                "政敌": ["王安石"]
            },
            "王安石": {
                "政敌": ["苏轼", "欧阳修"]
            }
        }

    def _draw_graph(self):
        person = self.graph_person.get().strip()
        if person not in self._graph_data:
            self.graph_canvas.delete("all")
            self.graph_canvas.create_text(300, 150, text="未找到该人物", font=('Unifont', 14))
            return
        data = self._graph_data[person]
        self.graph_canvas.delete("all")
        # 以人物为中心画节点
        center_x, center_y = 300, 150
        self.graph_canvas.create_oval(center_x-30, center_y-20, center_x+30, center_y+20, fill='lightblue')
        self.graph_canvas.create_text(center_x, center_y, text=person, font=('Unifont', 10))
        # 绘制关系
        colors = ['red', 'green', 'blue', 'orange']
        y_offset = 50
        for idx, (rel, targets) in enumerate(data.items()):
            y = center_y + y_offset + idx*40
            self.graph_canvas.create_text(center_x-80, y, text=rel+":", anchor=tk.E, font=('Unifont', 9))
            for j, target in enumerate(targets):
                tx = center_x + j*60 + 20
                self.graph_canvas.create_line(center_x, center_y, tx, y, fill=colors[idx%len(colors)], width=2)
                self.graph_canvas.create_oval(tx-15, y-10, tx+15, y+10, fill='lightyellow')
                self.graph_canvas.create_text(tx, y, text=target, font=('Unifont', 8))

