    def load_chemical_dictionary(self):
        """从 JSON 文件加载化学字典数据"""
        dict_file = "./res/data/dict_data.json"
        try:
            with open(dict_file, 'r', encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            messagebox.showerror("错误", f"找不到字典文件: {dict_file}")
            return {}
        except json.JSONDecodeError as e:
            messagebox.showerror("错误", f"字典文件格式错误: {e}")
            return {}
        
