        info_label.pack(pady=(0, 15))
        
        # 查询区域
        query_frame = tk.Frame(main_frame)
        query_frame.pack(fill=tk.X, pady=(0, 10))
        
        tk.Label(query_frame, text="汉字:", font=("Unifont", 12)).pack(side=tk.LEFT, padx=(0, 10))
        
        query_var = tk.StringVar()
        query_entry = tk.Entry(query_frame, textvariable=query_var, font=("Unifont", 12), width=15)
        query_entry.pack(side=tk.LEFT, padx=(0, 10))
        query_entry.bind('<Return>', lambda e: do_query())
        
        def do_query():
            word = query_var.get().strip()
            if not word:
                result_text.config(state=tk.NORMAL)
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, "请输入要查询的汉字")
                result_text.config(state=tk.DISABLED)
                return
            
            if word in dictionary:
                meaning = dictionary[word]
                result = f"【{word}】\n\n{meaning}"
                # 尝试添加额外信息（如果存在）
                if "元素" in meaning and "元素符号" in meaning:
                    result += "\n\n（化学元素相关）"
            else:
                result = f"未找到「{word}」的释义\n\n请检查输入是否正确，或该词暂未收录"
            
            result_text.config(state=tk.NORMAL)
            result_text.delete(1.0, tk.END)
            result_text.insert(tk.END, result)
            result_text.config(state=tk.DISABLED)
        
        query_button = tk.Button(query_frame, text="查询", command=do_query,
                                 font=("Unifont", 10), bg="#4CAF50", fg="white", width=8)
        query_button.pack(side=tk.LEFT)
        
        # 结果展示区域
        result_frame = tk.Frame(main_frame)
        result_frame.pack(fill=tk.BOTH, expand=True, pady=(10, 0))
        
        result_text = tk.Text(result_frame, wrap=tk.WORD, font=("Unifont", 11), 
                              relief=tk.SUNKEN, bd=1)
        scrollbar = tk.Scrollbar(result_frame, orient=tk.VERTICAL, command=result_text.yview)
        result_text.configure(yscrollcommand=scrollbar.set)
        result_text.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        result_text.config(state=tk.DISABLED)
        
        # 常用字快捷按钮
        common_frame = tk.Frame(main_frame)
        common_frame.pack(fill=tk.X, pady=(15, 5))
        
        tk.Label(common_frame, text="常用查询:", font=("Unifont", 9)).pack(side=tk.LEFT, padx=(0, 10))
        
        common_words = ["氢", "氧", "碳", "铁", "铜"]
