    def parse_formula_to_vector(self, formula):
        """解析化学式，返回元素 -> 原子个数的字典（例如 {'H':2, 'O':1}）"""
        import re
        pattern = r'([A-Z][a-z]?)(\d*)'
        matches = re.findall(pattern, formula)
        counter = {}
        for elem, num_str in matches:
            num = int(num_str) if num_str else 1
            counter[elem] = counter.get(elem, 0) + num
        return counter

    def show_similarity_comparator(self):
        """化合物相似性比较器，支持基础模式（元素集合）和扩展模式（元素计数向量）"""
        import tkinter as tk
        from tkinter import ttk
        import re

        win = tk.Toplevel(self.root)
        win.title("化合物相似性比较 (Tanimoto)")
        win.geometry("650x520")
        win.resizable(False, False)
        win.transient(self.root)
        win.grab_set()

        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/moto.ico')
            win.iconphoto(True, icon_image)
        except:
            pass
        
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 325
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 260
        win.geometry(f"+{x}+{y}")
        
        main_frame = tk.Frame(win, padx=15, pady=15)
        main_frame.pack(fill=tk.BOTH, expand=True)
        
        # 标题
        tk.Label(main_frame, text="Tanimoto 相似性系数计算", font=("Unifont", 14)).pack(pady=(0,5))
        tk.Label(main_frame, text="比较两个化合物的分子组成相似性", font=("Unifont", 9), fg="gray").pack(pady=(0,15))
        
        # 模式选择
        mode_var = tk.StringVar(value="basic")
        mode_frame = tk.Frame(main_frame)
        mode_frame.pack(fill=tk.X, pady=(0,10))
        tk.Label(mode_frame, text="计算模式：", font=("Unifont", 10)).pack(side=tk.LEFT, padx=(0,10))
        tk.Radiobutton(mode_frame, text="基础模式 (元素种类集合)", variable=mode_var, value="basic").pack(side=tk.LEFT, padx=(0,15))
        tk.Radiobutton(mode_frame, text="扩展模式 (考虑原子个数)", variable=mode_var, value="extended").pack(side=tk.LEFT)
        
        # 化学式 A 输入
        frame_a = tk.Frame(main_frame)
        frame_a.pack(fill=tk.X, pady=5)
        tk.Label(frame_a, text="化合物 A :", width=12, anchor=tk.W).pack(side=tk.LEFT)
        formula_a_var = tk.StringVar()
        entry_a = tk.Entry(frame_a, textvariable=formula_a_var, font=("Unifont", 11), width=28)
        entry_a.pack(side=tk.LEFT, padx=5, fill=tk.X, expand=True)
        
        # 化学式 B 输入
        frame_b = tk.Frame(main_frame)
        frame_b.pack(fill=tk.X, pady=5)
        tk.Label(frame_b, text="化合物 B :", width=12, anchor=tk.W).pack(side=tk.LEFT)
        formula_b_var = tk.StringVar()
        entry_b = tk.Entry(frame_b, textvariable=formula_b_var, font=("Unifont", 11), width=28)
        entry_b.pack(side=tk.LEFT, padx=5, fill=tk.X, expand=True)
        
        # 结果标签
        result_label = tk.Label(main_frame, text="", font=("Unifont", 10), justify=tk.LEFT, fg="blue", wraplength=580)
        result_label.pack(fill=tk.X, pady=15)
        
        def compute_similarity():
            formula_a = formula_a_var.get().strip()
            formula_b = formula_b_var.get().strip()
            mode = mode_var.get()
            if not formula_a or not formula_b:
                result_label.config(text="❌ 请完整输入两个化学式", fg="red")
                return
            try:
                if mode == "basic":
                    # 基础模式：元素集合
                    set_a = set(re.findall(r'([A-Z][a-z]?)', formula_a))
                    set_b = set(re.findall(r'([A-Z][a-z]?)', formula_b))
                    if not set_a or not set_b:
                        result_label.config(text="❌ 无法解析化学式中的元素", fg="red")
                        return
                    intersection = set_a & set_b
                    union = set_a | set_b
                    tanimoto = len(intersection) / (len(set_a) + len(set_b) - len(intersection))
                    result = (
                        f"元素集合 A : {sorted(set_a)}\n"
                        f"元素集合 B : {sorted(set_b)}\n"
                        f"交集 : {sorted(intersection)} (|A∩B| = {len(intersection)})\n"
                        f"并集 : {sorted(union)} (|A∪B| = {len(union)})\n\n"
                        f"Tanimoto 系数 = {tanimoto:.4f}\n"
                    )
                else:  # extended 模式
                    vec_a = self.parse_formula_to_vector(formula_a)
                    vec_b = self.parse_formula_to_vector(formula_b)
                    if not vec_a or not vec_b:
                        result_label.config(text="❌ 无法解析化学式，请检查格式", fg="red")
                        return
                    all_keys = set(vec_a.keys()) | set(vec_b.keys())
                    dot = 0
                    norm_a_sq = 0
                    norm_b_sq = 0
                    for key in all_keys:
                        a_val = vec_a.get(key, 0)
                        b_val = vec_b.get(key, 0)
                        dot += a_val * b_val
                        norm_a_sq += a_val * a_val
                        norm_b_sq += b_val * b_val
                    tanimoto = dot / (norm_a_sq + norm_b_sq - dot) if (norm_a_sq + norm_b_sq - dot) != 0 else 0
                    result = (
                        f"元素计数向量 A : {dict(sorted(vec_a.items()))}\n"
                        f"元素计数向量 B : {dict(sorted(vec_b.items()))}\n"
                        f"点积 = {dot}, |A|² = {norm_a_sq}, |B|² = {norm_b_sq}\n\n"
                        f"广义 Tanimoto 系数 = {tanimoto:.4f}\n"
                    )
                # 相似性评语
                if tanimoto > 0.8:
                    result += "相似程度 : 很高"
                elif tanimoto > 0.6:
                    result += "相似程度 : 较高"
                elif tanimoto > 0.4:
                    result += "相似程度 : 中等"
                elif tanimoto > 0.2:
                    result += "相似程度 : 较低"
                else:
                    result += "相似程度 : 很低"
                result_label.config(text=result, fg="darkgreen")
            except Exception as e:
                result_label.config(text=f"⚠️ 计算出错: {str(e)}", fg="red")
        
        # 计算按钮
        btn_calc = tk.Button(main_frame, text="计算相似度", command=compute_similarity,
                             font=("Unifont", 11), bg="#4CAF50", fg="white", width=15)
        btn_calc.pack(pady=10)
        
        # 示例按钮区域
        example_frame = tk.Frame(main_frame)
        example_frame.pack(fill=tk.X, pady=5)
        tk.Label(example_frame, text="示例 : ", font=("Unifont", 9)).pack(side=tk.LEFT)
        examples = [
            ("水 vs 过氧化氢", ("H2O", "H2O2")),
            ("甲烷 vs 乙烷", ("CH4", "C2H6")),
            ("乙醇 vs 甲醚", ("C2H5OH", "CH3OCH3")),
            ("氯化钠 vs 氯化钾", ("NaCl", "KCl")),
            ("硫酸 vs 盐酸", ("H2SO4", "HCl")),
        ]
        def set_example(form_a, form_b):
            formula_a_var.set(form_a)
            formula_b_var.set(form_b)
            compute_similarity()
        for name, (fa, fb) in examples:
            btn = tk.Button(example_frame, text=name, command=lambda f=fa, g=fb: set_example(f, g),
                            font=("Unifont", 8), relief=tk.RIDGE)
            btn.pack(side=tk.LEFT, padx=3)
        
        # 说明文字
        info = tk.Label(main_frame,
                        text="基础模式：只比较元素种类（Jaccard 相似度）。\n扩展模式：比较每个元素的原子个数（向量 Tanimoto），适用于区分同分异构体等场景。",
                        font=("Unifont", 8), fg="gray", justify=tk.LEFT)
        info.pack(pady=(15,5))
        
        close_btn = tk.Button(main_frame, text="关闭", command=win.destroy, width=10)
        close_btn.pack(pady=5)

