    def get_system_status(self):
        """使用标准库获取系统状态（CPU占用、内存使用、CPU温度）"""

        system = platform.system()
        status = {}

        # ---------- CPU 占用率 ----------
        if system == "Windows":
            try:
                output = subprocess.check_output(
                    "wmic cpu get loadpercentage", shell=True, encoding="gbk"
                )
                # 输出示例：LoadPercentage\n 12\n
                numbers = re.findall(r"\d+", output)
                if numbers:
                    status["cpu_percent"] = numbers[0]
            except:
                status["cpu_percent"] = "未知"
        elif system == "Linux":
            try:
                # 读取 /proc/stat 第一行，计算 cpu 使用率（两次采样，此处简化，仅取当前瞬间）
                # 更准确的方法需要两次读取间隔，为简单起见，这里使用 top 命令
                output = subprocess.check_output(
                    "top -bn1 | grep 'Cpu(s)'", shell=True, encoding="utf-8"
                )
                # 示例：%Cpu(s):  5.2 us,  2.1 sy,  0.0 ni, 92.3 id,...
                match = re.search(r"(\d+\.?\d*)\s*id", output)
                if match:
                    idle = float(match.group(1))
                    status["cpu_percent"] = str(round(100 - idle, 1))
                else:
                    status["cpu_percent"] = "未知"
            except:
                status["cpu_percent"] = "未知"
        else:  # macOS, FreeBSD 等
            try:
                output = subprocess.check_output(
                    "top -l 1 | grep 'CPU usage'", shell=True, encoding="utf-8"
                )
                # 示例：CPU usage: 3.5% user, 2.1% sys, 94.4% idle
                match = re.search(r"(\d+\.?\d*)% idle", output)
                if match:
                    idle = float(match.group(1))
                    status["cpu_percent"] = str(round(100 - idle, 1))
                else:
                    status["cpu_percent"] = "未知"
            except:
                status["cpu_percent"] = "未知"

        # ---------- 内存使用 ----------
        if system == "Windows":
            try:
                output = subprocess.check_output(
                    "wmic OS get TotalVisibleMemorySize,FreePhysicalMemory",
                    shell=True,
                    encoding="gbk",
                )
                lines = output.strip().splitlines()
                # 第二行类似 " 16777216     8388608"
                if len(lines) >= 2:
                    parts = lines[1].split()
                    if len(parts) >= 2:
                        total = int(parts[0]) / 1024  # KB -> MB
                        free = int(parts[1]) / 1024
                        used = total - free
                        used_percent = (used / total) * 100
                        status["mem_used"] = f"{used:.0f} MB"
                        status["mem_total"] = f"{total:.0f} MB"
                        status["mem_percent"] = f"{used_percent:.1f}"
            except:
                status["mem_used"] = status["mem_total"] = status["mem_percent"] = "未知"
        elif system == "Linux":
            try:
                output = subprocess.check_output("free -m", shell=True, encoding="utf-8")
                lines = output.splitlines()
                for line in lines:
                    if line.startswith("Mem:"):
                        parts = line.split()
                        total = int(parts[1])
                        used = int(parts[2])
                        used_percent = (used / total) * 100
                        status["mem_used"] = f"{used} MB"
                        status["mem_total"] = f"{total} MB"
                        status["mem_percent"] = f"{used_percent:.1f}"
                        break
            except:
                status["mem_used"] = status["mem_total"] = status["mem_percent"] = "未知"
        else:  # macOS
            try:
                output = subprocess.check_output("vm_stat", shell=True, encoding="utf-8")
                # 解析页面大小和空闲/活跃/非活跃页面
                page_size_output = subprocess.check_output(
                    "sysctl hw.pagesize", shell=True, encoding="utf-8"
                )
                page_size = int(page_size_output.split()[-1]) / 1024 / 1024  # 转为 MB
                # 获取物理内存总量
                total_output = subprocess.check_output(
                    "sysctl hw.memsize", shell=True, encoding="utf-8"
                )
                total_mb = int(total_output.split()[-1]) / 1024 / 1024
                # 解析 vm_stat
                free_pages = None
                active_pages = None
                inactive_pages = None
                for line in output.splitlines():
                    if "Pages free:" in line:
                        free_pages = int(line.split(":")[1].strip().replace(".", ""))
                    elif "Pages active:" in line:
                        active_pages = int(line.split(":")[1].strip().replace(".", ""))
                    elif "Pages inactive:" in line:
                        inactive_pages = int(line.split(":")[1].strip().replace(".", ""))
                if free_pages is not None and active_pages is not None and inactive_pages is not None:
                    used_pages = active_pages + inactive_pages
                    used_mb = used_pages * page_size
                    used_percent = (used_mb / total_mb) * 100
                    status["mem_used"] = f"{used_mb:.0f} MB"
                    status["mem_total"] = f"{total_mb:.0f} MB"
                    status["mem_percent"] = f"{used_percent:.1f}"
                else:
                    status["mem_used"] = status["mem_total"] = status["mem_percent"] = "未知"
            except:
                status["mem_used"] = status["mem_total"] = status["mem_percent"] = "未知"

        # ---------- CPU 温度 ----------
        if system == "Windows":
            try:
                # 使用 wmic 读取温度（可能需要管理员权限，且部分硬件不支持）
                output = subprocess.check_output(
                    "wmic /namespace:\\\\root\\wmi PATH MSAcpi_ThermalZoneTemperature get CurrentTemperature",
                    shell=True,
                    encoding="gbk",
                )
                numbers = re.findall(r"\d+", output)
                if numbers:
                    # 温度单位是开尔文*10，转换为摄氏度
                    temp_kelvin = int(numbers[0]) / 10.0
                    temp_celsius = temp_kelvin - 273.15
                    status["cpu_temp"] = f"{temp_celsius:.1f} °C"
                else:
                    status["cpu_temp"] = "不支持"
            except:
                status["cpu_temp"] = "不支持"
        elif system == "Linux":
            try:
                # 读取 /sys/class/thermal/thermal_zone0/temp
                with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
                    temp_millideg = int(f.read().strip())
                    status["cpu_temp"] = f"{temp_millideg / 1000:.1f} °C"
            except:
                status["cpu_temp"] = "不支持"
        else:  # macOS
            try:
                output = subprocess.check_output(
                    "sysctl hw.sensor.cpu.temperature", shell=True, encoding="utf-8"
                )
                # 输出示例：hw.sensor.cpu.temperature: 45.0 C
                match = re.search(r"(\d+\.?\d*)\s*C", output)
                if match:
                    status["cpu_temp"] = f"{match.group(1)} °C"
                else:
                    status["cpu_temp"] = "不支持"
            except:
                status["cpu_temp"] = "不支持"

        # 组装显示文本
        text = (
            f"CPU 占用率 : {status.get('cpu_percent', '未知')}%\n"
            f"内存使用   : {status.get('mem_used', '?')} / {status.get('mem_total', '?')} MB  ({status.get('mem_percent', '?')}%)\n"
            f"CPU 温度   : {status.get('cpu_temp', '不支持')}"
        )
        return text 

    def show_custom_function(self):
        """自定义函数计算器：用户定义公式，保存/加载，计算"""
        win = tk.Toplevel(self.root)
        win.title("自定义函数计算器")
        win.geometry("700x600")
        win.transient(self.root)
        win.grab_set()

        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/calc.ico')
            win.iconphoto(True, icon_image)
        except:
            pass

        # 统一字体
        base_font = ('Unifont', 10)
        title_font = ('Unifont', 12)

        # 数据文件路径
        data_dir = "./res/data"
        os.makedirs(data_dir, exist_ok=True)
        json_file = os.path.join(data_dir, "func_data.json")

        # 加载已保存的函数
        def load_functions():
            if os.path.exists(json_file):
                try:
                    with open(json_file, 'r', encoding='utf-8') as f:
                        return json.load(f)
                except:
                    return {}
            return {}

        def save_functions(func_dict):
            try:
                with open(json_file, 'w', encoding='utf-8') as f:
                    json.dump(func_dict, f, ensure_ascii=False, indent=2)
                return True
            except:
                return False

        # 主框架
        main_frame = tk.Frame(win)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        # ---- 当前函数定义区 ----
        define_frame = tk.LabelFrame(main_frame, text=" 定义新函数 ", font=title_font)
        define_frame.pack(fill=tk.X, pady=(0, 10))

        tk.Label(define_frame, text="函数名:", font=base_font).grid(row=0, column=0, sticky=tk.W, padx=5, pady=5)
        func_name_var = tk.StringVar()
        name_entry = tk.Entry(define_frame, textvariable=func_name_var, font=base_font, width=20)
        name_entry.grid(row=0, column=1, padx=5, pady=5)

        tk.Label(define_frame, text="公式 f(x) =", font=base_font).grid(row=1, column=0, sticky=tk.W, padx=5, pady=5)
        formula_var = tk.StringVar()
        formula_entry = tk.Entry(define_frame, textvariable=formula_var, font=base_font, width=50)
        formula_entry.grid(row=1, column=1, columnspan=2, padx=5, pady=5, sticky=tk.W)

        # 说明标签
        info_label = tk.Label(define_frame, text="可使用 x 作为变量，支持 + - * / ** 及 math 函数（如 sin, cos, sqrt, log, exp）",
                              font=('Unifont', 8), fg="gray")
        info_label.grid(row=2, column=0, columnspan=3, sticky=tk.W, padx=5)

        # ---- 保存/删除按钮 ----
        button_frame = tk.Frame(define_frame)
        button_frame.grid(row=3, column=0, columnspan=3, pady=10)

        def save_current_func():
            name = func_name_var.get().strip()
            formula = formula_var.get().strip()
            if not name or not formula:
                messagebox.showwarning("警告", "函数名和公式不能为空")
                return
            # 验证公式合法性
            if not self.validate_formula(formula):
                messagebox.showerror("错误", "公式无效，请检查语法\n示例: x**2 + 2*x + 1")
                return
            funcs = load_functions()
            funcs[name] = formula
            if save_functions(funcs):
                messagebox.showinfo("成功", f"函数 '{name}' 已保存")
                refresh_list()
                func_name_var.set("")
                formula_var.set("")
            else:
                messagebox.showerror("错误", "保存失败")

        def delete_selected():
            selected = listbox.curselection()
            if not selected:
                messagebox.showwarning("警告", "请先选择要删除的函数")
                return
            name = listbox.get(selected[0])
            if messagebox.askyesno("确认", f"删除函数 '{name}'？"):
                funcs = load_functions()
                if name in funcs:
                    del funcs[name]
                    if save_functions(funcs):
                        refresh_list()
                        messagebox.showinfo("成功", f"已删除 '{name}'")
                    else:
                        messagebox.showerror("错误", "删除失败")

        tk.Button(button_frame, text="保存函数", command=save_current_func, font=base_font, width=12).pack(side=tk.LEFT, padx=5)
        tk.Button(button_frame, text="删除选中", command=delete_selected, font=base_font, width=12).pack(side=tk.LEFT, padx=5)

        # ---- 已保存函数列表 ----
        list_frame = tk.LabelFrame(main_frame, text=" 已保存的函数 ", font=title_font)
        list_frame.pack(fill=tk.BOTH, expand=True, pady=(0, 10))

        scrollbar = tk.Scrollbar(list_frame)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        listbox = tk.Listbox(list_frame, yscrollcommand=scrollbar.set, font=base_font, height=8)
        listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.config(command=listbox.yview)

        def refresh_list():
            listbox.delete(0, tk.END)
            funcs = load_functions()
            for name in sorted(funcs.keys()):
                listbox.insert(tk.END, name)

        def on_select(event):
            selection = listbox.curselection()
            if selection:
                name = listbox.get(selection[0])
                funcs = load_functions()
                if name in funcs:
                    func_name_var.set(name)
                    formula_var.set(funcs[name])

        listbox.bind("<<ListboxSelect>>", on_select)
        refresh_list()

        # ---- 计算区域 ----
        calc_frame = tk.LabelFrame(main_frame, text=" 计算 ", font=title_font)
        calc_frame.pack(fill=tk.X)

        tk.Label(calc_frame, text="x =", font=base_font).grid(row=0, column=0, sticky=tk.W, padx=5, pady=5)
        x_var = tk.StringVar(value="0")
        x_entry = tk.Entry(calc_frame, textvariable=x_var, font=base_font, width=15)
        x_entry.grid(row=0, column=1, padx=5, pady=5)

        tk.Label(calc_frame, text="结果 f(x) =", font=base_font).grid(row=0, column=2, sticky=tk.W, padx=5, pady=5)
        result_var = tk.StringVar(value="")
        result_label = tk.Label(calc_frame, textvariable=result_var, font=base_font, fg="blue", anchor=tk.W)
        result_label.grid(row=0, column=3, padx=5, pady=5, sticky=tk.W)

        def calculate():
            formula = formula_var.get().strip()
            if not formula:
                messagebox.showwarning("警告", "请输入公式或从列表中选择")
                return
            try:
                x = float(x_var.get())
            except ValueError:
                messagebox.showerror("错误", "x 必须是数字")
                return
            # 计算
            result = self.evaluate_formula(formula, x)
            if result is not None:
                result_var.set(f"{result:.10g}")
            else:
                result_var.set("计算错误")

        tk.Button(calc_frame, text="计算", command=calculate, font=base_font, width=10).grid(row=0, column=4, padx=10, pady=5)

        # 关闭按钮
        close_btn = tk.Button(main_frame, text="关闭", command=win.destroy, font=base_font, width=10)
        close_btn.pack(pady=10)

    def validate_formula(self, formula):
        """验证公式语法（不执行，仅检查）"""
        try:
            # 使用 math 命名空间
            namespace = {'x': 1.0, **{k: getattr(math, k) for k in dir(math) if not k.startswith('_')}}
            compile(formula, '<string>', 'eval')
            eval(formula, {"__builtins__": {}}, namespace)
            return True
        except Exception:
            return False

    def evaluate_formula(self, formula, x):
        """安全计算公式"""
        try:
            # 允许的数学函数
            allowed = {k: getattr(math, k) for k in dir(math) if not k.startswith('_')}
            namespace = {'x': x, **allowed}
            # 限制内置函数
            result = eval(formula, {"__builtins__": {}}, namespace)
            return result
        except Exception:
            return None

    # ---------- 附件：简易文字处理（完善版）----------
    def simple_word_processor(self):
        """简易文字处理：支持字体/字号、查找替换"""
        from tkinter import font as tkfont
        from tkinter import simpledialog

        win = tk.Toplevel(self.root)
        win.title("简易文字处理")
        win.geometry("800x600")
        win.transient(self.root)
        win.grab_set()

        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/office.ico')
            win.iconphoto(True, icon_image)
        except:
            pass

        # 工具栏
        toolbar = tk.Frame(win)
        toolbar.pack(fill=tk.X, padx=2, pady=2)

        # 字体选择
        font_families = list(tkfont.families())
        font_family_var = tk.StringVar(value="Unifont")
        font_menu = tk.OptionMenu(toolbar, font_family_var, *font_families[:30])
        font_menu.config(width=10)
        font_menu.pack(side=tk.LEFT, padx=2)

        # 字号选择
        size_var = tk.StringVar(value="11")
        size_spin = tk.Spinbox(toolbar, from_=8, to=72, textvariable=size_var, width=4)
        size_spin.pack(side=tk.LEFT, padx=2)

        text_area = tk.Text(win, wrap=tk.WORD, font=('Unifont', 11), undo=True)
        scrollbar = tk.Scrollbar(win, command=text_area.yview)
        text_area.configure(yscrollcommand=scrollbar.set)
        text_area.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

        # 状态栏
        status_label = tk.Label(win, text="就绪", anchor=tk.W, relief=tk.SUNKEN)
        status_label.pack(side=tk.BOTTOM, fill=tk.X)

        def apply_font(event=None):
            family = font_family_var.get()
            try:
                size = int(size_var.get())
            except:
                size = 11
            text_area.config(font=(family, size))
            status_label.config(text=f"字体: {family} {size}pt")

        font_family_var.trace('w', lambda *a: apply_font())
        size_var.trace('w', lambda *a: apply_font())

        # 按钮框架
        button_frame = tk.Frame(win)
        button_frame.pack(fill=tk.X, padx=5, pady=5)

        current_file = [None]

        def new_file():
            text_area.delete(1.0, tk.END)
            current_file[0] = None
            win.title("简易文字处理 - 新建文件")
            status_label.config(text="新建文件")

        def open_file():
            file_path = filedialog.askopenfilename(
                title="打开文本文件",
                filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
            )
            if file_path:
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                    text_area.delete(1.0, tk.END)
                    text_area.insert(1.0, content)
                    current_file[0] = file_path
                    win.title(f"简易文字处理 - {os.path.basename(file_path)}")
                    status_label.config(text=f"已打开: {file_path}")
                except Exception as e:
                    messagebox.showerror("错误", f"无法打开文件：{e}")

        def save_file():
            if current_file[0]:
                try:
                    with open(current_file[0], 'w', encoding='utf-8') as f:
                        f.write(text_area.get(1.0, tk.END))
                    status_label.config(text=f"已保存: {current_file[0]}")
                except Exception as e:
                    messagebox.showerror("错误", f"保存失败：{e}")
            else:
                save_as_file()

        def save_as_file():
            file_path = filedialog.asksaveasfilename(
                title="保存文件",
                defaultextension=".txt",
                filetypes=[("文本文件", "*.txt"), ("所有文件", "*.*")]
            )
            if file_path:
                try:
                    with open(file_path, 'w', encoding='utf-8') as f:
                        f.write(text_area.get(1.0, tk.END))
                    current_file[0] = file_path
                    win.title(f"简易文字处理 - {os.path.basename(file_path)}")
                    status_label.config(text=f"已保存: {file_path}")
                except Exception as e:
                    messagebox.showerror("错误", f"保存失败：{e}")

        def find_replace():
            # 查找替换对话框
            dialog = tk.Toplevel(win)
            dialog.title("查找/替换")
            dialog.geometry("300x150")
            dialog.transient(win)
            dialog.grab_set()

            tk.Label(dialog, text="查找:").grid(row=0, column=0, sticky=tk.W, padx=5, pady=5)
            find_var = tk.StringVar()
            tk.Entry(dialog, textvariable=find_var, width=25).grid(row=0, column=1, padx=5, pady=5)

            tk.Label(dialog, text="替换为:").grid(row=1, column=0, sticky=tk.W, padx=5, pady=5)
            replace_var = tk.StringVar()
            tk.Entry(dialog, textvariable=replace_var, width=25).grid(row=1, column=1, padx=5, pady=5)

            def do_replace():
                find_text = find_var.get()
                replace_text = replace_var.get()
                if not find_text:
                    return
                content = text_area.get(1.0, tk.END)
                new_content = content.replace(find_text, replace_text)
                if new_content != content:
                    text_area.delete(1.0, tk.END)
                    text_area.insert(1.0, new_content)
                    status_label.config(text=f"替换完成: '{find_text}' -> '{replace_text}'")
                else:
                    status_label.config(text=f"未找到 '{find_text}'")
                dialog.destroy()

            tk.Button(dialog, text="替换全部", command=do_replace, width=10).grid(row=2, column=0, columnspan=2, pady=10)

        tk.Button(button_frame, text="新建", command=new_file, width=8).pack(side=tk.LEFT, padx=2)
        tk.Button(button_frame, text="打开", command=open_file, width=8).pack(side=tk.LEFT, padx=2)
        tk.Button(button_frame, text="保存", command=save_file, width=8).pack(side=tk.LEFT, padx=2)
        tk.Button(button_frame, text="另存为", command=save_as_file, width=8).pack(side=tk.LEFT, padx=2)
        tk.Button(button_frame, text="查找/替换", command=find_replace, width=10).pack(side=tk.LEFT, padx=2)
        tk.Button(button_frame, text="关闭", command=win.destroy, width=8).pack(side=tk.RIGHT, padx=2)

        apply_font()

    # ---------- 附件：简易电子表格（完善版）----------
    def simple_spreadsheet(self):
        """简易电子表格：支持删除行、清空、简单求和"""

        win = tk.Toplevel(self.root)
        win.title("简易电子表格")
        win.geometry("850x550")
        win.transient(self.root)
        win.grab_set()

        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/office.ico')
            win.iconphoto(True, icon_image)
        except:
            pass

        main_frame = tk.Frame(win)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)

        # 默认列标题
        default_columns = ["A", "B", "C", "D", "E"]
        tree = ttk.Treeview(main_frame, columns=default_columns, show="headings")
        for col in default_columns:
            tree.heading(col, text=col)
            tree.column(col, width=120, anchor="center")
        tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        scroll_y = ttk.Scrollbar(main_frame, orient=tk.VERTICAL, command=tree.yview)
        scroll_x = ttk.Scrollbar(main_frame, orient=tk.HORIZONTAL, command=tree.xview)
        tree.configure(yscrollcommand=scroll_y.set, xscrollcommand=scroll_x.set)
        scroll_y.pack(side=tk.RIGHT, fill=tk.Y)
        scroll_x.pack(side=tk.BOTTOM, fill=tk.X)

        # 状态栏显示选中单元格或计算结果
        status_var = tk.StringVar(value="就绪")
        status_bar = tk.Label(win, textvariable=status_var, anchor=tk.W, relief=tk.SUNKEN)
        status_bar.pack(side=tk.BOTTOM, fill=tk.X)

        # 双击编辑单元格
        def on_double_click(event):
            region = tree.identify_region(event.x, event.y)
            if region != "cell":
                return
            item = tree.selection()[0]
            col = tree.identify_column(event.x)
            col_idx = int(col[1:]) - 1
            x, y, width, height = tree.bbox(item, col)
            value = tree.item(item, "values")[col_idx]

            entry = tk.Entry(tree, font=('Unifont', 10))
            entry.place(x=x, y=y, width=width, height=height)
            entry.insert(0, value)
            entry.focus()

            def save_edit(event=None):
                new_val = entry.get()
                values = list(tree.item(item, "values"))
                values[col_idx] = new_val
                tree.item(item, values=values)
                entry.destroy()
                status_var.set(f"已修改: {col}{tree.index(item)+1} = {new_val}")

            entry.bind("<Return>", save_edit)
            entry.bind("<FocusOut>", lambda e: entry.destroy())

        tree.bind("<Double-1>", on_double_click)

        # 显示当前选中单元格位置
        def on_select(event):
            selected = tree.selection()
            if selected:
                item = selected[0]
                row_idx = tree.index(item) + 1
                status_var.set(f"选中行 {row_idx}")

        tree.bind("<<TreeviewSelect>>", on_select)

        # 按钮框架
        button_frame = tk.Frame(win)
        button_frame.pack(fill=tk.X, padx=5, pady=5)

        def add_row():
            tree.insert("", "end", values=[""] * len(tree["columns"]))
            status_var.set("已添加新行")

        def delete_selected():
            selected = tree.selection()
            if not selected:
                messagebox.showwarning("警告", "请先选中要删除的行")
                return
            if messagebox.askyesno("确认", f"删除 {len(selected)} 行？"):
                for item in selected:
                    tree.delete(item)
                status_var.set(f"已删除 {len(selected)} 行")

        def clear_all():
            if messagebox.askyesno("确认", "清空所有数据？"):
                for item in tree.get_children():
                    tree.delete(item)
                status_var.set("已清空表格")

        def sum_column():
            # 要求用户选择列（字母）
            col_name = tk.simpledialog.askstring("求和", "请输入列字母 (如 A, B)", parent=win)
            if not col_name or col_name not in tree["columns"]:
                messagebox.showerror("错误", "无效的列名")
                return
            col_idx = tree["columns"].index(col_name)
            total = 0
            for item in tree.get_children():
                val = tree.item(item, "values")[col_idx]
                try:
                    total += float(val)
                except:
                    pass
            status_var.set(f"列 {col_name} 求和: {total}")

        def save_csv():
            file_path = filedialog.asksaveasfilename(
                title="保存为CSV",
                defaultextension=".csv",
                filetypes=[("CSV文件", "*.csv")]
            )
            if file_path:
                try:
                    with open(file_path, 'w', newline='', encoding='utf-8-sig') as f:
                        writer = csv.writer(f)
                        writer.writerow(tree["columns"])
                        for child in tree.get_children():
                            writer.writerow(tree.item(child, "values"))
                    status_var.set(f"已保存到 {os.path.basename(file_path)}")
                except Exception as e:
                    messagebox.showerror("错误", f"保存失败：{e}")

        def open_csv():
            file_path = filedialog.askopenfilename(
                title="打开CSV文件",
                filetypes=[("CSV文件", "*.csv")]
            )
            if file_path:
                try:
                    with open(file_path, 'r', encoding='utf-8-sig') as f:
                        reader = csv.reader(f)
                        rows = list(reader)
                    if not rows:
                        return
                    for child in tree.get_children():
                        tree.delete(child)
                    headers = rows[0]
                    tree["columns"] = headers
                    for col in headers:
                        tree.heading(col, text=col)
                        tree.column(col, width=120, anchor="center")
                    for row in rows[1:]:
                        tree.insert("", "end", values=row[:len(headers)])
                    win.title(f"简易电子表格 - {os.path.basename(file_path)}")
                    status_var.set(f"已打开 {os.path.basename(file_path)}")
                except Exception as e:
                    messagebox.showerror("错误", f"打开失败：{e}")

        tk.Button(button_frame, text="新增行", command=add_row, width=8).pack(side=tk.LEFT, padx=2)
        tk.Button(button_frame, text="删除选中行", command=delete_selected, width=10).pack(side=tk.LEFT, padx=2)
        tk.Button(button_frame, text="清空表格", command=clear_all, width=8).pack(side=tk.LEFT, padx=2)
        tk.Button(button_frame, text="求和", command=sum_column, width=6).pack(side=tk.LEFT, padx=2)
        tk.Button(button_frame, text="打开CSV", command=open_csv, width=8).pack(side=tk.LEFT, padx=2)
        tk.Button(button_frame, text="保存CSV", command=save_csv, width=8).pack(side=tk.LEFT, padx=2)
        tk.Button(button_frame, text="关闭", command=win.destroy, width=8).pack(side=tk.RIGHT, padx=2)

        add_row()  # 初始空行

    # ---------- 附件：简易演示文稿（完善版，修复nonlocal错误）----------
    def simple_presentation(self):
        """简易演示文稿：左侧幻灯片列表，支持新增/删除/切换"""
        win = tk.Toplevel(self.root)
        win.title("简易演示文稿")
        win.geometry("900x600")
        win.transient(self.root)
        win.grab_set()

        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/office.ico')
            viewer.iconphoto(True, icon_image)
        except:
            pass

        # 数据存储
        slides = []  # 元素 {"title": "...", "content": "..."}
        current_index = 0

        # 布局：左侧列表 + 右侧编辑区
        left_frame = tk.Frame(win, width=180, relief=tk.RAISED, bd=1)
        left_frame.pack(side=tk.LEFT, fill=tk.Y, padx=5, pady=5)
        left_frame.pack_propagate(False)

        right_frame = tk.Frame(win)
        right_frame.pack(side=tk.RIGHT, fill=tk.BOTH, expand=True, padx=5, pady=5)

        # 左侧列表
        tk.Label(left_frame, text="幻灯片列表", font=('Unifont', 10)).pack(pady=5)
        listbox = tk.Listbox(left_frame, font=('Unifont', 9), height=20)
        listbox.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)

        # 右侧编辑区
        slide_frame = tk.Frame(right_frame, relief=tk.RAISED, bd=2, bg="white")
        slide_frame.pack(fill=tk.BOTH, expand=True, pady=10)

        title_entry = tk.Text(slide_frame, height=2, font=('Unifont', 18), wrap=tk.WORD)
        title_entry.pack(fill=tk.X, padx=10, pady=10)
        content_text = tk.Text(slide_frame, height=15, font=('Unifont', 12), wrap=tk.WORD)
        content_text.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)

        # 按钮框架
        btn_frame = tk.Frame(right_frame)
        btn_frame.pack(fill=tk.X)

        status_var = tk.StringVar(value="就绪")
        status_label = tk.Label(right_frame, textvariable=status_var, anchor=tk.W, relief=tk.SUNKEN)
        status_label.pack(side=tk.BOTTOM, fill=tk.X, pady=(5,0))

        def update_listbox():
            listbox.delete(0, tk.END)
            for i, slide in enumerate(slides):
                title = slide["title"].strip()
                if not title:
                    title = f"幻灯片 {i+1}"
                elif len(title) > 20:
                    title = title[:17] + "..."
                listbox.insert(tk.END, f"{i+1}. {title}")
            if slides:
                listbox.selection_set(current_index)
                listbox.see(current_index)
            status_var.set(f"共 {len(slides)} 张幻灯片")

        def update_display():
            if slides and 0 <= current_index < len(slides):
                data = slides[current_index]
                title_entry.delete(1.0, tk.END)
                title_entry.insert(1.0, data["title"])
                content_text.delete(1.0, tk.END)
                content_text.insert(1.0, data["content"])
                win.title(f"简易演示文稿 - 幻灯片 {current_index+1}/{len(slides)}")
                update_listbox()
            else:
                title_entry.delete(1.0, tk.END)
                content_text.delete(1.0, tk.END)
                win.title("简易演示文稿 - 无幻灯片")

        def save_current():
            if slides and 0 <= current_index < len(slides):
                slides[current_index]["title"] = title_entry.get(1.0, tk.END).rstrip("\n")
                slides[current_index]["content"] = content_text.get(1.0, tk.END).rstrip("\n")

        # ----- 以下函数都必须将 nonlocal 声明放在第一行 -----
        def new_slide():
            nonlocal current_index
            save_current()
            slides.append({"title": "新幻灯片", "content": "在此输入内容..."})
            current_index = len(slides) - 1
            update_display()
            status_var.set("已新建幻灯片")

        def delete_slide():
            nonlocal current_index
            if not slides:
                return
            if messagebox.askyesno("确认", f"删除幻灯片 {current_index+1}？"):
                save_current()
                del slides[current_index]
                if not slides:
                    current_index = 0
                else:
                    if current_index >= len(slides):
                        current_index = len(slides) - 1
                update_display()
                status_var.set("已删除幻灯片")

        def prev_slide():
            nonlocal current_index
            if slides and current_index > 0:
                save_current()
                current_index -= 1
                update_display()

        def next_slide():
            nonlocal current_index
            if slides and current_index < len(slides) - 1:
                save_current()
                current_index += 1
                update_display()

        def on_listbox_select(event):
            nonlocal current_index
            if not slides:
                return
            selection = listbox.curselection()
            if selection:
                save_current()
                current_index = selection[0]
                update_display()

        listbox.bind("<<ListboxSelect>>", on_listbox_select)

        # 按钮
        tk.Button(btn_frame, text="新建幻灯片", command=new_slide, width=12).pack(side=tk.LEFT, padx=2)
        tk.Button(btn_frame, text="删除幻灯片", command=delete_slide, width=12).pack(side=tk.LEFT, padx=2)
        tk.Button(btn_frame, text="上一张", command=prev_slide, width=8).pack(side=tk.LEFT, padx=2)
        tk.Button(btn_frame, text="下一张", command=next_slide, width=8).pack(side=tk.LEFT, padx=2)
        tk.Button(btn_frame, text="关闭", command=win.destroy, width=8).pack(side=tk.RIGHT, padx=2)

        # 初始化一张幻灯片
        slides.append({"title": "欢迎使用演示文稿", "content": "双击幻灯片列表可切换\n在此编辑内容"})
        current_index = 0
        update_display()

    def show_orbital_viewer(self):
        """显示电子云图像查看器 - 仅支持 GIF 格式"""
        viewer = tk.Toplevel(self.root)
        viewer.title("电子云图像查看器")
        viewer.geometry("700x600")
        viewer.resizable(True, True)

        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/orbit.ico')
            viewer.iconphoto(True, icon_image)
        except:
            pass
        
        # 居中显示
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 350
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 300
        viewer.geometry(f"+{x}+{y}")
        
        main_frame = tk.Frame(viewer)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
        
        # 标题
        title = tk.Label(main_frame, text="原子轨道电子云图像", font=('Unifont', 14))
        title.pack(pady=(0, 10))
        
        # 轨道选择框架
        select_frame = tk.Frame(main_frame)
        select_frame.pack(fill=tk.X, pady=(0, 10))
        
        tk.Label(select_frame, text="选择轨道:", font=('Unifont', 10)).pack(side=tk.LEFT, padx=(0, 10))
        
        # 常见轨道列表（可根据实际 GIF 文件名扩充）
        orbitals = ['s',
                    'p-1','p0','p1',
                    'd-2','d-1','d0','d1','d2',
                    'f-3','f-2','f-1','f0','f1','f2','f3']
        
        orbit_var = tk.StringVar(value="s")
        orbit_menu = ttk.Combobox(select_frame, textvariable=orbit_var, values=orbitals, width=10, state="readonly")
        orbit_menu.pack(side=tk.LEFT, padx=(0, 10))
        
        # 创建一个带滚动条的 Canvas，用于显示可能过大的图像
        canvas_frame = tk.Frame(main_frame)
        canvas_frame.pack(fill=tk.BOTH, expand=True, pady=(0, 10))
        
        canvas = tk.Canvas(canvas_frame, bg='white')
        h_scroll = tk.Scrollbar(canvas_frame, orient=tk.HORIZONTAL, command=canvas.xview)
        v_scroll = tk.Scrollbar(canvas_frame, orient=tk.VERTICAL, command=canvas.yview)
        canvas.configure(xscrollcommand=h_scroll.set, yscrollcommand=v_scroll.set)
        
        canvas.grid(row=0, column=0, sticky="nsew")
        h_scroll.grid(row=1, column=0, sticky="ew")
        v_scroll.grid(row=0, column=1, sticky="ns")
        
        canvas_frame.grid_rowconfigure(0, weight=1)
        canvas_frame.grid_columnconfigure(0, weight=1)
        
        # 用于在 Canvas 上显示图像的容器
        image_on_canvas = canvas.create_image(0, 0, anchor="nw", image=None)
        
        # 状态/提示标签
        status_label = tk.Label(main_frame, text="", font=('Unifont', 9), fg='gray')
        status_label.pack(fill=tk.X)
        
        # 保存当前 PhotoImage 对象的引用，防止被垃圾回收
        current_photo = None
        
        def update_image(event=None):
            nonlocal current_photo
            orbital = orbit_var.get().strip()
            if not orbital:
                return
            
            # 构建图像路径
            image_dir = "./res/images/orbits/"
            image_path = os.path.join(image_dir, f"{orbital}.gif")
            
            if os.path.exists(image_path):
                try:
                    photo = tk.PhotoImage(file=image_path)
                    current_photo = photo  # 保持引用
                    
                    # 更新 Canvas 上图像的大小和位置
                    canvas.itemconfig(image_on_canvas, image=photo)
                    canvas.config(scrollregion=(0, 0, photo.width(), photo.height()))
                    # 可选：将视图居中或定位到左上角
                    canvas.xview_moveto(0)
                    canvas.yview_moveto(0)
                    
                    status_label.config(text=f"当前显示: {orbital} 轨道", fg='green')
                except Exception as e:
                    status_label.config(text=f"加载图像失败: {orbital} - {str(e)}", fg='red')
                    canvas.itemconfig(image_on_canvas, image='')
            else:
                # 显示占位符文本
                canvas.itemconfig(image_on_canvas, image='')
                canvas.delete("placeholder")
                placeholder = canvas.create_text(
                    canvas.winfo_width() // 2, canvas.winfo_height() // 2,
                    text=f"未找到图像文件\n{orbital}.gif\n请将图像放入 {image_dir}",
                    font=('Unifont', 12), fill='gray', anchor="center", tag="placeholder"
                )
                # 当窗口大小改变时更新占位符位置
                def on_resize(e):
                    canvas.coords(placeholder, canvas.winfo_width() // 2, canvas.winfo_height() // 2)
                canvas.bind("<Configure>", on_resize)
                status_label.config(text=f"找不到轨道 {orbital} 的图像", fg='red')
        
        # 绑定选择事件
        orbit_menu.bind('<<ComboboxSelected>>', update_image)
        # 初始加载
        update_image()
        
        # 关闭按钮
        close_btn = tk.Button(main_frame, text="关闭", font='Unifont', command=viewer.destroy, width=10)
        close_btn.pack(pady=5)

    def show_dna_rna_converter(self):
        """DNA/RNA 互补序列转换器"""
        win = tk.Toplevel(self.root)
        win.title("DNA/RNA 互补序列转换")
        win.geometry("600x400")
        win.resizable(True, True)
        win.transient(self.root)
        win.grab_set()

        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/bio.ico')
            win.iconphoto(True, icon_image)
        except:
            pass
        x = self.root.winfo_x() + (self.root.winfo_width() - 600) // 2
        y = self.root.winfo_y() + (self.root.winfo_height() - 400) // 2
        win.geometry(f"+{x}+{y}")

        tk.Label(win, text="输入序列 (5'→3', 只含 A,T,G,C,U):", font=('Unifont', 10)).pack(pady=5)
        seq_entry = tk.Text(win, height=5, font=('Unifont', 10))
        seq_entry.pack(fill=tk.X, padx=10, pady=5)

        # 模式选择
        mode_var = tk.StringVar(value="DNA→DNA互补")
        modes = ["DNA→DNA互补", "DNA→RNA互补", "RNA→DNA互补", "RNA→RNA互补"]
        mode_menu = ttk.Combobox(win, textvariable=mode_var, values=modes, state="readonly")
        mode_menu.pack(pady=5)

        result_text = tk.Text(win, height=5, font=('Unifont', 10), bg='#f0f0f0')
        result_text.pack(fill=tk.X, padx=10, pady=5)
        result_text.config(state=tk.DISABLED)

        def convert():
            seq = seq_entry.get("1.0", tk.END).strip().upper()
            if not seq:
                return
            mode = mode_var.get()
            # 互补规则
            dna_comp = {'A':'T', 'T':'A', 'G':'C', 'C':'G'}
            rna_comp = {'A':'U', 'U':'A', 'G':'C', 'C':'G'}
            rna_from_dna = {'A':'U', 'T':'A', 'G':'C', 'C':'G'}
            dna_from_rna = {'A':'T', 'U':'A', 'G':'C', 'C':'G'}

            if mode == "DNA→DNA互补":
                mapping = dna_comp
                result = ''.join(mapping.get(ch, '?') for ch in seq)
                out_type = "DNA (3'→5')"
            elif mode == "DNA→RNA互补":
                mapping = rna_from_dna
                result = ''.join(mapping.get(ch, '?') for ch in seq)
                out_type = "RNA (3'→5')"
            elif mode == "RNA→DNA互补":
                mapping = dna_from_rna
                result = ''.join(mapping.get(ch, '?') for ch in seq)
                out_type = "DNA (3'→5')"
            else:  # RNA→RNA互补
                mapping = rna_comp
                result = ''.join(mapping.get(ch, '?') for ch in seq)
                out_type = "RNA (3'→5')"

            result_text.config(state=tk.NORMAL)
            result_text.delete("1.0", tk.END)
            result_text.insert(tk.END, f"互补序列 ({out_type}):\n{result}")
            result_text.config(state=tk.DISABLED)

        tk.Button(win, text="转换", command=convert, font=('Unifont', 10)).pack(pady=10)
        tk.Button(win, text="关闭", command=win.destroy, font=('Unifont', 10)).pack(pady=5)

    def show_protein_mw_calculator(self):
        """蛋白质分子量计算器（基于单字母氨基酸序列）"""
        win = tk.Toplevel(self.root)
        win.title("蛋白质分子量计算器")
        win.geometry("600x450")
        win.resizable(True, True)
        win.transient(self.root)
        win.grab_set()

        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/bio.ico')
            win.iconphoto(True, icon_image)
        except:
            pass
        x = self.root.winfo_x() + (self.root.winfo_width() - 600) // 2
        y = self.root.winfo_y() + (self.root.winfo_height() - 450) // 2
        win.geometry(f"+{x}+{y}")

        # 氨基酸单字母代码及分子量（Dalton, 游离氨基酸残基平均分子量）
        aa_mw = {
            'A': 89.09, 'R': 174.20, 'N': 132.12, 'D': 133.10, 'C': 121.15,
            'E': 147.13, 'Q': 146.15, 'G': 75.07, 'H': 155.15, 'I': 131.17,
            'L': 131.17, 'K': 146.19, 'M': 149.21, 'F': 165.19, 'P': 115.13,
            'S': 105.09, 'T': 119.12, 'W': 204.23, 'Y': 181.19, 'V': 117.15
        }
        # 水分子量
        water_mw = 18.015

        tk.Label(win, text="输入蛋白质序列 (单字母氨基酸，如 MVHLTPEEK):", font=('Unifont', 10)).pack(pady=5)
        seq_entry = tk.Text(win, height=6, font=('Unifont', 10))
        seq_entry.pack(fill=tk.X, padx=10, pady=5)

        # 是否扣除水分子
        remove_water_var = tk.BooleanVar(value=True)
        tk.Checkbutton(win, text="扣除水分子（计算残基总分子量）", variable=remove_water_var, font=('Unifont', 9)).pack()

        result_label = tk.Label(win, text="", font=('Unifont', 11), fg="blue")
        result_label.pack(pady=10)
        details_label = tk.Label(win, text="", font=('Unifont', 9), fg="gray", justify=tk.LEFT)
        details_label.pack(pady=5)

        def calculate():
            seq = seq_entry.get("1.0", tk.END).strip().upper()
            if not seq:
                return
            # 只保留有效字符
            seq = ''.join(ch for ch in seq if ch in aa_mw)
            if not seq:
                result_label.config(text="未找到有效氨基酸")
                return
            total_mw = sum(aa_mw[aa] for aa in seq)
            if remove_water_var.get():
                # 每个肽键失去一分子水，肽键数 = 氨基酸数目 - 1
                total_mw -= (len(seq) - 1) * water_mw
            result_label.config(text=f"分子量: {total_mw:.2f} Da")
            # 显示氨基酸组成统计
            counts = {aa: seq.count(aa) for aa in set(seq)}
            details = "氨基酸组成:\n" + ", ".join(f"{aa}:{counts[aa]}" for aa in sorted(counts.keys()))
            details_label.config(text=details)

        tk.Button(win, text="计算", command=calculate, font=('Unifont', 10)).pack(pady=5)
        tk.Button(win, text="关闭", command=win.destroy, font=('Unifont', 10)).pack(pady=5)

    def show_pI_estimator(self):
        """等电点估算器（基于氨基酸组成）"""
        win = tk.Toplevel(self.root)
        win.title("等电点估算器")
        win.geometry("650x500")
        win.resizable(True, True)
        win.transient(self.root)
        win.grab_set()

        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/bio.ico')
            win.iconphoto(True, icon_image)
        except:
            pass
        x = self.root.winfo_x() + (self.root.winfo_width() - 650) // 2
        y = self.root.winfo_y() + (self.root.winfo_height() - 500) // 2
        win.geometry(f"+{x}+{y}")

        # 氨基酸侧链 pKa 近似值（用于等电点估算）
        side_pKa = {
            'D': 3.9,   # Aspartic acid
            'E': 4.3,   # Glutamic acid
            'C': 8.3,   # Cysteine (reduced)
            'H': 6.0,   # Histidine
            'K': 10.5,  # Lysine
            'R': 12.5,  # Arginine
            'Y': 10.1,  # Tyrosine
            # 末端氨基和羧基
            'Nterm': 8.0,
            'Cterm': 3.1
        }

        tk.Label(win, text="输入蛋白质序列 (单字母氨基酸):", font=('Unifont', 10)).pack(pady=5)
        seq_entry = tk.Text(win, height=6, font=('Unifont', 10))
        seq_entry.pack(fill=tk.X, padx=10, pady=5)

        result_label = tk.Label(win, text="", font=('Unifont', 11), fg="blue")
        result_label.pack(pady=10)

        def estimate_pI():
            seq = seq_entry.get("1.0", tk.END).strip().upper()
            seq = ''.join(ch for ch in seq if ch in side_pKa or ch in "ACDEFGHIKLMNPQRSTVWY")
            if len(seq) < 2:
                result_label.config(text="序列太短，无法估算")
                return
            # 统计带电荷侧链的数量
            counts = {}
            for aa in seq:
                if aa in side_pKa:
                    counts[aa] = counts.get(aa, 0) + 1
            # 构造带电荷基团的 pKa 列表：每个基团出现次数
            pos_groups = []  # 正电基团 pKa (质子化时带正电)
            neg_groups = []  # 负电基团 pKa (去质子化时带负电)
            # 酸性侧链
            for aa in ['D', 'E']:
                for _ in range(counts.get(aa, 0)):
                    neg_groups.append(side_pKa[aa])
            # 碱性侧链
            for aa in ['C', 'H', 'K', 'R', 'Y']:
                for _ in range(counts.get(aa, 0)):
                    pos_groups.append(side_pKa[aa])
            # 添加末端
            pos_groups.append(side_pKa['Nterm'])   # 氨基
            neg_groups.append(side_pKa['Cterm'])   # 羧基

            # 排序
            pos_groups.sort()
            neg_groups.sort()

            # 估算等电点：净电荷为零时的 pH
            # 简单方法：平均正负 pKa 中位数？这里使用标准方法：计算不同 pH 下净电荷，二分逼近
            def net_charge(pH):
                charge = 0.0
                # 正电基团：当 pH < pKa 时质子化带正电
                for pKa in pos_groups:
                    # 质子化比例 = 1/(1+10^(pH-pKa))
                    # 电荷 = +1 * 质子化比例
                    protonated = 1.0 / (1.0 + 10.0**(pH - pKa))
                    charge += protonated
                # 负电基团：当 pH > pKa 时去质子化带负电
                for pKa in neg_groups:
                    deprotonated = 1.0 / (1.0 + 10.0**(pKa - pH))
                    charge -= deprotonated
                return charge

            # 二分法找净电荷为零的 pH
            low, high = 0.0, 14.0
            for _ in range(50):
                mid = (low + high) / 2
                charge = net_charge(mid)
                if charge > 0:
                    low = mid
                else:
                    high = mid
            pI = (low + high) / 2
            result_label.config(text=f"估算等电点 pI ≈ {pI:.2f}")

        tk.Button(win, text="估算", command=estimate_pI, font=('Unifont', 10)).pack(pady=5)
        tk.Button(win, text="关闭", command=win.destroy, font=('Unifont', 10)).pack(pady=5)

    def show_buffer_calculator(self):
        """缓冲液配制计算器（Henderson-Hasselbalch 方程）"""
        win = tk.Toplevel(self.root)
        win.title("缓冲液配制计算器")
        win.geometry("600x500")
        win.resizable(False, False)
        win.transient(self.root)
        win.grab_set()

        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/bio.ico')
            win.iconphoto(True, icon_image)
        except:
            pass
        x = self.root.winfo_x() + (self.root.winfo_width() - 600) // 2
        y = self.root.winfo_y() + (self.root.winfo_height() - 500) // 2
        win.geometry(f"+{x}+{y}")

        tk.Label(win, text="Henderson-Hasselbalch 方程: pH = pKa + log([A-]/[HA])", font=('Unifont', 10)).pack(pady=5)

        # 预设缓冲对及 pKa
        buffers = {
            "柠檬酸 (pKa1=3.13)": 3.13,
            "柠檬酸 (pKa2=4.76)": 4.76,
            "醋酸/醋酸钠": 4.76,
            "磷酸 (pKa2=7.21)": 7.21,
            "Tris-HCl": 8.10,
            "碳酸 (pKa1=6.35)": 6.35,
            "碳酸 (pKa2=10.33)": 10.33,
            "HEPES": 7.55,
            "Glycine (pKa2=9.78)": 9.78,
        }
        
        frame = tk.Frame(win)
        frame.pack(pady=10)
        tk.Label(frame, text="选择缓冲对:", font=('Unifont', 10)).grid(row=0, column=0, sticky=tk.W)
        buffer_var = tk.StringVar(value="醋酸/醋酸钠")
        buffer_combo = ttk.Combobox(frame, textvariable=buffer_var, values=list(buffers.keys()), state="readonly", width=20)
        buffer_combo.grid(row=0, column=1, padx=5)

        tk.Label(frame, text="目标 pH:", font=('Unifont', 10)).grid(row=1, column=0, sticky=tk.W, pady=5)
        ph_var = tk.StringVar(value="7.0")
        ph_entry = tk.Entry(frame, textvariable=ph_var, font=('Unifont', 10), width=10)
        ph_entry.grid(row=1, column=1, sticky=tk.W)

        tk.Label(frame, text="总浓度 (mol/L):", font=('Unifont', 10)).grid(row=2, column=0, sticky=tk.W, pady=5)
        conc_var = tk.StringVar(value="0.1")
        conc_entry = tk.Entry(frame, textvariable=conc_var, font=('Unifont', 10), width=10)
        conc_entry.grid(row=2, column=1, sticky=tk.W)

        tk.Label(frame, text="体积 (L):", font=('Unifont', 10)).grid(row=3, column=0, sticky=tk.W, pady=5)
        vol_var = tk.StringVar(value="1.0")
        vol_entry = tk.Entry(frame, textvariable=vol_var, font=('Unifont', 10), width=10)
        vol_entry.grid(row=3, column=1, sticky=tk.W)

        result_text = tk.Text(win, height=8, font=('Unifont', 10), bg='#f0f0f0')
        result_text.pack(fill=tk.X, padx=10, pady=10)
        result_text.config(state=tk.DISABLED)

        def calculate():
            try:
                buffer_name = buffer_var.get()
                pKa = buffers[buffer_name]
                pH = float(ph_var.get())
                total_conc = float(conc_var.get())
                vol = float(vol_var.get())
            except:
                messagebox.showerror("错误", "请输入有效的数值")
                return
            # 计算 [A-]/[HA] 比例
            ratio = 10 ** (pH - pKa)  # [A-]/[HA]
            # 总浓度 = [HA] + [A-]
            # [HA] = total_conc / (1 + ratio)
            # [A-] = total_conc - [HA]
            if ratio == 0:
                messagebox.showerror("错误", "比率计算错误")
                return
            ha_conc = total_conc / (1 + ratio)
            a_conc = total_conc - ha_conc
            # 所需物质的量
            ha_mol = ha_conc * vol
            a_mol = a_conc * vol
            result_text.config(state=tk.NORMAL)
            result_text.delete("1.0", tk.END)
            result_text.insert(tk.END, f"缓冲对: {buffer_name}\n")
            result_text.insert(tk.END, f"pKa = {pKa}\n\n")
            result_text.insert(tk.END, f"目标 pH = {pH}\n")
            result_text.insert(tk.END, f"[A-]/[HA] = {ratio:.3f}\n")
            result_text.insert(tk.END, f"[HA] = {ha_conc:.4f} mol/L\n")
            result_text.insert(tk.END, f"[A-] = {a_conc:.4f} mol/L\n\n")
            result_text.insert(tk.END, f"对于 {vol} L 溶液:\n")
            result_text.insert(tk.END, f"需要弱酸 HA: {ha_mol:.4f} mol\n")
            result_text.insert(tk.END, f"需要共轭碱 A-: {a_mol:.4f} mol\n")
            if buffer_name == "醋酸/醋酸钠":
                result_text.insert(tk.END, "提示: 可用冰醋酸和醋酸钠配制\n")
            result_text.config(state=tk.DISABLED)

        tk.Button(win, text="计算", command=calculate, font=('Unifont', 10)).pack(pady=5)
        tk.Button(win, text="关闭", command=win.destroy, font=('Unifont', 10)).pack(pady=5)

