        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 250
        pericraft_window.geometry(f"+{x}+{y}")
        
        # 创建主框架
        main_frame = tk.Frame(pericraft_window, bg='black')
        main_frame.pack(fill=tk.BOTH, expand=True, padx=20, pady=20)
        
        # 创建标题（带ASCII艺术效果）
        title_frame = tk.Frame(main_frame, bg='black')
        title_frame.pack(fill=tk.X, pady=(0, 20))
        
        title_art = [
            "██████╗ ███████╗██████╗ ██╗ ██████╗██████╗  █████╗ ███████╗████████╗",
            "██╔══██╗██╔════╝██╔══██╗██║██╔════╝██╔══██╗██╔══██╗██╔════╝╚══██╔══╝",
            "██████╔╝█████╗  ██████╔╝██║██║     ██████╔╝███████║█████╗     ██║   ",
            "██╔═══╝ ██╔══╝  ██╔══██╗██║██║     ██╔══██╗██║  ██║██╔══╝     ██║   ",
            "██║     ███████╗██║  █Python Edition█║  ██║██   ██╝██║        ██║   ",
            "╚═╝     ╚══════╝╚═╝  ╚═╝╚═╝ ╚═════╝╚═╝  ╚═╝ ╚════╝ ╚═╝        ╚═╝   "
        ]
        
        for art_line in title_art:
            art_label = tk.Label(title_frame, text=art_line,
                                font=('Unifont', 8),
                                fg='#00FF00', bg='black')
            art_label.pack()
        
        # 创建诗歌显示区域
        poem_frame = tk.Frame(main_frame, bg='black', relief=tk.SUNKEN, bd=1)
        poem_frame.pack(fill=tk.BOTH, expand=True, pady=(10, 10))
        
        poem_text = tk.Text(poem_frame, 
                            font=('Unifont', 11),
                            fg='#00FF00', bg='black',
                            wrap=tk.WORD,
                            relief=tk.FLAT,
                            highlightthickness=0,
                            borderwidth=0,
                            padx=10,
                            pady=10)
        poem_text.pack(fill=tk.BOTH, expand=True)
        
        # 配置文本标签
        poem_text.tag_configure('center', justify='center')
        poem_text.tag_configure('line', spacing1=5, spacing2=5)
        
        # 读取诗歌数据
        poem_lines = []
        try:
            with open("./res/data/poem_data.txt", 'r', encoding='utf-8') as file:
                for line in file:
                    line = line.rstrip('\n')
                    if not line.startswith('#'):
                        poem_lines.append(line)
        except FileNotFoundError:
            poem_lines = ["", "诗歌文件未找到", "请检查 ./res/data/poem_data.txt", ""]
        except Exception as e:
            poem_lines = ["", f"读取文件错误: {str(e)}", ""]
        
        # 进度条框架
        progress_frame = tk.Frame(main_frame, bg='black')
        progress_frame.pack(fill=tk.X, pady=(10, 0))
        
        progress_label = tk.Label(progress_frame, text="播放进度:", 
                                 font=('Unifont', 9),
                                 fg='#00FF00', bg='black')
        progress_label.pack(side=tk.LEFT, padx=(0, 10))
        
        progress_bar = tk.Label(progress_frame, text="",
                               font=('Unifont', 9),
                               fg='#00FF00', bg='black')
        progress_bar.pack(side=tk.LEFT)
        
        # 滚动显示变量
        current_line = 0
        lines_per_page = 12
        
        def update_progress():
            """更新进度条"""
            if len(poem_lines) > 0:
                progress = int((current_line / len(poem_lines)) * 50)
                bar = "█" * progress + "░" * (50 - progress)
                progress_bar.config(text=f"[{bar}] {int((current_line / len(poem_lines)) * 100)}%")
        
        def scroll_poem():
            """滚动显示诗歌"""
            nonlocal current_line
            
            # 清空当前显示
            poem_text.delete(1.0, tk.END)
            
            # 计算要显示的行范围
            start_idx = current_line
            end_idx = min(current_line + lines_per_page, len(poem_lines))
            
            # 显示当前页的诗歌
            display_lines = poem_lines[start_idx:end_idx]
            for line in display_lines:
                if line == "":
                    poem_text.insert(tk.END, "\n")
                else:
                    poem_text.insert(tk.END, f"{line}\n\n", 'center')
            
            # 滚动到顶部
            poem_text.see(1.0)
            
            # 更新进度
            update_progress()
            
            # 更新当前行索引
            current_line += lines_per_page
            
            # 如果还有更多内容，继续滚动
            if current_line < len(poem_lines):
                pericraft_window.after(3000, scroll_poem)
            else:
                # 播放完毕，更新进度并关闭
                progress_label.config(text="播放完成!")
                pericraft_window.after(3000, pericraft_window.destroy)
        
        # 启动滚动显示
        update_progress()
        pericraft_window.after(1000, scroll_poem)
        
        # 底部按钮框架
        button_frame = tk.Frame(main_frame, bg='black')
        button_frame.pack(fill=tk.X, pady=(10, 0))
        
        close_button = tk.Button(button_frame, text="关闭", 
                                command=pericraft_window.destroy,
                                font=('Unifont', 10),
                                bg='#333333', fg='#00FF00',
                                relief=tk.RAISED,
                                cursor='hand2',
                                width=10)
        close_button.pack()

