        left_frame.pack_propagate(False)
        
        # 左侧标题
        list_title = tk.Label(left_frame, text="📖 参考资料列表", 
                             font=('Unifont', 12))
        list_title.pack(pady=(10, 5))
        
        # 搜索框
        search_frame = tk.Frame(left_frame)
        search_frame.pack(fill=tk.X, padx=10, pady=(0, 10))
        
        search_var = tk.StringVar()
        search_entry = tk.Entry(search_frame, textvariable=search_var, 
                               font=('Unifont', 10))
        search_entry.pack(side=tk.LEFT, fill=tk.X, expand=True)
        
        def filter_list():
            """过滤参考资料列表"""
            keyword = search_var.get().strip().lower()
            listbox.delete(0, tk.END)
            for ref in sorted(self.reference_data.keys()):
                if keyword in ref.lower():
                    listbox.insert(tk.END, ref)
        
        search_button = tk.Button(search_frame, text="🔍", 
                                 command=filter_list,
                                 font=('Unifont', 9), width=3)
        search_button.pack(side=tk.RIGHT, padx=(5, 0))
        
        search_entry.bind('<KeyRelease>', lambda e: filter_list())
        
        # 参考资料列表
        listbox_frame = tk.Frame(left_frame)
        listbox_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=(0, 10))
        
        scrollbar = tk.Scrollbar(listbox_frame)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        listbox = tk.Listbox(listbox_frame, yscrollcommand=scrollbar.set,
                            font=('Unifont', 11), bg='#f5f5f5',
                            selectbackground='#0078D7', selectforeground='white')
        listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.config(command=listbox.yview)
        
        # 填充参考资料列表
        for ref_name in sorted(self.reference_data.keys()):
            listbox.insert(tk.END, ref_name)
        
        # 右侧 - 内容显示区
        right_frame = tk.Frame(content_frame)
        right_frame.pack(side=tk.RIGHT, fill=tk.BOTH, expand=True)
        
        # 当前参考资料标题
        current_title_var = tk.StringVar(value="请选择参考资料")
        current_title_label = tk.Label(right_frame, textvariable=current_title_var,
                                       font=('Unifont', 14))
        current_title_label.pack(anchor=tk.W, pady=(0, 10))
        
        # 内容显示区域
        content_display_frame = tk.Frame(right_frame, relief=tk.SUNKEN, bd=1)
        content_display_frame.pack(fill=tk.BOTH, expand=True)
        
        # 文本框和滚动条
        text_widget = tk.Text(content_display_frame, wrap=tk.WORD, 
                             font=('Unifont', 11))
        text_scrollbar = tk.Scrollbar(content_display_frame, orient=tk.VERTICAL, 
                                     command=text_widget.yview)
        text_widget.configure(yscrollcommand=text_scrollbar.set)
        
        text_widget.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        text_scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        # 设置文本框标签样式（无粗体）
        text_widget.tag_configure('section', font=('Unifont', 13))
        text_widget.tag_configure('subtitle', font=('Unifont', 12))
        
        def show_reference_content(event=None):
            """显示选中的参考资料内容"""
            selection = listbox.curselection()
            if not selection:
                return
            
            ref_name = listbox.get(selection[0])
            current_title_var.set(ref_name)
            
            # 获取内容
            if ref_name in self.reference_data:
                content = self.reference_data[ref_name]
            else:
                content = f"未找到参考资料: {ref_name}"
            
            # 更新显示
            text_widget.config(state=tk.NORMAL)
            text_widget.delete(1.0, tk.END)
            
            # 插入内容（保持原有格式）
            text_widget.insert(tk.END, content)
            
            # 将光标移到开头
            text_widget.see(1.0)
            text_widget.config(state=tk.DISABLED)
        
        # 绑定列表选择事件
