    def display_table(self, table_name, parent_frame):
        """显示选定的表格"""
        # 清除原有内容
        for widget in parent_frame.winfo_children():
            widget.destroy()
        
        table_data = self.table_parser.get_table_data(table_name)
        if not table_data:
            error_label = tk.Label(parent_frame, text=f"无法加载表格: {table_name}", 
                                  font=('Unifont', 12), fg='red')
            error_label.pack(expand=True)
            return
        
        # 创建表格显示框架
        table_frame = tk.Frame(parent_frame)
        table_frame.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)
        
        # 表格标题
        title_label = tk.Label(table_frame, text=table_data['title'], 
                              font=('Unifont', 14), fg='darkblue')
        title_label.pack(pady=(0, 10))
        
        # 创建滚动区域
        canvas = tk.Canvas(table_frame)
        scrollbar = tk.Scrollbar(table_frame, orient=tk.VERTICAL, command=canvas.yview)
        scrollable_frame = tk.Frame(canvas)
        
        scrollable_frame.bind(
            "<Configure>",
            lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
        )
        
        canvas.create_window((0, 0), window=scrollable_frame, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)
        
        # 创建表格
        if table_data['headers']:
            # 有标题行的表格
            self._create_table_with_headers(scrollable_frame, table_data)
        else:
            # 无标题行的表格
            self._create_simple_table(scrollable_frame, table_data)
        
        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        # 添加原始内容显示选项
        self._add_raw_content_button(parent_frame, table_data)

    def _create_table_with_headers(self, parent, table_data):
        """创建带标题行的表格"""
        headers = table_data['headers']
        rows = table_data['rows']
        
        if not rows:
            tk.Label(parent, text="没有数据", font=('Unifont', 10)).pack(pady=20)
            return
        
        # 创建表格框架
        tree_frame = tk.Frame(parent)
        tree_frame.pack(fill=tk.BOTH, expand=True)
        
        # 创建Treeview
        tree = ttk.Treeview(tree_frame, columns=headers, show="headings", height=15)
        
        # 设置列标题和宽度
        for header in headers:
            tree.heading(header, text=header)
            tree.column(header, width=120, anchor='center')
        
        # 添加数据行
        for row in rows:
            # 确保行数据与标题列数匹配
            if len(row) >= len(headers):
                tree.insert("", tk.END, values=row[:len(headers)])
            else:
                # 补齐缺失的列
                padded_row = row + [''] * (len(headers) - len(row))
                tree.insert("", tk.END, values=padded_row)
        
        # 添加滚动条
        v_scrollbar = ttk.Scrollbar(tree_frame, orient=tk.VERTICAL, command=tree.yview)
        h_scrollbar = ttk.Scrollbar(tree_frame, orient=tk.HORIZONTAL, command=tree.xview)
        tree.configure(yscrollcommand=v_scrollbar.set, xscrollcommand=h_scrollbar.set)
        
        tree.grid(row=0, column=0, sticky='nsew')
        v_scrollbar.grid(row=0, column=1, sticky='ns')
        h_scrollbar.grid(row=1, column=0, sticky='ew')
        
        tree_frame.grid_rowconfigure(0, weight=1)
        tree_frame.grid_columnconfigure(0, weight=1)
        
        # 添加统计信息
        info_label = tk.Label(parent, text=f"共 {len(rows)} 行数据", 
                             font=('Unifont', 9), fg='gray')
        info_label.pack(pady=(5, 0))

    def _create_simple_table(self, parent, table_data):
        """创建简单表格（无标题行）"""
        rows = table_data['rows']
        
        if not rows:
            tk.Label(parent, text="没有数据", font=('Unifont', 10)).pack(pady=20)
            return
        
        # 计算最大列数
        max_cols = max(len(row) for row in rows) if rows else 0
        
        # 创建表格框架
        table_frame = tk.Frame(parent)
        table_frame.pack(fill=tk.BOTH, expand=True)
        
        # 创建Canvas用于滚动
        canvas = tk.Canvas(table_frame)
        v_scrollbar = tk.Scrollbar(table_frame, orient=tk.VERTICAL, command=canvas.yview)
        h_scrollbar = tk.Scrollbar(table_frame, orient=tk.HORIZONTAL, command=canvas.xview)
        scrollable_frame = tk.Frame(canvas)
        
        scrollable_frame.bind(
            "<Configure>",
            lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
        )
        
        canvas.create_window((0, 0), window=scrollable_frame, anchor="nw")
        canvas.configure(yscrollcommand=v_scrollbar.set, xscrollcommand=h_scrollbar.set)
        
        # 创建表格网格
        for i, row in enumerate(rows):
            for j, cell in enumerate(row):
                # 交替行颜色
                bg_color = '#f0f0f0' if i % 2 == 0 else 'white'
                label = tk.Label(scrollable_frame, text=cell, 
                               font=('Unifont', 10), bg=bg_color,
                               relief=tk.RIDGE, bd=1, width=15)
                label.grid(row=i, column=j, sticky='nsew', padx=1, pady=1)
        
        # 设置列权重
        for j in range(max_cols):
            scrollable_frame.grid_columnconfigure(j, weight=1)
        
        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        v_scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        h_scrollbar.pack(side=tk.BOTTOM, fill=tk.X)
        
        # 添加统计信息
        info_label = tk.Label(parent, text=f"共 {len(rows)} 行, {max_cols} 列", 
                             font=('Unifont', 9), fg='gray')
        info_label.pack(pady=(5, 0))

    def _add_raw_content_button(self, parent, table_data):
        """添加显示原始内容的按钮"""
        def show_raw_content():
            raw_window = tk.Toplevel(parent)
            raw_window.title("原始数据")
            raw_window.geometry("600x400")
            
            text_widget = tk.Text(raw_window, wrap=tk.WORD, font=('Unifont', 10))
            scrollbar = tk.Scrollbar(raw_window, orient=tk.VERTICAL, command=text_widget.yview)
            text_widget.configure(yscrollcommand=scrollbar.set)
            
            text_widget.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
            scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
            
            text_widget.insert(tk.END, table_data['raw_content'])
            text_widget.config(state=tk.DISABLED)
        
        button_frame = tk.Frame(parent)
        button_frame.pack(pady=5)
        
        raw_button = tk.Button(button_frame, text="查看原始数据", 
                              command=show_raw_content,
                              font=('Unifont', 9))
        raw_button.pack()

    class TableParser:
        """表格数据解析器内部类"""
        
        def __init__(self):
            self.tables = {}
        
        def parse_tables_from_file(self, filename="./res/data/charts_data.txt"):
            """从文件解析所有表格"""
            self.tables = {}
            
            try:
                with open(filename, 'r', encoding='utf-8') as file:
                    lines = file.readlines()
                
                current_table = None
                current_content = []
                
                for line_num, line in enumerate(lines, 1):
                    line = line.rstrip('\n')
                    
                    # 跳过空行和注释行
                    if not line.strip() or line.strip().startswith('#'):
                        continue
                    
                    # 检查是否是表格名称行（包含|分隔符）
                    if '|' in line:
                        # 保存前一个表格
                        if current_table and current_content:
                            self.tables[current_table] = self._parse_table_content(current_content)
                        
                        # 开始新表格
                        parts = line.split('|', 1)
                        current_table = parts[0].strip()
                        content_start = parts[1] if len(parts) > 1 else ""
                        current_content = [content_start] if content_start else []
                    else:
                        # 继续当前表格内容
                        if current_table is not None:
                            current_content.append(line)
                
                # 保存最后一个表格
                if current_table and current_content:
                    self.tables[current_table] = self._parse_table_content(current_content)
                
                return self.tables
                
            except FileNotFoundError:
                messagebox.showerror('错误', f"找不到表格数据文件 {filename}")
                return {}
            except Exception as e:
                messagebox.showerror('错误', f"读取表格数据时发生错误: {e}")
                return {}
        
        def _parse_table_content(self, content_lines):
            """解析表格内容，返回结构化数据"""
            structured_data = {
                'title': '',
                'headers': [],
                'rows': [],
                'raw_content': '\n'.join(content_lines)
            }
            
            # 合并内容并处理转义符
            full_content = '\n'.join(content_lines).replace('\\n', '\n')
            
            # 分离标题和内容
            lines = full_content.split('\n')
            if lines:
                structured_data['title'] = lines[0].strip()
                content_lines = lines[1:] if len(lines) > 1 else []
            else:
                content_lines = []
            
            # 解析表格数据
            for line in content_lines:
                line = line.strip()
                if not line:
                    continue
                
                # 按$分割数据行
                if '$' in line:
                    # 检查是否是标题行（包含列标题）
                    if not structured_data['headers'] and self._is_header_row(line):
                        structured_data['headers'] = [item.strip() for item in line.split('$') if item.strip()]
                    else:
                        row_data = [item.strip() for item in line.split('$') if item.strip()]
                        if row_data:
                            structured_data['rows'].append(row_data)
            
            return structured_data
        
        def _is_header_row(self, line):
            """判断是否是标题行"""
            # 简单判断：如果包含常见的标题关键词，认为是标题行
            header_keywords = ['元素', '化合价', '价态', '颜色', '范围', '顺序', '电势']
            parts = line.split('$')
            for part in parts:
                for keyword in header_keywords:
                    if keyword in part:
                        return True
            return False
        
        def get_table_list(self):
            """获取所有表格名称列表"""
            return list(self.tables.keys())
        
        def get_table_data(self, table_name):
            """获取指定表格的数据"""
            return self.tables.get(table_name, None)

