    def load_cas_database_from_file(self):
        """从TXT文件加载CAS数据库"""
        database = {}
        filename = "./res/data/cas_data.txt"
        
        try:
            with open(filename, 'r', encoding='utf-8') as file:
                for line_num, line in enumerate(file, 1):
                    line = line.strip()
                    
                    # 跳过空行和注释行
                    if not line or line.startswith('#'):
                        continue
                    
                    # 按竖线分割数据
                    parts = line.split('|')
                    
                    if len(parts) >= 10:  # 确保有足够的字段
                        chn_name, eng_name, cas, formula, mw, mp, bp, density, hazard,用途 = parts[:10]
                        
                        # 确定类别
                        category = "其他"
                        if "酸" in chn_name or chn_name.endswith("酸"):
                            category = "酸"
                        elif "碱" in chn_name or chn_name == "氢氧化钠" or chn_name == "氨":
                            category = "碱"
                        elif "盐" in chn_name or chn_name.endswith("化钠") or chn_name.endswith("化钙"):
                            category = "盐"
                        elif chn_name in ["乙醇", "甲醇", "丙酮", "苯", "甲苯", "氯仿", "乙醚"]:
                            category = "溶剂"
                        elif chn_name in ["阿司匹林", "青霉素", "咖啡因"]:
                            category = "医药"
                        elif "C" in formula and not any(x in chn_name for x in ["酸", "碱", "盐"]):
                            category = "有机物"
                        else:
                            category = "无机物"
                        
                        # 构建数据库条目
                        database[chn_name] = {
                            "chn_name": chn_name,
                            "eng_name": eng_name,
                            "cas": cas,
                            "formula": formula,
                            "mw": mw,
                            "mp": mp,
                            "bp": bp,
                            "density": density,
                            "hazard": hazard,
                            "用途": 用途,
                            "category": category
                        }
                    else:
                        print(f"警告: 第{line_num}行数据格式错误: {line}")
                        
        except FileNotFoundError:
            messagebox.showerror("错误", f"找不到CAS数据库文件: {filename}\n请确保文件存在于正确位置。")
            return self.get_default_cas_database()
        except Exception as e:
            messagebox.showerror("错误", f"读取CAS数据库时发生错误: {e}")
            return self.get_default_cas_database()
        
        return database

