    def roll_dice(self, count_var, sides_var, result_text, total_label, detail_text):
        """执行掷骰子操作"""
        try:
            # 获取骰子数量和面数
            dice_count = int(count_var.get())
            dice_sides = int(sides_var.get())
            
            # 验证输入
            if dice_count <= 0 or dice_count > 100:
                messagebox.showerror("错误", "骰子数量必须在1-100之间！")
                return
            if dice_sides < 2 or dice_sides > 1000:
                messagebox.showerror("错误", "骰子面数必须在2-1000之间！")
                return
            
            # 导入随机数模块
            import random
            import time
            
            # 掷骰子
            results = []
            total = 0
            for i in range(dice_count):
                roll = random.randint(1, dice_sides)
                results.append(roll)
                total += roll
            
            # 更新总计显示
            total_label.config(text=f"总计: {total}")
            
            # 更新结果文本框（显示简洁结果）
            result_text.config(state=tk.NORMAL)
            result_text.delete(1.0, tk.END)
            
            if dice_count == 1:
                result_text.insert(tk.END, f"掷出了: {results[0]}")
            else:
                result_text.insert(tk.END, f"掷出了 {dice_count} 个 d{dice_sides} 骰子\n总和: {total}")
            result_text.config(state=tk.DISABLED)
            
            # 清空详细结果文本框
            detail_text.delete(1.0, tk.END)
            
            # 显示每个骰子的结果
            if dice_count == 1:
                detail_text.insert(tk.END, f"🎲 结果: {results[0]}\n")
            else:
                detail_text.insert(tk.END, "各骰子结果:\n")
                for i, result in enumerate(results, 1):
                    # 添加一些视觉效果
                    bar = "█" * (result * 20 // dice_sides)  # 简单的进度条效果
                    detail_text.insert(tk.END, f"  🎲 {i:2d}: {result:3d} {bar}\n")
                
                # 添加统计信息
                detail_text.insert(tk.END, "\n📊 统计信息:\n")
                detail_text.insert(tk.END, f"  最大值: {max(results)}\n")
                detail_text.insert(tk.END, f"  最小值: {min(results)}\n")
                detail_text.insert(tk.END, f"  平均值: {total/dice_count:.2f}\n")
                
                # 计算标准差（可选）
                if dice_count > 1:
                    variance = sum((x - total/dice_count) ** 2 for x in results) / dice_count
                    std_dev = variance ** 0.5
                    detail_text.insert(tk.END, f"  标准差: {std_dev:.2f}\n")
            
            # 添加骰子表情（根据结果）
            if dice_count == 1 and dice_sides == 20:
                if results[0] == 20:
                    detail_text.insert(tk.END, "\n✨ 大成功！ ✨ 完美掷骰！")
                    result_text.config(state=tk.NORMAL)
                    result_text.insert(tk.END, " ✨大成功✨")
                    result_text.config(state=tk.DISABLED)
                elif results[0] == 1:
                    detail_text.insert(tk.END, "\n💥 大失败！ 💥 运气太差了...")
                    result_text.config(state=tk.NORMAL)
                    result_text.insert(tk.END, " 💥大失败💥")
                    result_text.config(state=tk.DISABLED)
            
            # 为所有骰子添加特殊效果
            if all(r == dice_sides for r in results):
                detail_text.insert(tk.END, "\n🌟 完美全满！ 🌟")
            elif all(r == 1 for r in results):
                detail_text.insert(tk.END, "\n😱 全部最小值！ 😱")
            
        except ValueError:
            messagebox.showerror("错误", "请输入有效的数字！")
        except Exception as e:
            messagebox.showerror("错误", f"发生错误: {str(e)}")

