    def open_windows_recorder(self):
        """打开Windows录音机"""
        try:
            '''
            # 方法1: 打开系统录音机（Windows 10/11）
            try:
                # 方法1: 直接运行SoundRecorder.exe
                soundrecorder_exe = r"C:\\Windows\\System32\\SoundRecorder.exe"
                
                if os.path.exists(soundrecorder_exe):
                    subprocess.Popen([soundrecorder_exe])
                    self.recording_status.set("已打开录音机")
                else:
                    # 如果System32中没有，尝试SysWOW64
                    soundrecorder_exe = r"C:\\Windows\\SysWOW64\\SoundRecorder.exe"
                    if os.path.exists(soundrecorder_exe):
                        subprocess.Popen([soundrecorder_exe])
                        self.recording_status.set("已打开录音机")
                    else:
                        self.recording_status.set("未找到录音机，请手动按Win+R输入soundrecorder")
            except:
                self.recording_status.set(f"打开失败: {str(e)}")
            
            '''
            try:
                subprocess.Popen(["start", "shell:AppsFolder\\Microsoft.WindowsSoundRecorder_8wekyb3d8bbwe!App"], shell=True)
                time.sleep(1)
                self.recording_status.set("已打开录音机")
                return
            except:
                pass
            
            # 方法3: 使用Windows录音机可执行文件路径
            recorder_paths = [
                r"C:\\Windows\\System32\\SoundRecorder.exe",
                r"C:\\Windows\\SysWOW64\\SoundRecorder.exe",
                r"C:\\Windows\win.ini"  # 回退方案
            ]
            
            for path in recorder_paths:
                if os.path.exists(path):
                    subprocess.Popen([path])
                    self.recording_status.set("已打开录音机")
                    return
            
            # 方法4: 打开录音文件夹
            self.open_recordings_folder()
            self.recording_status.set("请使用其他录音软件")
            
        except Exception as e:
            self.recording_status.set(f"打开失败: {str(e)}")

    def quick_windows_record(self):
        """快速录音（使用PowerShell录音）"""
        try:
            # 创建录音目录
            recordings_dir = os.path.join(os.path.expanduser("~"), "录音")
            if not os.path.exists(recordings_dir):
                os.makedirs(recordings_dir)
            
            # 生成文件名
            filename = self.filename_var.get().strip()
            if not filename:
                filename = "录音"
            
            # 清理文件名
            filename = re.sub(r'[<>:"/\\|?*]', '_', filename)
            
            # 添加时间戳
            timestamp = time.strftime("%Y%m%d_%H%M%S")
            recording_file = os.path.join(recordings_dir, f"{filename}_{timestamp}.wav")
            
            self.recording_status.set("正在录音...")
            
            # 使用PowerShell录音（需要Windows 10+）
            ps_script = f"""
            # 设置参数
            $outputFile = "{recording_file}"
            
            # 录音命令
            Add-Type -AssemblyName System.Windows.Forms
            Add-Type -AssemblyName System.Windows.Media
            
            # 创建录音对象
            $recorder = New-Object System.Windows.Media.MediaPlayer
            $recorder.Source = $outputFile
            
            # 开始录音
            $recorder.Play()
            Write-Host "录音开始..."
            
            # 等待5秒（可以修改时长）
            Start-Sleep -Seconds 5
            
            # 停止录音
            $recorder.Stop()
            Write-Host "录音完成！"
            Write-Host "文件保存在: $outputFile"
            """
            
            # 执行PowerShell脚本
            process = subprocess.Popen(
                ["powershell", "-Command", ps_script],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                creationflags=subprocess.CREATE_NO_WINDOW
            )
            
            # 等待录音完成
            time.sleep(6)  # 比录音时间长1秒
            
            # 检查文件是否创建
            if os.path.exists(recording_file):
                self.recording_file = recording_file
                file_size = os.path.getsize(recording_file) / 1024  # KB
                self.recording_status.set(f"录音完成 ({file_size:.1f} KB)")
            else:
                self.recording_status.set("录音完成（文件可能较小）")
            
        except Exception as e:
            self.recording_status.set(f"录音失败: {str(e)}")

    def play_windows_recording(self):
        """播放录音文件"""
        try:
            if self.recording_file and os.path.exists(self.recording_file):
                # 使用系统默认播放器打开
                os.startfile(self.recording_file)
                self.recording_status.set("正在播放...")
            else:
                # 让用户选择文件
                import tkinter.filedialog as filedialog
                
                filetypes = [
                    ("音频文件", "*.wav *.mp3 *.m4a *.wma"),
                    ("WAV文件", "*.wav"),
                    ("MP3文件", "*.mp3"),
                    ("所有文件", "*.*")
                ]
                
                audio_file = filedialog.askopenfilename(
                    title="选择音频文件",
                    filetypes=filetypes
                )
                
                if audio_file:
                    self.recording_file = audio_file
                    os.startfile(audio_file)
                    self.recording_status.set("正在播放...")
                else:
                    self.recording_status.set("未选择文件")
                    
        except Exception as e:
            self.recording_status.set(f"播放失败: {str(e)}")

    def open_recordings_folder(self):
        """打开录音文件夹"""
        try:
            # 录音文件夹路径
            recordings_dir = os.path.join(os.path.expanduser("~"), "录音")
            
            # 如果文件夹不存在，创建它
            if not os.path.exists(recordings_dir):
                os.makedirs(recordings_dir)
            
            # 打开文件夹
            subprocess.Popen(f'explorer "{recordings_dir}"')
            self.recording_status.set("已打开录音文件夹")
            
        except Exception as e:
            self.recording_status.set(f"打开失败: {str(e)}")

    def show_molecule_viewer(self):
        """显示3D分子查看器"""
        # 创建分子查看器窗口
        molecule_window = tk.Toplevel(self.root)
        molecule_window.title("3D分子模型查看器")
        molecule_window.geometry("900x700")  
