    def show_reaction_rate_calculator(self):
        """显示反应速率计算器"""
        calculator_window = tk.Toplevel(self.root)
        calculator_window.title("反应速率计算器")
        calculator_window.geometry("700x600")
        try:
            icon_image = tk.PhotoImage(file='./res/icon/func/physics.ico')
            calculator_window.iconphoto(True, icon_image)
        except:
            pass
        
        # 居中显示
        calculator_window.transient(self.root)
        calculator_window.grab_set()
        
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 350
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 300
        calculator_window.geometry(f"+{x}+{y}")
        
        # 创建主框架
        main_frame = tk.Frame(calculator_window)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=20, pady=20)
        
        # 标题
        title_label = tk.Label(main_frame, text="反应速率计算器", 
                          font=('Unifont', 14))
        title_label.pack(pady=(0, 15))
        
        # 使用笔记本式布局
        notebook = ttk.Notebook(main_frame)
        notebook.pack(fill=tk.BOTH, expand=True, pady=(0, 10))
        
        # 标签1: 速率定律计算
        rate_law_frame = tk.Frame(notebook)
        notebook.add(rate_law_frame, text="速率定律")
        
        # 速率定律: rate = k[A]^m[B]^n
        equation_label = tk.Label(rate_law_frame, 
                             text="速率定律: rate = k[A]^m[B]^n",
                             font=('Unifont', 11), fg='blue')
        equation_label.pack(pady=10)
        
        # 输入参数
        params_frame = tk.Frame(rate_law_frame)
        params_frame.pack(fill=tk.X, pady=10)
        
        params = [
            ("速率常数 k:", "1.0"),
            ("[A] 浓度:", "1.0"),
            ("[A] 反应级数 m:", "1"),
            ("[B] 浓度:", "1.0"),
            ("[B] 反应级数 n:", "0")
        ]
        
        entries = {}
        for i, (label_text, default) in enumerate(params):
            frame = tk.Frame(params_frame)
            frame.pack(fill=tk.X, pady=3)
            
            tk.Label(frame, text=label_text, width=20, anchor='w').pack(side=tk.LEFT)
            
            var = tk.StringVar(value=default)
            entry = tk.Entry(frame, textvariable=var, width=15)
            entry.pack(side=tk.LEFT)
            
            param_name = label_text.replace(":", "").strip()
            entries[param_name] = var
        
        # 速率计算函数
        def calculate_rate():
            try:
                k = float(entries['速率常数 k'].get())
                conc_A = float(entries['[A] 浓度'].get())
                m = float(entries['[A] 反应级数 m'].get())
                conc_B = float(entries['[B] 浓度'].get())
                n = float(entries['[B] 反应级数 n'].get())
                
                # 计算速率
                rate = k * (conc_A ** m) * (conc_B ** n)
                
                # 显示结果
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, "速率定律计算结果:\n")
                result_text.insert(tk.END, "=" * 40 + "\n")
                result_text.insert(tk.END, f"输入参数:\n")
                result_text.insert(tk.END, f"  速率常数 k = {k}\n")
                result_text.insert(tk.END, f"  [A] = {conc_A}, 级数 m = {m}\n")
                result_text.insert(tk.END, f"  [B] = {conc_B}, 级数 n = {n}\n")
                result_text.insert(tk.END, "=" * 40 + "\n")
                result_text.insert(tk.END, f"计算过程:\n")
                result_text.insert(tk.END, f"  rate = k[A]^m[B]^n\n")
                result_text.insert(tk.END, f"       = {k} × ({conc_A})^{m} × ({conc_B})^{n}\n")
                
                if conc_A != 0 and m != 0:
                    result_text.insert(tk.END, f"       = {k} × {conc_A**m:.4f} × {conc_B**n:.4f}\n")
                
                result_text.insert(tk.END, f"       = {rate:.4e}\n")
                result_text.insert(tk.END, "=" * 40 + "\n")
                result_text.insert(tk.END, f"总反应级数 = {m+n:.1f}\n")
                
            except ValueError as e:
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, f"错误: {e}\n请检查输入值")
        
        # 标签2: 阿伦尼乌斯方程
        arrhenius_frame = tk.Frame(notebook)
        notebook.add(arrhenius_frame, text="阿伦尼乌斯方程")
        
        # 阿伦尼乌斯方程: k = A·exp(-Ea/RT)
        arrhenius_label = tk.Label(arrhenius_frame, 
                              text="阿伦尼乌斯方程: k = A·exp(-Ea/RT)",
                              font=('Unifont', 11), fg='blue')
        arrhenius_label.pack(pady=10)
        
        # 输入参数
        arrhenius_params_frame = tk.Frame(arrhenius_frame)
        arrhenius_params_frame.pack(fill=tk.X, pady=10)
        
        arrhenius_params = [
            ("指前因子 A:", "1.0e12"),
            ("活化能 Ea (J/mol):", "50000"),
            ("温度 T (K):", "298.15")
        ]
        
        arrhenius_entries = {}
        for i, (label_text, default) in enumerate(arrhenius_params):
            frame = tk.Frame(arrhenius_params_frame)
            frame.pack(fill=tk.X, pady=5)
            
            tk.Label(frame, text=label_text, width=25, anchor='w').pack(side=tk.LEFT)
            
            var = tk.StringVar(value=default)
            entry = tk.Entry(frame, textvariable=var, width=15)
            entry.pack(side=tk.LEFT)
            
            param_name = label_text.split()[0]
            arrhenius_entries[param_name] = var
        
        # 阿伦尼乌斯方程计算函数
        def calculate_arrhenius():
            try:
                # 处理科学计数法
                A_str = arrhenius_entries['指前因子'].get()
                A = float(A_str) if 'e' not in A_str.lower() else float(A_str.replace('e', 'E'))
                
                Ea = float(arrhenius_entries['活化能'].get())
                T = float(arrhenius_entries['温度'].get())
                
                R = 8.314462  # J/(mol·K)
                
                # 计算速率常数 k
                k = A * math.exp(-Ea / (R * T))
                
                # 显示结果
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, "阿伦尼乌斯方程计算结果:\n")
                result_text.insert(tk.END, "=" * 40 + "\n")
                result_text.insert(tk.END, f"输入参数:\n")
                result_text.insert(tk.END, f"  指前因子 A = {A:.2e}\n")
                result_text.insert(tk.END, f"  活化能 Ea = {Ea} J/mol\n")
                result_text.insert(tk.END, f"  温度 T = {T} K\n")
                result_text.insert(tk.END, "=" * 40 + "\n")
                result_text.insert(tk.END, f"计算过程:\n")
                result_text.insert(tk.END, f"  k = A·exp(-Ea/RT)\n")
                result_text.insert(tk.END, f"    = {A:.2e} × exp(-{Ea}/({R}×{T}))\n")
                result_text.insert(tk.END, f"    = {A:.2e} × exp({-Ea/(R*T):.4f})\n")
                result_text.insert(tk.END, f"    = {k:.4e}\n")
                
            except ValueError as e:
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, f"错误: {e}\n请检查输入值")
        
        # 标签3: 半衰期计算
        half_life_frame = tk.Frame(notebook)
        notebook.add(half_life_frame, text="半衰期")
        
        # 半衰期公式
        half_life_label = tk.Label(half_life_frame, 
                              text="半衰期计算: t½ = ln2/k (一级反应)",
                              font=('Unifont', 11), fg='blue')
        half_life_label.pack(pady=10)
        
        # 输入参数
        half_life_params_frame = tk.Frame(half_life_frame)
        half_life_params_frame.pack(fill=tk.X, pady=10)
        
        half_life_params = [
            ("速率常数 k:", "0.01"),
            ("反应级数 n:", "1"),
            ("初始浓度 [A]₀:", "1.0")
        ]
        
        half_life_entries = {}
        for i, (label_text, default) in enumerate(half_life_params):
            frame = tk.Frame(half_life_params_frame)
            frame.pack(fill=tk.X, pady=5)
            
            tk.Label(frame, text=label_text, width=25, anchor='w').pack(side=tk.LEFT)
            
            var = tk.StringVar(value=default)
            entry = tk.Entry(frame, textvariable=var, width=15)
            entry.pack(side=tk.LEFT)
            
            param_name = label_text.replace(":", "").strip()
            half_life_entries[param_name] = var
        
        # 半衰期计算函数
        def calculate_half_life():
            try:
                k = float(half_life_entries['速率常数 k'].get())
                n = float(half_life_entries['反应级数 n'].get())
                A0 = float(half_life_entries['初始浓度 [A]₀'].get())
                
                # 根据反应级数计算半衰期
                if n == 1:
                    # 一级反应: t½ = ln(2)/k
                    t_half = math.log(2) / k
                    formula = "t½ = ln(2)/k"
                elif n == 2:
                    # 二级反应: t½ = 1/(k[A]₀)
                    t_half = 1 / (k * A0)
                    formula = "t½ = 1/(k[A]₀)"
                elif n == 0:
                    # 零级反应: t½ = [A]₀/(2k)
                    t_half = A0 / (2 * k)
                    formula = "t½ = [A]₀/(2k)"
                else:
                    # 其他级数
                    t_half = None
                    formula = f"需要通用公式"
                
                # 显示结果
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, "半衰期计算结果:\n")
                result_text.insert(tk.END, "=" * 40 + "\n")
                result_text.insert(tk.END, f"输入参数:\n")
                result_text.insert(tk.END, f"  速率常数 k = {k}\n")
                result_text.insert(tk.END, f"  反应级数 n = {n}\n")
                result_text.insert(tk.END, f"  初始浓度 [A]₀ = {A0}\n")
                result_text.insert(tk.END, "=" * 40 + "\n")
                
                if t_half is not None:
                    result_text.insert(tk.END, f"计算公式:\n  {formula}\n")
                    result_text.insert(tk.END, "=" * 40 + "\n")
                    result_text.insert(tk.END, f"半衰期 t½ = {t_half:.4f}\n")
                    result_text.insert(tk.END, f"单位取决于k的单位\n")
                else:
                    result_text.insert(tk.END, f"暂不支持 n={n} 级反应的半衰期计算\n")
                    
            except ValueError as e:
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, f"错误: {e}\n请检查输入值")
        
        # 按钮框架
        button_frame = tk.Frame(main_frame)
        button_frame.pack(pady=10)
        
        rate_button = tk.Button(button_frame, text="计算速率", command=calculate_rate,
                           font=('Unifont', 10), width=15)
        rate_button.pack(side=tk.LEFT, padx=5)
        
        arrhenius_button = tk.Button(button_frame, text="阿伦尼乌斯方程", command=calculate_arrhenius,
                                font=('Unifont', 10), width=15)
        arrhenius_button.pack(side=tk.LEFT, padx=5)
        
        half_life_button = tk.Button(button_frame, text="计算半衰期", command=calculate_half_life,
                                font=('Unifont', 10), width=15)
        half_life_button.pack(side=tk.LEFT, padx=5)
        
        # 结果文本框
        result_frame = tk.Frame(main_frame)
        result_frame.pack(fill=tk.BOTH, expand=True)
        
        result_text = tk.Text(result_frame, wrap=tk.WORD, font=('Unifont', 10), height=12)
        result_scrollbar = tk.Scrollbar(result_frame, orient=tk.VERTICAL, command=result_text.yview)
        result_text.configure(yscrollcommand=result_scrollbar.set)
        
        result_text.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        result_scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        result_text.insert(tk.END, "请选择计算类型并输入参数")
        
        # 关闭按钮
        close_button = tk.Button(main_frame, text="关闭", 
                            command=calculator_window.destroy,
                            font=('Unifont', 10), width=10)
        close_button.pack(pady=10)

    def show_thermodynamics_calculator(self):
        """显示热力学计算器"""
        calculator_window = tk.Toplevel(self.root)
        calculator_window.title("热力学计算器")
        calculator_window.geometry("700x650")
        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/physics.ico')
            calculator_window.iconphoto(True, icon_image)
        except:
            pass
        # 居中显示
        calculator_window.transient(self.root)
        calculator_window.grab_set()
        
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 350
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 325
        calculator_window.geometry(f"+{x}+{y}")
        
        # 创建主框架
        main_frame = tk.Frame(calculator_window)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=20, pady=20)
        
        # 标题
        title_label = tk.Label(main_frame, text="热力学计算器", 
                          font=('Unifont', 14))
        title_label.pack(pady=(0, 15))
        
        # 热力学基本方程
        equation_label = tk.Label(main_frame, 
                             text="ΔG = ΔH - TΔS   (吉布斯自由能)",
                             font=('Unifont', 11), fg='blue')
        equation_label.pack(pady=(0, 10))
        
        # 使用笔记本式布局
        notebook = ttk.Notebook(main_frame)
        notebook.pack(fill=tk.BOTH, expand=True, pady=(0, 10))
        
        # 标签1: 吉布斯自由能计算
        gibbs_frame = tk.Frame(notebook)
        notebook.add(gibbs_frame, text="吉布斯自由能")
        
        # 输入参数
        gibbs_params_frame = tk.Frame(gibbs_frame)
        gibbs_params_frame.pack(fill=tk.X, pady=15)
        
        gibbs_params = [
            ("焓变 ΔH (kJ/mol):", "-100"),
            ("熵变 ΔS (J/mol·K):", "-50"),
            ("温度 T (K):", "298.15")
        ]
        
        gibbs_entries = {}
        for i, (label_text, default) in enumerate(gibbs_params):
            frame = tk.Frame(gibbs_params_frame)
            frame.pack(fill=tk.X, pady=5)
            
            tk.Label(frame, text=label_text, width=25, anchor='w').pack(side=tk.LEFT)
            
            var = tk.StringVar(value=default)
            entry = tk.Entry(frame, textvariable=var, width=15)
            entry.pack(side=tk.LEFT)
            
            param_name = label_text.split()[0]
            gibbs_entries[param_name] = var
        
        # 吉布斯自由能计算函数
        def calculate_gibbs():
            try:
                delta_H = float(gibbs_entries['ΔH'].get())  # kJ/mol
                delta_S = float(gibbs_entries['ΔS'].get())  # J/mol·K
                T = float(gibbs_entries['T'].get())  # K
                
                # 计算吉布斯自由能: ΔG = ΔH - TΔS
                # 注意单位转换: ΔS需要从J转换为kJ
                delta_G = delta_H - (T * delta_S / 1000)
                
                # 计算平衡常数: ΔG = -RT lnK
                R = 8.314462  # J/(mol·K)
                if delta_G != 0:
                    K = math.exp(-delta_G * 1000 / (R * T))  # 注意ΔG单位转换
                else:
                    K = 1.0
                
                # 显示结果
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, "吉布斯自由能计算结果:\n")
                result_text.insert(tk.END, "=" * 50 + "\n")
                result_text.insert(tk.END, f"输入参数:\n")
                result_text.insert(tk.END, f"  焓变 ΔH = {delta_H} kJ/mol\n")
                result_text.insert(tk.END, f"  熵变 ΔS = {delta_S} J/mol·K\n")
                result_text.insert(tk.END, f"  温度 T = {T} K\n")
                result_text.insert(tk.END, "=" * 50 + "\n")
                result_text.insert(tk.END, f"计算过程:\n")
                result_text.insert(tk.END, f"  公式: ΔG = ΔH - TΔS\n")
                result_text.insert(tk.END, f"      = {delta_H} - {T}×({delta_S}/1000)\n")
                result_text.insert(tk.END, f"      = {delta_H} - {T*delta_S/1000:.4f}\n")
                result_text.insert(tk.END, f"      = {delta_G:.4f} kJ/mol\n")
                result_text.insert(tk.END, "=" * 50 + "\n")
                result_text.insert(tk.END, f"结果分析:\n")
                
                if delta_G < 0:
                    result_text.insert(tk.END, f"  ΔG = {delta_G:.4f} kJ/mol < 0\n")
                    result_text.insert(tk.END, f"  → 反应在{T}K时自发进行\n")
                elif delta_G > 0:
                    result_text.insert(tk.END, f"  ΔG = {delta_G:.4f} kJ/mol > 0\n")
                    result_text.insert(tk.END, f"  → 反应在{T}K时非自发\n")
                else:
                    result_text.insert(tk.END, f"  ΔG = 0 kJ/mol\n")
                    result_text.insert(tk.END, f"  → 反应处于平衡状态\n")
                
                result_text.insert(tk.END, "=" * 50 + "\n")
                result_text.insert(tk.END, f"平衡常数计算:\n")
                result_text.insert(tk.END, f"  公式: ΔG = -RT lnK\n")
                result_text.insert(tk.END, f"  lnK = -ΔG/RT = -{delta_G*1000:.2f}/({R}×{T})\n")
                result_text.insert(tk.END, f"  K = {K:.4e}\n")
                
                if K > 1:
                    result_text.insert(tk.END, f"  K > 1: 平衡向右移动\n")
                elif K < 1:
                    result_text.insert(tk.END, f"  K < 1: 平衡向左移动\n")
                else:
                    result_text.insert(tk.END, f"  K = 1: 平衡居中\n")
                    
            except ValueError as e:
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, f"错误: {e}\n请检查输入值")
        
        # 标签2: 热力学循环
        cycle_frame = tk.Frame(notebook)
        notebook.add(cycle_frame, text="热力学循环")
        
        # 热力学第一定律
        first_law_label = tk.Label(cycle_frame, 
                              text="热力学第一定律: ΔU = Q + W",
                              font=('Unifont', 11), fg='blue')
        first_law_label.pack(pady=10)
        
        # 输入参数
        cycle_params_frame = tk.Frame(cycle_frame)
        cycle_params_frame.pack(fill=tk.X, pady=10)
        
        cycle_params = [
            ("热 Q (J):", "100"),
            ("功 W (J):", "-50"),
            ("内能变化 ΔU (J):", "")
        ]
        
        cycle_entries = {}
        for i, (label_text, default) in enumerate(cycle_params):
            frame = tk.Frame(cycle_params_frame)
            frame.pack(fill=tk.X, pady=5)
            
            tk.Label(frame, text=label_text, width=25, anchor='w').pack(side=tk.LEFT)
            
            var = tk.StringVar(value=default)
            entry = tk.Entry(frame, textvariable=var, width=15)
            entry.pack(side=tk.LEFT)
            
            param_name = label_text.split()[0]
            cycle_entries[param_name] = var
        
        # 热力学循环计算函数
        def calculate_cycle():
            try:
                Q = cycle_entries['热'].get()
                W = cycle_entries['功'].get()
                delta_U = cycle_entries['内能变化'].get()
                
                # 检查已知量和未知量
                known = []
                if Q: known.append(('Q', float(Q)))
                if W: known.append(('W', float(W)))
                if delta_U: known.append(('ΔU', float(delta_U)))
                
                if len(known) != 2:
                    result_text.delete(1.0, tk.END)
                    result_text.insert(tk.END, "错误: 请填写任意两个已知量\n")
                    result_text.insert(tk.END, "公式: ΔU = Q + W")
                    return
                
                # 计算未知量
                if not Q:
                    # 计算 Q = ΔU - W
                    Q_val = known[1][1] - known[0][1] if known[0][0] == 'W' else known[0][1] - known[1][1]
                    cycle_entries['热'].set(f"{Q_val:.4f}")
                    result = f"计算结果: Q = ΔU - W = {Q_val:.4f} J"
                elif not W:
                    # 计算 W = ΔU - Q
                    W_val = known[1][1] - known[0][1] if known[0][0] == 'Q' else known[0][1] - known[1][1]
                    cycle_entries['功'].set(f"{W_val:.4f}")
                    result = f"计算结果: W = ΔU - Q = {W_val:.4f} J"
                else:
                    # 计算 ΔU = Q + W
                    delta_U_val = known[0][1] + known[1][1]
                    cycle_entries['内能变化'].set(f"{delta_U_val:.4f}")
                    result = f"计算结果: ΔU = Q + W = {delta_U_val:.4f} J"
                
                # 显示结果
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, "热力学第一定律计算:\n")
                result_text.insert(tk.END, "=" * 40 + "\n")
                result_text.insert(tk.END, f"公式: ΔU = Q + W\n")
                result_text.insert(tk.END, "=" * 40 + "\n")
                result_text.insert(tk.END, f"已知量:\n")
                for name, value in known:
                    result_text.insert(tk.END, f"  {name} = {value} J\n")
                result_text.insert(tk.END, "=" * 40 + "\n")
                result_text.insert(tk.END, f"{result}\n")
                
            except ValueError as e:
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, f"错误: {e}\n请检查输入值")
        
        # 标签3: 热力学数据表
        data_frame = tk.Frame(notebook)
        notebook.add(data_frame, text="常见热力学数据")
        
        # 常见物质的热力学数据
        thermo_data = [
            ("物质", "状态", "ΔHf⁰ (kJ/mol)", "S⁰ (J/mol·K)", "ΔGf⁰ (kJ/mol)"),
            ("H₂O", "l", "-285.8", "70.0", "-237.2"),
            ("H₂O", "g", "-241.8", "188.8", "-228.6"),
            ("CO₂", "g", "-393.5", "213.8", "-394.4"),
            ("CH₄", "g", "-74.8", "186.3", "-50.8"),
            ("C₂H₆", "g", "-84.7", "229.2", "-32.8"),
            ("NH₃", "g", "-46.1", "192.5", "-16.5"),
            ("O₂", "g", "0.0", "205.2", "0.0"),
            ("N₂", "g", "0.0", "191.6", "0.0"),
            ("H₂", "g", "0.0", "130.7", "0.0"),
            ("CO", "g", "-110.5", "197.7", "-137.2"),
            ("NO", "g", "90.3", "210.8", "86.6"),
            ("NO₂", "g", "33.2", "240.1", "51.3"),
            ("SO₂", "g", "-296.8", "248.2", "-300.1"),
            ("HCl", "g", "-92.3", "186.9", "-95.3"),
            ("NaCl", "s", "-411.2", "72.1", "-384.1"),
            ("CaCO₃", "s", "-1207.6", "92.9", "-1128.8"),
            ("CaO", "s", "-635.1", "39.7", "-604.0"),
        ]
        
        # 创建表格
        tree = ttk.Treeview(data_frame, columns=("物质", "状态", "ΔHf⁰", "S⁰", "ΔGf⁰"), show="headings")
        
        for i, col in enumerate(["物质", "状态", "ΔHf⁰", "S⁰", "ΔGf⁰"]):
            tree.heading(col, text=col)
            tree.column(col, width=100)
        
        for data in thermo_data[1:]:
            tree.insert("", tk.END, values=data)
        
        scrollbar = ttk.Scrollbar(data_frame, orient=tk.VERTICAL, command=tree.yview)
        tree.configure(yscrollcommand=scrollbar.set)
        
        tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=5, pady=5)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        # 按钮框架
        button_frame = tk.Frame(main_frame)
        button_frame.pack(pady=10)
        
        gibbs_button = tk.Button(button_frame, text="计算吉布斯自由能", command=calculate_gibbs,
                            font=('Unifont', 10), width=20)
        gibbs_button.pack(side=tk.LEFT, padx=5)
        
        cycle_button = tk.Button(button_frame, text="计算热力学循环", command=calculate_cycle,
                            font=('Unifont', 10), width=20)
        cycle_button.pack(side=tk.LEFT, padx=5)
        
        # 示例按钮
        example_button = tk.Button(button_frame, text="水生成示例",
                              command=lambda: self.load_thermo_example(gibbs_entries),
                              font=('Unifont', 10), width=15)
        example_button.pack(side=tk.LEFT, padx=5)
        
        # 结果文本框
        result_frame = tk.Frame(main_frame)
        result_frame.pack(fill=tk.BOTH, expand=True)
        
        result_text = tk.Text(result_frame, wrap=tk.WORD, font=('Unifont', 10), height=15)
        result_scrollbar = tk.Scrollbar(result_frame, orient=tk.VERTICAL, command=result_text.yview)
        result_text.configure(yscrollcommand=result_scrollbar.set)
        
        result_text.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        result_scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        result_text.insert(tk.END, "请选择计算类型并输入参数")
        
        # 关闭按钮
        close_button = tk.Button(main_frame, text="关闭", 
                            command=calculator_window.destroy,
                            font=('Unifont', 10), width=10)
        close_button.pack(pady=10)

    def load_thermo_example(self, gibbs_entries):
        """加载热力学计算示例"""
        # 水的生成反应: H₂ + 1/2O₂ → H₂O(l)
        gibbs_entries['ΔH'].set("-285.8")    # kJ/mol
        gibbs_entries['ΔS'].set("-163.2")    # J/mol·K (注意这是反应熵变，不是生成熵)
        gibbs_entries['T'].set("298.15")

    def show_quantum_chemistry_calculator(self):
        """显示量子化学计算器"""
        calculator_window = tk.Toplevel(self.root)
        calculator_window.title("量子化学计算器")
        calculator_window.geometry("700x600")
        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/physics.ico')
            calculator_window.iconphoto(True, icon_image)
        except:
            pass
        
        # 居中显示
        calculator_window.transient(self.root)
        calculator_window.grab_set()
        
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 350
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 300
        calculator_window.geometry(f"+{x}+{y}")
        
        # 创建主框架
        main_frame = tk.Frame(calculator_window)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=20, pady=20)
        
        # 标题
        title_label = tk.Label(main_frame, text="量子化学计算器", 
                          font=('Unifont', 14))
        title_label.pack(pady=(0, 15))
        
        # 量子化学公式
        equation_label = tk.Label(main_frame, 
                             text="德布罗意关系: λ = h/p = h/(mv)",
                             font=('Unifont', 11), fg='blue')
        equation_label.pack(pady=(0, 10))
        
        # 使用笔记本式布局
        notebook = ttk.Notebook(main_frame)
        notebook.pack(fill=tk.BOTH, expand=True, pady=(0, 10))
        
        # 标签1: 德布罗意波长计算
        de_broglie_frame = tk.Frame(notebook)
        notebook.add(de_broglie_frame, text="德布罗意波长")
        
        # 输入参数
        de_broglie_params_frame = tk.Frame(de_broglie_frame)
        de_broglie_params_frame.pack(fill=tk.X, pady=15)
        
        de_broglie_params = [
            ("质量 m (kg):", "9.109e-31"),
            ("速度 v (m/s):", "2.188e6"),
            ("波长 λ (m):", "")
        ]
        
        de_broglie_entries = {}
        for i, (label_text, default) in enumerate(de_broglie_params):
            frame = tk.Frame(de_broglie_params_frame)
            frame.pack(fill=tk.X, pady=5)
            
            tk.Label(frame, text=label_text, width=20, anchor='w').pack(side=tk.LEFT)
            
            var = tk.StringVar(value=default)
            entry = tk.Entry(frame, textvariable=var, width=20)
            entry.pack(side=tk.LEFT)
            
            param_name = label_text.split()[0]
            de_broglie_entries[param_name] = var
        
        # 德布罗意波长计算函数
        def calculate_de_broglie():
            try:
                h = 6.62607015e-34  # 普朗克常数 (J·s)
                
                m_str = de_broglie_entries['质量'].get()
                v_str = de_broglie_entries['速度'].get()
                lambda_str = de_broglie_entries['波长'].get()
                
                # 处理科学计数法
                def parse_sci(val):
                    if 'e' in val.lower():
                        parts = val.lower().split('e')
                        return float(parts[0]) * (10 ** float(parts[1]))
                    return float(val)
                
                known = []
                if m_str: known.append(('m', parse_sci(m_str)))
                if v_str: known.append(('v', parse_sci(v_str)))
                if lambda_str: known.append(('λ', parse_sci(lambda_str)))
                
                if len(known) != 2:
                    result_text.delete(1.0, tk.END)
                    result_text.insert(tk.END, "错误: 请填写任意两个已知量\n")
                    result_text.insert(tk.END, "公式: λ = h/(mv)")
                    return
                
                # 计算未知量
                if not m_str:
                    # 计算 m = h/(λv)
                    if 'λ' in dict(known) and 'v' in dict(known):
                        m_val = h / (dict(known)['λ'] * dict(known)['v'])
                        de_broglie_entries['质量'].set(f"{m_val:.4e}")
                        result = f"计算结果: m = h/(λv) = {m_val:.4e} kg"
                elif not v_str:
                    # 计算 v = h/(mλ)
                    if 'm' in dict(known) and 'λ' in dict(known):
                        v_val = h / (dict(known)['m'] * dict(known)['λ'])
                        de_broglie_entries['速度'].set(f"{v_val:.4e}")
                        result = f"计算结果: v = h/(mλ) = {v_val:.4e} m/s"
                else:
                    # 计算 λ = h/(mv)
                    lambda_val = h / (dict(known)['m'] * dict(known)['v'])
                    de_broglie_entries['波长'].set(f"{lambda_val:.4e}")
                    result = f"计算结果: λ = h/(mv) = {lambda_val:.4e} m"
                
                # 显示结果
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, "德布罗意波长计算:\n")
                result_text.insert(tk.END, "=" * 50 + "\n")
                result_text.insert(tk.END, f"公式: λ = h/(mv)\n")
                result_text.insert(tk.END, f"普朗克常数 h = {h:.4e} J·s\n")
                result_text.insert(tk.END, "=" * 50 + "\n")
                result_text.insert(tk.END, f"已知量:\n")
                for name, value in known:
                    result_text.insert(tk.END, f"  {name} = {value:.4e}\n")
                result_text.insert(tk.END, "=" * 50 + "\n")
                result_text.insert(tk.END, f"{result}\n")
                
            except (ValueError, ZeroDivisionError) as e:
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, f"错误: {e}\n请检查输入值")
        
        # 标签2: 氢原子能级计算
        hydrogen_frame = tk.Frame(notebook)
        notebook.add(hydrogen_frame, text="氢原子能级")
        
        # 氢原子能级公式
        hydrogen_label = tk.Label(hydrogen_frame, 
                             text="氢原子能级: Eₙ = -13.6/n² eV",
                             font=('Unifont', 11), fg='blue')
        hydrogen_label.pack(pady=10)
        
        # 输入参数
        hydrogen_params_frame = tk.Frame(hydrogen_frame)
        hydrogen_params_frame.pack(fill=tk.X, pady=10)
        
        hydrogen_params = [
            ("主量子数 n:", "1"),
            ("能级 E (eV):", "")
        ]
        
        hydrogen_entries = {}
        for i, (label_text, default) in enumerate(hydrogen_params):
            frame = tk.Frame(hydrogen_params_frame)
            frame.pack(fill=tk.X, pady=5)
            
            tk.Label(frame, text=label_text, width=15, anchor='w').pack(side=tk.LEFT)
            
            var = tk.StringVar(value=default)
            entry = tk.Entry(frame, textvariable=var, width=15)
            entry.pack(side=tk.LEFT)
            
            param_name = label_text.split()[0]
            hydrogen_entries[param_name] = var
        
        # 氢原子能级计算函数
        def calculate_hydrogen():
            try:
                n_str = hydrogen_entries['主量子数'].get()
                E_str = hydrogen_entries['能级'].get()
                
                if n_str and not E_str:
                    # 计算能级 E = -13.6/n²
                    n = float(n_str)
                    E = -13.6 / (n ** 2)
                    hydrogen_entries['能级'].set(f"{E:.4f}")
                    
                    result_text.delete(1.0, tk.END)
                    result_text.insert(tk.END, "氢原子能级计算:\n")
                    result_text.insert(tk.END, "=" * 40 + "\n")
                    result_text.insert(tk.END, f"公式: Eₙ = -13.6/n²\n")
                    result_text.insert(tk.END, f"主量子数 n = {n}\n")
                    result_text.insert(tk.END, "=" * 40 + "\n")
                    result_text.insert(tk.END, f"能级 E = -13.6/{n}² = {E:.4f} eV\n")
                    
                    # 能级示意图
                    result_text.insert(tk.END, "\n氢原子能级示意图:\n")
                    for i in range(1, 6):
                        energy = -13.6 / (i ** 2)
                        level = "n=" + str(i)
                        result_text.insert(tk.END, f"  {level:4} : {energy:7.3f} eV\n")
                    
                elif E_str and not n_str:
                    # 计算主量子数 n = sqrt(-13.6/E)
                    E = float(E_str)
                    if E >= 0:
                        result_text.delete(1.0, tk.END)
                        result_text.insert(tk.END, "错误: 氢原子能级必须为负值")
                        return
                    
                    n = math.sqrt(-13.6 / E)
                    hydrogen_entries['主量子数'].set(f"{n:.2f}")
                    
                    result_text.delete(1.0, tk.END)
                    result_text.insert(tk.END, "氢原子主量子数计算:\n")
                    result_text.insert(tk.END, "=" * 40 + "\n")
                    result_text.insert(tk.END, f"公式: n = √(-13.6/E)\n")
                    result_text.insert(tk.END, f"能级 E = {E} eV\n")
                    result_text.insert(tk.END, "=" * 40 + "\n")
                    result_text.insert(tk.END, f"主量子数 n = √(-13.6/{E}) = {n:.2f}\n")
                    result_text.insert(tk.END, f"最接近的整数: n ≈ {round(n)}\n")
                    
                else:
                    result_text.delete(1.0, tk.END)
                    result_text.insert(tk.END, "请只填写一个未知量\n")
                    result_text.insert(tk.END, "已知E求n，或已知n求E")
                    
            except ValueError as e:
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, f"错误: {e}\n请检查输入值")
        
        # 标签3: 量子数解释
        quantum_numbers_frame = tk.Frame(notebook)
        notebook.add(quantum_numbers_frame, text="量子数")
        
        # 量子数说明
        quantum_text = tk.Text(quantum_numbers_frame, wrap=tk.WORD, font=('Unifont', 10), height=15)
        quantum_scrollbar = tk.Scrollbar(quantum_numbers_frame, orient=tk.VERTICAL, command=quantum_text.yview)
        quantum_text.configure(yscrollcommand=quantum_scrollbar.set)
        
        quantum_text.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        quantum_scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        quantum_info = """量子数说明:

    1. 主量子数 (n)
       - 描述电子层大小和能量
       - 取值范围: n = 1, 2, 3, ...
       - 对应电子层: K, L, M, N, ...

    2. 角量子数 (l)
       - 描述轨道形状
       - 取值范围: l = 0, 1, 2, ..., n-1
       - 对应轨道: s(l=0), p(l=1), d(l=2), f(l=3)

    3. 磁量子数 (mₗ)
       - 描述轨道空间取向
       - 取值范围: mₗ = -l, -l+1, ..., 0, ..., l-1, l

    4. 自旋量子数 (mₛ)
       - 描述电子自旋方向
       - 取值范围: mₛ = +1/2 或 -1/2

    轨道填充规则:
    • 每个轨道最多容纳2个电子
    • 能量最低原理
    • 泡利不相容原理
    • 洪特规则

    示例轨道:
    1s²: n=1, l=0, 容纳2电子
    2p⁶: n=2, l=1, 容纳6电子
    3d¹⁰: n=3, l=2, 容纳10电子

    量子数组合数量:
    • 对于给定的n: 有n²个轨道
    • 每个轨道: 最多2个电子
    • 总计: 2n²个电子
    """
        
        quantum_text.insert(tk.END, quantum_info)
        quantum_text.config(state=tk.DISABLED)
        
        # 按钮框架
        button_frame = tk.Frame(main_frame)
        button_frame.pack(pady=10)
        
        de_broglie_button = tk.Button(button_frame, text="德布罗意波长", command=calculate_de_broglie,
                                 font=('Unifont', 10), width=15)
        de_broglie_button.pack(side=tk.LEFT, padx=5)
        
        hydrogen_button = tk.Button(button_frame, text="氢原子能级", command=calculate_hydrogen,
                               font=('Unifont', 10), width=15)
        hydrogen_button.pack(side=tk.LEFT, padx=5)
        
        # 示例按钮
        electron_example_button = tk.Button(button_frame, text="电子示例",
                                       command=lambda: self.load_quantum_example(de_broglie_entries),
                                       font=('Unifont', 10), width=15)
        electron_example_button.pack(side=tk.LEFT, padx=5)
        
        # 结果文本框
        result_frame = tk.Frame(main_frame)
        result_frame.pack(fill=tk.BOTH, expand=True)
        
        result_text = tk.Text(result_frame, wrap=tk.WORD, font=('Unifont', 10), height=12)
        result_scrollbar = tk.Scrollbar(result_frame, orient=tk.VERTICAL, command=result_text.yview)
        result_text.configure(yscrollcommand=result_scrollbar.set)
        
        result_text.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        result_scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        result_text.insert(tk.END, "请选择计算类型并输入参数")
        
        # 关闭按钮
        close_button = tk.Button(main_frame, text="关闭", 
                            command=calculator_window.destroy,
                            font=('Unifont', 10), width=10)
        close_button.pack(pady=10)

    def load_quantum_example(self, de_broglie_entries):
        """加载量子化学计算示例"""
        # 氢原子中电子的德布罗意波长
        de_broglie_entries['质量'].set("9.109e-31")    # 电子质量
