    def show_uncertainty_analyzer(self):
        """不确定度分析器"""
        uncertainty_window = tk.Toplevel(self.root)
        uncertainty_window.title("不确定度分析")
        uncertainty_window.geometry("450x600")
        uncertainty_window.resizable(False, False)
        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/analyze.ico')
            uncertainty_window.iconphoto(True, icon_image)
        except:
            pass
        
        # 居中显示
        uncertainty_window.transient(self.root)
        uncertainty_window.grab_set()
        
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 225
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 300
        uncertainty_window.geometry(f"+{x}+{y}")
        
        # 主框架
        main_frame = tk.Frame(uncertainty_window, padx=20, pady=15)
        main_frame.pack(fill=tk.BOTH, expand=True)
        
        # 标题
        tk.Label(main_frame, text="不确定度分析", 
                font=('Unifont', 12)).pack(pady=(0, 10))
        
        # 数据输入区域
        data_frame = tk.Frame(main_frame)
        data_frame.pack(fill=tk.X, pady=5)
        
        # 数据列表
        tk.Label(data_frame, text="测量数据列表:").pack(anchor='w')
        
        listbox_frame = tk.Frame(data_frame)
        listbox_frame.pack(fill=tk.X, pady=5)
        
        data_listbox = tk.Listbox(listbox_frame, height=6, width=20)
        scrollbar = tk.Scrollbar(listbox_frame, command=data_listbox.yview)
        data_listbox.configure(yscrollcommand=scrollbar.set)
        
        data_listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        # 数据输入控件
        input_controls = tk.Frame(data_frame)
        input_controls.pack(fill=tk.X, pady=5)
        
        tk.Label(input_controls, text="数据值:").pack(side=tk.LEFT)
        
        data_var = tk.StringVar()
        tk.Entry(input_controls, textvariable=data_var, width=15).pack(side=tk.LEFT, padx=5)
        
        def add_data():
            try:
                value = float(data_var.get())
                data_listbox.insert(tk.END, f"{value:.4f}")
                data_var.set("")
            except ValueError:
                tk.messagebox.showerror("错误", "请输入有效数字")
        
        tk.Button(input_controls, text="添加", command=add_data).pack(side=tk.LEFT, padx=5)
        
        def remove_data():
            selected = data_listbox.curselection()
            if selected:
                data_listbox.delete(selected)
        
        tk.Button(input_controls, text="删除", command=remove_data).pack(side=tk.LEFT, padx=5)
        
        def clear_all_data():
            data_listbox.delete(0, tk.END)
        
        tk.Button(input_controls, text="清空", command=clear_all_data).pack(side=tk.LEFT, padx=5)
        
        # 置信水平选择
        conf_frame = tk.Frame(main_frame)
        conf_frame.pack(fill=tk.X, pady=10)
        
        tk.Label(conf_frame, text="置信水平:").pack(side=tk.LEFT)
        
        conf_var = tk.StringVar(value="95")
        conf_options = ["90", "95", "99"]
        for option in conf_options:
            tk.Radiobutton(conf_frame, text=f"{option}%", variable=conf_var, 
                          value=option).pack(side=tk.LEFT, padx=5)
        
        # 计算按钮
        def calculate_uncertainty():
            # 获取数据
            data = []
            for i in range(data_listbox.size()):
                try:
                    value = float(data_listbox.get(i))
                    data.append(value)
                except:
                    continue
            
            if len(data) < 2:
                tk.messagebox.showerror("错误", "至少需要2个测量值")
                return
            
            # 计算统计量
            n = len(data)
            mean = sum(data) / n
            
            # 标准差
            if n > 1:
                variance = sum((x - mean) ** 2 for x in data) / (n - 1)
                std_dev = math.sqrt(variance)
                std_err = std_dev / math.sqrt(n)
            else:
                std_dev = 0
                std_err = 0
            
            # 置信区间（简化计算）
            conf_level = float(conf_var.get()) / 100
            alpha = 1 - conf_level
            
            # t值表（简化）
            t_values = {0.90: 1.645, 0.95: 1.960, 0.99: 2.576}
            t_value = t_values.get(conf_level, 1.960)
            
            margin_error = t_value * std_err
            ci_lower = mean - margin_error
            ci_upper = mean + margin_error
            
            # 相对不确定度
            rel_uncertainty = (std_err / mean * 100) if mean != 0 else 0
            
            # 显示结果
            result = f"统计分析结果:\n\n"
            result += f"测量次数 (n): {n}\n"
            result += f"平均值 (x̄): {mean:.4f}\n"
            result += f"标准偏差 (s): {std_dev:.4f}\n"
            result += f"相对标准偏差 (RSD): {std_dev/mean*100:.2f}%\n\n"
            result += f"标准不确定度 (u): {std_err:.4f}\n"
            result += f"相对不确定度: {rel_uncertainty:.2f}%\n\n"
            result += f"{conf_var.get()}% 置信区间:\n"
            result += f"  ({ci_lower:.4f}, {ci_upper:.4f})\n"
            result += f"  区间宽度: {ci_upper-ci_lower:.4f}"
            
            result_text.delete(1.0, tk.END)
            result_text.insert(tk.END, result)
        
        tk.Button(main_frame, text="计算不确定度", command=calculate_uncertainty,
                 width=15).pack(pady=10)
        
        # 结果区域
        result_frame = tk.Frame(main_frame)
        result_frame.pack(fill=tk.BOTH, expand=True)
        
        result_text = tk.Text(result_frame, height=12, width=40, 
                             font=('Unifont', 9), wrap=tk.WORD)
        scrollbar = tk.Scrollbar(result_frame, command=result_text.yview)
        result_text.configure(yscrollcommand=scrollbar.set)
        
        result_text.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

    def show_standard_solution_prep(self):
        """标准溶液配制计算器"""
        prep_window = tk.Toplevel(self.root)
        prep_window.title("标准溶液配制")
        prep_window.geometry("400x500")
        prep_window.resizable(False, False)
        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/analyze.ico')
            prep_window.iconphoto(True, icon_image)
        except:
            pass
        
        # 居中显示
        prep_window.transient(self.root)
        prep_window.grab_set()
        
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 200
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 250
        prep_window.geometry(f"+{x}+{y}")
        
        # 主框架
        main_frame = tk.Frame(prep_window, padx=20, pady=15)
        main_frame.pack(fill=tk.BOTH, expand=True)
        
        # 标题
        tk.Label(main_frame, text="标准溶液配制", 
                font=('Unifont', 12)).pack(pady=(0, 10))
        
        # 输入区域
        input_frame = tk.Frame(main_frame)
        input_frame.pack(fill=tk.X, pady=5)
        
        # 目标浓度
        tk.Label(input_frame, text="目标浓度 (mol/L):", width=15, anchor='w').grid(row=0, column=0, pady=3, sticky='w')
        target_conc_var = tk.StringVar(value="0.1")
        tk.Entry(input_frame, textvariable=target_conc_var, width=12).grid(row=0, column=1, padx=5)
        
        # 目标体积
        tk.Label(input_frame, text="目标体积 (mL):", width=15, anchor='w').grid(row=1, column=0, pady=3, sticky='w')
        target_vol_var = tk.StringVar(value="1000")
        tk.Entry(input_frame, textvariable=target_vol_var, width=12).grid(row=1, column=1, padx=5)
        
        # 摩尔质量
        tk.Label(input_frame, text="摩尔质量 (g/mol):", width=15, anchor='w').grid(row=2, column=0, pady=3, sticky='w')
        molar_mass_var = tk.StringVar(value="40.00")  # NaOH
        tk.Entry(input_frame, textvariable=molar_mass_var, width=12).grid(row=2, column=1, padx=5)
        
        # 纯度
        tk.Label(input_frame, text="试剂纯度 (%):", width=15, anchor='w').grid(row=3, column=0, pady=3, sticky='w')
        purity_var = tk.StringVar(value="99.5")
        tk.Entry(input_frame, textvariable=purity_var, width=12).grid(row=3, column=1, padx=5)
        
        # 配制方式选择
        tk.Label(input_frame, text="配制方式:", width=15, anchor='w').grid(row=4, column=0, pady=3, sticky='w')
        method_var = tk.StringVar(value="direct")
        
        method_frame = tk.Frame(input_frame)
        method_frame.grid(row=4, column=1, columnspan=2, sticky='w', padx=5)
        
        tk.Radiobutton(method_frame, text="直接配制", variable=method_var, 
                      value="direct").pack(side=tk.LEFT, padx=5)
        tk.Radiobutton(method_frame, text="稀释配制", variable=method_var, 
                      value="dilution").pack(side=tk.LEFT, padx=5)
        
        # 母液浓度（仅稀释时需要）
        tk.Label(input_frame, text="母液浓度 (mol/L):", width=15, anchor='w').grid(row=5, column=0, pady=3, sticky='w')
        stock_conc_var = tk.StringVar(value="1.0")
        tk.Entry(input_frame, textvariable=stock_conc_var, width=12, 
                state='disabled').grid(row=5, column=1, padx=5)
        
        def toggle_method():
            if method_var.get() == "dilution":
                stock_conc_entry.config(state='normal')
            else:
                stock_conc_entry.config(state='disabled')
        
        method_var.trace('w', lambda *args: toggle_method())
        
        stock_conc_entry = tk.Entry(input_frame, textvariable=stock_conc_var, width=12, 
                                   state='disabled')
        stock_conc_entry.grid(row=5, column=1, padx=5)
        
        # 计算按钮
        def calculate_preparation():
            try:
                target_conc = float(target_conc_var.get())
                target_vol_ml = float(target_vol_var.get())
                molar_mass = float(molar_mass_var.get())
                purity = float(purity_var.get()) / 100  # 转换为小数
                
                method = method_var.get()
                
                if method == "direct":
                    # 直接配制
                    # 所需物质的量
                    moles_needed = target_conc * (target_vol_ml / 1000)
                    
                    # 所需纯物质质量
                    pure_mass_needed = moles_needed * molar_mass
                    
                    # 实际称取质量（考虑纯度）
                    actual_mass = pure_mass_needed / purity
                    
                    result = f"直接配制方案:\n\n"
                    result += f"目标浓度: {target_conc} mol/L\n"
                    result += f"目标体积: {target_vol_ml} mL\n"
                    result += f"摩尔质量: {molar_mass} g/mol\n"
                    result += f"试剂纯度: {purity*100:.1f}%\n\n"
                    result += f"计算结果:\n"
                    result += f"所需物质的量: {moles_needed:.4f} mol\n"
                    result += f"理论称取质量: {pure_mass_needed:.4f} g\n"
                    result += f"实际称取质量: {actual_mass:.4f} g\n\n"
                    result += f"操作步骤:\n"
                    result += f"1. 准确称取 {actual_mass:.4f} g 试剂\n"
                    result += f"2. 用少量溶剂溶解\n"
                    result += f"3. 转移至 {target_vol_ml} mL 容量瓶\n"
                    result += f"4. 定容，摇匀"
                    
                else:
                    # 稀释配制
                    stock_conc = float(stock_conc_var.get())
                    
                    # 所需母液体积
                    stock_volume = (target_conc * target_vol_ml) / stock_conc
                    
                    # 配制母液所需质量（如果也需要计算）
                    moles_stock = stock_conc * (stock_volume / 1000)
                    mass_stock = (moles_stock * molar_mass) / purity
                    
                    result = f"稀释配制方案:\n\n"
                    result += f"目标浓度: {target_conc} mol/L\n"
                    result += f"目标体积: {target_vol_ml} mL\n"
                    result += f"母液浓度: {stock_conc} mol/L\n\n"
                    result += f"计算结果:\n"
                    result += f"所需母液体积: {stock_volume:.2f} mL\n\n"
                    result += f"操作步骤:\n"
                    result += f"1. 移取 {stock_volume:.2f} mL 母液\n"
                    result += f"2. 转移至 {target_vol_ml} mL 容量瓶\n"
                    result += f"3. 定容，摇匀\n\n"
                    result += f"母液配制参考:\n"
                    result += f"需称取 {mass_stock:.4f} g 试剂配制成 {stock_volume:.0f} mL {stock_conc} mol/L 溶液"
                
                result_text.delete(1.0, tk.END)
                result_text.insert(tk.END, result)
                
            except ValueError:
                tk.messagebox.showerror("错误", "请输入有效的数字")
        
        button_frame = tk.Frame(main_frame)
        button_frame.pack(pady=10)
        
        tk.Button(button_frame, text="计算", command=calculate_preparation,
                 width=10).pack(side=tk.LEFT, padx=5)
        
        # 预设物质
        def set_preset(name, mm):
            molar_mass_var.set(str(mm))
        
        preset_frame = tk.Frame(button_frame)
        preset_frame.pack(side=tk.LEFT, padx=10)
        
        tk.Label(preset_frame, text="预设:").pack(side=tk.LEFT)
        
        presets = [("NaOH", "40.00"), ("HCl", "36.46"), 
                   ("NaCl", "58.44"), ("KHP", "204.22")]
        
        for name, mm in presets:
            tk.Button(preset_frame, text=name, width=5,
                     command=lambda m=mm: molar_mass_var.set(m)).pack(side=tk.LEFT, padx=2)
        
        # 结果区域
        result_frame = tk.Frame(main_frame)
        result_frame.pack(fill=tk.BOTH, expand=True, pady=(10, 0))
        
        result_text = tk.Text(result_frame, height=12, width=35, 
                             font=('Unifont', 9), wrap=tk.WORD)
        scrollbar = tk.Scrollbar(result_frame, command=result_text.yview)
        result_text.configure(yscrollcommand=scrollbar.set)
        
        result_text.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

