        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 350
        viewer_window.geometry(f"+{x}+{y}")
        
        # 创建主框架
        main_frame = tk.Frame(viewer_window)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
        
        # 标题和控制栏
        control_frame = tk.Frame(main_frame)
        control_frame.pack(fill=tk.X, pady=(0, 10))
        
        title_label = tk.Label(control_frame, text="表形式查看器", 
                              font=('Unifont', 14))
        title_label.pack(side=tk.LEFT)
        
        # 表形式选择
        form_frame = tk.Frame(control_frame)
        form_frame.pack(side=tk.RIGHT)
        
        tk.Label(form_frame, text="表形式:", font=('Unifont', 10)).pack(side=tk.LEFT, padx=(0, 5))
        
        # 表形式选项
        table_forms = ["标准表", "大表", "短式表"]
        self.table_form_var = tk.StringVar(value="标准表")
        
        for form in table_forms:
            tk.Radiobutton(form_frame, text=form, variable=self.table_form_var, 
                          value=form, font=('Unifont', 9),
                          command=self.update_table_view).pack(side=tk.LEFT, padx=5)
        
        # 创建表格显示区域
        self.viewer_table_frame = tk.Frame(main_frame, bg='white', relief=tk.SUNKEN, bd=2)
