    def update_table_view(self):
        """根据选择的表形式更新显示"""
        # 清空当前表格
        for widget in self.viewer_table_frame.winfo_children():
            widget.destroy()
        
        form = self.table_form_var.get()
        
        if form == "标准表":
            self.show_standard_table()
        elif form == "大表":
            self.show_large_table()
        elif form == "短式表":
            self.show_short_table()

