    def create_viewer_table(self, layout, title=""):
        """在查看器中创建指定布局的表格"""
        # 添加标题
        if title:
            title_label = tk.Label(self.viewer_table_frame, text=title, 
                                  font=('Unifont', 12),
                                  bg='white')
            title_label.grid(row=0, column=0, columnspan=len(layout[0]) if layout else 18, 
                            pady=(5, 10), sticky='n')
        
        # 创建状态栏用于查看器内部
        viewer_status = tk.Label(self.viewer_table_frame, 
                               text="点击元素查看详细信息", 
                               relief=tk.SUNKEN, anchor=tk.W,
                               bg='white')
        viewer_status.grid(row=len(layout)+2, column=0, 
                          columnspan=len(layout[0]) if layout else 18,
                          sticky='ew', pady=(10, 0))
        
        # 创建按钮网格
        for i, row in enumerate(layout, start=1):  # 从第1行开始，第0行是标题
            for j, symbol in enumerate(row):
                if symbol and symbol in self.elements:
                    btn = ElementButton(self.viewer_table_frame, symbol, self.elements, viewer_status, self)
                    btn.grid(row=i, column=j, padx=2, pady=2, sticky='nsew')
                    
                    # 设置网格权重，使按钮均匀分布
                    self.viewer_table_frame.grid_columnconfigure(j, weight=1)
                elif symbol and symbol.startswith('*'):
                    # 处理带星号的元素（如*La表示镧系位置）
                    actual_symbol = symbol.replace('*', '')
                    if actual_symbol in self.elements:
                        btn = ElementButton(self.viewer_table_frame, actual_symbol, self.elements, viewer_status, self)
                        btn.grid(row=i, column=j, padx=2, pady=2, sticky='nsew')
                        
                        # 添加星号标记
                        star_label = tk.Label(self.viewer_table_frame, text="*", 
                                            font=('Unifont', 8), fg='red',
                                            bg='white')
                        star_label.grid(row=i, column=j, sticky='ne', padx=(0, 2), pady=(2, 0))
                        
                        self.viewer_table_frame.grid_columnconfigure(j, weight=1)
                    else:
                        # 空单元格
                        empty = tk.Label(self.viewer_table_frame, text="", 
                                       width=5, height=2, bg='white')
                        empty.grid(row=i, column=j, padx=2, pady=2)
                else:
                    # 空单元格
                    empty = tk.Label(self.viewer_table_frame, text="", 
                                   width=5, height=2, bg='white')
                    empty.grid(row=i, column=j, padx=2, pady=2)
        
        # 设置行权重
        for i in range(len(layout) + 3):  # 包括标题行和状态栏
            self.viewer_table_frame.grid_rowconfigure(i, weight=1 if i>0 and i<=len(layout) else 0)

