    def populate_country_list(self):
        """填充国家列表"""
        self.country_listbox.delete(0, tk.END)
        
        # 按字母顺序排序
        sorted_countries = sorted(self.country_elements_data.keys())
        
        for country in sorted_countries:
            # 获取元素数量
            element_count = len(self.country_elements_data[country])
            display_text = f"{country} ({element_count}种)"
            self.country_listbox.insert(tk.END, display_text)

    def filter_countries_list(self, keyword):
        """根据关键词筛选国家列表"""
        self.country_listbox.delete(0, tk.END)
        
        sorted_countries = sorted(self.country_elements_data.keys())
        filtered_count = 0
        
        for country in sorted_countries:
            if not keyword or keyword.lower() in country.lower():
                element_count = len(self.country_elements_data[country])
                display_text = f"{country} ({element_count}种)"
                self.country_listbox.insert(tk.END, display_text)
                filtered_count += 1
        
        if keyword:
            self.stats_label.config(text=f"找到 {filtered_count} 个包含 '{keyword}' 的国家/地区", fg='green')
        else:
            self.stats_label.config(text=f"共 {len(self.country_elements_data)} 个国家/地区", fg='blue')

    def on_country_selected(self, event):
        """国家选择事件处理"""
        selection = self.country_listbox.curselection()
        if not selection:
            return
        
        # 获取选中的国家
        index = selection[0]
        selected_text = self.country_listbox.get(index)
        country_name = selected_text.split(" (")[0]  # 提取国家名称
        
        # 显示国家详情
        self.show_country_detail(country_name)

    def show_country_detail(self, country_name):
        """显示国家详细信息"""
        # 移除初始提示
        if hasattr(self, 'initial_label') and self.initial_label:
            self.initial_label.destroy()
        
        # 清除旧的详情内容
        if self.detail_canvas:
            self.detail_canvas.destroy()
        if self.detail_scrollbar:
            self.detail_scrollbar.destroy()
        
        # 获取该国的元素数据
        if country_name not in self.country_elements_data:
            error_label = tk.Label(self.detail_frame, text=f"找不到国家: {country_name}",
                                 font=('Unifont', 12), fg='red')
            error_label.pack(pady=50)
            return
        
        elements = self.country_elements_data[country_name]
        
        # 创建滚动框架
        self.detail_canvas = tk.Canvas(self.detail_frame, bg='white')
        self.detail_scrollbar = tk.Scrollbar(self.detail_frame, orient=tk.VERTICAL, 
                                            command=self.detail_canvas.yview)
        scrollable_frame = tk.Frame(self.detail_canvas)
        
        scrollable_frame.bind(
            "<Configure>",
            lambda e: self.detail_canvas.configure(scrollregion=self.detail_canvas.bbox("all"))
        )
        
        self.detail_canvas.create_window((0, 0), window=scrollable_frame, anchor="nw")
        self.detail_canvas.configure(yscrollcommand=self.detail_scrollbar.set)
        
        self.detail_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        self.detail_scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        
        # === 显示国家详细信息 ===
        
        # 国家标题
        title_frame = tk.Frame(scrollable_frame, bg='#E9ECEF', height=40)
        title_frame.pack(fill=tk.X, pady=(0, 10))
        title_frame.pack_propagate(False)
        
        country_label = tk.Label(title_frame, text=f"🏴 {country_name}", 
                                font=('Unifont', 14),
                                bg='#E9ECEF',
                                fg='#2C3E50')
        country_label.pack(side=tk.LEFT, padx=15, pady=5)
        
        # 元素数量统计
        count_label = tk.Label(title_frame, 
                              text=f"出产元素: {len(elements)} 种",
                              font=('Unifont', 11),
                              bg='#E9ECEF',
                              fg='#6C757D')
        count_label.pack(side=tk.RIGHT, padx=15, pady=5)
        
        # 元素展示区域
        elements_frame = tk.LabelFrame(scrollable_frame, text=" 出产元素列表 ",
                                     font=('Unifont', 12),
                                     relief=tk.GROOVE, bd=2)
        elements_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
        
        # 创建元素按钮网格
        row_size = 6  # 每行显示6个元素
        for i, element_symbol in enumerate(elements):
            row = i // row_size
            col = i % row_size
            
            element_frame = tk.Frame(elements_frame)
            element_frame.grid(row=row, column=col, padx=8, pady=8)
            
            if element_symbol in self.elements:
                element_data = self.elements[element_symbol]
                element_name = element_data['name']
                
                # 元素信息卡片
                card_frame = tk.Frame(element_frame, relief=tk.RAISED, bd=2, 
                                    bg=self.get_element_color(element_data['category']))
                card_frame.pack()
                
                # 元素符号（大字体）
                symbol_label = tk.Label(card_frame, text=element_symbol,
                                      font=('Unifont', 14),
                                      bg=self.get_element_color(element_data['category']),
                                      fg='white',
                                      width=4)
                symbol_label.pack(pady=(5, 2))
                
                # 元素名称
                name_label = tk.Label(card_frame, text=element_name,
                                    font=('Unifont', 9),
                                    bg=self.get_element_color(element_data['category']),
                                    fg='white')
                name_label.pack(pady=(0, 5))
                
                # 查看按钮
                view_btn = tk.Button(element_frame, text="查看",
                                   command=lambda sym=element_symbol: self.show_element_info(sym),
                                   font=('Unifont', 8),
                                   bg='#4CAF50', fg='white')
                view_btn.pack(fill=tk.X)
                
            else:
                # 未知元素
                unknown_frame = tk.Frame(element_frame, relief=tk.RAISED, bd=2, 
                                       bg='#E9ECEF')
                unknown_frame.pack()
                
                symbol_label = tk.Label(unknown_frame, text=element_symbol,
                                      font=('Unifont', 14),
                                      bg='#E9ECEF',
                                      fg='#6C757D',
                                      width=4)
                symbol_label.pack(pady=(5, 2))
                
                name_label = tk.Label(unknown_frame, text="(未知)",
                                    font=('Unifont', 9),
                                    bg='#E9ECEF',
                                    fg='#6C757D')
                name_label.pack(pady=(0, 5))
        
        # 如果元素数量不是row_size的倍数，填充空白
        remainder = len(elements) % row_size
        if remainder != 0:
            for col in range(remainder, row_size):
                empty_frame = tk.Frame(elements_frame, width=80, height=100)
                empty_frame.grid(row=len(elements) // row_size, column=col)
        
        # 国家矿产资源概况
        overview_frame = tk.LabelFrame(scrollable_frame, text=" 矿产资源概况 ",
                                     font=('Unifont', 12),
                                     relief=tk.GROOVE, bd=2)
        overview_frame.pack(fill=tk.X, padx=10, pady=(10, 5))
        
        # 生成矿产资源概况
        overview_text = self.generate_mineral_overview(country_name, elements)
        overview_label = tk.Label(overview_frame, text=overview_text,
                                font=('Unifont', 10),
                                justify=tk.LEFT,
                                wraplength=500)
        overview_label.pack(padx=10, pady=10)
        
        # 地理分布信息
        geo_frame = tk.LabelFrame(scrollable_frame, text=" 地理分布特点 ",
                                font=('Unifont', 12),
                                relief=tk.GROOVE, bd=2)
        geo_frame.pack(fill=tk.X, padx=10, pady=5)
        
        geo_text = self.generate_geographic_info(country_name, elements)
        geo_label = tk.Label(geo_frame, text=geo_text,
                            font=('Unifont', 10),
                            justify=tk.LEFT,
                            wraplength=500)
        geo_label.pack(padx=10, pady=10)

    def generate_mineral_overview(self, country_name, elements):
        """生成矿产资源概况"""
        # 统计不同类型的元素
        metal_count = 0
        nonmetal_count = 0
        rare_count = 0
        
        for symbol in elements:
            if symbol in self.elements:
                category = self.elements[symbol]['category']
                if '金属' in category:
                    metal_count += 1
                else:
                    nonmetal_count += 1
                
                if symbol in ['Au', 'Ag', 'Pt', 'Pd', 'Rh', 'Ir', 'Os', 'Ru']:
                    rare_count += 1
        
        overview = f"{country_name} 的矿产资源特点:\n\n"
        overview += f"• 金属矿产: {metal_count} 种\n"
        overview += f"• 非金属矿产: {nonmetal_count} 种\n"
        
        if rare_count > 0:
            overview += f"• 贵金属矿产: {rare_count} 种\n"
        
        # 判断资源丰富程度
        total = len(elements)
        if total >= 15:
            overview += f"• 资源丰富度: ⭐⭐⭐⭐⭐ (非常丰富)\n"
        elif total >= 10:
            overview += f"• 资源丰富度: ⭐⭐⭐⭐ (丰富)\n"
        elif total >= 5:
            overview += f"• 资源丰富度: ⭐⭐⭐ (中等)\n"
        else:
            overview += f"• 资源丰富度: ⭐⭐ (较少)\n"
        
        # 主要矿产类型
        if metal_count > nonmetal_count:
            overview += f"• 主要矿产类型: 金属矿产为主\n"
        else:
            overview += f"• 主要矿产类型: 非金属矿产为主\n"
        
        return overview

