    def load_substance_data_for_display(self):
        """从文件加载物质数据，返回包含名称和描述的字典列表"""
        substance_file = "./res/data/substance_data.txt"
        substances = []
        
        try:
            if os.path.exists(substance_file):
                with open(substance_file, 'r', encoding='utf-8') as file:
                    for line_num, line in enumerate(file, 1):
                        line = line.strip()
                        # 跳过空行和注释行
                        if line and not line.startswith('#'):
                            # 按竖线分割名称和描述
                            if '|' in line:
                                name, description = line.split('|', 1)
                                substances.append({
                                    'name': name.strip(),
                                    'description': description.strip()
                                })
                            else:
                                # 如果没有竖线，整行作为名称，描述为空
                                substances.append({
                                    'name': line.strip(),
                                    'description': '暂无描述'
                                })
                
                # 按名称排序
                substances.sort(key=lambda x: x['name'])
                
            else:
                # 如果文件不存在，创建示例文件
                self.create_example_substance_file(substance_file)
                substances = self.load_substance_data_for_display()  # 重新加载
                
        except Exception as e:
            print(f"读取物质数据文件失败: {str(e)}")
            # 返回空列表而不是示例数据
            substances = []
        
        return substances

    def filter_substances(self, keyword, listbox, status_label):
        """根据关键词筛选物质"""
        listbox.delete(0, tk.END)
        
        filtered_count = 0
        for substance in self.all_substances:
            # 在名称和描述中搜索关键词
            if (not keyword or 
                keyword.lower() in substance['name'].lower() or 
                keyword.lower() in substance['description'].lower()):
                
                display_text = f"{substance['name']} - {substance['description']}"
                listbox.insert(tk.END, display_text)
                filtered_count += 1
        
        if keyword:
            status_label.config(text=f"找到 {filtered_count} 个包含 '{keyword}' 的物质", fg='green')
        else:
            status_label.config(text=f"显示所有 {filtered_count} 种物质", fg='blue')

