    def refresh_plugins(self):
        """刷新插件列表"""
        # 清空树形视图
        for item in self.plugin_tree.get_children():
            self.plugin_tree.delete(item)
        
        # 发现插件
        self.plugin_manager.discover_plugins()
        plugins_info = self.plugin_manager.get_all_plugins_info()
        
        # 添加插件到列表
        for plugin_name, info in plugins_info.items():
            status = "✅ 已加载" if info['loaded'] else "❌ 未加载"
            
            self.plugin_tree.insert('', 'end', values=(
                plugin_name,
                status,
                info.get('version', '未知'),
                info.get('author', '未知'),
                info.get('description', '无描述')
            ))
        
        self.plugin_status.config(text=f"发现 {len(plugins_info)} 个插件")

    def on_plugin_select(self, event):
        """插件选择事件"""
        selection = self.plugin_tree.selection()
        if selection:
            item = selection[0]
            plugin_name = self.plugin_tree.item(item, 'values')[0]
            plugin_info = self.plugin_manager.get_plugin_info(plugin_name)
            
            # 更新按钮状态
            if plugin_info['loaded']:
                self.load_btn.config(state=tk.DISABLED)
                self.unload_btn.config(state=tk.NORMAL)
            else:
                self.load_btn.config(state=tk.NORMAL)
                self.unload_btn.config(state=tk.DISABLED)
            
            self.info_btn.config(state=tk.NORMAL)
        else:
            self.load_btn.config(state=tk.DISABLED)
            self.unload_btn.config(state=tk.DISABLED)
            self.info_btn.config(state=tk.DISABLED)

    def load_selected_plugin(self):
        """加载选中的插件"""
        selection = self.plugin_tree.selection()
        if selection:
            plugin_name = self.plugin_tree.item(selection[0], 'values')[0]
            success, message = self.plugin_manager.load_plugin(plugin_name)
            
            self.plugin_status.config(text=message, fg='green' if success else 'red')
            
            if success:
                # 刷新列表显示新状态
                self.refresh_plugins()

    def unload_selected_plugin(self):
        """卸载选中的插件"""
        selection = self.plugin_tree.selection()
        if selection:
            plugin_name = self.plugin_tree.item(selection[0], 'values')[0]
            success, message = self.plugin_manager.unload_plugin(plugin_name)
            
            self.plugin_status.config(text=message, fg='green' if success else 'red')
            
            if success:
                # 刷新列表显示新状态
                self.refresh_plugins()

    def show_plugin_info(self):
        """显示插件详细信息"""
        selection = self.plugin_tree.selection()
        if selection:
            plugin_name = self.plugin_tree.item(selection[0], 'values')[0]
            plugin_info = self.plugin_manager.get_plugin_info(plugin_name)
            
            info_window = tk.Toplevel(self.root)
            info_window.title(f"插件信息 - {plugin_name}")
            info_window.geometry("500x400")
            
            # 创建信息文本
            info_text = f"""插件名称: {plugin_info['name']}
    状态: {'✅ 已加载' if plugin_info['loaded'] else '❌ 未加载'}
    版本: {plugin_info.get('version', '未知')}
    作者: {plugin_info.get('author', '未知')}

    描述:
    {plugin_info.get('description', '无描述')}

    路径: {self.plugin_manager.plugins.get(plugin_name, '未知')}
    """
            
            text_widget = tk.Text(info_window, wrap=tk.WORD, font=('Unifont', 10))
            text_widget.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
            text_widget.insert(tk.END, info_text)
            text_widget.config(state=tk.DISABLED)
            
            close_btn = tk.Button(info_window, text="关闭", 
                                command=info_window.destroy,
                                font=('Unifont', 10))
            close_btn.pack(pady=10)

    def create_plugin_template(self):
        """创建插件模板文件"""
        template_content = '''"""
    示例插件 - 插件开发模板
    """

    import tkinter as tk
    from tkinter import messagebox

    class ExamplePlugin:
        """示例插件类"""
        
        # 插件标识
        is_plugin = True
        
        def __init__(self, app):
            """
            初始化插件
            
            Args:
                app: 主应用程序实例
            """
            self.app = app
            self.name = "示例插件"
            self.version = "1.0.0"
            self.author = "开发者名称"
            self.description = "这是一个示例插件"
        
        def get_metadata(self):
            """获取插件元数据"""
            return {
                'name': self.name,
                'version': self.version,
                'author': self.author,
                'description': self.description
            }
        
        def initialize(self):
            """插件初始化"""
            # 在这里添加插件初始化代码
            # 例如：注册菜单项、绑定事件等
            
            # 示例：在工具菜单中添加插件菜单项
            if hasattr(self.app, 'tools_menu'):
                self.app.tools_menu.add_command(
                    label="示例插件功能",
                    command=self.show_example_dialog
                )
            
            print(f"插件 {self.name} 初始化完成")
        
        def cleanup(self):
            """插件清理"""
            # 在这里清理插件资源
            # 例如：移除菜单项、取消事件绑定等
            print(f"插件 {self.name} 已清理")
        
        def show_example_dialog(self):
            """显示示例对话框"""
            messagebox.showinfo("示例插件", "这是示例插件的功能！")
        
        # 可以添加更多插件方法...
        def custom_method(self, data):
            """自定义方法示例"""
            return f"处理数据: {data}"

    # 插件必须有一个主要的插件类
    # 类名可以自定义，但必须包含 is_plugin = True 属性
    '''
        
        template_path = os.path.join(self.plugin_manager.plugins_dir, "example_plugin.py")
        
        try:
            with open(template_path, 'w', encoding='utf-8') as f:
                f.write(template_content)
            
            messagebox.showinfo("成功", f"插件模板已创建到: {template_path}")
            self.refresh_plugins()
        except Exception as e:
            messagebox.showerror("错误", f"创建模板失败: {str(e)}")

