    def show_organic_molecule_builder(self):
        """显示有机物分子搭建器 - 简化自定义版本"""
        builder_window = tk.Toplevel(self.root)
        builder_window.title("分子搭建器")
        builder_window.geometry("900x800")
        builder_window.resizable(True, True)
        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/molecule.ico')
            builder_window.iconphoto(True, icon_image)
        except:
            pass
        
        # 居中显示
        builder_window.transient(self.root)
        builder_window.grab_set()
        
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 450
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 325
        builder_window.geometry(f"+{x}+{y}")
        
        # 创建主框架
        main_frame = tk.Frame(builder_window)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=15, pady=15)
        
        # 标题
        title_label = tk.Label(main_frame, text="分子搭建器", 
                              font=('Unifont', 16),
                              fg='darkgreen')
        title_label.pack(pady=(0, 15))

        # ============ 顶部预设分子下拉菜单 ============
        preset_dir = "./res/mlcls/"
        if not os.path.exists(preset_dir):
            try:
                os.makedirs(preset_dir, exist_ok=True)
                print(f"[分子搭建器] 已创建预设目录: {preset_dir}")
            except Exception as e:
                print(f"[分子搭建器] 创建预设目录失败: {e}")

        def scan_presets():
            """扫描预设目录，返回 {显示名: 完整路径}"""
            result = {}
            if os.path.exists(preset_dir):
                try:
                    for fname in sorted(os.listdir(preset_dir)):
                        if fname.lower().endswith('.mlcl'):
                            full_path = os.path.join(preset_dir, fname)
                            display = os.path.splitext(fname)[0]
                            # 尝试读取文件第一行注释作为显示名
                            try:
                                with open(full_path, 'r', encoding='utf-8') as f:
                                    for _ in range(5):
                                        line = f.readline().strip()
                                        if not line:
                                            break
                                        if '分子:' in line or '名称:' in line:
                                            display = line.split(':', 1)[1].strip()
                                            break
                            except Exception:
                                pass
                            # 重名保护
                            if display in result:
                                display = f"{display} ({os.path.splitext(fname)[0]})"
                            result[display] = full_path
                except Exception as e:
                    print(f"[分子搭建器] 扫描预设失败: {e}")
            return result

        # 保存到实例属性，供后续刷新使用
        self._preset_dir = preset_dir
        self._preset_files = scan_presets()

        # 顶部工具条
        top_bar = tk.LabelFrame(main_frame, text=" 预设分子 ",
                               font=('Unifont', 11),
                               relief=tk.GROOVE, bd=2)
        top_bar.pack(fill=tk.X, pady=(0, 15))

        preset_var = tk.StringVar(value="-- 选择预设分子 --")
        preset_options = ["-- 选择预设分子 --"] + list(self._preset_files.keys())

        tk.Label(top_bar, text="预设:", font=('Unifont', 10)).pack(
            side=tk.LEFT, padx=(10, 5), pady=8)

        preset_menu = ttk.Combobox(top_bar, textvariable=preset_var,
                                   values=preset_options, state="readonly",
                                   font=('Unifont', 10), width=32)
        preset_menu.pack(side=tk.LEFT, padx=(0, 10), pady=8)

        preset_count_label = tk.Label(
            top_bar, text=f"共 {len(self._preset_files)} 个",
            font=('Unifont', 9), fg='gray')
        preset_count_label.pack(side=tk.LEFT, padx=(0, 10), pady=8)

        def load_preset(event=None):
            """加载选中的预设 mlcl"""
            name = preset_var.get()
            if not name or name == "-- 选择预设分子 --":
                return
            path = self._preset_files.get(name)
            if path and os.path.exists(path):
                try:
                    self.load_mlcl_file(path)
                except Exception as e:
                    messagebox.showerror("错误", f"加载预设失败:\n{e}")
            else:
                messagebox.showwarning("提示", f"找不到文件:\n{path}")

        def refresh_presets():
            """重新扫描预设目录"""
            self._preset_files = scan_presets()
            new_options = ["-- 选择预设分子 --"] + list(self._preset_files.keys())
            preset_menu['values'] = new_options
            preset_var.set("-- 选择预设分子 --")
            preset_count_label.config(text=f"共 {len(self._preset_files)} 个")
            try:
                self.builder_status.config(
                    text=f"已刷新，扫描到 {len(self._preset_files)} 个预设分子")
            except Exception:
                pass

        def open_preset_dir():
            """用系统文件管理器打开预设目录"""
            try:
                abs_dir = os.path.abspath(preset_dir)
                if platform.system() == "Windows":
                    os.startfile(abs_dir)
                elif platform.system() == "Darwin":
                    subprocess.Popen(["open", abs_dir])
                else:
                    subprocess.Popen(["xdg-open", abs_dir])
            except Exception as e:
                messagebox.showerror("错误", f"无法打开目录:\n{e}")

        # 右侧按钮
        tk.Button(top_bar, text="加载", command=load_preset,
                  font=('Unifont', 9), bg='#4CAF50', fg='white', width=6
                  ).pack(side=tk.RIGHT, padx=(0, 10), pady=8)
        tk.Button(top_bar, text="刷新", command=refresh_presets,
                  font=('Unifont', 9), width=6
                  ).pack(side=tk.RIGHT, padx=(0, 4), pady=8)
        tk.Button(top_bar, text="目录", command=open_preset_dir,
                  font=('Unifont', 9), width=6
                  ).pack(side=tk.RIGHT, padx=(0, 4), pady=8)

        # 选中即加载
        preset_menu.bind('<<ComboboxSelected>>', load_preset)
        # ============ 顶部预设分子下拉菜单 结束 ============
        
        # 创建左右分栏
        content_frame = tk.Frame(main_frame)
        content_frame.pack(fill=tk.BOTH, expand=True)
        
        # 左侧工具栏
        left_frame = tk.Frame(content_frame, width=250)
        left_frame.pack(side=tk.LEFT, fill=tk.Y, padx=(0, 10))
        left_frame.pack_propagate(False)
        
        # 右侧画布区域
        right_frame = tk.Frame(content_frame)
        right_frame.pack(side=tk.RIGHT, fill=tk.BOTH, expand=True)
        
        # 初始化搭建器
        self.setup_simple_molecule_builder(left_frame, right_frame, builder_window)
        
        # 关闭按钮
        close_btn = tk.Button(main_frame, text="关闭", 
                             command=builder_window.destroy,
                             font=('Unifont', 10), width=10)
        close_btn.pack(pady=10)

