    def on_atom_symbol_changed(self, *args):
        """原子符号变化时的回调函数"""
        symbol = self.atom_symbol_var.get().strip()
        
        if not symbol:
            return
        
        # 转换为标准格式（首字母大写，后续小写）
        formatted_symbol = symbol[0].upper() + (symbol[1:].lower() if len(symbol) > 1 else "")
        
        # 检查是否为标准元素
        if formatted_symbol in self.element_to_color:
            # 是标准元素，自动设置颜色和半径
            color = self.element_to_color[formatted_symbol]
            self.current_color = color
            
            # 更新颜色预览
            self.color_preview.config(bg=color)
            
            # 更新元素信息标签
            element_name = self.get_element_name(formatted_symbol)
            atomic_number = self.element_to_z.get(formatted_symbol, "?")
            self.element_info_label.config(
                text=f"{formatted_symbol} ({element_name}, Z={atomic_number})",
                fg='darkgreen'  # 绿色表示标准元素
            )
            
            # 自动设置推荐的半径
            if formatted_symbol in self.element_radii:
                self.atom_radius_var.set(self.element_radii[formatted_symbol])
            
            # 更新状态
            self.builder_status.config(
                text=f"已识别为标准元素: {formatted_symbol} ({element_name}) - 自动应用元素颜色"
            )
        else:
            # 非标准元素，保持当前颜色
            self.element_info_label.config(
                text="自定义原子",
                fg='darkred'  # 红色表示自定义
            )
            
            # 更新状态
            self.builder_status.config(
                text=f"非标准元素符号: {symbol} - 使用自定义颜色"
            )

    def select_common_element(self, symbol, color):
        """选择常见元素"""
        self.atom_symbol_var.set(symbol)
        # on_atom_symbol_changed会自动触发

