    def load_molecule_file(self):
        """加载分子文件 - 支持.mlcl和.json格式"""
        # 弹出文件选择对话框
        filename = filedialog.askopenfilename(
            defaultextension=".mlcl",
            filetypes=[
                ("分子文件", "*.mlcl"),
                ("JSON文件", "*.json"),
                ("所有文件", "*.*")
            ],
            title="打开分子文件"
        )
        
        if not filename:  # 用户取消选择
            return
        
        try:
            # 根据文件扩展名选择加载方式
            if filename.endswith('.mlcl'):
                self.load_mlcl_file(filename)
            elif filename.endswith('.json'):
                self.load_json_file(filename)
            else:
                # 尝试自动检测文件类型
                with open(filename, 'r', encoding='utf-8') as f:
                    first_line = f.readline().strip()
                    if first_line.startswith('MOLECULE_FILE'):
                        self.load_mlcl_file(filename)
                    else:
                        # 尝试作为JSON加载
                        self.load_json_file(filename)
            
        except UnicodeDecodeError:
            # 如果UTF-8解码失败，尝试其他编码
            try:
                with open(filename, 'r', encoding='gbk') as f:
                    first_line = f.readline().strip()
                    if first_line.startswith('MOLECULE_FILE'):
                        self.load_mlcl_file(filename, encoding='gbk')
                    else:
                        messagebox.showerror("错误", "无法识别的文件格式或编码")
            except:
                messagebox.showerror("错误", "文件读取失败：不支持的编码格式")
                
        except Exception as e:
            messagebox.showerror("错误", f"加载文件失败:\n{str(e)}")

    def load_mlcl_file(self, filename, encoding='utf-8'):
        """加载.mlcl格式分子文件"""
        with open(filename, 'r', encoding=encoding) as f:
            lines = f.readlines()
        
        # 清空当前画布
        self.clear_builder_canvas()
        
        atoms_section = False
        bonds_section = False
        
        # 临时存储原子和键
        atoms = []
        bonds = []
        
        for line in lines:
            line = line.strip()
            
            if not line or line.startswith('#'):
                continue  # 跳过空行和注释
            
            if line == '[ATOMS]':
                atoms_section = True
                bonds_section = False
                continue
            elif line == '[BONDS]':
                atoms_section = False
                bonds_section = True
                continue
            elif line.startswith('['):
                # 进入其他部分，停止解析原子和键
                atoms_section = False
                bonds_section = False
                continue
            
            if atoms_section:
                # 解析原子行：格式为 "索引: 符号 x y 颜色 半径"
                parts = line.split(':')
                if len(parts) >= 2:
                    atom_data = parts[1].strip().split()
                    if len(atom_data) >= 5:
                        atom = {
                            'symbol': atom_data[0],
                            'x': float(atom_data[1]),
                            'y': float(atom_data[2]),
                            'color': atom_data[3],
                            'radius': int(atom_data[4]),
                            'bonds': []  # 初始化为空，后面会根据键更新
                        }
                        atoms.append(atom)
            
            elif bonds_section:
                # 解析键行：格式为 "起始原子-结束原子: 键级"
                if ':' in line:
                    key_part, value_part = line.split(':', 1)
                    key_part = key_part.strip()
                    value_part = value_part.strip()
                    
                    if '-' in key_part:
                        atom_indices = key_part.split('-')
                        if len(atom_indices) == 2:
                            try:
                                start_atom = int(atom_indices[0])
                                end_atom = int(atom_indices[1])
                                order = int(value_part)
                                
                                bond = {
                                    'start_atom': start_atom,
                                    'end_atom': end_atom,
                                    'order': order
                                }
                                bonds.append(bond)
                            except ValueError:
                                continue  # 跳过格式错误的行
        
        # 设置原子和键
        self.builder_atoms = atoms
        self.builder_bonds = bonds
        
        # 更新原子的键连接信息
        for i, bond in enumerate(bonds):
            if bond['start_atom'] < len(atoms):
                atoms[bond['start_atom']]['bonds'].append(i)
            if bond['end_atom'] < len(atoms):
                atoms[bond['end_atom']]['bonds'].append(i)
        
        # 重绘画布
        self.redraw_builder_canvas()
        
        # 显示加载成功信息
        filename_only = os.path.basename(filename)
        atom_count = len(atoms)
        bond_count = len(bonds)
        
        # 更新状态显示
        self.builder_status.config(
            text=f"已加载: {filename_only} ({atom_count}个原子, {bond_count}个键)"
        )
        
        # 显示文件基本信息
        info_text = f"📂 文件已加载: {filename_only}\n\n"
        info_text += f"📊 分子信息:\n"
        info_text += f"• 原子数量: {atom_count}\n"
        info_text += f"• 化学键数量: {bond_count}\n"
        
        if atom_count > 0:
            # 计算元素组成
            element_count = {}
            for atom in atoms:
                symbol = atom['symbol']
                element_count[symbol] = element_count.get(symbol, 0) + 1
            
            info_text += f"• 元素种类: {len(element_count)}\n"
            info_text += f"• 元素组成: "
            element_list = [f"{sym}{cnt}" for sym, cnt in sorted(element_count.items())]
            info_text += ", ".join(element_list) + "\n"
        
        # 显示在分子信息框中
        self.molecule_info.config(state=tk.NORMAL)
        self.molecule_info.delete(1.0, tk.END)
        self.molecule_info.insert(tk.END, info_text)
        self.molecule_info.insert(tk.END, "\n💡 提示: 点击'分析分子'查看详细分析")
        self.molecule_info.config(state=tk.DISABLED)
        
        messagebox.showinfo("加载成功", 
                           f"文件加载成功！\n\n"
                           f"文件: {filename_only}\n"
                           f"原子数: {atom_count}\n"
                           f"键数: {bond_count}")

    def load_json_file(self, filename):
        """加载JSON格式分子文件"""
        with open(filename, 'r', encoding='utf-8') as f:
            data = json.load(f)
        
        # 清空当前画布
        self.clear_builder_canvas()
        
        # 根据JSON结构加载数据
        if 'atoms' in data and 'bonds' in data:
            # 加载原子
            atoms = []
            for atom_data in data['atoms']:
                atom = {
                    'symbol': atom_data.get('symbol', 'C'),
                    'x': atom_data.get('x', 100),
                    'y': atom_data.get('y', 100),
                    'color': atom_data.get('color', 'black'),
                    'radius': atom_data.get('radius', 15),
                    'bonds': []  # 初始化为空
                }
                atoms.append(atom)
            
            # 加载键
            bonds = []
            for bond_data in data['bonds']:
                bond = {
                    'start_atom': bond_data.get('start_atom', 0),
                    'end_atom': bond_data.get('end_atom', 1),
                    'order': bond_data.get('order', 1)
                }
                bonds.append(bond)
            
            # 设置原子和键
            self.builder_atoms = atoms
            self.builder_bonds = bonds
            
            # 更新原子的键连接信息
            for i, bond in enumerate(bonds):
                if bond['start_atom'] < len(atoms):
                    atoms[bond['start_atom']]['bonds'].append(i)
                if bond['end_atom'] < len(atoms):
                    atoms[bond['end_atom']]['bonds'].append(i)
            
            # 重绘画布
            self.redraw_builder_canvas()
            
            # 显示成功信息
            filename_only = os.path.basename(filename)
            self.builder_status.config(
                text=f"已加载JSON文件: {filename_only}"
            )
            
            messagebox.showinfo("加载成功", 
                               f"JSON文件加载成功！\n\n"
                               f"文件: {filename_only}\n"
                               f"原子数: {len(atoms)}\n"
                               f"键数: {len(bonds)}")
        else:
            messagebox.showerror("错误", "JSON文件格式不正确，缺少'atoms'或'bonds'字段")

    def save_as_json(self):
        """保存为JSON格式文件（作为扩展功能）"""
        if not self.builder_atoms:
            messagebox.showinfo("提示", "没有分子可保存")
            return
        
        filename = filedialog.asksaveasfilename(
            defaultextension=".json",
            filetypes=[("JSON文件", "*.json"), ("所有文件", "*.*")],
            title="保存为JSON格式"
        )
        
        if not filename:
            return
        
        try:
            # 构建JSON数据结构
            molecule_data = {
                'metadata': {
                    'version': '1.0',
                    'generated': datetime.datetime.now().isoformat(),
                    'application': '分子搭建器'
                },
                'atoms': self.builder_atoms,
                'bonds': self.builder_bonds,
                'analysis': self.analyze_molecular_formula()
            }
            
            # 保存为JSON文件
            with open(filename, 'w', encoding='utf-8') as f:
                json.dump(molecule_data, f, ensure_ascii=False, indent=2)
            
            messagebox.showinfo("保存成功", f"分子已保存为JSON格式:\n{filename}")
            
        except Exception as e:
            messagebox.showerror("错误", f"保存JSON文件失败:\n{str(e)}")

    def choose_atom_color(self):
        """打开颜色选择器选择原子颜色"""
        # 打开颜色选择器
        color_code = colorchooser.askcolor(
            title="选择原子颜色",
            initialcolor=self.current_color
        )
        
        if color_code[0] is not None:  # 用户选择了颜色
            hex_color = color_code[1]
            self.current_color = hex_color
            
            # 更新颜色预览
            self.color_preview.config(bg=hex_color)
            
            # 如果是标准元素但用户选择了自定义颜色，更新标签
            symbol = self.atom_symbol_var.get().strip()
            formatted_symbol = symbol[0].upper() + (symbol[1:].lower() if len(symbol) > 1 else "")
            
            if formatted_symbol in self.element_to_color:
                # 用户覆盖了标准颜色，显示自定义状态
                self.element_info_label.config(
                    text=f"{formatted_symbol} (自定义颜色)",
                    fg='darkorange'  # 橙色表示自定义了标准元素
                )
            
            # 更新状态显示
            self.builder_status.config(text=f"已选择自定义颜色: {hex_color}")

    def add_custom_atom(self, x, y):
        """添加自定义原子"""
        # 确保工具是原子模式
        if self.tool_var.get() != "atom":
            return
        
        symbol = self.atom_symbol_var.get().strip()
        if not symbol:
            self.builder_status.config(text="错误: 请输入原子符号")
            return
        
        # 格式化符号（首字母大写，后续小写）
        formatted_symbol = symbol[0].upper() + (symbol[1:].lower() if len(symbol) > 1 else "")
        
        color = self.current_color
        radius = self.atom_radius_var.get()
        
        atom = {
            'symbol': formatted_symbol,  # 使用格式化后的符号
            'x': x,
            'y': y,
            'color': color,
            'radius': radius,
            'bonds': []  # 连接的键
        }
        
        self.builder_atoms.append(atom)
        self.redraw_builder_canvas()
        
        # 显示添加成功信息
        if formatted_symbol in self.element_to_color:
            element_name = self.get_element_name(formatted_symbol)
            self.builder_status.config(text=f"添加了 {formatted_symbol} ({element_name}) 原子")
        else:
            self.builder_status.config(text=f"添加了自定义原子: {formatted_symbol}")


    def on_tool_change(self):
        """工具改变时的回调"""
        tool = self.tool_var.get()
        if tool == "select":
            self.builder_canvas.config(cursor="arrow")
            self.builder_status.config(text="选择模式: 点击选择原子")
        elif tool == "atom":
            self.builder_canvas.config(cursor="crosshair")
            symbol = self.atom_symbol_var.get()
            color = self.current_color
            radius = self.atom_radius_var.get()
            self.builder_status.config(text=f"原子模式: 点击画布添加 {symbol} 原子 (颜色: {color}, 半径: {radius})")
        elif tool == "bond":
            self.builder_canvas.config(cursor="plus")
            self.builder_status.config(text="键模式: 点击两个原子创建化学键")
        elif tool == "delete":
            self.builder_canvas.config(cursor="pirate")
            self.builder_status.config(text="删除模式: 点击原子或键进行删除")

    def on_canvas_click(self, event):
        """画布点击事件"""
        tool = self.tool_var.get()
        
        if tool == "atom":
            self.add_custom_atom(event.x, event.y)
        elif tool == "select":
            self.select_atom(event.x, event.y)
        elif tool == "bond":
            self.start_bond_creation(event.x, event.y)
        elif tool == "delete":
            self.delete_element(event.x, event.y)

    def select_atom(self, x, y):
        """选择原子"""
        self.selected_atom = None
        
        for i, atom in enumerate(self.builder_atoms):
            distance = ((atom['x'] - x) ** 2 + (atom['y'] - y) ** 2) ** 0.5
            if distance <= atom['radius']:
                self.selected_atom = i
                self.dragging_atom = i
                self.builder_status.config(text=f"选中 {atom['symbol']} 原子")
                break
        
        self.redraw_builder_canvas()

    def start_bond_creation(self, x, y):
        """开始创建键"""
        self.bond_start_atom = None
        
        for i, atom in enumerate(self.builder_atoms):
            distance = ((atom['x'] - x) ** 2 + (atom['y'] - y) ** 2) ** 0.5
            if distance <= atom['radius']:
                self.bond_start_atom = i
                self.builder_status.config(text=f"从 {atom['symbol']} 原子开始创建键")
                break

    def on_canvas_drag(self, event):
        """画布拖动事件"""
        if self.dragging_atom is not None:
            # 拖动原子
            atom_index = self.dragging_atom
            atom = self.builder_atoms[atom_index]
            
            # 更新原子位置
            atom['x'] = event.x
            atom['y'] = event.y
            
            # 重绘画布
            self.redraw_builder_canvas()

    def on_canvas_release(self, event):
        """画布释放事件"""
        tool = self.tool_var.get()
        
        if tool == "bond" and hasattr(self, 'bond_start_atom'):
            # 完成键的创建
            self.finish_bond_creation(event.x, event.y)
        
        self.dragging_atom = None

    def finish_bond_creation(self, x, y):
        """完成键的创建"""
        end_atom = None
        
        for i, atom in enumerate(self.builder_atoms):
            distance = ((atom['x'] - x) ** 2 + (atom['y'] - y) ** 2) ** 0.5
            if distance <= atom['radius'] and i != self.bond_start_atom:
                end_atom = i
                break
        
        if end_atom is not None:
            bond_order = self.bond_var.get()
            
            bond = {
                'start_atom': self.bond_start_atom,
                'end_atom': end_atom,
                'order': bond_order
            }
            
            # 检查是否已存在相同的键
            bond_exists = False
            for existing_bond in self.builder_bonds:
                if (existing_bond['start_atom'] == self.bond_start_atom and 
                    existing_bond['end_atom'] == end_atom) or \
                   (existing_bond['start_atom'] == end_atom and 
                    existing_bond['end_atom'] == self.bond_start_atom):
                    bond_exists = True
                    break
            
            if not bond_exists:
                self.builder_bonds.append(bond)
                
                # 更新原子的键信息
                self.builder_atoms[self.bond_start_atom]['bonds'].append(len(self.builder_bonds)-1)
                self.builder_atoms[end_atom]['bonds'].append(len(self.builder_bonds)-1)
                
                start_symbol = self.builder_atoms[self.bond_start_atom]['symbol']
                end_symbol = self.builder_atoms[end_atom]['symbol']
                self.builder_status.config(text=f"创建了 {bond_order} 键: {start_symbol}-{end_symbol}")
            else:
                self.builder_status.config(text="键已存在")
        
        self.redraw_builder_canvas()
        if hasattr(self, 'bond_start_atom'):
            delattr(self, 'bond_start_atom')

    def delete_element(self, x, y):
        """删除原子（以及与其相连的键） - 完整安全版"""
        # 1. 查找点击位置是否落在某个原子上
        atom_to_delete = None
        for i, atom in enumerate(self.builder_atoms):
            # 确保原子有必要的坐标和半径
            if not all(k in atom for k in ('x', 'y', 'radius')):
                continue
            distance = ((atom['x'] - x) ** 2 + (atom['y'] - y) ** 2) ** 0.5
            if distance <= atom['radius']:
                atom_to_delete = i
                break

        if atom_to_delete is None:
            self.builder_status.config(text="未选中任何原子")
            return

        # 2. 收集与该原子相关的键索引（有效键）
        bonds_to_remove = []
        for idx, bond in enumerate(self.builder_bonds):
            # 安全获取 start_atom 和 end_atom，若为 None 则跳过该键（视为无效）
            start = bond.get('start_atom')
            end = bond.get('end_atom')
            if start is None or end is None:
                # 无效键，也标记为删除（一并清理）
                bonds_to_remove.append(idx)
                continue
            if start == atom_to_delete or end == atom_to_delete:
                bonds_to_remove.append(idx)

        # 3. 从大到小删除键
        for idx in sorted(set(bonds_to_remove), reverse=True):
            del self.builder_bonds[idx]
            # 更新所有原子的 bonds 列表（移除该键索引，并修正大于 idx 的索引）
            for atom in self.builder_atoms:
                if 'bonds' in atom and atom['bonds']:
                    # 过滤掉等于 idx 的索引
                    atom['bonds'] = [b for b in atom['bonds'] if b != idx]
                    # 将大于 idx 的索引减 1
                    atom['bonds'] = [b if b < idx else b-1 for b in atom['bonds']]

        # 4. 删除原子
        symbol = self.builder_atoms[atom_to_delete].get('symbol', '?')
        del self.builder_atoms[atom_to_delete]

        # 5. 更新剩余键的原子索引（大于删除索引的减 1）
        for bond in self.builder_bonds:
            # 再次确保 start_atom 和 end_atom 不是 None
            if bond.get('start_atom') is not None and bond['start_atom'] > atom_to_delete:
                bond['start_atom'] -= 1
            if bond.get('end_atom') is not None and bond['end_atom'] > atom_to_delete:
                bond['end_atom'] -= 1

        # 6. 清理所有无效键（start 或 end 为 None 的键）
        self.builder_bonds = [
            b for b in self.builder_bonds
            if b.get('start_atom') is not None and b.get('end_atom') is not None
        ]

        # 7. 重绘画布并更新状态
        self.builder_status.config(text=f"删除了 {symbol} 原子")
        self.redraw_builder_canvas()

    def redraw_builder_canvas(self):
        """重绘画布"""
        self.builder_canvas.delete("all")
        
        # 绘制键
        for bond in self.builder_bonds:
            try:
                start_atom = self.builder_atoms[bond['start_atom']]
                end_atom = self.builder_atoms[bond['end_atom']]
                # 确保坐标存在且为数字
                if not all(isinstance(v, (int, float)) for v in (start_atom['x'], start_atom['y'], end_atom['x'], end_atom['y'])):
                    continue
            except (IndexError, KeyError, TypeError):
                # 跳过无效键（例如索引越界或字段缺失）
                continue
            
            # 根据键级绘制不同样式的线
            if bond['order'] == 1:
                # 单键
                self.builder_canvas.create_line(
                    start_atom['x'], start_atom['y'],
                    end_atom['x'], end_atom['y'],
                    width=3, fill='black'
                )
            elif bond['order'] == 2:
                # 双键
                dx = end_atom['x'] - start_atom['x']
                dy = end_atom['y'] - start_atom['y']
                length = (dx**2 + dy**2)**0.5
                if length > 0:
                    perp_x = -dy/length * 3
                    perp_y = dx/length * 3
                    
                    self.builder_canvas.create_line(
                        start_atom['x'] + perp_x, start_atom['y'] + perp_y,
                        end_atom['x'] + perp_x, end_atom['y'] + perp_y,
                        width=2, fill='black'
                    )
                    self.builder_canvas.create_line(
                        start_atom['x'] - perp_x, start_atom['y'] - perp_y,
                        end_atom['x'] - perp_x, end_atom['y'] - perp_y,
                        width=2, fill='black'
                    )
            elif bond['order'] == 3:
                # 三键
                dx = end_atom['x'] - start_atom['x']
                dy = end_atom['y'] - start_atom['y']
                length = (dx**2 + dy**2)**0.5
                if length > 0:
                    perp_x = -dy/length * 5
                    perp_y = dx/length * 5
                    
                    self.builder_canvas.create_line(
                        start_atom['x'], start_atom['y'],
                        end_atom['x'], end_atom['y'],
                        width=2, fill='black'
                    )
                    self.builder_canvas.create_line(
                        start_atom['x'] + perp_x, start_atom['y'] + perp_y,
                        end_atom['x'] + perp_x, end_atom['y'] + perp_y,
                        width=2, fill='black'
                    )
                    self.builder_canvas.create_line(
                        start_atom['x'] - perp_x, start_atom['y'] - perp_y,
                        end_atom['x'] - perp_x, end_atom['y'] - perp_y,
                        width=2, fill='black'
                    )
        
        # 绘制原子
        for i, atom in enumerate(self.builder_atoms):
            if not all(isinstance(v, (int, float)) for v in (atom['x'], atom['y'])):
                continue
            color = atom['color']
            radius = atom['radius']
            
            # 绘制原子圆圈
            self.builder_canvas.create_oval(
                atom['x'] - radius, atom['y'] - radius,
                atom['x'] + radius, atom['y'] + radius,
                fill=color, outline='black', width=2
            )
            
            # 确定文字颜色（根据背景色自动选择对比色）
            text_color = self.get_contrast_color(color)
            
            # 绘制原子符号
            self.builder_canvas.create_text(
                atom['x'], atom['y'],
                text=atom['symbol'],
                font=('Unifont', 10),
                fill=text_color
            )
            
            # 如果原子被选中，绘制选择框
            if i == self.selected_atom:
                self.builder_canvas.create_oval(
                    atom['x'] - radius - 3, atom['y'] - radius - 3,
                    atom['x'] + radius + 3, atom['y'] + radius + 3,
                    outline='red', width=2
                )

    def get_contrast_color(self, bg_color):
        """根据背景色返回对比色（黑或白）"""
        # 如果是十六进制颜色
        if bg_color.startswith('#'):
            try:
                # 提取RGB值
                r = int(bg_color[1:3], 16)
                g = int(bg_color[3:5], 16)
                b = int(bg_color[5:7], 16)
                
                # 计算亮度（相对亮度公式）
                brightness = (0.299 * r + 0.587 * g + 0.114 * b) / 255
                return 'white' if brightness < 0.5 else 'black'
            except:
                return 'black'
        
        # 对于颜色名称
        dark_colors = ['black', 'darkred', 'darkgreen', 'darkblue', 'navy', 'maroon']
        light_colors = ['white', 'yellow', 'lightblue', 'lightgreen', 'cyan', 'pink']
        
        if bg_color in dark_colors:
            return 'white'
        elif bg_color in light_colors:
            return 'black'
        else:
            return 'black'  # 默认

    def clear_builder_canvas(self):
        """清空画布"""
        self.builder_atoms = []
        self.builder_bonds = []
        self.selected_atom = None
        self.redraw_builder_canvas()
        self.builder_status.config(text="画布已清空")
        
        # 清空分子信息
        self.molecule_info.config(state=tk.NORMAL)
        self.molecule_info.delete(1.0, tk.END)
        self.molecule_info.insert(tk.END, "在此搭建分子...")
        self.molecule_info.config(state=tk.DISABLED)

    def analyze_molecule(self):
        """分析分子 - 增强版"""
        if not self.builder_atoms:
            self.builder_status.config(text="没有分子可分析")
            return
        
        # 获取各种分析结果
        formula_analysis = self.analyze_molecular_formula()
        bond_analysis = self.analyze_bonds()
        structure_analysis = self.analyze_structure()
        features = self.identify_molecular_features()
        
        # 显示分析结果
        self.molecule_info.config(state=tk.NORMAL)
        self.molecule_info.delete(1.0, tk.END)
        
        self.molecule_info.insert(tk.END, f"🧪 分子分析结果:\n\n", 'title')
        self.molecule_info.tag_configure('title', font=('Unifont', 12), foreground='darkblue')
        
        # 分子式信息
        self.molecule_info.insert(tk.END, f"📊 基本信息:\n")
        self.molecule_info.insert(tk.END, f"• 分子式: {formula_analysis['formula']}\n")
        self.molecule_info.insert(tk.END, f"• 分子量: {formula_analysis['molecular_weight']:.3f} g/mol\n")
        self.molecule_info.insert(tk.END, f"• 原子总数: {formula_analysis['total_atoms']}\n")
        self.molecule_info.insert(tk.END, f"• 元素种类: {formula_analysis['element_types']}\n\n")
        
        # 键信息
        self.molecule_info.insert(tk.END, f"🔗 键信息:\n")
        self.molecule_info.insert(tk.END, f"• 键总数: {bond_analysis['total_bonds']}\n")
        self.molecule_info.insert(tk.END, f"• 单键: {bond_analysis['single_bonds']} 个\n")
        self.molecule_info.insert(tk.END, f"• 双键: {bond_analysis['double_bonds']} 个\n")
        self.molecule_info.insert(tk.END, f"• 三键: {bond_analysis['triple_bonds']} 个\n\n")
        
        # 结构信息
        self.molecule_info.insert(tk.END, f"🏗️ 结构信息:\n")
        self.molecule_info.insert(tk.END, f"• 最大连接度: {structure_analysis['max_connectivity']}\n")
        self.molecule_info.insert(tk.END, f"• 平均连接度: {structure_analysis['avg_connectivity']:.2f}\n")
        self.molecule_info.insert(tk.END, f"• 孤立原子: {structure_analysis['isolated_atoms']} 个\n")
        self.molecule_info.insert(tk.END, f"• 环状结构: {'是' if structure_analysis['has_rings'] else '否'}\n\n")
        
        # 元素组成
        self.molecule_info.insert(tk.END, f"🧬 元素组成:\n")
        for element, count in formula_analysis['element_count'].items():
            percentage = count / formula_analysis['total_atoms'] * 100
            self.molecule_info.insert(tk.END, f"• {element}: {count} 原子 ({percentage:.1f}%)\n")
        
        self.molecule_info.insert(tk.END, f"\n")
        
        # 分子特征
        self.molecule_info.insert(tk.END, f"🎯 分子特征:\n")
        for feature in features:
            self.molecule_info.insert(tk.END, f"• {feature}\n")
        
        self.molecule_info.config(state=tk.DISABLED)
        self.builder_status.config(text=f"分析了分子: {formula_analysis['formula']}")

    def analyze_molecular_formula(self):
        """分析分子式"""
        atom_count = {}
        total_weight = 0.0
        
        # 原子量数据
        atomic_weights = {
            'H': 1.008, 'C': 12.011, 'N': 14.007, 'O': 16.000,
            'F': 19.000, 'P': 30.974, 'S': 32.06, 'Cl': 35.45,
            'Br': 79.904, 'I': 126.90, 'He': 4.0026, 'Li': 6.94,
            'Be': 9.0122, 'B': 10.81, 'Na': 22.990, 'Mg': 24.305,
            'Al': 26.982, 'Si': 28.085, 'K': 39.098, 'Ca': 40.078,
            'Fe': 55.845, 'Cu': 63.546, 'Zn': 65.38, 'Ag': 107.87,
            'Au': 196.97, 'Hg': 200.59, 'Pb': 207.2
        }
        
        for atom in self.builder_atoms:
            symbol = atom['symbol']
            atom_count[symbol] = atom_count.get(symbol, 0) + 1
            total_weight += atomic_weights.get(symbol, 12.0)  # 默认碳原子量
        
        # 生成标准分子式（C, H, 其他按字母顺序）
        formula_parts = []
        
        # 碳原子
        if 'C' in atom_count and atom_count['C'] > 0:
            count = atom_count['C']
            formula_parts.append(f"C{count if count > 1 else ''}")
        
        # 氢原子
        if 'H' in atom_count and atom_count['H'] > 0:
            count = atom_count['H']
            formula_parts.append(f"H{count if count > 1 else ''}")
        
        # 其他元素按字母顺序
        other_elements = []
        for element in sorted(atom_count.keys()):
            if element not in ['C', 'H'] and atom_count[element] > 0:
                count = atom_count[element]
                other_elements.append(f"{element}{count if count > 1 else ''}")
        
        formula_parts.extend(other_elements)
        formula = "".join(formula_parts)
        
        return {
            'formula': formula,
            'molecular_weight': total_weight,
            'total_atoms': len(self.builder_atoms),
            'element_types': len(atom_count),
            'element_count': atom_count
        }

    def analyze_bonds(self):
        """分析化学键"""
        bond_distribution = {'单键': 0, '双键': 0, '三键': 0}
        
        for bond in self.builder_bonds:
            if bond['order'] == 1:
                bond_distribution['单键'] += 1
            elif bond['order'] == 2:
                bond_distribution['双键'] += 1
            elif bond['order'] == 3:
                bond_distribution['三键'] += 1
        
        return {
            'total_bonds': len(self.builder_bonds),
            'single_bonds': bond_distribution['单键'],
            'double_bonds': bond_distribution['双键'],
            'triple_bonds': bond_distribution['三键'],
            'bond_distribution': bond_distribution
        }

    def analyze_structure(self):
        """分析分子结构"""
        # 计算原子连接度
        connectivity = []
        isolated_atoms = 0
        
        for atom in self.builder_atoms:
            atom_connectivity = len(atom['bonds'])
            connectivity.append(atom_connectivity)
            if atom_connectivity == 0:
                isolated_atoms += 1
        
        # 简单环检测（通过连接性推断）
        has_rings = self.detect_rings()
        
        return {
            'max_connectivity': max(connectivity) if connectivity else 0,
            'avg_connectivity': sum(connectivity) / len(connectivity) if connectivity else 0,
            'isolated_atoms': isolated_atoms,
            'has_rings': has_rings
        }

    def detect_rings(self):
        """简单环检测"""
        if len(self.builder_atoms) < 3:
            return False
        
        # 简单的环检测：如果存在三角形或更大的环结构
        visited = set()
        
        def dfs(current, parent, depth):
            if current in visited:
                return depth >= 3  # 找到环
            
            visited.add(current)
            
            # 获取当前原子的连接
            current_bonds = self.builder_atoms[current]['bonds']
            for bond_index in current_bonds:
                bond = self.builder_bonds[bond_index]
                next_atom = bond['end_atom'] if bond['start_atom'] == current else bond['start_atom']
                
                if next_atom != parent:  # 避免回到父节点
                    if dfs(next_atom, current, depth + 1):
                        return True
            
            visited.remove(current)
            return False
        
        # 从每个原子开始搜索
        for i in range(len(self.builder_atoms)):
            if dfs(i, -1, 0):
                return True
        
        return False

    def identify_molecular_features(self):
        """识别分子特征"""
        features = []
        atom_count = {}
        
        # 统计元素
        for atom in self.builder_atoms:
            symbol = atom['symbol']
            atom_count[symbol] = atom_count.get(symbol, 0) + 1
        
        # 基于元素组成的特征
        if atom_count.get('C', 0) > 0:
            features.append("含碳化合物")
            if atom_count.get('H', 0) > 0:
                features.append("有机分子")
        
        if atom_count.get('O', 0) > 0:
            features.append("含氧化合物")
        
        if atom_count.get('N', 0) > 0:
            features.append("含氮化合物")
        
        # 基于键的特征
        bond_analysis = self.analyze_bonds()
        if bond_analysis['double_bonds'] > 0:
            features.append("含有双键")
        if bond_analysis['triple_bonds'] > 0:
            features.append("含有三键")
        
        # 基于结构的特征
        structure_analysis = self.analyze_structure()
        if structure_analysis['has_rings']:
            features.append("环状结构")
        if structure_analysis['isolated_atoms'] > 0:
            features.append("含有孤立原子")
        
        # 基于大小的特征
        total_atoms = len(self.builder_atoms)
        if total_atoms <= 5:
            features.append("小分子")
        elif total_atoms <= 15:
            features.append("中等分子")
        else:
            features.append("大分子")
        
        # 基于连接性的特征
        if structure_analysis['max_connectivity'] == 4:
            features.append("四面体碳中心")
        
        return features

    def save_molecule_file(self):
        """保存分子为.mlcl文件，包含分子分析"""
        if not self.builder_atoms:
            messagebox.showinfo("提示", "没有分子可保存")
            return
        
        # 弹出文件保存对话框
        from tkinter import filedialog
        filename = filedialog.asksaveasfilename(
            defaultextension=".mlcl",
            filetypes=[("分子文件", "*.mlcl"), ("所有文件", "*.*")],
            title="保存分子文件"
        )
        
        if not filename:
            return
        
        try:
            # 构建文件内容
            content = "MOLECULE_FILE v2.0\n"
            content += f"# 分子搭建器导出文件\n"
            content += f"# 生成时间: {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n\n"
            
            # 原子信息
            content += "[ATOMS]\n"
            for i, atom in enumerate(self.builder_atoms):
                content += f"{i}: {atom['symbol']} {atom['x']} {atom['y']} {atom['color']} {atom['radius']}\n"
            
            # 键信息
            content += "\n[BONDS]\n"
            for bond in self.builder_bonds:
                content += f"{bond['start_atom']}-{bond['end_atom']}: {bond['order']}\n"
            
            # === 新增分子分析部分 ===
            content += "\n[ANALYSIS]\n"
            
            # 分子式分析
            formula_analysis = self.analyze_molecular_formula()
            content += f"分子式: {formula_analysis['formula']}\n"
            content += f"分子量: {formula_analysis['molecular_weight']:.3f} g/mol\n"
            content += f"原子总数: {formula_analysis['total_atoms']}\n"
            content += f"元素种类: {formula_analysis['element_types']}\n"
            
            # 键分析
            bond_analysis = self.analyze_bonds()
            content += f"键总数: {bond_analysis['total_bonds']}\n"
            content += f"单键数: {bond_analysis['single_bonds']}\n"
            content += f"双键数: {bond_analysis['double_bonds']}\n"
            content += f"三键数: {bond_analysis['triple_bonds']}\n"
            
            # 结构分析
            structure_analysis = self.analyze_structure()
            content += f"最大连接度: {structure_analysis['max_connectivity']}\n"
            content += f"平均连接度: {structure_analysis['avg_connectivity']:.2f}\n"
            content += f"孤立原子数: {structure_analysis['isolated_atoms']}\n"
            content += f"环状结构: {'是' if structure_analysis['has_rings'] else '否'}\n"
            
            # 元素组成
            content += "\n[ELEMENT_COMPOSITION]\n"
            for element, count in formula_analysis['element_count'].items():
                content += f"{element}: {count} 原子 ({count/formula_analysis['total_atoms']*100:.1f}%)\n"
            
            # 键类型分布
            content += "\n[BOND_DISTRIBUTION]\n"
            for bond_type, count in bond_analysis['bond_distribution'].items():
                content += f"{bond_type}: {count} 个\n"
            
            # 原子连接性
            content += "\n[ATOM_CONNECTIVITY]\n"
            for i, atom in enumerate(self.builder_atoms):
                connectivity = len(atom['bonds'])
                content += f"原子 {i} ({atom['symbol']}): {connectivity} 个连接\n"
            
            # 分子特征
            content += "\n[MOLECULAR_FEATURES]\n"
            features = self.identify_molecular_features()
            for feature in features:
                content += f"- {feature}\n"
            
            # 写入文件
            with open(filename, 'w', encoding='utf-8') as f:
                f.write(content)
            
            # 显示保存成功信息，包含分析摘要
            analysis_summary = f"分子已保存到:\n{filename}\n\n"
            analysis_summary += f"分子分析摘要:\n"
            analysis_summary += f"• 分子式: {formula_analysis['formula']}\n"
            analysis_summary += f"• 分子量: {formula_analysis['molecular_weight']:.3f} g/mol\n"
            analysis_summary += f"• 键类型: {bond_analysis['single_bonds']}单/{bond_analysis['double_bonds']}双/{bond_analysis['triple_bonds']}三\n"
            analysis_summary += f"• 结构特征: {', '.join(features[:3])}\n"
            
            messagebox.showinfo("保存成功", analysis_summary)
            
        except Exception as e:
            messagebox.showerror("错误", f"保存文件失败:\n{str(e)}")

    def show_chemistry_lab(self):
        """显示化学实验模拟工具 - 完整功能优化版"""
        lab_window = tk.Toplevel(self.root)
        lab_window.title("化学实验模拟")
        lab_window.geometry("900x800")
        lab_window.resizable(True, True)
        try:

            icon_image = tk.PhotoImage(file='./res/icon/func/experiment.ico')
            lab_window.iconphoto(True, icon_image)
        except:
            pass
        
        # 居中显示
        lab_window.transient(self.root)
        lab_window.grab_set()
        
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 450
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 350
        lab_window.geometry(f"+{x}+{y}")
        
        # 创建主框架
        main_frame = tk.Frame(lab_window)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=20, pady=20)
        
        # 标题
        title_label = tk.Label(main_frame, text="化学实验模拟实验室", 
                              font=('Unifont', 16),
                              fg='darkblue')
        title_label.pack(pady=(0, 15))
        
        # 创建选项卡
        notebook = ttk.Notebook(main_frame)
        notebook.pack(fill=tk.BOTH, expand=True)
        
        # === 选项卡1: 反应模拟 ===
        reaction_frame = tk.Frame(notebook)
        notebook.add(reaction_frame, text="反应模拟")
        self.create_reaction_simulator(reaction_frame)
        
        # === 选项卡2: 仪器使用 ===
        instruments_frame = tk.Frame(notebook)
        notebook.add(instruments_frame, text="实验仪器")
        self.create_instruments_demo(instruments_frame)
        
        # === 选项卡3: 安全知识 ===
        safety_frame = tk.Frame(notebook)
        notebook.add(safety_frame, text="实验安全")
        self.create_safety_guide(safety_frame)
        
        # 关闭按钮
        close_button = tk.Button(main_frame, text="关闭", 
                               command=lab_window.destroy,
                               font=('Unifont', 10), width=10)
        close_button.pack(pady=10)

    def start_experiment(self):
        """开始实验模拟 - 性能优化版"""
        reaction = self.reaction_var.get()
        if not reaction:
            return
        
        # 停止之前的动画
        self.stop_all_animations()
        
        self.phenomenon_text.config(state=tk.NORMAL)
        self.phenomenon_text.delete(1.0, tk.END)
        
        # 清空画布并绘制基础装置
        self.lab_canvas.delete("all")
        self.draw_lab_apparatus()
        
        # 根据反应类型显示不同现象
        if "HCl + NaOH" in reaction:
            self.simulate_acid_base_optimized()
            self.phenomenon_text.insert(tk.END, "🔬 酸碱中和反应\n\n")
            self.phenomenon_text.insert(tk.END, "• 盐酸(HCl)与氢氧化钠(NaOH)混合\n")
            self.phenomenon_text.insert(tk.END, "• 溶液温度略微升高\n")
            self.phenomenon_text.insert(tk.END, "• 生成氯化钠(NaCl)和水(H₂O)\n")
            self.phenomenon_text.insert(tk.END, "• 溶液呈中性(pH=7)")
            
        elif "Zn + 2HCl" in reaction:
            self.simulate_metal_acid_optimized()
            self.phenomenon_text.insert(tk.END, "🔬 金属与酸反应\n\n")
            self.phenomenon_text.insert(tk.END, "• 锌粒与盐酸剧烈反应\n")
            self.phenomenon_text.insert(tk.END, "• 产生大量氢气气泡(H₂↑)\n")
            self.phenomenon_text.insert(tk.END, "• 锌粒逐渐溶解\n")
            self.phenomenon_text.insert(tk.END, "• 生成氯化锌(ZnCl₂)溶液")
            
        elif "AgNO₃ + NaCl" in reaction:
            self.simulate_precipitation_optimized()
            self.phenomenon_text.insert(tk.END, "🔬 沉淀反应\n\n")
            self.phenomenon_text.insert(tk.END, "• 硝酸银与氯化钠溶液混合\n")
            self.phenomenon_text.insert(tk.END, "• 立即产生白色絮状沉淀\n")
            self.phenomenon_text.insert(tk.END, "• 沉淀为氯化银(AgCl)\n")
            self.phenomenon_text.insert(tk.END, "• 沉淀不溶于硝酸")

        elif "CaCO₃ + 2HCl" in reaction:
            self.simulate_gas_generation_optimized()
            self.phenomenon_text.insert(tk.END, "🔬 气体生成反应\n\n")
            self.phenomenon_text.insert(tk.END, "• 碳酸钙与盐酸反应\n")
            self.phenomenon_text.insert(tk.END, "• 产生大量二氧化碳气泡(CO₂↑)\n")
            self.phenomenon_text.insert(tk.END, "• 碳酸钙逐渐溶解\n")
            self.phenomenon_text.insert(tk.END, "• 生成氯化钙溶液\n")
            self.phenomenon_text.insert(tk.END, "• 可用澄清石灰水检验CO₂")
            
        elif "CH₄ + 2O₂" in reaction:
            self.simulate_combustion_reaction_optimized()
            self.phenomenon_text.insert(tk.END, "🔬 燃烧反应\n\n")
            self.phenomenon_text.insert(tk.END, "• 甲烷在空气中燃烧\n")
            self.phenomenon_text.insert(tk.END, "• 产生明亮的蓝色火焰\n")
            self.phenomenon_text.insert(tk.END, "• 放出大量热量\n")
            self.phenomenon_text.insert(tk.END, "• 生成二氧化碳和水\n")
            self.phenomenon_text.insert(tk.END, "• 使澄清石灰水变浑浊")
            
        elif "Fe + CuSO₄" in reaction:
            self.simulate_replacement_reaction_optimized()
            self.phenomenon_text.insert(tk.END, "🔬 置换反应\n\n")
            self.phenomenon_text.insert(tk.END, "• 铁钉放入硫酸铜溶液\n")
            self.phenomenon_text.insert(tk.END, "• 铁钉表面析出红色铜\n")
            self.phenomenon_text.insert(tk.END, "• 溶液蓝色逐渐变浅\n")
            self.phenomenon_text.insert(tk.END, "• 生成硫酸亚铁溶液\n")
            self.phenomenon_text.insert(tk.END, "• 铁钉质量减小，铜沉积增加")
        
        self.phenomenon_text.config(state=tk.DISABLED)

    def stop_all_animations(self):
        """停止所有动画"""
        if hasattr(self, 'animation_jobs'):
            for job in self.animation_jobs:
                if job:
                    self.root.after_cancel(job)
            self.animation_jobs = []
        else:
            self.animation_jobs = []

    def simulate_acid_base_optimized(self):
        """模拟酸碱中和反应 - 优化版"""
        canvas = self.lab_canvas
        
        # 酸溶液（红色）
        canvas.create_oval(self.beaker_x - 55, self.beaker_y - 75, 
                          self.beaker_x + 55, self.beaker_y - 10,
                          fill='#FF6B6B', outline='', tags="acid")
        
        # 简化滴加动画（只有2步）
        def add_base_drops(step=0):
            if step < 2:
                canvas.delete("droplet")
                
                y_offset = -100 - step * 20
                canvas.create_oval(self.beaker_x - 6, y_offset, 
                                 self.beaker_x + 6, y_offset + 12,
                                 fill='#6B8EFF', outline='#4A6FDC', width=1, tags="droplet")
                
                job = canvas.after(300, lambda: add_base_drops(step + 1))
                self.animation_jobs.append(job)
            else:
                show_mixture()
        
        def show_mixture():
            canvas.delete("acid")
            canvas.delete("droplet")
            
            # 混合后的中性溶液
            canvas.create_oval(self.beaker_x - 55, self.beaker_y - 75, 
                              self.beaker_x + 55, self.beaker_y - 10,
                              fill='#D8BFD8', outline='', tags="mixture")
            
            # 温度升高
            canvas.delete("thermometer_fill")
            canvas.create_rectangle(self.beaker_x + 83, self.beaker_y - 60, 
                                  self.beaker_x + 87, self.beaker_y - 20,
                                  fill='red', outline='', tags="thermometer_fill")
        
        # 开始动画
        add_base_drops()

    def simulate_metal_acid_optimized(self):
        """模拟金属与酸反应 - 优化版"""
        canvas = self.lab_canvas
        
        # 酸溶液
        canvas.create_oval(self.beaker_x - 55, self.beaker_y - 75, 
                          self.beaker_x + 55, self.beaker_y - 10,
                          fill='#FFA500', outline='', tags="acid_solution")
        
        # 锌粒
        zinc_positions = [
            (self.beaker_x - 20, self.beaker_y - 50),
            (self.beaker_x, self.beaker_y - 55),
            (self.beaker_x + 20, self.beaker_y - 48)
        ]
        
        for i, (x, y) in enumerate(zinc_positions):
            canvas.create_oval(x-8, y-8, x+8, y+8, 
                              fill='#C0C0C0', outline='gray', width=1, tags=f"zinc_{i}")
        
        # 优化气泡动画（减少数量和频率）
        def bubble_animation(step=0):
            if step < 6:  # 减少动画步数
                canvas.delete("bubbles")
                
                # 减少气泡数量
                for i in range(5):
                    x = self.beaker_x - 30 + (i * 18 + step * 3) % 60
                    y = self.beaker_y - 60 - (step * 6 + i * 4)
                    size = 3 + (i % 2)  # 减少大小变化
                    
                    if y > self.beaker_y - 75:
                        canvas.create_oval(x-size, y-size, x+size, y+size, 
                                         fill='#87CEEB', outline='#5F9EA0', width=1, tags="bubbles")
                
                job = canvas.after(200, lambda: bubble_animation(step + 1))  # 增加间隔
                self.animation_jobs.append(job)
        
        bubble_animation()

    def simulate_precipitation_optimized(self):
        """模拟沉淀反应 - 优化版"""
        canvas = self.lab_canvas
        
        # 初始溶液
        canvas.create_oval(self.beaker_x - 55, self.beaker_y - 75, 
                          self.beaker_x + 55, self.beaker_y - 10,
                          fill='#F0F8FF', outline='', tags="solution")
        
        # 优化沉淀动画（减少步骤）
        def precipitation_animation(step=0):
            if step < 2:  # 减少动画步骤
                canvas.delete("precipitate")
                
                # 每步增加沉淀数量
                num_precipitates = (step + 1) * 12
                
                for i in range(num_precipitates):
                    x = self.beaker_x - 35 + (i % 6) * 14
                    y = self.beaker_y - 35 + (i // 6) * 8
                    size = 3
                    
                    canvas.create_oval(x-size, y-size, x+size, y+size,
                                     fill='white', outline='lightgray', width=1, tags="precipitate")
                
                job = canvas.after(400, lambda: precipitation_animation(step + 1))  # 增加间隔
                self.animation_jobs.append(job)
        
        precipitation_animation()

    def draw_lab_apparatus(self):
        """绘制实验室装置 - 完整但优化版"""
        canvas = self.lab_canvas
        canvas.update()
        canvas_width = canvas.winfo_width()
        canvas_height = canvas.winfo_height()
        
        if canvas_width <= 1 or canvas_height <= 1:
            canvas.after(100, self.draw_lab_apparatus)
            return
        
        # 清空画布
        canvas.delete("all")
        
        # 背景
        canvas.create_rectangle(0, 0, canvas_width, canvas_height, fill='#F0F8FF', outline='')
        
        # 实验台
        bench_height = 80
        canvas.create_rectangle(0, canvas_height - bench_height, canvas_width, canvas_height, 
                              fill='#8B4513', outline='#654321', width=3)
        
        # 实验台纹理（简化）
        for i in range(0, canvas_width, 30):  # 增加间隔
            canvas.create_line(i, canvas_height - bench_height, i, canvas_height, 
                             fill='#654321', width=1)
        
        # 烧杯位置
        self.beaker_x = canvas_width // 2
        self.beaker_y = canvas_height - bench_height - 100
        
        # 绘制烧杯
        self.draw_beaker_optimized(canvas)
        
        # 绘制其他实验器材
        self.draw_other_apparatus_optimized(canvas, canvas_width, canvas_height)

    def draw_beaker_optimized(self, canvas):
        """绘制烧杯 - 优化版"""
        # 烧杯主体
        canvas.create_oval(self.beaker_x - 60, self.beaker_y - 80, 
                          self.beaker_x + 60, self.beaker_y + 20,
                          fill='#E6F3FF', outline='#4682B4', width=2)
        
        # 烧杯口
        canvas.create_line(self.beaker_x - 50, self.beaker_y - 80,
                          self.beaker_x + 50, self.beaker_y - 80,
                          fill='#4682B4', width=2)
        
        # 烧杯刻度（减少数量）
        for i in range(1, 4):
            y_pos = self.beaker_y - 80 + i * 25
            canvas.create_line(self.beaker_x - 55, y_pos, self.beaker_x - 48, y_pos,
                              fill='#4682B4', width=1)
            canvas.create_line(self.beaker_x + 48, y_pos, self.beaker_x + 55, y_pos,
                              fill='#4682B4', width=1)

    def draw_other_apparatus_optimized(self, canvas, width, height):
        """绘制其他实验器材 - 优化版"""
        # 酒精灯（左侧）
        lamp_x = self.beaker_x - 150
        lamp_y = height - 180
        
        # 酒精灯（简化绘制）
        canvas.create_rectangle(lamp_x - 15, lamp_y + 40, lamp_x + 15, lamp_y + 60,
                              fill='#C0C0C0', outline='#808080', width=1)
        canvas.create_oval(lamp_x - 20, lamp_y, lamp_x + 20, lamp_y + 40,
                          fill='#FFFFFF', outline='#808080', width=1)
        canvas.create_line(lamp_x, lamp_y, lamp_x, lamp_y - 8,
                          fill='#8B4513', width=2)
        canvas.create_polygon(lamp_x - 4, lamp_y - 20, lamp_x, lamp_y - 30, lamp_x + 4, lamp_y - 20,
                             fill='#FF4500', outline='#FF0000', width=1)
        
        # 试剂瓶（右侧）
        bottle_x = self.beaker_x + 150
        bottle_y = height - 180
        
        canvas.create_rectangle(bottle_x - 20, bottle_y, bottle_x + 20, bottle_y + 60,
                              fill='#87CEEB', outline='#4682B4', width=1)
        canvas.create_rectangle(bottle_x - 15, bottle_y - 15, bottle_x + 15, bottle_y,
                              fill='#87CEEB', outline='#4682B4', width=1)
        canvas.create_rectangle(bottle_x - 18, bottle_y + 15, bottle_x + 18, bottle_y + 35,
                              fill='white', outline='#4682B4', width=1)
        canvas.create_text(bottle_x, bottle_y + 25, text="HCl", font=('Unifont', 8))
        
        # 温度计
        self.draw_thermometer_optimized(canvas)

    def draw_thermometer_optimized(self, canvas):
        """绘制温度计 - 优化版"""
        # 温度计外壳
        canvas.create_rectangle(self.beaker_x + 80, self.beaker_y - 100, 
                              self.beaker_x + 90, self.beaker_y - 20,
                              fill='white', outline='black', width=1)
        
        # 温度计刻度（减少数量）
        for i in range(3):
            y_pos = self.beaker_y - 100 + i * 40
            canvas.create_line(self.beaker_x + 90, y_pos, self.beaker_x + 95, y_pos,
                              fill='black', width=1)
            canvas.create_text(self.beaker_x + 100, y_pos, text=str(20 + i * 20), 
                              font=('Unifont', 7))
        
        # 初始液柱
        canvas.create_rectangle(self.beaker_x + 83, self.beaker_y - 40, 
                              self.beaker_x + 87, self.beaker_y - 20,
                              fill='red', outline='', tags="thermometer_fill")

    def simulate_gas_generation_optimized(self):
        """模拟气体生成反应（碳酸钙与盐酸）- 优化版"""
        canvas = self.lab_canvas
        
        # 绘制锥形瓶（代替烧杯）
        # 锥形瓶底部
        canvas.create_oval(self.beaker_x - 60, self.beaker_y - 40, 
                          self.beaker_x + 60, self.beaker_y + 20,
                          fill='#E6F3FF', outline='#4682B4', width=2,
                          tags="flask_body")
        
        # 锥形瓶颈部
        canvas.create_polygon(
            self.beaker_x - 40, self.beaker_y - 40,
            self.beaker_x - 20, self.beaker_y - 80,
            self.beaker_x + 20, self.beaker_y - 80,
            self.beaker_x + 40, self.beaker_y - 40,
            fill='#E6F3FF', outline='#4682B4', width=2,
            tags="flask_neck"
        )
        
        # 瓶口
        canvas.create_line(self.beaker_x - 15, self.beaker_y - 80,
                          self.beaker_x + 15, self.beaker_y - 80,
                          fill='#4682B4', width=3,
                          tags="flask_mouth")
        
        # 酸溶液（浅黄色）
        canvas.create_oval(self.beaker_x - 55, self.beaker_y - 35, 
                          self.beaker_x + 55, self.beaker_y - 10,
                          fill='#FFFACD', outline='',
                          tags="acid_solution")
        
        # 碳酸钙固体（白色块状）
        caco3_positions = [
            (self.beaker_x - 25, self.beaker_y - 30),
            (self.beaker_x - 10, self.beaker_y - 35),
            (self.beaker_x + 5, self.beaker_y - 28),
            (self.beaker_x + 20, self.beaker_y - 33)
        ]
        
        for i, (x, y) in enumerate(caco3_positions):
            # 绘制不规则形状的固体颗粒
            points = [
                x-5, y-5,
                x+3, y-8,
                x+7, y-1,
                x-2, y+4,
                x-7, y+2
            ]
            canvas.create_polygon(points,
                                 fill='white', outline='#D3D3D3', width=1,
                                 tags=f"caco3_{i}")
        
        # 导气管
        tube_x = self.beaker_x + 80
        tube_y = self.beaker_y - 80
        
        # 导气管连接到锥形瓶
        canvas.create_line(self.beaker_x + 15, self.beaker_y - 80,
                          tube_x - 30, tube_y,
                          fill='gray', width=2,
                          tags="tube_connector")
        
        # 水平导气管
        canvas.create_line(tube_x - 30, tube_y,
                          tube_x + 50, tube_y,
                          fill='gray', width=2,
                          tags="tube_horizontal")
        
        # 垂直导气管（收集气体）
        canvas.create_line(tube_x + 50, tube_y,
                          tube_x + 50, tube_y + 60,
                          fill='gray', width=2,
                          tags="tube_vertical")
        
        # 集气瓶（水槽法收集CO2）
        gas_bottle_x = tube_x + 50
        gas_bottle_y = tube_y + 40
        
        # 集气瓶（装满水倒置）
        canvas.create_rectangle(gas_bottle_x - 25, gas_bottle_y - 40,
                               gas_bottle_x + 25, gas_bottle_y + 40,
                               fill='#87CEEB', outline='#4682B4', width=2,
                               tags="gas_bottle")
        
        # 水槽
        trough_x = tube_x + 50
        trough_y = tube_y + 100
        
        canvas.create_rectangle(trough_x - 60, trough_y,
                               trough_x + 60, trough_y + 20,
                               fill='#ADD8E6', outline='#4682B4', width=2,
                               tags="water_trough")
        
        # 气体生成动画
        def gas_generation_animation(step=0):
            if step < 8:  # 减少动画步数
                # 清除上一帧的气泡
                canvas.delete("co2_bubbles")
                canvas.delete("gas_bubbles")
                
                # 反应瓶中的气泡（CO2产生）
                for i in range(6):  # 减少气泡数量
                    # 气泡从固体位置上升
                    base_x = self.beaker_x - 20 + (i % 3) * 20
                    base_y = self.beaker_y - 30
                    
                    # 气泡上升路径
                    x_offset = math.sin(step * 0.5 + i) * 8
                    y_offset = -step * 8 - i * 2
                    
                    x = base_x + x_offset
                    y = base_y + y_offset
                    
                    if y > self.beaker_y - 80:  # 气泡在瓶内
                        size = 2 + (i % 2)
                        canvas.create_oval(x-size, y-size, x+size, y+size,
                                         fill='white', outline='#D3D3D3', width=1,
                                         tags="co2_bubbles")
                
                # 导气管中的气泡
                if step > 2:  # 延迟一点开始
                    for j in range(3):
                        # 气泡沿导气管移动
                        tube_progress = (step - 3) * 0.1 + j * 0.3
                        if 0 <= tube_progress <= 1.0:
                            # 计算导气管上的位置
                            if tube_progress < 0.4:  # 连接管部分
                                start_x = self.beaker_x + 15
                                start_y = self.beaker_y - 80
                                end_x = tube_x - 30
                                end_y = tube_y
                            elif tube_progress < 0.7:  # 水平管部分
                                start_x = tube_x - 30
                                start_y = tube_y
                                end_x = tube_x + 50
                                end_y = tube_y
                            else:  # 垂直管部分
                                start_x = tube_x + 50
                                start_y = tube_y
                                end_x = tube_x + 50
                                end_y = tube_y + 60
                                tube_progress = (tube_progress - 0.7) / 0.3
                            
                            # 线性插值计算当前位置
                            if tube_progress < 0.4:
                                segment_progress = tube_progress / 0.4
                                x = start_x + (end_x - start_x) * segment_progress
                                y = start_y + (end_y - start_y) * segment_progress
                            elif tube_progress < 0.7:
                                segment_progress = (tube_progress - 0.4) / 0.3
                                x = start_x + (end_x - start_x) * segment_progress
                                y = start_y + (end_y - start_y) * segment_progress
                            else:
                                segment_progress = tube_progress
                                x = start_x + (end_x - start_x) * segment_progress
                                y = start_y + (end_y - start_y) * segment_progress
                            
                            # 绘制导气管中的气泡
                            size = 3
                            canvas.create_oval(x-size, y-size, x+size, y+size,
                                             fill='white', outline='#D3D3D3', width=1,
                                             tags="gas_bubbles")
                
                # 集气瓶中的气体聚集
                if step > 4:
                    # 计算气体占据的高度（从底部开始）
                    gas_height = min(30, (step - 4) * 6)
                    
                    # 绘制气体层（用浅蓝色表示）
                    canvas.delete("gas_layer")
                    gas_top = gas_bottle_y + 40 - gas_height
                    canvas.create_rectangle(gas_bottle_x - 25, gas_top,
                                           gas_bottle_x + 25, gas_bottle_y + 40,
                                           fill='#F0F8FF', outline='#666666', width=1,
                                           tags="gas_layer")
                    
                    # 添加CO2标签
                    canvas.create_text(gas_bottle_x, gas_bottle_y + 20,
                                      text="CO₂", font=('Unifont', 9),
                                      fill='#333333', tags="gas_label")
                
                # 碳酸钙逐渐溶解
                if step > 2:
                    dissolve_factor = min(1.0, (step - 2) / 6.0)
                    
                    for i in range(len(caco3_positions)):
                        canvas.delete(f"caco3_{i}")
                        
                        # 根据溶解程度调整大小和颜色
                        if dissolve_factor < 0.7:
                            # 计算新的大小（逐渐变小）
                            scale = 1.0 - dissolve_factor * 1.4
                            
                            x, y = caco3_positions[i]
                            points = [
                                x-5*scale, y-5*scale,
                                x+3*scale, y-8*scale,
                                x+7*scale, y-1*scale,
                                x-2*scale, y+4*scale,
                                x-7*scale, y+2*scale
                            ]
                            
                            # 计算颜色变浅程度
                            gray_value = int(255 * (1.0 - dissolve_factor * 0.8))
                            if gray_value < 150:
                                gray_value = 150
                            
                            fill_color = f'#{gray_value:02x}{gray_value:02x}{gray_value:02x}'
                            outline_color = f'#{(gray_value-50):02x}{(gray_value-50):02x}{(gray_value-50):02x}'
                            
                            canvas.create_polygon(points,
                                                 fill=fill_color,
                                                 outline=outline_color,
                                                 width=1,
                                                 tags=f"caco3_{i}")
                
                job = canvas.after(250, lambda: gas_generation_animation(step + 1))
                self.animation_jobs.append(job)
        
        # 导入math模块用于正弦函数
        import math
        
        # 开始动画
        gas_generation_animation()

    def simulate_combustion_reaction_optimized(self):
        """模拟燃烧反应（甲烷燃烧）- 优化版"""
        canvas = self.lab_canvas
        
        # 绘制燃烧匙
        spoon_x = self.beaker_x
        spoon_y = self.beaker_y - 120
        
        # 燃烧匙柄
        canvas.create_line(spoon_x, spoon_y,
                          spoon_x, spoon_y + 40,
                          fill='#8B4513', width=4,
                          tags="spoon_handle")
        
        # 燃烧匙头（椭圆形）
        canvas.create_oval(spoon_x - 15, spoon_y + 30,
                          spoon_x + 15, spoon_y + 50,
                          fill='#C0C0C0', outline='#808080', width=2,
                          tags="spoon_bowl")
        
        # 甲烷气体源（集气瓶）
        gas_source_x = self.beaker_x - 100
        gas_source_y = self.beaker_y - 80
        
        canvas.create_rectangle(gas_source_x - 25, gas_source_y - 40,
                               gas_source_x + 25, gas_source_y + 40,
                               fill='#F0F8FF', outline='#4682B4', width=2,
                               tags="gas_source")
        
        canvas.create_text(gas_source_x, gas_source_y,
                          text="CH₄", font=('Unifont', 10),
                          fill='#333333', tags="gas_label")
        
        # 导气管
        canvas.create_line(gas_source_x + 25, gas_source_y,
                          spoon_x - 30, spoon_y + 40,
                          fill='gray', width=2,
                          tags="gas_tube")
        
        # 添加阀门
        canvas.create_oval(spoon_x - 35, spoon_y + 35,
                          spoon_x - 25, spoon_y + 45,
                          fill='#808080', outline='#666666', width=1,
                          tags="valve")
        
        # 绘制烧杯（用于收集燃烧产物检验）
        beaker2_x = self.beaker_x + 100
        beaker2_y = self.beaker_y - 80
        
        canvas.create_oval(beaker2_x - 40, beaker2_y - 40,
                          beaker2_x + 40, beaker2_y + 20,
                          fill='#E6F3FF', outline='#4682B4', width=2,
                          tags="product_beaker")
        
        # 烧杯中预先加入澄清石灰水
        canvas.create_oval(beaker2_x - 35, beaker2_y - 35,
                          beaker2_x + 35, beaker2_y - 10,
                          fill='#F0FFF0', outline='',
                          tags="limewater")
        
        canvas.create_text(beaker2_x, beaker2_y + 30,
                          text="澄清石灰水", font=('Unifont', 8),
                          fill='#333333', tags="limewater_label")
        
        # 燃烧动画
        def combustion_animation(step=0):
            if step < 10:  # 动画总步数
                # 清除上一帧的火焰和气体
                canvas.delete("flame")
                canvas.delete("methane_gas")
                canvas.delete("co2_bubbles")
                canvas.delete("turbidity")
                
                # 阶段1：甲烷气体流出（前3步）
                if step < 3:
                    # 绘制甲烷气体流
                    for i in range(3):
                        # 气体从导气管流出
                        x = spoon_x - 30 + (i * 8)
                        y = spoon_y + 40 - (step * 5) - (i * 3)
                        size = 4 + (i % 2)
                        
                        # 使用浅蓝色表示甲烷气体
                        canvas.create_oval(x-size, y-size, x+size, y+size,
                                         fill='#ADD8E6',
                                         outline='#5F9EA0', width=1,
                                         tags="methane_gas")
                
                # 阶段2：点火燃烧（第3步开始）
                if step >= 3:
                    # 绘制火焰
                    flame_height = 20 + min(step - 3, 3) * 8
                    
                    # 火焰内层（黄色）
                    flame_points_inner = [
                        spoon_x, spoon_y + 40,
                        spoon_x - 8, spoon_y + 40 - flame_height * 0.7,
                        spoon_x, spoon_y + 40 - flame_height,
                        spoon_x + 8, spoon_y + 40 - flame_height * 0.7
                    ]
                    
                    canvas.create_polygon(flame_points_inner,
                                         fill='#FFD700', outline='#FFA500', width=1,
                                         tags="flame")
                    
                    # 火焰外层（橙色）
                    flame_points_outer = [
                        spoon_x, spoon_y + 40,
                        spoon_x - 12, spoon_y + 40 - flame_height * 0.6,
                        spoon_x, spoon_y + 40 - flame_height * 0.9,
                        spoon_x + 12, spoon_y + 40 - flame_height * 0.6
                    ]
                    
                    # 火焰闪烁效果
                    if step % 2 == 0:
                        flame_color = '#FF8C00'
                    else:
                        flame_color = '#FF4500'
                    
                    canvas.create_polygon(flame_points_outer,
                                         fill=flame_color,
                                         outline='#FF6347', width=1,
                                         tags="flame")
                    
                    # 火星效果（偶尔出现）
                    if step % 3 == 0:
                        spark_x = spoon_x - 10 + (step % 5)
                        spark_y = spoon_y + 40 - flame_height - 5
                        canvas.create_oval(spark_x-1, spark_y-1, spark_x+1, spark_y+1,
                                         fill='#FF0000', outline='',
                                         tags="flame")
                
                # 阶段3：燃烧产物检验（第5步开始）
                if step >= 5:
                    # 燃烧产物（CO2）进入石灰水
                    # 绘制气泡进入石灰水
                    bubble_step = step - 5
                    
                    if bubble_step < 4:
                        for i in range(3):
                            x = beaker2_x - 10 + (i * 10)
                            y = beaker2_y - 30 - bubble_step * 8 + (i * 2)
                            size = 2 + (i % 2)
                            
                            canvas.create_oval(x-size, y-size, x+size, y+size,
                                             fill='white', outline='#D3D3D3', width=1,
                                             tags="co2_bubbles")
                    
                    # 石灰水变浑浊（第8步开始）
                    if step >= 8:
                        # 计算浑浊程度
                        turbidity_level = min(0.7, (step - 8) * 0.1)
                        
                        # 创建浑浊层
                        canvas.delete("turbidity")
                        
                        # 生成多个白色颗粒模拟浑浊
                        num_particles = int(20 * turbidity_level)
                        for i in range(num_particles):
                            x = beaker2_x - 30 + (i % 6) * 12
                            y = beaker2_y - 35 + ((i // 6) % 4) * 10
                            size = 1 + (i % 3)
                            
                            # 使用浅灰色表示浑浊颗粒
                            gray_value = 200 + int(30 * turbidity_level)
                            fill_color = f'#{gray_value:02x}{gray_value:02x}{gray_value:02x}'
                            
                            canvas.create_oval(x-size, y-size, x+size, y+size,
                                             fill=fill_color,
                                             outline='#D3D3D3',
                                             width=1,
                                             tags="turbidity")
                        
                        # 添加文字说明
                        if step == 9:
                            canvas.create_text(beaker2_x, beaker2_y + 50,
                                              text="石灰水变浑浊，证明生成CO₂",
                                              font=('Unifont', 9),
                                              fill='#333333',
                                              tags="turbidity_text")
                
                job = canvas.after(300, lambda: combustion_animation(step + 1))
                self.animation_jobs.append(job)
        
        # 开始动画
        combustion_animation()

    def simulate_replacement_reaction_optimized(self):
        """模拟置换反应（铁与硫酸铜）- 优化版"""
        canvas = self.lab_canvas
        
        # 绘制烧杯（盛放硫酸铜溶液）
        # 硫酸铜溶液（蓝色）
        canvas.create_oval(self.beaker_x - 55, self.beaker_y - 75, 
                          self.beaker_x + 55, self.beaker_y - 10,
                          fill='#87CEEB', outline='', tags="cuso4_solution")
        
        # 溶液颜色标签
        canvas.create_text(self.beaker_x, self.beaker_y - 85,
                          text="CuSO₄溶液", font=('Unifont', 9),
                          fill='#333333', tags="solution_label")
        
        # 铁钉（多个，模拟投入过程）
        iron_nails = []
        nail_start_x = self.beaker_x - 120
        nail_start_y = self.beaker_y - 180
        
        # 绘制3个铁钉在烧杯外（准备投入）
        for i in range(3):
            nail_x = nail_start_x + i * 40
            nail_y = nail_start_y
            
            # 铁钉主体（矩形）
            canvas.create_rectangle(nail_x - 3, nail_y - 15,
                                   nail_x + 3, nail_y + 5,
                                   fill='#808080', outline='#666666', width=1,
                                   tags=f"iron_nail_{i}_outside")
            
            # 铁钉头（圆形）
            canvas.create_oval(nail_x - 4, nail_y - 18,
                              nail_x + 4, nail_y - 12,
                              fill='#A9A9A9', outline='#666666', width=1,
                              tags=f"iron_nail_{i}_head")
            
            iron_nails.append({
                'id': i,
                'x': nail_x,
                'y': nail_y,
                'in_solution': False,
                'dissolve_step': 0
            })
        
        # 铜沉积层标签位置
        copper_deposit_y = self.beaker_y - 10
        
        # 置换反应动画
        def replacement_animation(step=0):
            if step < 15:  # 动画总步数
                # 清除上一帧的动态元素
                canvas.delete("falling_nail")
                canvas.delete("copper_deposit")
                canvas.delete("reaction_bubbles")
                canvas.delete("color_change")
                
                # 阶段1：铁钉落入溶液（0-4步）
                if step < 5:
                    # 每个铁钉依次落入
                    nail_index = step
                    if nail_index < len(iron_nails):
                        nail = iron_nails[nail_index]
                        
                        # 隐藏外部的铁钉
                        canvas.delete(f"iron_nail_{nail_index}_outside")
                        canvas.delete(f"iron_nail_{nail_index}_head")
                        
                        # 绘制下落的铁钉
                        fall_distance = min(80, step * 25)
                        nail_y_current = nail['y'] + fall_distance
                        
                        # 铁钉主体
                        canvas.create_rectangle(nail['x'] - 3, nail_y_current - 15,
                                              nail['x'] + 3, nail_y_current + 5,
                                              fill='#808080', outline='#666666', width=1,
                                              tags="falling_nail")
                        
                        # 铁钉头
                        canvas.create_oval(nail['x'] - 4, nail_y_current - 18,
                                          nail['x'] + 4, nail_y_current - 12,
                                          fill='#A9A9A9', outline='#666666', width=1,
                                          tags="falling_nail")
                        
                        # 当铁钉进入溶液
                        if fall_distance >= 80:
                            nail['in_solution'] = True
                            nail['solution_x'] = self.beaker_x - 30 + nail_index * 20
                            nail['solution_y'] = self.beaker_y - 50
                
                # 阶段2：置换反应进行（5-14步）
                if step >= 5:
                    # 绘制溶液中的铁钉
                    for nail in iron_nails:
                        if nail['in_solution']:
                            # 铁钉逐渐溶解（颜色变浅，尺寸变小）
                            dissolve_factor = min(1.0, (step - 5 - nail['id'] * 2) / 6.0)
                            
                            if dissolve_factor < 1.0:
                                # 计算当前大小
                                width = 3 * (1.0 - dissolve_factor * 0.8)
                                length = 20 * (1.0 - dissolve_factor * 0.8)
                                
                                # 计算颜色变浅程度
                                gray_value = int(200 * (1.0 - dissolve_factor * 0.6))
                                if gray_value < 100:
                                    gray_value = 100
                                
                                # 绘制溶解中的铁钉
                                canvas.delete(f"iron_in_solution_{nail['id']}")
                                
                                # 铁钉颜色随溶解变浅
                                fill_color = f'#{gray_value:02x}{gray_value:02x}{gray_value:02x}'
                                outline_color = f'#{gray_value-40:02x}{gray_value-40:02x}{gray_value-40:02x}'
                                
                                # 铁钉主体
                                canvas.create_rectangle(
                                    nail['solution_x'] - width,
                                    nail['solution_y'] - length/2,
                                    nail['solution_x'] + width,
                                    nail['solution_y'] + length/2,
                                    fill=fill_color,
                                    outline=outline_color,
                                    width=1,
                                    tags=f"iron_in_solution_{nail['id']}"
                                )
                                
                                # 铁钉头
                                head_gray_value = int(gray_value * 0.8)
                                head_fill_color = f'#{head_gray_value:02x}{head_gray_value:02x}{head_gray_value:02x}'
                                head_outline_color = f'#{head_gray_value-30:02x}{head_gray_value-30:02x}{head_gray_value-30:02x}'
                                
                                canvas.create_oval(
                                    nail['solution_x'] - width*1.3,
                                    nail['solution_y'] - length/2 - width*0.5,
                                    nail['solution_x'] + width*1.3,
                                    nail['solution_y'] - length/2 + width*0.5,
                                    fill=head_fill_color,
                                    outline=head_outline_color,
                                    width=1,
                                    tags=f"iron_in_solution_{nail['id']}"
                                )
                                
                                # 反应气泡（铁置换铜时产生）
                                if dissolve_factor > 0.2 and dissolve_factor < 0.8:
                                    bubble_step = int((dissolve_factor - 0.2) * 30)
                                    
                                    # 从铁钉表面产生小气泡
                                    for i in range(2):
                                        x = nail['solution_x'] + (i - 0.5) * width * 2
                                        y = nail['solution_y'] - length/2 + bubble_step * 3 + i * 2
                                        size = 1 + (i % 2)
                                        
                                        canvas.create_oval(x-size, y-size, x+size, y+size,
                                                         fill='white', outline='#D3D3D3', width=1,
                                                         tags="reaction_bubbles")
                    
                    # 铜沉积（红色金属铜）
                    if step >= 7:
                        # 计算铜沉积量
                        deposit_factor = min(1.0, (step - 7) / 8.0)
                        
                        # 清除旧沉积层
                        canvas.delete("copper_deposit")
                        
                        # 在烧杯底部绘制铜沉积
                        num_copper_particles = int(15 * deposit_factor)
                        
                        for i in range(num_copper_particles):
                            # 沉积在烧杯底部
                            x = self.beaker_x - 40 + (i % 10) * 8
                            y = copper_deposit_y - (i // 10) * 5
                            
                            # 铜颗粒大小和形状略有不同
                            size = 2 + (i % 3)
                            shape_variation = (i % 4) - 2
                            
                            # 绘制铜颗粒（红褐色）
                            canvas.create_oval(x-size + shape_variation,
                                             y-size,
                                             x+size + shape_variation,
                                             y+size,
                                             fill='#B87333',  # 铜色
                                             outline='#8B4513',
                                             width=1,
                                             tags="copper_deposit")
                        
                        # 添加铜沉积标签
                        if deposit_factor > 0.3:
                            canvas.create_text(self.beaker_x, copper_deposit_y - 30,
                                              text="铜沉积", font=('Unifont', 9),
                                              fill='#8B4513', tags="copper_label")
                    
                    # 溶液颜色变化（蓝色变浅）
                    if step >= 6:
                        color_change_factor = min(0.7, (step - 6) * 0.07)
                        
                        # 计算新颜色（蓝色逐渐变浅，带绿色调）
                        base_r, base_g, base_b = 0x87, 0xCE, 0xEB  # 原蓝色
                        
                        # 蓝色减少，绿色增加（FeSO4溶液为浅绿色）
                        new_r = int(base_r * (1 - color_change_factor * 0.3))
                        new_g = int(base_g * (1 + color_change_factor * 0.2))
                        new_b = int(base_b * (1 - color_change_factor * 0.5))
                        
                        # 确保颜色值在0-255范围内
                        new_r = max(0, min(255, new_r))
                        new_g = max(0, min(255, new_g))
                        new_b = max(0, min(255, new_b))
                        
                        new_color = f'#{new_r:02x}{new_g:02x}{new_b:02x}'
                        
                        # 更新溶液颜色
                        canvas.delete("cuso4_solution")
                        canvas.create_oval(self.beaker_x - 55, self.beaker_y - 75, 
                                          self.beaker_x + 55, self.beaker_y - 10,
                                          fill=new_color, outline='', tags="cuso4_solution")
                        
                        # 更新溶液标签
                        if step >= 10:
                            canvas.delete("solution_label")
                            canvas.create_text(self.beaker_x, self.beaker_y - 85,
                                              text="FeSO₄溶液", font=('Unifont', 9),
                                              fill='#333333', tags="solution_label")
                
                job = canvas.after(300, lambda: replacement_animation(step + 1))
                self.animation_jobs.append(job)
        
        # 开始动画
        replacement_animation()

    def reset_experiment(self):
        """重置实验 - 优化版"""
        # 停止所有动画
        self.stop_all_animations()
        
        self.lab_canvas.delete("all")
        self.draw_lab_apparatus()
        
        self.phenomenon_text.config(state=tk.NORMAL)
        self.phenomenon_text.delete(1.0, tk.END)
        self.phenomenon_text.insert(tk.END, "点击'开始实验'观察化学反应现象...")
        self.phenomenon_text.config(state=tk.DISABLED)

    def create_reaction_simulator(self, parent):
        """创建化学反应模拟器"""
        # 反应选择框架
        reaction_select_frame = tk.LabelFrame(parent, text=" 选择化学反应 ", 
                                            font=('Unifont', 11),
                                            relief=tk.GROOVE, bd=2)
