    def setup_balance_interface(self, equation):
        """设置配平界面"""
        # 清空之前的输入框
        for widget in self.coefficient_frame.winfo_children():
            widget.destroy()
        
        self.coefficient_vars = []
        self.coefficient_entries = []
        
        # 解析方程式中的化合物
        reactants, products = equation.split('→')
        reactant_list = [r.strip() for r in reactants.split('+')]
        product_list = [p.strip() for p in products.split('+')]
        all_compounds = reactant_list + product_list
        
        # 创建系数输入框
        for i, compound in enumerate(all_compounds):
            frame = tk.Frame(self.coefficient_frame)
            frame.pack(side=tk.LEFT, padx=8)
            
            var = tk.StringVar(value="1")
            entry = tk.Entry(frame, textvariable=var, font=('Unifont', 10), width=3)
            entry.pack()
            
            label = tk.Label(frame, text=compound, font=('Unifont', 10))
            label.pack()
            
            self.coefficient_vars.append(var)
            self.coefficient_entries.append(entry)
            
            # 在反应物和生成物之间添加箭头
            if i == len(reactant_list) - 1:
                arrow_frame = tk.Frame(self.coefficient_frame)
                arrow_frame.pack(side=tk.LEFT, padx=5)
                tk.Label(arrow_frame, text="→", font=('Unifont', 12)).pack()

    def check_balance(self):
        """检查配平结果"""
        try:
            user_coefficients = []
            for var in self.coefficient_vars:
                value = var.get().strip()
                if value == "":
                    value = "1"
                user_coefficients.append(int(value))
            
            correct_coefficients = self.balance_questions[self.current_balance_index]["coefficients"]
            
            if user_coefficients == correct_coefficients:
                # 配平正确
                self.balance_score += 10
                self.total_score.set(self.total_score.get() + 10)
                self.balance_score_var.set(str(self.balance_score))
                self.balance_feedback.config(
                    text=f"✓ 配平正确！ +10分\n{self.balance_questions[self.current_balance_index]['balanced']}",
                    fg='green'
                )
            else:
                self.balance_feedback.config(
                    text="✗ 配平错误，请检查系数",
                    fg='red'
                )
                
        except ValueError:
            self.balance_feedback.config(
                text="请输入有效的整数系数",
                fg='red'
            )

    def show_balance_answer(self):
        """显示配平答案"""
        balanced_eq = self.balance_questions[self.current_balance_index]["balanced"]
        self.balance_feedback.config(
            text=f"正确答案:\n{balanced_eq}",
            fg='blue'
        )

    def next_balance_question(self):
        """下一道配平题目"""
        self.current_balance_index = (self.current_balance_index + 1) % len(self.balance_questions)
        current_question = self.balance_questions[self.current_balance_index]
        
        self.equation_label.config(text=current_question["equation"])
        self.setup_balance_interface(current_question["equation"])
        self.balance_feedback.config(text="")

