        tk.Label(progress_frame, text="测验分数:", font=('Unifont', 10)).pack(side=tk.LEFT, padx=(20, 0))
        self.quiz_score_var = tk.StringVar(value="0")
        score_display = tk.Label(progress_frame, textvariable=self.quiz_score_var,
                                font=('Unifont', 10), fg='green')
        score_display.pack(side=tk.LEFT, padx=(5, 0))
        
