    def setup_quiz_question(self, question_data):
        """设置测验题目"""
        # 清空选项
        for widget in self.quiz_options_frame.winfo_children():
            widget.destroy()
        
        self.quiz_option_vars = []
        self.quiz_question_label.config(text=question_data["question"])
        
        # 创建选项
        for i, option in enumerate(question_data["options"]):
            var = tk.BooleanVar()
            self.quiz_option_vars.append(var)
            
            rb = tk.Radiobutton(self.quiz_options_frame, text=option, variable=var,
                               font=('Unifont', 10), value=True,
                               command=lambda idx=i: self.on_quiz_option_select(idx))
            rb.pack(anchor=tk.W, pady=2)
            
            # 如果之前已经选择过，恢复选择状态
            if self.quiz_answers[self.current_quiz_index] == i:
                var.set(True)

    def on_quiz_option_select(self, index):
        """处理选项选择"""
        # 确保只有一个选项被选中
        for i, var in enumerate(self.quiz_option_vars):
            if i != index:
                var.set(False)
        
        # 保存答案
        self.quiz_answers[self.current_quiz_index] = index

    def submit_quiz_answer(self):
        """提交测验答案"""
        selected_index = self.quiz_answers[self.current_quiz_index]
        
        if selected_index is None:
            self.quiz_feedback.config(text="请选择一个答案", fg='red')
            return
        
        current_question = self.quiz_questions[self.current_quiz_index]
        
        if selected_index == current_question["correct"]:
            # 答案正确
            if self.quiz_answers[self.current_quiz_index] is not None and \
               self.quiz_answers[self.current_quiz_index] != selected_index:
                # 之前已经回答过且错误，现在改正确了，不给分
                pass
            else:
                # 第一次回答正确
                self.quiz_score += 5
                self.total_score.set(self.total_score.get() + 5)
                self.quiz_score_var.set(str(self.quiz_score))
            
            self.quiz_feedback.config(
                text=f"✓ 正确！\n{current_question['explanation']}",
                fg='green'
            )
        else:
            self.quiz_feedback.config(
                text=f"✗ 错误\n{current_question['explanation']}",
                fg='red'
            )

    def next_quiz_question(self):
        """下一道测验题目"""
        self.current_quiz_index = (self.current_quiz_index + 1) % len(self.quiz_questions)
        self.setup_quiz_question(self.quiz_questions[self.current_quiz_index])
        self.progress_var.set(f"进度: {self.current_quiz_index + 1}/{len(self.quiz_questions)}")
        self.quiz_feedback.config(text="")

    def show_quiz_results(self):
        """显示测验结果"""
        total_questions = len(self.quiz_questions)
        correct_count = 0
        
        for i, answer in enumerate(self.quiz_answers):
            if answer == self.quiz_questions[i]["correct"]:
                correct_count += 1
        
        score_percentage = (correct_count / total_questions) * 100
        
        result_text = f"测验结果:\n"
        result_text += f"正确: {correct_count}/{total_questions}\n"
        result_text += f"得分: {score_percentage:.1f}%\n\n"
        
        if score_percentage >= 80:
            result_text += "优秀！你对化学知识掌握得很好！"
        elif score_percentage >= 60:
            result_text += "良好！继续努力！"
        else:
            result_text += "需要加强学习，加油！"
        
        self.quiz_feedback.config(text=result_text, fg='blue')

