    def plot_titration_curve(self, canvas, titration_type, acid_conc, base_conc, acid_volume, pka, pkb):
        """绘制滴定曲线"""
        canvas.delete("all")
        
        # 画布尺寸
        width = canvas.winfo_width()
        height = canvas.winfo_height()
        
        if width <= 1 or height <= 1:
            width, height = 600, 400
        
        # 边距
        margin = 60
        graph_width = width - 2 * margin
        graph_height = height - 2 * margin
        
        # 绘制坐标轴
        canvas.create_line(margin, margin, margin, height - margin, width=2)  # Y轴
        canvas.create_line(margin, height - margin, width - margin, height - margin, width=2)  # X轴
        
        # 坐标轴标签
        canvas.create_text(margin - 30, margin + graph_height // 2, 
                          text="pH", font=('Unifont', 10), angle=90)
        canvas.create_text(margin + graph_width // 2, height - margin + 20, 
                          text="加入碱体积 (mL)", font=('Unifont', 10))
        
        # 计算滴定数据
        data_points = self.calculate_titration_data(titration_type, acid_conc, base_conc, 
                                                   acid_volume, pka, pkb)
        
        if not data_points:
            canvas.create_text(width // 2, height // 2, 
                              text="计算错误，请检查参数", font=('Unifont', 12), fill='red')
            return
        
        # 绘制曲线
        points = []
        max_volume = max(vol for vol, _ in data_points)
        max_ph = max(ph for _, ph in data_points)
        min_ph = min(ph for _, ph in data_points)
        
        for volume, ph in data_points:
            x = margin + (volume / max_volume) * graph_width
            y = height - margin - ((ph - min_ph) / (max_ph - min_ph)) * graph_height
            points.append((x, y))
        
        # 绘制连线
        for i in range(1, len(points)):
            canvas.create_line(points[i-1][0], points[i-1][1], 
                              points[i][0], points[i][1], 
                              fill='blue', width=2)
        
        # 绘制数据点
        for x, y in points:
            canvas.create_oval(x-2, y-2, x+2, y+2, fill='red')
        
        # 添加刻度
        # X轴刻度
        for i in range(0, int(max_volume) + 1, int(max_volume/5)):
            x = margin + (i / max_volume) * graph_width
            canvas.create_line(x, height - margin - 5, x, height - margin + 5, width=1)
            canvas.create_text(x, height - margin + 15, text=str(i), font=('Unifont', 8))
        
        # Y轴刻度
        ph_range = max_ph - min_ph
        for i in range(int(min_ph), int(max_ph) + 1):
            y = height - margin - ((i - min_ph) / ph_range) * graph_height
            canvas.create_line(margin - 5, y, margin + 5, y, width=1)
            canvas.create_text(margin - 20, y, text=str(i), font=('Unifont', 8))
        
        # 添加标题
        type_names = {
            "strong_strong": "强酸-强碱滴定",
            "weak_strong": "弱酸-强碱滴定", 
            "strong_weak": "强酸-弱碱滴定",
            "weak_weak": "弱酸-弱碱滴定"
        }
        
        title = f"{type_names[titration_type]}曲线"
        canvas.create_text(width // 2, 20, text=title, font=('Unifont', 12))
        
        # 显示当量点
        equiv_volume = (acid_conc * acid_volume) / base_conc
        equiv_ph = self.calculate_equivalence_ph(titration_type, pka, pkb)
        
        if 0 <= equiv_volume <= max_volume:
            x_equiv = margin + (equiv_volume / max_volume) * graph_width
            y_equiv = height - margin - ((equiv_ph - min_ph) / (max_ph - min_ph)) * graph_height
            
            canvas.create_oval(x_equiv-4, y_equiv-4, x_equiv+4, y_equiv+4, 
                              outline='red', width=2)
            canvas.create_text(x_equiv, y_equiv - 20, 
                              text=f"当量点\n({equiv_volume:.1f}mL, pH={equiv_ph:.1f})", 
                              font=('Unifont', 8), fill='red')

    def calculate_titration_data(self, titration_type, acid_conc, base_conc, 
                               acid_volume, pka, pkb):
        """计算滴定数据点"""
        data_points = []
        
        # 计算当量体积
        equiv_volume = (acid_conc * acid_volume) / base_conc
        
        # 生成体积点（从0到2倍当量体积）
        volumes = []
        for i in range(0, 201):
            volume = i * equiv_volume * 2 / 200
            volumes.append(volume)
        
        for volume in volumes:
            if titration_type == "strong_strong":
                ph = self.calculate_strong_strong_ph(acid_conc, base_conc, acid_volume, volume)
            elif titration_type == "weak_strong":
                ph = self.calculate_weak_strong_ph(acid_conc, base_conc, acid_volume, volume, pka)
            elif titration_type == "strong_weak":
                ph = self.calculate_strong_weak_ph(acid_conc, base_conc, acid_volume, volume, pkb)
            else:  # weak_weak
                ph = self.calculate_weak_weak_ph(acid_conc, base_conc, acid_volume, volume, pka, pkb)
            
            if ph is not None and 0 <= ph <= 14:
                data_points.append((volume, ph))
        
        return data_points

    def calculate_strong_strong_ph(self, acid_conc, base_conc, acid_volume, base_volume):
        """计算强酸-强碱滴定的pH"""
        total_acid_moles = acid_conc * acid_volume / 1000
        total_base_moles = base_conc * base_volume / 1000
        total_volume = (acid_volume + base_volume) / 1000
        
        if total_base_moles < total_acid_moles:
            # 酸性区域
            excess_acid = total_acid_moles - total_base_moles
            h_conc = excess_acid / total_volume
            return -math.log10(h_conc) if h_conc > 0 else 14
        elif total_base_moles > total_acid_moles:
            # 碱性区域
            excess_base = total_base_moles - total_acid_moles
            oh_conc = excess_base / total_volume
            return 14 + math.log10(oh_conc) if oh_conc > 0 else 0
        else:
            # 当量点
            return 7.0

    def calculate_weak_strong_ph(self, acid_conc, base_conc, acid_volume, base_volume, pka):
        """计算弱酸-强碱滴定的pH"""
        total_acid_moles = acid_conc * acid_volume / 1000
        total_base_moles = base_conc * base_volume / 1000
        total_volume = (acid_volume + base_volume) / 1000
        
        if total_base_moles == 0:
            # 初始点
            return pka / 2
        elif total_base_moles < total_acid_moles:
            # 缓冲区域
            acid_remaining = total_acid_moles - total_base_moles
            salt_formed = total_base_moles
            return pka + math.log10(salt_formed / acid_remaining) if acid_remaining > 0 else 14
        elif total_base_moles == total_acid_moles:
            # 当量点
            return 7 + pka / 2
        else:
            # 碱性区域
            excess_base = total_base_moles - total_acid_moles
            oh_conc = excess_base / total_volume
            return 14 + math.log10(oh_conc) if oh_conc > 0 else 0

    def calculate_strong_weak_ph(self, acid_conc, base_conc, acid_volume, base_volume, pkb):
        """计算强酸-弱碱滴定的pH"""
        # 类似弱酸-强碱，但pH计算相反
        ph_weak_strong = self.calculate_weak_strong_ph(base_conc, acid_conc, base_volume, acid_volume, pkb)
        return 14 - ph_weak_strong if ph_weak_strong is not None else None

    def calculate_weak_weak_ph(self, acid_conc, base_conc, acid_volume, base_volume, pka, pkb):
        """计算弱酸-弱碱滴定的pH"""
        total_acid_moles = acid_conc * acid_volume / 1000
        total_base_moles = base_conc * base_volume / 1000
        
        if total_base_moles < total_acid_moles:
            # 酸性缓冲区域
            return pka + math.log10(total_base_moles / (total_acid_moles - total_base_moles))
        elif total_base_moles > total_acid_moles:
            # 碱性缓冲区域
            return 14 - pkb - math.log10(total_acid_moles / (total_base_moles - total_acid_moles))
        else:
            # 当量点
            return (pka + (14 - pkb)) / 2

    def calculate_equivalence_ph(self, titration_type, pka, pkb):
        """计算当量点的pH"""
        if titration_type == "strong_strong":
            return 7.0
        elif titration_type == "weak_strong":
            return 7 + pka / 2
        elif titration_type == "strong_weak":
            return 7 - pkb / 2
        else:  # weak_weak
            return (pka + (14 - pkb)) / 2

    def show_echo_cave(self):
        """显示回音洞 - 随机化学笑话、梗、知识"""
        try:
            # 读取回音洞数据文件
            echo_file = "./res/data/splashes_data.txt"
            
            if os.path.exists(echo_file):
                with open(echo_file, 'r', encoding='utf-8') as file:
                    lines = [line.strip() for line in file if line.strip() and not line.startswith('#')]
                
                if lines:
                    # 随机选择一条消息
                    random_message = random.choice(lines)
                    # 显示消息框
                    messagebox.showinfo("回音洞 🎵", random_message)
                else:
                    messagebox.showinfo("回音洞", "回音洞数据文件为空，请添加一些化学相关的句子吧！")
            else:
                # 如果文件不存在，创建示例文件
                self.create_default_echo_data(echo_file)
                messagebox.showinfo("回音洞", "已创建回音洞数据文件，请按F5刷新或重新点击查看！")
                
        except Exception as e:
            messagebox.showerror("错误", f"读取回音洞数据时出错: {str(e)}")

    def create_default_echo_data(self, filepath):
        """创建默认的回音洞数据"""
        default_data = """为什么化学家喜欢喝茶？因为茶有很好的溶液性！
    氧气对二氧化碳说：你为什么不带火？二氧化碳回答：我是CO2，不是CO！
    化学家的浪漫：你是我的π键，我愿意与你共享电子
    实验室守则：不要把实验室的酸带到家里，家里的醋会吃醋
    """
        
        try:
            # 确保目录存在
            os.makedirs(os.path.dirname(filepath), exist_ok=True)
            
            with open(filepath, 'w', encoding='utf-8') as file:
                file.write(default_data)
            print(f"已创建默认回音洞数据文件: {filepath}")
        except Exception as e:
            print(f"创建回音洞数据文件失败: {str(e)}") 

