    def send_feedback(self):
        """发送反馈邮件"""
        sender_email = self.sender_var.get().strip()
        feedback_content = self.feedback_text.get(1.0, tk.END).strip()
        
        # 验证输入
        if not sender_email:
            self.status_label.config(text="错误: 请输入您的邮箱地址", fg='red')
            return
            
        if not feedback_content:
            self.status_label.config(text="错误: 请输入反馈内容", fg='red')
            return
        
        # 简单的邮箱格式验证
        if '@' not in sender_email or '.' not in sender_email:
            self.status_label.config(text="错误: 请输入有效的邮箱地址", fg='red')
            return
        
        try:
            # 使用标准库发送邮件
            self.send_email_via_smtp(sender_email, feedback_content)
            self.status_label.config(text="反馈发送成功！感谢您的意见。", fg='green')
            
            # 3秒后清空内容
            self.root.after(3000, self.clear_feedback)
            
        except Exception as e:
            self.status_label.config(text=f"发送失败: {str(e)}", fg='red')

    def send_email_via_smtp(self, sender_email, content):
        """使用smtplib发送邮件"""
        try:
            # 配置SMTP服务器（这里使用Outlook的SMTP服务器）
            smtp_server = "smtp-mail.outlook.com"
            smtp_port = 587
            
            # 创建邮件内容
            message = MIMEMultipart()
            message["From"] = sender_email
            message["To"] = "sivenioo@163.com"
            message["Subject"] = "应用反馈"
            
            # 邮件正文
            body = f"""
    用户反馈信息：
    发件人: {sender_email}
    发送时间: {self.get_current_time()}
            
    反馈内容：
    {content}
            
    ---
    此邮件由元素周期表应用反馈工具自动发送
            """
            
            message.attach(MIMEText(body, "plain"))
            
            # 显示密码输入对话框
            password = self.ask_for_password(sender_email)
            if not password:
                raise Exception("密码输入已取消")
            
            # 连接到SMTP服务器并发送邮件
            self.status_label.config(text="正在连接邮件服务器...", fg='blue')
            self.root.update()
            
            server = smtplib.SMTP(smtp_server, smtp_port)
            server.starttls()  # 启用安全传输
            
            self.status_label.config(text="正在登录...", fg='blue')
            self.root.update()
            
            server.login(sender_email, password)
            
            self.status_label.config(text="正在发送邮件...", fg='blue')
            self.root.update()
            
            text = message.as_string()
            server.sendmail(sender_email, "sivenioo@163.com", text)
            server.quit()
            
        except smtplib.SMTPAuthenticationError:
            raise Exception("邮箱或密码错误，请检查登录信息")
        except smtplib.SMTPException as e:
            raise Exception(f"邮件发送失败: {str(e)}")
        except Exception as e:
            raise Exception(f"发送过程中出现错误: {str(e)}")

    def ask_for_password(self, email):
        """弹出密码输入对话框"""
        password_window = tk.Toplevel(self.root)
        password_window.title("邮箱密码验证")
        password_window.geometry("400x200")
        password_window.resizable(False, False)
        password_window.transient(self.root)
        password_window.grab_set()
        
        # 居中显示
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 200
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 100
        password_window.geometry(f"+{x}+{y}")
        
        main_frame = tk.Frame(password_window)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=20, pady=20)
        
        tk.Label(main_frame, text=f"请输入 {email} 的密码:", 
                font=('Unifont', 11)).pack(anchor=tk.W, pady=(0, 10))
        
        tk.Label(main_frame, text="密码仅用于邮件发送，不会被保存", 
                font=('Unifont', 9), fg='gray').pack(anchor=tk.W, pady=(0, 15))
        
        password_var = tk.StringVar()
        password_entry = tk.Entry(main_frame, textvariable=password_var, 
                             font=('Unifont', 11), show="*", width=30)
        password_entry.pack(fill=tk.X, pady=(0, 20))
        
        result = [None]  # 使用列表来传递结果
        
        def on_ok():
            result[0] = password_var.get()
            password_window.destroy()
        
        def on_cancel():
            result[0] = None
            password_window.destroy()
        
        button_frame = tk.Frame(main_frame)
        button_frame.pack(fill=tk.X)
        
        tk.Button(button_frame, text="确定", command=on_ok,
                 font=('Unifont', 10), width=8).pack(side=tk.LEFT, padx=(0, 10))
        tk.Button(button_frame, text="取消", command=on_cancel,
                 font=('Unifont', 10), width=8).pack(side=tk.LEFT)
        
        # 绑定回车键
        password_window.bind('<Return>', lambda e: on_ok())
        
        password_entry.focus_set()
        password_window.wait_window()
        
        return result[0]

    def get_current_time(self):
        """获取当前时间字符串"""
