    def load_equation_data(self, filename="./res/data/equation_data.txt"):
        """从TXT文件加载方程式数据"""
        equations = []
        
        try:
            with open(filename, 'r', encoding='utf-8') as file:
                for line_num, line in enumerate(file, 1):
                    line = line.strip()
                    
                    # 跳过空行和注释行
                    if not line or line.startswith('#'):
                        continue
                    
                    # 解析方程式格式： "序号. 方程式"
                    if '.' in line:
                        # 找到第一个点号的位置
                        dot_index = line.find('.')
                        if dot_index > 0:
                            number_part = line[:dot_index].strip()
                            equation_part = line[dot_index+1:].strip()
                            
                            # 提取序号和方程式
                            try:
                                number = int(number_part)
                                equations.append({
                                    'number': number,
                                    'equation': equation_part,
                                    'full_text': line
                                })
                            except ValueError:
                                # 如果序号不是数字，直接存储
                                equations.append({
                                    'number': line_num,
                                    'equation': line[dot_index+1:].strip(),
                                    'full_text': line
                                })
                    else:
                        # 如果没有序号，使用行号
                        equations.append({
                            'number': line_num,
                            'equation': line,
                            'full_text': line
                        })
                    
        except FileNotFoundError:
            messagebox.showerror('错误', f"警告: 找不到方程式数据文件 {filename}")
            return []
        except Exception as e:
            messagebox.showerror('错误', f"读取方程式数据时发生错误: {e}")
            return []
        
        return equations

