    def search_equations(self, keyword, equation_list, result_label, detail_text=None):
        """搜索方程式"""
        equation_list.delete(0, tk.END)
        
        if not self.equations_data:
            equation_list.insert(tk.END, "没有找到方程式数据")
            result_label.config(text="无数据", fg='red')
            return
        
        # 存储当前匹配的方程式
        self.current_matched_equations = []
        
        for equation in self.equations_data:
            # 搜索关键词（不区分大小写）
            if not keyword or keyword.lower() in equation['equation'].lower():
                self.current_matched_equations.append(equation)
        
        # 显示匹配的方程式
        for equation in self.current_matched_equations:
            # 显示格式：序号. 方程式
            display_text = f"{equation['number']}. {equation['equation']}"
            equation_list.insert(tk.END, display_text)
        
        # 更新结果统计
        count = len(self.current_matched_equations)
        if keyword:
            result_label.config(text=f"找到 {count} 个包含 '{keyword}' 的方程式", fg='green')
        else:
            result_label.config(text=f"共 {count} 个方程式", fg='blue')
        
        # 清空详情显示
        if detail_text:
            detail_text.config(state=tk.NORMAL)
            detail_text.delete(1.0, tk.END)
            detail_text.config(state=tk.DISABLED)

    # 修改选择事件处理函数
    def on_equation_select(event):
        selection = equation_list.curselection()
        if selection and hasattr(self, 'matched_equations'):
            index_in_list = selection[0]
            if index_in_list < len(self.matched_equations):
                # 直接从匹配的方程式列表中获取
                equation = self.matched_equations[index_in_list]
                self.show_equation_detail(equation, detail_text)

    def show_equation_detail(self, equation, detail_text):
        """显示方程式详情"""
        detail_text.config(state=tk.NORMAL)
        detail_text.delete(1.0, tk.END)
        
        # 创建详细的方程式信息
        info = f"方程式编号: {equation['number']}\n\n"
        info += f"化学方程式:\n{equation['equation']}\n\n"
        
        # 显示反应物和生成物
        reactants_products = self.parse_reactants_products(equation['equation'])
        if reactants_products:
            reactants, products = reactants_products
            info += f"反应物: {reactants}\n"
            info += f"生成物: {products}\n\n"
        
        # 添加一些化学知识提示
        info += "提示: 可以使用摩尔质量计算器计算各物质的质量关系"
        
        detail_text.insert(tk.END, info)
        detail_text.config(state=tk.DISABLED)

    def parse_reactants_products(self, equation):
        """解析反应物和生成物"""
        try:
            # 简单的解析，基于箭头或等号分割
            if '→' in equation:
                parts = equation.split('→')
            elif '=' in equation:
                parts = equation.split('=')
            else:
                return None
            
            if len(parts) == 2:
                reactants = parts[0].strip()
                products = parts[1].strip()
                return reactants, products
        except:
            pass
        
        return None

