    def draw_comparison_chart(self, canvas, data_type, count, sort_order):
        """绘制元素数据比较柱状图"""
        canvas.delete("all")
        
        # 收集数据
        element_data = []
        for symbol, data in self.elements.items():
            try:
                value = self.parse_element_value(data, data_type)
                if value is not None:
                    element_data.append({
                        'symbol': symbol,
                        'name': data['name'],
                        'value': value,
                        'category': data['category']
                    })
            except (ValueError, KeyError):
                continue
        
        if not element_data:
            canvas.create_text(400, 200, text="无法获取数据", font=('Unifont', 16), fill='red')
            return
        
        # 排序数据
        element_data.sort(key=lambda x: x['value'], reverse=(sort_order == "desc"))
        
        # 限制显示数量
        display_data = element_data[:count]
        
        if not display_data:
            canvas.create_text(400, 200, text="没有有效数据可显示", font=('Unifont', 16), fill='red')
            return
        
        # 设置图表参数
        canvas_width = max(1200, len(display_data) * 60)  # 动态宽度
        canvas_height = 500
        canvas.config(scrollregion=(0, 0, canvas_width, canvas_height))
        
        margin = 80
        chart_width = canvas_width - 2 * margin
        chart_height = canvas_height - 2 * margin
        bar_width = chart_width / len(display_data) * 0.8
        
        # 计算最大值和最小值
        values = [item['value'] for item in display_data]
        max_value = max(values)
        min_value = min(values)
        value_range = max_value - min_value
        
        # 类别颜色映射
        category_colors = {
            # 金属区域（红-橙-黄）
        "碱金属": "#FF8080",      # 浅红
        "碱土金属": "#FFA380",    # 浅橙红
        "过渡金属": "#FFC680",    # 浅橙色
        "后过渡金属": "#FFE680",  # 浅黄橙
        
        # 半金属/类金属区域（黄绿过渡）
        "类金属": "#CCD980",      # 橄榄绿
        
        # 非金属区域（绿-蓝）
        "非金属": "#80CC80",      # 草绿色
        "卤素": "#80B3CC",        # 青绿色
        
        # 惰性气体区域（蓝-紫）
        "稀有气体": "#8099CC",    # 浅蓝色
        
        # 内过渡金属（紫-红紫）
        "镧系": "#B380CC",        # 浅紫色
        "锕系": "#CC80B3",        # 浅紫红色
        
        "未知": "#D9D9D9" 
        }
        
        # 绘制标题
        title_text = self.get_data_type_title(data_type)
        canvas.create_text(canvas_width // 2, 20, 
                      text=f"元素{title_text}比较图 (显示前{count}个元素)",
                      font=('Unifont', 14),
                      fill='darkblue')
        
        # 绘制坐标轴
        canvas.create_line(margin, canvas_height - margin, 
                      canvas_width - margin, canvas_height - margin, width=2)  # X轴
        canvas.create_line(margin, margin, margin, canvas_height - margin, width=2)  # Y轴
        
        # 绘制Y轴刻度
        y_ticks = 5
        for i in range(y_ticks + 1):
            y = margin + (chart_height * i / y_ticks)
            value = max_value - (value_range * i / y_ticks)
            canvas.create_line(margin - 5, y, margin, y, width=1)
            canvas.create_text(margin - 10, y, text=f"{value:.1f}", 
                          font=('Unifont', 8), anchor=tk.E)
        
        # 绘制柱状图
        for i, item in enumerate(display_data):
            x = margin + (i + 0.1) * bar_width
            bar_height = ((item['value'] - min_value) / value_range) * chart_height if value_range > 0 else chart_height
            
            # 柱状图颜色
            color = category_colors.get(item['category'], "#778899")
            
            # 绘制柱子
            canvas.create_rectangle(
                x, canvas_height - margin - bar_height,
                x + bar_width * 0.8, canvas_height - margin,
                fill=color, outline='black', width=1
            )
            
            # 显示数值
            value_text = f"{item['value']:.1f}" if isinstance(item['value'], float) else str(item['value'])
            canvas.create_text(x + bar_width * 0.4, canvas_height - margin - bar_height - 10,
                          text=value_text, font=('Unifont', 8), fill='black')
            
            # 显示元素符号
            canvas.create_text(x + bar_width * 0.4, canvas_height - margin + 15,
                          text=item['symbol'], font=('Unifont', 9), fill='darkblue')
            
            # 显示元素名称（小字体）
            canvas.create_text(x + bar_width * 0.4, canvas_height - margin + 30,
                          text=item['name'], font=('Unifont', 7), fill='gray')
        
        # 绘制图例
        legend_x = canvas_width - 150
        legend_y = 50
        categories = list(set([item['category'] for item in display_data]))
        
        canvas.create_text(legend_x, legend_y - 20, text="元素类别", 
                      font=('Unifont', 10), anchor=tk.W)
        
        for i, category in enumerate(categories):
            y = legend_y + i * 20
            color = category_colors.get(category, "#778899")
            canvas.create_rectangle(legend_x, y, legend_x + 15, y + 12, 
                               fill=color, outline='black')
            canvas.create_text(legend_x + 20, y + 6, text=category, 
                          font=('Unifont', 8), anchor=tk.W)
        
        # 更新信息标签
        info_text = f"显示: {title_text} | 元素数量: {len(display_data)} | 数值范围: {min_value:.1f} - {max_value:.1f}"
        if hasattr(self, 'info_label'):
            self.info_label.config(text=info_text)

    def parse_element_value(self, data, data_type):
        """解析元素数值数据"""
        try:
            if data_type == "atomic_mass":
                # 解析原子量
                mass_str = data['mass'].strip('[]')
                return float(mass_str)
            
            elif data_type == "atomic_number":
                return data['number']
            
            elif data_type == "atomic_radius":
                radius_str = data.get('atomic_radius', '0').replace('pm', '').strip()
                return float(radius_str) if radius_str and radius_str != '未知' else None
            
            elif data_type == "density":
                density_str = data.get('density', '0').replace('g/cm³', '').strip()
                return float(density_str) if density_str and density_str != '未知' else None
            
            elif data_type == "melting_point":
                mp_str = data.get('melting_point', '0').replace('°C', '').strip()
                return float(mp_str) if mp_str and mp_str != '未知' else None
            
            elif data_type == "boiling_point":
                bp_str = data.get('boiling_point', '0').replace('°C', '').strip()
                return float(bp_str) if bp_str and bp_str != '未知' else None
            
        except (ValueError, KeyError):
            return None
        
        return None

    def get_data_type_title(self, data_type):
        """获取数据类型的显示标题"""
        titles = {
            "atomic_mass": "原子量",
            "atomic_number": "原子序数", 
            "atomic_radius": "原子半径(pm)",
            "density": "密度(g/cm³)",
            "melting_point": "熔点(°C)",
            "boiling_point": "沸点(°C)"
        }
        return titles.get(data_type, "数据")

