    def display_molecule_info(self, molecule):
        """显示分子信息"""
        # 更新信息标签
        info_text = f"{molecule['name']} ({molecule['formula']}) - {molecule['type']}"
        self.molecule_info_label.config(text=info_text)
        
        # 清空画布并绘制分子结构
        self.molecule_canvas.delete("all")
        self.draw_molecule_structure(molecule)
        
        # 更新详细信息
        self.update_molecule_details(molecule)

    def draw_molecule_structure(self, molecule):
        """绘制分子结构"""
        canvas = self.molecule_canvas
        canvas_width = canvas.winfo_width()
        canvas_height = canvas.winfo_height()
        
        if canvas_width <= 1 or canvas_height <= 1:
            canvas.after(100, lambda: self.draw_molecule_structure(molecule))
            return
        
        center_x = canvas_width // 2
        center_y = canvas_height // 2
        
        try:
            # 根据分子名称选择不同的绘制方法
            if molecule['name'] == '苯':
                self.draw_benzene(canvas, center_x, center_y)
            elif molecule['name'] == '甲烷':
                self.draw_methane(canvas, center_x, center_y)
            elif molecule['name'] == '乙烯':
                self.draw_ethylene(canvas, center_x, center_y)
            elif molecule['name'] == '乙醇':
                self.draw_ethanol(canvas, center_x, center_y)
            elif molecule['name'] == '葡萄糖':
                self.draw_glucose(canvas, center_x, center_y)
            else:
                # 默认绘制方法 - 简单球棍模型
                self.draw_generic_molecule(canvas, center_x, center_y, molecule)
                
        except Exception as e:
            canvas.create_text(center_x, center_y,
                          text=f"无法绘制分子结构: {str(e)}",
                          font=('Unifont', 12),
                          fill='red')

    def draw_benzene(self, canvas, center_x, center_y):
        """绘制苯分子结构"""
        radius = 120
        hexagon_points = []
        
        # 计算六边形顶点
        for i in range(6):
            angle = math.radians(i * 60)
            x = center_x + radius * math.cos(angle)
            y = center_y + radius * math.sin(angle)
            hexagon_points.append((x, y))
        
        # 绘制碳碳键（单键和双键交替）
        for i in range(6):
            x1, y1 = hexagon_points[i]
            x2, y2 = hexagon_points[(i + 1) % 6]
            
            # 绘制单键
            canvas.create_line(x1, y1, x2, y2, width=3, fill='black')
            
            # 每隔一个键绘制双键（苯环的共振结构）
            if i % 2 == 0:
                # 在键的旁边绘制第二条线表示双键
                dx = (y2 - y1) * 0.1
                dy = (x1 - x2) * 0.1
                canvas.create_line(x1 + dx, y1 + dy, x2 + dx, y2 + dy, 
                              width=2, fill='black')
        
        # 绘制碳原子
        for x, y in hexagon_points:
            canvas.create_oval(x - 15, y - 15, x + 15, y + 15, 
                          fill='gray', outline='black', width=2)
            canvas.create_text(x, y, text="C", font=('Unifont', 10), fill='white')
        
        # 绘制氢原子
        h_radius = radius + 40
        for i in range(6):
            angle = math.radians(i * 60)
            x = center_x + h_radius * math.cos(angle)
            y = center_y + h_radius * math.sin(angle)
            
            canvas.create_oval(x - 12, y - 12, x + 12, y + 12,
                          fill='lightblue', outline='blue', width=2)
            canvas.create_text(x, y, text="H", font=('Unifont', 9), fill='darkblue')
            
            # 连接碳氢键
            cx, cy = hexagon_points[i]
            canvas.create_line(cx + (x-cx)*0.2, cy + (y-cy)*0.2, 
                          x - (x-cx)*0.2, y - (y-cy)*0.2,
                          width=2, fill='gray')

    def draw_methane(self, canvas, center_x, center_y):
        """绘制甲烷分子结构（四面体）"""
        # 碳原子在中心
        canvas.create_oval(center_x - 20, center_y - 20, center_x + 20, center_y + 20,
                      fill='gray', outline='black', width=2)
        canvas.create_text(center_x, center_y, text="C", 
                      font=('Unifont', 12), fill='white')
        
        # 四个氢原子在四面体的顶点
        bond_length = 80
        angles = [45, 135, 225, 315]  # 四面体近似角度
        
        for i, angle in enumerate(angles):
            rad_angle = math.radians(angle)
            x = center_x + bond_length * math.cos(rad_angle)
            y = center_y + bond_length * math.sin(rad_angle)
            
            # 氢原子
            canvas.create_oval(x - 15, y - 15, x + 15, y + 15,
                          fill='lightblue', outline='blue', width=2)
            canvas.create_text(x, y, text="H", 
                          font=('Unifont', 10), fill='darkblue')
            
            # 碳氢键
            canvas.create_line(center_x, center_y, x, y, width=3, fill='black')

    def draw_ethylene(self, canvas, center_x, center_y):
        """绘制乙烯分子结构"""
        bond_length = 60
        
        # 两个碳原子
        c1_x, c1_y = center_x - bond_length, center_y
        c2_x, c2_y = center_x + bond_length, center_y
        
        # 碳碳双键
        canvas.create_line(c1_x, c1_y, c2_x, c2_y, width=4, fill='black')
        canvas.create_line(c1_x, c1_y - 5, c2_x, c2_y - 5, width=2, fill='black')
        
        # 碳原子
        canvas.create_oval(c1_x - 15, c1_y - 15, c1_x + 15, c1_y + 15,
                      fill='gray', outline='black', width=2)
        canvas.create_oval(c2_x - 15, c2_y - 15, c2_x + 15, c2_y + 15,
                      fill='gray', outline='black', width=2)
        canvas.create_text(c1_x, c1_y, text="C", font=('Unifont', 10), fill='white')
        canvas.create_text(c2_x, c2_y, text="C", font=('Unifont', 10), fill='white')
        
        # 氢原子
        h_positions = [
            (c1_x - 40, c1_y - 30), (c1_x - 40, c1_y + 30),
            (c2_x + 40, c2_y - 30), (c2_x + 40, c2_y + 30)
        ]
        
        for x, y in h_positions:
            canvas.create_oval(x - 12, y - 12, x + 12, y + 12,
                          fill='lightblue', outline='blue', width=2)
            canvas.create_text(x, y, text="H", font=('Unifont', 9), fill='darkblue')
            
            # 连接到最近的碳原子
            if x < center_x:
                target_x, target_y = c1_x, c1_y
            else:
                target_x, target_y = c2_x, c2_y
            
            canvas.create_line(x, y, target_x, target_y, width=2, fill='gray')

    def draw_ethanol(self, canvas, center_x, center_y):
        """绘制乙醇分子结构"""
        # 设置键长
        bond_length = 50
        
        # 两个碳原子的位置 - 水平排列
        c1_x, c1_y = center_x - bond_length, center_y  # CH3碳
        c2_x, c2_y = center_x + bond_length, center_y  # CH2碳
        
        # 氧原子的位置 - 连接到第二个碳上
        o_x, o_y = c2_x + bond_length, c2_y
        
        # 绘制碳碳键
        canvas.create_line(c1_x, c1_y, c2_x, c2_y, width=3, fill='black')
        
        # 绘制碳氧键
        canvas.create_line(c2_x, c2_y, o_x, o_y, width=3, fill='red')
        
        # 绘制碳原子
        canvas.create_oval(c1_x - 12, c1_y - 12, c1_x + 12, c1_y + 12,
                      fill='gray', outline='black', width=2)
        canvas.create_oval(c2_x - 12, c2_y - 12, c2_x + 12, c2_y + 12,
                      fill='gray', outline='black', width=2)
        canvas.create_text(c1_x, c1_y, text="C", font=('Unifont', 9), fill='white')
        canvas.create_text(c2_x, c2_y, text="C", font=('Unifont', 9), fill='white')
        
        # 绘制氧原子
        canvas.create_oval(o_x - 12, o_y - 12, o_x + 12, o_y + 12,
                      fill='red', outline='darkred', width=2)
        canvas.create_text(o_x, o_y, text="O", font=('Unifont', 9), fill='white')
        
        # 绘制氢原子
        # CH3基团的三个氢（甲基）
        h1_positions = [
            (c1_x - 25, c1_y - 20),  # 左上
            (c1_x - 25, c1_y + 20),  # 左下  
            (c1_x, c1_y - 35)        # 正上
        ]
        
        # CH2基团的两个氢（亚甲基）
        h2_positions = [
            (c2_x - 20, c2_y - 25),  # 左上
            (c2_x - 20, c2_y + 25)   # 左下
        ]
        
        # 羟基的氢
        h_oh_x, h_oh_y = o_x + 25, o_y
        
        # 绘制甲基的氢原子和键
        for x, y in h1_positions:
            canvas.create_oval(x - 8, y - 8, x + 8, y + 8,
                          fill='lightblue', outline='blue', width=1)
            canvas.create_text(x, y, text="H", font=('Unifont', 7), fill='darkblue')
            canvas.create_line(c1_x, c1_y, x, y, width=2, fill='gray')
        
        # 绘制亚甲基的氢原子和键
        for x, y in h2_positions:
            canvas.create_oval(x - 8, y - 8, x + 8, y + 8,
                          fill='lightblue', outline='blue', width=1)
            canvas.create_text(x, y, text="H", font=('Unifont', 7), fill='darkblue')
            canvas.create_line(c2_x, c2_y, x, y, width=2, fill='gray')
        
        # 绘制羟基的氢原子和键
        canvas.create_oval(h_oh_x - 8, h_oh_y - 8, h_oh_x + 8, h_oh_y + 8,
                      fill='lightblue', outline='blue', width=1)
        canvas.create_text(h_oh_x, h_oh_y, text="H", font=('Unifont', 7), fill='darkblue')
        canvas.create_line(o_x, o_y, h_oh_x, h_oh_y, width=2, fill='gray')
        
        # 添加官能团标注
        canvas.create_text(center_x, center_y - 60,
                      text="乙醇 C₂H₅OH",
                      font=('Unifont', 12),
                      fill='darkblue')
        canvas.create_text(c2_x, c2_y - 45,
                      text="CH₂",
                      font=('Unifont', 8),
                      fill='darkgreen')
        canvas.create_text(c1_x, c1_y - 45,
                      text="CH₃",
                      font=('Unifont', 8),
                      fill='darkgreen')
        canvas.create_text(o_x, o_y + 25,
                      text="OH",
                      font=('Unifont', 8),
                      fill='darkred')

    def draw_glucose(self, canvas, center_x, center_y):
        """绘制葡萄糖分子简化结构"""
        # 显示葡萄糖的环状结构简图
        canvas.create_text(center_x, center_y,
                      text="葡萄糖 (C₆H₁₂O₆)\n环状结构\n\n"
                          "    OH    OH\n"
                          "    |     |\n"
                          "H-C-C-C-C-C-H\n"
                          "  | | | | | |\n"
                          "  OH H OH H OH",
                      font=('Unifont', 12),
                      justify=tk.LEFT)

    def draw_generic_molecule(self, canvas, center_x, center_y, molecule):
        """绘制通用分子结构"""
