    # 修改 update_molecule_details 方法
    def update_molecule_details(self, molecule):
        """更新分子详细信息"""
        # 更新文本框
        self.detail_text.config(state=tk.NORMAL)
        self.detail_text.delete(1.0, tk.END)
        
        # 添加分子信息
        info_text = f"分子名称: {molecule['name']}\n"
        info_text += f"化学式: {molecule['formula']}\n"
        info_text += f"分子类型: {molecule['type']}\n"
        info_text += f"SMILES: {molecule.get('smiles', 'N/A')}\n\n"
        
        # 添加描述
