    def display_electron_config(self, search_term, content_frame, status_label):
        """显示元素的电子排布"""
        if not search_term.strip():
            status_label.config(text="请输入搜索内容", fg='red')
            return
        
        search_term = search_term.strip()
        found_element = None
        element_data = None
        
        # 在元素数据中搜索
        for symbol, data in self.elements.items():
            # 匹配元素符号（不区分大小写）
            if symbol.lower() == search_term.lower():
                found_element = symbol
                element_data = data
                break
            # 匹配元素名称
            elif data['name'].lower() == search_term.lower():
                found_element = symbol
                element_data = data
                break
            # 匹配原子序数
            elif str(data['number']) == search_term:
                found_element = symbol
                element_data = data
                break
        
        if found_element and element_data:
            status_label.config(text=f"找到元素: {found_element} - {element_data['name']}", fg='green')
            self.show_electron_config_details(found_element, element_data, content_frame)
        else:
            status_label.config(text=f"未找到元素: {search_term}", fg='red')
            # 清空内容区域
            for widget in content_frame.winfo_children():
                widget.destroy()
            error_label = tk.Label(content_frame, 
                              text=f"未找到元素: {search_term}\n请检查输入是否正确",
                              font=('Unifont', 12),
                              fg='red',
                              justify=tk.CENTER)
            error_label.place(relx=0.5, rely=0.5, anchor=tk.CENTER)

