    def get_max_electrons(self, orbital):
        """获取轨道的最大电子数"""
        max_electrons = {
            's': 2,
            'p': 6,
            'd': 10,
            'f': 14
        }
        return max_electrons.get(orbital, 0)

    def create_energy_level_diagram(self, element_data, parent):
        """创建能级示意图"""
        diagram_frame = tk.LabelFrame(parent, text=" 能级示意图", 
                                 font=('Unifont', 12),
                                 relief=tk.GROOVE, bd=2)
        diagram_frame.pack(fill=tk.X, pady=(0, 20))
        
        # 创建画布
        canvas = tk.Canvas(diagram_frame, height=600, width=600,bg='white', relief=tk.SUNKEN, bd=1)
        canvas.pack(fill=tk.X, padx=10, pady=10)
        
        # 获取电子排布信息
        config = element_data.get('electron_config', '')
        if not config or config == '未知':
            info_label = tk.Label(diagram_frame, 
                             text="无法获取电子排布信息",
                             font=('Unifont', 10),
                             fg='red')
            info_label.pack()
            return
        
        try:
            # 获取元素符号
            element_symbol = None
            for symbol, data in self.elements.items():
                if data == element_data:
                    element_symbol = symbol
                    break
            
            if not element_symbol:
                element_symbol = "?"
            
            # 解析电子排布
            import re
            
            # 处理上标数字转换
            superscript_to_normal = {
                '⁰': '0', '¹': '1', '²': '2', '³': '3', '⁴': '4',
                '⁵': '5', '⁶': '6', '⁷': '7', '⁸': '8', '⁹': '9'
            }
            
            config_normal = config
            for sup, normal in superscript_to_normal.items():
                config_normal = config_normal.replace(sup, normal)
            
            # 处理稀有气体核心表示法
            core_configs = {
                '[He]': '1s2',
                '[Ne]': '1s2 2s2 2p6', 
                '[Ar]': '1s2 2s2 2p6 3s2 3p6',
                '[Kr]': '1s2 2s2 2p6 3s2 3p6 4s2 3d10 4p6',
                '[Xe]': '1s2 2s2 2p6 3s2 3p6 4s2 3d10 4p6 5s2 4d10 5p6',
                '[Rn]': '1s2 2s2 2p6 3s2 3p6 4s2 3d10 4p6 5s2 4d10 5p6 6s2 4f14 5d10 6p6'
            }
            
            full_config = config_normal
            for core, replacement in core_configs.items():
                if core in full_config:
                    full_config = full_config.replace(core, replacement)
            
            # 匹配电子排布模式
            pattern = r'(\d+)([spdf])(\d+)'
            matches = re.findall(pattern, full_config)
            
            if not matches:
                # 如果没找到匹配，尝试更简单的模式
                pattern_simple = r'(\d)([spdf])(\d)'
                matches = re.findall(pattern_simple, full_config)
            
            if not matches:
                raise ValueError(f"无法解析电子排布: {config}")
            
            # 能级顺序（按能量从低到高）
            energy_levels = [
                '1s', 
                '2s', '2p', 
                '3s', '3p', 
                '4s', '3d', '4p', 
                '5s', '4d', '5p', 
                '6s', '4f', '5d', '6p', 
                '7s', '5f', '6d', '7p'
            ]
            
            # 收集有电子的能级
            occupied_levels = {}
            for n, orbital, electrons in matches:
                level = f"{n}{orbital}"
                try:
                    occupied_levels[level] = int(electrons)
                except ValueError:
                    occupied_levels[level] = 0
            
            # 绘制参数
            canvas_width = 600
            start_x = 100
            start_y = 50
            spacing = 30
            line_length = 350
            
            # 清空画布
            canvas.delete("all")
            
            # 绘制标题
            canvas.create_text(canvas_width//2, 20, 
                          text=f"{element_data['name']} ({element_symbol}) 能级示意图",
                          font=('Unifont', 12),
                          fill='darkblue')
            
            # 确定要显示的能级（最多显示前15个，避免过多）
            display_levels = []
            for level in energy_levels:
                if level in occupied_levels or len(display_levels) < 10:
                    display_levels.append(level)
                if len(display_levels) >= 15:
                    break
            
            # 绘制能级线
            for i, level in enumerate(display_levels):
                y = start_y + i * spacing
                
                # 能级标签
                canvas.create_text(start_x - 40, y, 
                              text=level, 
                              font=('Unifont', 10),
                              anchor=tk.E,
                              fill='black')
                
                if level in occupied_levels:
                    # 有电子的能级用蓝色实线
                    canvas.create_line(start_x, y, start_x + line_length, y,
                                  fill='blue', width=2)
                    
                    # 显示电子数
                    electrons = occupied_levels[level]
                    canvas.create_text(start_x + line_length + 25, y,
                                  text=f"{electrons}e",
                                  font=('Unifont', 9),
                                  fill='darkgreen')
                    
                    # 绘制电子
                    orbital_type = level[-1]
                    max_electrons = self.get_max_electrons(orbital_type)
                    
                    # 根据轨道类型确定电子排列
                    if orbital_type == 's':
                        # s轨道：1个轨道，最多2个电子
                        columns = 1
                    elif orbital_type == 'p':
                        # p轨道：3个轨道，最多6个电子
                        columns = 3
                    elif orbital_type == 'd':
                        # d轨道：5个轨道，最多10个电子
                        columns = 5
                    else:  # f轨道
                        # f轨道：7个轨道，最多14个电子
                        columns = 7
                    
                    rows = (max_electrons + columns - 1) // columns
                    electron_radius = 4
                    
                    # 绘制电子点
                    for j in range(max_electrons):
                        row = j // columns
                        col = j % columns
                        electron_x = start_x + 20 + col * 15
                        electron_y = y - 8 + row * 8  # 稍微上下错开
                        
                        if j < electrons:
                            # 实心圆表示有电子
                            canvas.create_oval(electron_x - electron_radius, electron_y - electron_radius,
                                          electron_x + electron_radius, electron_y + electron_radius,
                                          fill='red', outline='darkred')
                        else:
                            # 空心圆表示空轨道
                            canvas.create_oval(electron_x - electron_radius, electron_y - electron_radius,
                                          electron_x + electron_radius, electron_y + electron_radius,
                                          fill='white', outline='lightgray')
                else:
                    # 无电子的能级用灰色虚线
                    canvas.create_line(start_x, y, start_x + line_length, y,
                                  fill='lightgray', width=1, dash=(2, 2))
            
            # 绘制能量方向箭头
            arrow_x = start_x - 20
            arrow_start_y = start_y - 10
            arrow_end_y = start_y + len(display_levels) * spacing + 10
            
            canvas.create_line(arrow_x, arrow_start_y, arrow_x, arrow_end_y,
                          fill='gray', width=1, arrow=tk.LAST)
            canvas.create_text(arrow_x - 10, (arrow_start_y + arrow_end_y) // 2,
                          text="能量\n增加",
                          font=('Unifont', 8),
                          fill='gray',
                          angle=90)
            
            # 绘制图例
            legend_y = start_y + len(display_levels) * spacing + 30
            
            # 图例标题
            canvas.create_text(start_x, legend_y - 15,
                          text="图例:",
                          font=('Unifont', 9),
                          anchor=tk.W)
            
            # 填充电子
            canvas.create_oval(start_x, legend_y, start_x + 10, legend_y + 10,
                          fill='red', outline='darkred')
            canvas.create_text(start_x + 15, legend_y + 5,
                          text="填充电子",
                          font=('Unifont', 8),
                          anchor=tk.W)
            
            # 空轨道
            canvas.create_oval(start_x + 80, legend_y, start_x + 90, legend_y + 10,
                          fill='white', outline='lightgray')
            canvas.create_text(start_x + 95, legend_y + 5,
                          text="空轨道",
                          font=('Unifont', 8),
                          anchor=tk.W)
            
            # 有电子能级
            canvas.create_line(start_x + 140, legend_y + 5, start_x + 160, legend_y + 5,
                          fill='blue', width=2)
            canvas.create_text(start_x + 165, legend_y + 5,
                          text="有电子能级",
                          font=('Unifont', 8),
                          anchor=tk.W)
            
            # 无电子能级
            canvas.create_line(start_x + 220, legend_y + 5, start_x + 240, legend_y + 5,
                          fill='lightgray', width=1, dash=(2, 2))
            canvas.create_text(start_x + 245, legend_y + 5,
                          text="无电子能级",
                          font=('Unifont', 8),
                          anchor=tk.W)
            
        except Exception as e:
            import traceback
            error_details = traceback.format_exc()
            print(f"绘制能级图错误详情: {error_details}")
            
            # 显示错误信息
            canvas.create_text(300, 100,
                          text=f"绘制能级图时出错",
                          font=('Unifont', 12),
                          fill='red')
            canvas.create_text(300, 130,
                          text=f"错误: {str(e)}",
                          font=('Unifont', 10),
                          fill='red')
            canvas.create_text(300, 160,
                          text="请检查电子排布数据格式",
                          font=('Unifont', 10),
                          fill='blue')

    def analyze_electron_config(self, config, parent):
        """解析电子排布"""
        analysis_frame = tk.LabelFrame(parent, text=" 电子排布解析", 
                                  font=('Unifont', 12),
                                  relief=tk.GROOVE, bd=2)
        analysis_frame.pack(fill=tk.X, pady=(0, 20))
        
        # 解析电子层分布
        try:
            import re
            
            # 处理稀有气体核心表示法 - 先提取核心部分
            core_configs = {
                '[He]': '1s²',
                '[Ne]': '1s² 2s² 2p⁶', 
                '[Ar]': '1s² 2s² 2p⁶ 3s² 3p⁶',
                '[Kr]': '1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d¹⁰ 4p⁶',
                '[Xe]': '1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d¹⁰ 4p⁶ 5s² 4d¹⁰ 5p⁶',
                '[Rn]': '1s² 2s² 2p⁶ 3s² 3p⁶ 4s² 3d¹⁰ 4p⁶ 5s² 4d¹⁰ 5p⁶ 6s² 4f¹⁴ 5d¹⁰ 6p⁶'
            }
            
            # 显示原始电子排布
            original_frame = tk.Frame(analysis_frame)
            original_frame.pack(fill=tk.X, pady=5, padx=10)
            
            original_label = tk.Label(original_frame, text=f"电子排布: {config}",
                                 font=('Unifont', 11),
                                 fg='darkblue')
            original_label.pack(anchor=tk.W)
            
            # 将上标数字转换为普通数字以便解析
            superscript_map = {
                '⁰': '0', '¹': '1', '²': '2', '³': '3', '⁴': '4',
                '⁵': '5', '⁶': '6', '⁷': '7', '⁸': '8', '⁹': '9'
            }
            
            config_normal = config
            for sup, normal in superscript_map.items():
                config_normal = config_normal.replace(sup, normal)
            
            # 处理核心表示法
            full_config = config_normal
            for core, replacement in core_configs.items():
                if core in full_config:
                    # 将核心的电子排布也转换为普通数字
                    replacement_normal = replacement
                    for sup, normal in superscript_map.items():
                        replacement_normal = replacement_normal.replace(sup, normal)
                    full_config = full_config.replace(core, replacement_normal)
            
            # 匹配电子排布模式 - 改进正则表达式
            pattern = r'(\d+)([spdf])(\d+)'
            matches = re.findall(pattern, full_config)
            
            if not matches:
                # 尝试其他可能的格式
                pattern2 = r'(\d)([spdf])(\d)'
                matches = re.findall(pattern2, full_config)
                if not matches:
                    raise ValueError(f"无法解析电子排布格式: {config}")
            
            total_electrons = 0
            orbital_info = []
            
            # 电子层统计
            shell_electrons = {}
            orbital_electrons = {}
            
            for n, orbital, electrons in matches:
                try:
                    n_int = int(n)
                    e_int = int(electrons)
                    total_electrons += e_int
                    
                    # 统计各层电子数
                    if n_int not in shell_electrons:
                        shell_electrons[n_int] = 0
                    shell_electrons[n_int] += e_int
                    
                    # 统计各轨道电子数
                    orbital_key = f"{n}{orbital}"
                    orbital_electrons[orbital_key] = e_int
                    orbital_info.append(f"{n}{orbital}⁽{e_int}⁾")
                    
                except ValueError as e:
                    print(f"解析电子数错误: {electrons}")
                    continue
            
            # 按能级顺序显示轨道
            energy_order = [
                '1s', '2s', '2p', '3s', '3p', '4s', '3d', '4p', '5s', '4d', '5p', 
                '6s', '4f', '5d', '6p', '7s', '5f', '6d', '7p'
            ]
            
            # 显示轨道电子分布
            orbitals_frame = tk.Frame(analysis_frame)
            orbitals_frame.pack(fill=tk.X, pady=10, padx=10)
            
            orbitals_label = tk.Label(orbitals_frame, text="轨道电子分布:",
                                 font=('Unifont', 11))
            orbitals_label.pack(anchor=tk.W)
            
            # 创建轨道显示框架
            orbitals_display_frame = tk.Frame(analysis_frame)
            orbitals_display_frame.pack(fill=tk.X, padx=10)
            
            current_row = 0
            current_col = 0
            max_cols = 4
            
            for orbital in energy_order:
                if orbital in orbital_electrons:
                    e_int = orbital_electrons[orbital]
                    max_e = self.get_max_electrons(orbital[-1])
                    
                    # 创建单个轨道框架
                    single_orbital_frame = tk.Frame(orbitals_display_frame, 
                                               relief=tk.RAISED, 
                                               bd=1,
                                               padx=5, 
                                               pady=5)
                    single_orbital_frame.grid(row=current_row, 
                                         column=current_col, 
                                         padx=5, 
                                         pady=5,
                                         sticky='w')
                    
                    # 轨道标签
                    orbital_label = tk.Label(single_orbital_frame, 
                                        text=f"{orbital}:",
                                        font=('Unifont', 9))
                    orbital_label.pack(anchor=tk.W)
                    
                    # 电子显示
                    electrons_text = ""
                    for i in range(max_e):
                        if i < e_int:
                            electrons_text += "●"  # 实心圆表示有电子
                        else:
                            electrons_text += "○"  # 空心圆表示空轨道
                        if (i + 1) % 5 == 0 and i < max_e - 1:
                            electrons_text += "\n"  # 每5个电子换行
                    
                    electrons_label = tk.Label(single_orbital_frame, 
                                          text=electrons_text,
                                          font=('Unifont', 10),
                                          fg='blue',
                                          justify=tk.LEFT)
                    electrons_label.pack(anchor=tk.W)
                    
                    # 电子数统计
                    count_label = tk.Label(single_orbital_frame, 
                                      text=f"{e_int}/{max_e}",
                                      font=('Unifont', 8),
                                      fg='darkgreen')
                    count_label.pack(anchor=tk.W)
                    
                    current_col += 1
                    if current_col >= max_cols:
                        current_col = 0
                        current_row += 1
            
            # 电子层统计
            if shell_electrons:
                shell_frame = tk.Frame(analysis_frame)
                shell_frame.pack(fill=tk.X, pady=10, padx=10)
                
                shell_text = "各电子层电子数: "
                shell_details = []
                for shell in sorted(shell_electrons.keys()):
                    # 将主量子数转换为K、L、M、N...表示法
                    shell_names = ['K', 'L', 'M', 'N', 'O', 'P', 'Q']
                    shell_name = shell_names[shell-1] if shell <= len(shell_names) else str(shell)
                    shell_details.append(f"{shell_name}层: {shell_electrons[shell]}e")
                shell_text += " | ".join(shell_details)
                
                shell_label = tk.Label(shell_frame, text=shell_text,
                                  font=('Unifont', 10),
                                  fg='purple')
                shell_label.pack()
            
            # 总电子数
            total_frame = tk.Frame(analysis_frame)
            total_frame.pack(fill=tk.X, pady=(10, 5), padx=10)
            
            total_label = tk.Label(total_frame, text=f"总电子数: {total_electrons}", 
                              font=('Unifont', 11),
                              fg='darkred')
            total_label.pack()
            
            # 显示解析后的完整电子排布
            if full_config != config_normal:
                full_config_frame = tk.Frame(analysis_frame)
                full_config_frame.pack(fill=tk.X, pady=5, padx=10)
                
                full_config_label = tk.Label(full_config_frame, 
                                        text=f"完整电子排布: {full_config}",
                                        font=('Unifont', 9),
                                        fg='gray')
                full_config_label.pack(anchor=tk.W)
            
        except Exception as e:
            import traceback
            error_details = traceback.format_exc()
            print(f"解析错误详情: {error_details}")
            
            error_label = tk.Label(analysis_frame, 
                              text=f"解析电子排布时出错: {str(e)}", 
                              font=('Unifont', 10), 
                              fg='red')
            error_label.pack()
            
            # 显示原始配置用于调试
            debug_label = tk.Label(analysis_frame,
                              text=f"原始配置: {config}",
                              font=('Unifont', 9),
                              fg='gray')
            debug_label.pack()

    def analyze_valence_electrons(self, config):
        """分析价电子"""
        try:
            # 简单的价电子分析
            if '[He]' in config or '[Ne]' in config or '[Ar]' in config or '[Kr]' in config or '[Xe]' in config or '[Rn]' in config:
                # 处理稀有气体核心表示法
                # 提取最外层的s和p轨道电子
                pattern = r'(\d+)([sp])(\d+)'
                matches = re.findall(pattern, config)
                
                if matches:
                    # 找到最大的主量子数
                    max_n = max(int(n) for n, _, _ in matches)
                    valence_electrons = 0
                    
                    for n, orbital, electrons in matches:
                        if int(n) == max_n and orbital in ['s', 'p']:
                            valence_electrons += int(electrons)
                    
                    return f"最外层 {valence_electrons} 个电子"
            
            return "请查看具体轨道分布"
            
        except:
            return "无法分析价电子"

    def show_chemical_properties(self, element_data, parent):
        """显示与电子排布相关的化学性质"""
        properties_frame = tk.LabelFrame(parent, text=" 化学性质关联 ", 
                                    font=('Unifont', 12),
                                    relief=tk.GROOVE, bd=2)
        properties_frame.pack(fill=tk.X, pady=(0, 20))
        
        properties_text = ""
        
        # 价电子分析
        valence_info = element_data.get('valence', ['未知'])
        if valence_info != ['未知']:
            properties_text += f"常见化合价: {', '.join(valence_info)}\n"
        
        # 电子构型与化学性质的关系
        config = element_data.get('electron_config', '')
        if config:
            if config.endswith('s¹'):
                properties_text += "• 具有一个价电子，易失去形成+1价阳离子\n"
            elif config.endswith('s²'):
                properties_text += "• 具有两个价电子，易失去形成+2价阳离子\n"
            elif 'd' in config and 'f' not in config:
                properties_text += "• 过渡金属，具有可变的化合价\n"
            elif config.endswith('p⁵'):
                properties_text += "• 卤素元素，易获得一个电子形成-1价阴离子\n"
            elif config.endswith('p⁶') or config.endswith('s² p⁶'):
                properties_text += "• 稀有气体，化学性质稳定\n"
        
        if properties_text:
            properties_label = tk.Label(properties_frame, text=properties_text,
                                  font=('Unifont', 10),
                                  justify=tk.LEFT)
            properties_label.pack(padx=10, pady=10)
        else:
            no_info_label = tk.Label(properties_frame, text="暂无相关化学性质信息",
                                font=('Unifont', 10),
                                fg='gray')
            no_info_label.pack(padx=10, pady=10)

