    def save_note_to_file(self, content):
        """保存笔记到文件"""
        try:
            # 确保目录存在
            notes_dir = "C:/pt/notes"
            if not os.path.exists(notes_dir):
                os.makedirs(notes_dir)
            
            note_file = os.path.join(notes_dir, "note.txt")
            
            with open(note_file, 'w', encoding='utf-8') as file:
                file.write(content)
            return True
        except Exception as e:
            messagebox.showerror("错误", f"保存笔记失败: {str(e)}")
            return False

    def load_note_from_file(self):
        """从文件加载笔记"""
        try:
            note_file = "./res/notes/note.txt"
            
            if os.path.exists(note_file):
                with open(note_file, 'r', encoding='utf-8') as file:
                    content = file.read()
                return content
            else:
                return ""
        except Exception as e:
            messagebox.showerror("错误", f"加载笔记失败: {str(e)}")
            return ""

