    def perform_element_search(self, search_term, search_window):
        """执行元素搜索并闪烁对应按钮"""
        if not search_term.strip():
            self.search_status_label.config(text="请输入搜索内容", fg='red')
            return
        
        search_term = search_term.strip()
        found_element = None
        
        # 在元素数据中搜索
        for symbol, data in self.elements.items():
            # 匹配元素符号（不区分大小写）
            if symbol.lower() == search_term.lower():
                found_element = symbol
                break
            # 匹配元素名称
            elif data['name'].lower() == search_term.lower():
                found_element = symbol
                break
            # 匹配原子序数
            elif str(data['number']) == search_term:
                found_element = symbol
                break
        
        if found_element:
            self.search_status_label.config(text=f"找到元素: {found_element} - {self.elements[found_element]['name']}", fg='green')
            # 闪烁对应的元素按钮
            self.flash_element_button(found_element)
            # 2秒后自动关闭搜索窗口
            search_window.after(2000, search_window.destroy)
        else:
            self.search_status_label.config(text=f"未找到元素: {search_term}", fg='red')

    def flash_element_button(self, symbol):
        """闪烁指定的元素按钮"""
        if symbol in self.element_buttons:
            button = self.element_buttons[symbol]
            
            # 在外部定义 category_colors，确保内部函数可以访问
            category_colors = {
                # 金属区域（红-橙-黄）
        "碱金属": "#FF8080",      # 浅红
        "碱土金属": "#FFA380",    # 浅橙红
        "过渡金属": "#FFC680",    # 浅橙色
        "后过渡金属": "#FFE680",  # 浅黄橙
        
        # 半金属/类金属区域（黄绿过渡）
        "类金属": "#CCD980",      # 橄榄绿
        
        # 非金属区域（绿-蓝）
        "非金属": "#80CC80",      # 草绿色
        "卤素": "#80B3CC",        # 青绿色
        
        # 惰性气体区域（蓝-紫）
        "稀有气体": "#8099CC",    # 浅蓝色
        
        # 内过渡金属（紫-红紫）
        "镧系": "#B380CC",        # 浅紫色
        "锕系": "#CC80B3",        # 浅紫红色
        
        "未知": "#D9D9D9" 
            }
            
            original_bg = category_colors.get(self.elements[symbol]["category"], "#E0E0E0")
            
            def flash(count=0):
                if count < 6:  # 闪烁3次（6次颜色变化）
                    if count % 2 == 0:
                        # 闪烁颜色 - 使用醒目的黄色
                        button.config(bg='#FFFF00')  # 亮黄色
                    else:
                        # 恢复原始颜色
                        button.config(bg=original_bg)
                    
                    # 安排下一次闪烁
                    button.after(200, lambda: flash(count + 1))
                else:
                    # 闪烁结束后确保恢复原始颜色
                    button.config(bg=original_bg)
            
            # 开始闪烁
            flash()
            
            # 确保元素在显示状态（如果被筛选隐藏了）
            if hasattr(self, 'current_filter') and self.current_filter != "全部":
                # 临时显示所有元素以便看到闪烁效果
                self.filter_elements_by_category("全部")
                # 闪烁结束后恢复原来的筛选状态
                button.after(1500, lambda: self.filter_elements_by_category(self.current_filter))
        else:
            # 如果搜索窗口还存在，更新状态标签
            if hasattr(self, 'search_status_label'):
                self.search_status_label.config(text=f"错误: 找不到元素按钮 {symbol}", fg='red')
        
