        list_title.pack(pady=10)

        # 创建文章列表和滚动条
        list_frame = tk.Frame(left_frame)
        list_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)

        # 文章列表（Listbox）
        article_listbox = tk.Listbox(list_frame, font=('Unifont', 10),
                                    selectmode=tk.SINGLE, height=15)
        article_listbox_scrollbar = tk.Scrollbar(list_frame, orient=tk.VERTICAL, 
                                               command=article_listbox.yview)
        article_listbox.configure(yscrollcommand=article_listbox_scrollbar.set)

        article_listbox.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
