    def create_custom_element(self, proton_var, neutron_var, electron_layers, 
                         category_var, state_var, preview_frame):
        """创建自定义元素"""
        try:
            protons = int(proton_var.get())
            neutrons = int(neutron_var.get())
            category = category_var.get()
            state = state_var.get()
        
            # 计算电子总数
            total_electrons = sum(int(layer.get()) for layer in electron_layers)
        
            # 显示创建结果
            result_text = f"🎉 元素创建成功！\n\n"
            result_text += f"原子序数: {protons}\n"
            result_text += f"中子数: {neutrons}\n"
            result_text += f"电子总数: {total_electrons}\n"
            result_text += f"质量数: {protons + neutrons}\n"
            result_text += f"类别: {category}\n"
            result_text += f"状态: {state}\n\n"
            result_text += "这是一个自定义元素！"
        
            # 在预览区域显示成功信息
            for widget in preview_frame.winfo_children():
                widget.destroy()
            
            success_label = tk.Label(preview_frame, text=result_text,
                               font=('Unifont', 11),
                               justify=tk.CENTER)
            success_label.place(relx=0.5, rely=0.5, anchor=tk.CENTER)
        
        except ValueError:
            tk.messagebox.showerror("错误", "请输入有效的数值！")

