    def perform_molar_mass_calculation(self, formula):
        """执行摩尔质量计算"""
        try:
            # 元素原子量数据（从元素数据中获取）
            element_masses = {}
            for symbol, data in self.elements.items():
                try:
                    # 尝试转换原子质量为浮点数
                    mass_str = data['mass'].strip('[]')  # 移除可能的中括号
                    mass = float(mass_str)
                    element_masses[symbol] = mass
                except (ValueError, KeyError):
                    # 如果无法转换，使用默认值或跳过
                    continue
        
            # 补充一些常见元素的默认值（以防元素数据不完整）
            default_masses = {
            'H': 1.008, 'He': 4.0026, 'Li': 6.94, 'Be': 9.0122, 'B': 10.81,
            'C': 12.011, 'N': 14.007, 'O': 15.999, 'F': 18.998, 'Ne': 20.180,
            'Na': 22.990, 'Mg': 24.305, 'Al': 26.982, 'Si': 28.085, 'P': 30.974,
            'S': 32.06, 'Cl': 35.45, 'Ar': 39.95, 'K': 39.098, 'Ca': 40.078,
            'Fe': 55.845, 'Cu': 63.546, 'Zn': 65.38, 'Ag': 107.87, 'I': 126.90,
            'Ba': 137.33, 'Pb': 207.2, 'U': 238.03
        }
        
            # 更新元素质量数据
            for elem, mass in default_masses.items():
                if elem not in element_masses:
                    element_masses[elem] = mass
        
            # 解析化学式并计算摩尔质量
            molar_mass, calculation_details = self.parse_chemical_formula(formula, element_masses)
        
            if molar_mass is not None:
                result = f"化学式: {formula}\n"
                result += f"摩尔质量: {molar_mass:.3f} g/mol\n\n"
                result += "计算过程:\n"
                result += calculation_details
                result += f"\n总计: {molar_mass:.3f} g/mol"
            else:
                result = f"无法计算化学式 '{formula}' 的摩尔质量\n"
                result += "请检查化学式格式是否正确"
            
        except Exception as e:
            result = f"计算错误: {str(e)}\n"
            result += "请检查化学式格式"
    
        return result

    def parse_chemical_formula(self, formula, element_masses):
        """解析化学式并计算摩尔质量"""
    
    
        # 处理水合物（如CuSO4·5H2O）
        if '·' in formula:
            parts = formula.split('·')
            main_formula = parts[0]
            hydrate_part = parts[1]
        
            # 解析水合物部分（如5H2O）
            hydrate_match = re.match(r'(\d*)([A-Z][a-z]*)(\d*)', hydrate_part)
            if hydrate_match:
                hydrate_count = int(hydrate_match.group(1)) if hydrate_match.group(1) else 1
                hydrate_element = hydrate_match.group(2)
                hydrate_subscript = int(hydrate_match.group(3)) if hydrate_match.group(3) else 1
            
                # 计算水合物的质量
                if hydrate_element in element_masses:
                    hydrate_mass = hydrate_count * hydrate_subscript * element_masses[hydrate_element]
                    # 这里简化处理，实际水合物计算更复杂
                    # 需要完整实现水合物的解析
            # 简化处理：暂时只计算主化学式
            formula = main_formula
    
        total_mass = 0.0
        calculation_details = ""
    
        # 使用正则表达式匹配元素和下标
        # 匹配模式：大写字母开头，可能跟小写字母，然后可能跟数字
        pattern = r'([A-Z][a-z]*)(\d*)'
        matches = re.findall(pattern, formula)
    
        if not matches:
            return None, "无法解析化学式"
    
        for element, subscript_str in matches:
            if element not in element_masses:
                return None, f"未知元素: {element}"
        
            subscript = int(subscript_str) if subscript_str else 1
            element_mass = element_masses[element]
            component_mass = element_mass * subscript
            total_mass += component_mass
        
            calculation_details += f"{element}"
            if subscript > 1:
                calculation_details += f"₍{subscript}₎"
            calculation_details += f": {element_mass:.3f} × {subscript} = {component_mass:.3f} g/mol\n"
    
        return total_mass, calculation_details

