    def search_and_display(self, term, content_widget, status_label):
        """执行搜索并显示结果"""
        status_label.config(text=f"正在搜索: {term}...", fg='orange')
        content_widget.delete(1.0, tk.END)
        content_widget.insert(tk.END, "正在搜索，请稍候...")
    
        # 在后台执行搜索（避免界面卡顿）
        def do_search():
            result = self.dictionary.search_chemical_term(term)
            # 回到主线程更新界面
            content_widget.after(0, lambda: self.update_search_result(term, result, content_widget, status_label))
    
        threading.Thread(target=do_search, daemon=True).start()

    def update_search_result(self, term, result, content_widget, status_label):
        """更新搜索结果到界面"""
        content_widget.delete(1.0, tk.END)
    
        # 添加标题
        content_widget.insert(tk.END, f"【{term}】\n\n", 'title')
        content_widget.tag_configure('title', font=('Unifont', 12), 
                                foreground='darkblue')
    
        # 添加内容
        content_widget.insert(tk.END, result)
    
        status_label.config(text=f"搜索完成: {term}", fg='green')

