class ElementButton(tk.Button):
    """自定义元素按钮类"""
    def __init__(self, master, symbol, **kwargs):
        super().__init__(master, **kwargs)
        self.symbol = symbol
        self.element_data = elements[symbol]
        
        # 根据元素类别设置背景颜色
        category_colors = {
            "非金属": "yellow",
            "稀有气体": "purple",
            "碱金属": "red",
            "碱土金属": "cyan",
            "类金属": "magenta",
            "卤素": "green",
            "过渡金属": "orange",
            "其他金属": "pink",
            "镧系": "blue",
            "锕系": "lime",
            "未知": "#CCCCCC"
        }
        
        color = category_colors.get(self.element_data["category"], "#CCCCCC")
        self.config(
            text=f"{self.element_data['number']}. {symbol}\n{self.element_data['name']}",
            bg=color,
            font=('Arial', 8),
            width=5,
            height=2,
            command=self.show_info
        )
    
    def show_info(self):
        """显示元素信息（包含图片）"""
        info_window = tk.Toplevel(self.master)
        info_window.title(f"元素信息 - {self.symbol}")
        info_window.geometry("600x400")  # 增大窗口以容纳图片
        info_window.resizable(False, False)
    
        # 居中显示信息窗口
        info_window.transient(self.master)
        info_window.grab_set()
    
        x = self.master.winfo_x() + (self.master.winfo_width() // 2) - 300
        y = self.master.winfo_y() + (self.master.winfo_height() // 2) - 200
        info_window.geometry(f"+{x}+{y}")
    
        # 创建主框架
        main_frame = tk.Frame(info_window)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=15, pady=15)
    
        # 创建顶部框架（用于图片和基本信息）
        top_frame = tk.Frame(main_frame)
        top_frame.pack(fill=tk.X, pady=(0, 15))
    
        # 左侧图片区域
        image_frame = tk.Frame(top_frame, width=300, height=150, relief=tk.SUNKEN, bd=1)
        image_frame.pack(side=tk.LEFT, padx=(0, 15))
        image_frame.pack_propagate(False)  # 防止框架自动调整大小
    
        # 显示元素图片
        self.show_element_image(image_frame)
    
        # 右侧基本信息区域
        info_frame = tk.Frame(top_frame)
        info_frame.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
    
        # 基本信息
        basic_info = (
            f"元素符号: {self.symbol}\n"
            f"元素名称: {self.element_data['name']}\n"
            f"原子序数: {self.element_data['number']}\n"
            f"原子质量: {self.element_data['mass']}\n"
            f"元素类别: {self.element_data['category']}"
        )
    
        basic_label = tk.Label(info_frame, text=basic_info, justify=tk.LEFT, 
                          font=('Arial', 11))
        basic_label.pack(anchor=tk.W)
    
        # 创建底部框架（用于详细信息）
        bottom_frame = tk.Frame(main_frame)
        bottom_frame.pack(fill=tk.BOTH, expand=True)
    
        # 详细信息
        detail_info = (
            f"电子构型: {self.element_data['electron_config']}\n"
            f"发现年份: {self.element_data['discovery']}\n"
            f"发现者: {self.element_data['discoverer']}"
        )
    
        detail_label = tk.Label(bottom_frame, text=detail_info, justify=tk.LEFT,
                           font=('Arial', 10))
        detail_label.pack(anchor=tk.W)
    
        # 关闭按钮
        close_button = tk.Button(info_window, text="关闭", command=info_window.destroy,
                            font=('Arial', 10), width=10)
        close_button.pack(pady=10)
    def show_element_image(self, parent):
        """显示元素图片"""
        try:
            # 图片文件路径（假设图片存放在images/elements/目录下）
            image_dir = "images/"
            image_path = os.path.join(image_dir, f"tt_{self.symbol}.gif")
        
            # 检查图片文件是否存在
            if os.path.exists(image_path):
                # 使用tkinter的PhotoImage加载GIF图片
                photo = tk.PhotoImage(file=image_path)
            
                # 创建图片标签
                image_label = tk.Label(parent, image=photo, bg='white')
                image_label.image = photo  # 保持引用防止垃圾回收
                image_label.pack(expand=True)
            
            else:
                # 如果图片不存在，显示占位符
                placeholder_text = f"{self.symbol}\n暂无图片"
                placeholder = tk.Label(parent, text=placeholder_text, 
                                  font=('Arial', 16),
                                  bg='lightgray', 
                                  relief=tk.RAISED, 
                                  bd=2,
                                  width=8,
                                  height=4)
            placeholder.pack(expand=True)
            
        except Exception as e:
            # 图片加载失败时的处理
            error_text = f"图片加载失败\n{str(e)}"
            error_label = tk.Label(parent, text=error_text, 
                              font=('Arial', 9), 
                              fg='red', 
                              bg='white',
                              justify=tk.CENTER)
            error_label.pack(expand=True)

class PeriodicTableApp:
    """元素周期表应用"""
    
    def __init__(self, root):
        self.root = root
        self.root.title("元素周期表")
        self.root.geometry("900x600")
        self.root.resizable(False, False)
        try:
            self.root.iconbitmap("./data/icon.ico")
        except:
            pass
        
        # 创建顶部菜单栏
        self.create_menu_bar()
        
        # 创建主框架
        main_frame = tk.Frame(root)
        main_frame.pack(expand=True, fill=tk.BOTH, padx=10, pady=10)
        
        # 标题
        title_label = tk.Label(main_frame, text="元素周期表", font=('Arial', 16, 'bold'))
        title_label.pack(pady=(0, 10))
        
        # 创建周期表框架
        table_frame = tk.Frame(main_frame)
        table_frame.pack(expand=True)
        
        # 布局元素按钮
        self.create_periodic_table(table_frame)
        
        # 状态栏
        status_bar = tk.Label(root, text="点击元素查看详细信息", relief=tk.SUNKEN, anchor=tk.W)
        status_bar.pack(side=tk.BOTTOM, fill=tk.X)

    def create_menu_bar(self):
        """创建顶部菜单栏"""
        menubar = tk.Menu(self.root)
        self.root.config(menu=menubar)
        
        # 实用图表菜单
        charts_menu = tk.Menu(menubar, tearoff=0)
        menubar.add_cascade(label="实用图表", menu=charts_menu)
        
        # 图表选项
        chart_options = [
            "溶解性表",
            "酸碱指示剂变色范围",
            "常见离子颜色",
            "金属活动性顺序",
            "元素电负性表",
            "标准电极电势表",
            "常见化合物颜色",
            "热力学数据表"
        ]
        
        for option in chart_options:
            charts_menu.add_command(
                label=option,
                command=lambda opt=option: self.show_chart(opt)
            )

        reference_menu = tk.Menu(menubar, tearoff=0)
        menubar.add_cascade(label="参考资料", menu=reference_menu)
    
        # 参考资料选项
        reference_options = [
        "化学方程式书写规则",
        "实验操作注意事项",
        "常见化学常数",
        "单位换算表",
        "安全警示",
        "元素周期表历史"
        ]
    
        for option in reference_options:
            reference_menu.add_command(
                label=option,
                command=lambda opt=option: self.show_reference(opt)
            )

        other_menu = tk.Menu(menubar, tearoff=0)
        menubar.add_cascade(label="其他", menu=other_menu)
    
        # 其他菜单选项
        other_menu.add_command(label="化学文章", command=self.show_chemistry_article)
        other_menu.add_separator()  # 添加分隔线
        other_menu.add_command(label="关于", command=self.show_about)
        other_menu.add_command(label="检查更新", command=self.update)
        
    def show_reference(self, reference_name):
        """显示选定的参考资料"""
        # 创建参考资料窗口
        ref_window = tk.Toplevel(self.root)
        ref_window.title(f"参考资料 - {reference_name}")
        ref_window.geometry("700x500")
        ref_window.resizable(True, True)
    
        # 居中显示
        ref_window.transient(self.root)
        ref_window.grab_set()
    
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 350
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 250
        ref_window.geometry(f"+{x}+{y}")
    
        # 创建主框架
        main_frame = tk.Frame(ref_window)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
    
        # 添加标题
        title_label = tk.Label(main_frame, text=reference_name, 
                          font=('Arial', 14))
        title_label.pack(pady=(0, 10))
    
        # 创建文本框和滚动条
        text_frame = tk.Frame(main_frame)
        text_frame.pack(fill=tk.BOTH, expand=True)
    
        text_widget = tk.Text(text_frame, wrap=tk.WORD, font=('Arial', 10))
        scrollbar = tk.Scrollbar(text_frame, orient=tk.VERTICAL, command=text_widget.yview)
        text_widget.configure(yscrollcommand=scrollbar.set)
    
        text_widget.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
    
        # 根据选项显示相应内容
        content = self.get_reference_content(reference_name)
        text_widget.insert(tk.END, content)
        text_widget.config(state=tk.DISABLED)  # 设置为只读
    
        # 关闭按钮
        close_button = tk.Button(main_frame, text="关闭", command=ref_window.destroy,
                            font=('Arial', 10), width=10)
        close_button.pack(pady=10)

    def show_chemistry_article(self):
        """从txt文件读取并显示化学文章"""
        # 创建文章窗口
        article_window = tk.Toplevel(self.root)
        article_window.title("化学文章")
        article_window.geometry("800x600")
        article_window.resizable(True, True)
    
        # 居中显示
        article_window.transient(self.root)
        article_window.grab_set()
    
        x = self.root.winfo_x() + (self.root.winfo_width() // 2) - 400
        y = self.root.winfo_y() + (self.root.winfo_height() // 2) - 300
        article_window.geometry(f"+{x}+{y}")
    
        # 创建主框架
        main_frame = tk.Frame(article_window)
        main_frame.pack(fill=tk.BOTH, expand=True, padx=15, pady=15)
    
        # 标题（从文件名获取或使用固定标题）
        article_title = "化学文章(小说）"
        title_label = tk.Label(main_frame, text=article_title, 
                          font=('Arial', 16, 'bold'))
        title_label.pack(pady=(0, 15))
    
        # 创建文本框和滚动条
        text_frame = tk.Frame(main_frame)
        text_frame.pack(fill=tk.BOTH, expand=True)
    
        text_widget = tk.Text(text_frame, wrap=tk.WORD, font=('Arial', 11))
        scrollbar = tk.Scrollbar(text_frame, orient=tk.VERTICAL, command=text_widget.yview)
        text_widget.configure(yscrollcommand=scrollbar.set)
    
        text_widget.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
    
        # 从txt文件读取文章内容
        try:
            # 假设文章文件名为 chemistry_article.txt
            article_file = "./texts/novel.txt"
        
            if os.path.exists(article_file):
                with open(article_file, 'r', encoding='utf-8') as file:
                    article_content = file.read()
            
                # 插入文章内容
                text_widget.insert(tk.END, article_content)
            
                # 尝试从文件内容中提取标题（第一行）
                first_line = article_content.split('\n')[0].strip()
                if first_line and len(first_line) < 50:  # 避免过长的第一行
                    title_label.config(text=first_line)
                    article_window.title(f"化学文章 - {first_line}")
                
            else:
                # 如果文件不存在，显示错误信息
                error_msg = f"文章文件未找到: {article_file}\n\n请确保文件存在于程序目录中。"
                text_widget.insert(tk.END, error_msg)
            
        except Exception as e:
            # 文件读取错误处理
            error_msg = f"读取文章时发生错误:\n{str(e)}\n\n请检查文件格式和编码。"
            text_widget.insert(tk.END, error_msg)
        
        text_widget.config(state=tk.DISABLED)  # 设置为只读
    
        # 关闭按钮
        close_button = tk.Button(main_frame, text="关闭", command=article_window.destroy,
                            font=('Arial', 10), width=10)
        close_button.pack(pady=10)

