        text_widget.pack(fill=tk.BOTH, expand=True, padx=5, pady=5)
        
        solubility_data = """
        常见物质溶解性表：
        
        ✓ = 可溶    ✗ = 不溶    △ = 微溶
        
        阴离子/阳离子  OH⁻  Cl⁻  SO₄²⁻  CO₃²⁻  NO₃⁻  PO₄³⁻
        Na⁺         ✓    ✓    ✓      ✓      ✓     ✓
        K⁺          ✓    ✓    ✓      ✓      ✓     ✓
        NH₄⁺        ✓    ✓    ✓      ✓      ✓     ✓
        Mg²⁺        ✗    ✓    ✓      ✗      ✓     ✗
        Ca²⁺        △    ✓    △      ✗      ✓     ✗
        Ba²⁺        ✓    ✓    ✗      ✗      ✓     ✗
        Al³⁺        ✗    ✓    ✓      ✗      ✓     ✗
        Fe²⁺        ✗    ✓    ✓      ✗      ✓     ✗
        Fe³⁺        ✗    ✓    ✓      ✗      ✓     ✗
        Cu²⁺        ✗    ✓    ✓      ✗      ✓     ✗
        Ag⁺         △    ✗    △      ✗      ✓     ✗
        Zn²⁺        ✗    ✓    ✓      ✗      ✓     ✗
        Pb²⁺        ✗    △    ✗      ✗      ✓     ✗
        """
        
        text_widget.insert(tk.END, solubility_data)
        text_widget.config(state=tk.DISABLED)

