        file_menu.add_command(label="打开音频文件", command=self.open_audio_file, accelerator="Ctrl+O")
        file_menu.add_command(label="打开SYY文件", command=self.open_syn_file, accelerator="Ctrl+Shift+O")
        file_menu.add_command(label="保存音调序列", command=self.save_tone_sequence, accelerator="Ctrl+S")
        file_menu.add_command(label="另存音调序列", command=self.save_as_tone_sequence, accelerator="Ctrl+Shift+S")
