        play_menu.add_command(label="播放音调序列", command=self.play_tone_sequence, accelerator="Ctrl+Shift+P")
        play_menu.add_command(label="停止播放", command=self.stop_playback, accelerator="Ctrl+Shift+X")
        play_menu.add_separator()
        play_menu.add_command(label="测试当前音调", command=self.test_current_tone)
        
        # 编辑菜单
        edit_menu = tk.Menu(menubar, tearoff=0)
        menubar.add_cascade(label="编辑", menu=edit_menu)
