    def create_toolbar(self):
        """创建工具栏"""
        toolbar = tk.Frame(self.root, bd=1, relief=tk.RAISED)
        toolbar.pack(side=tk.TOP, fill=tk.X)
        
        # 播放控制按钮
        play_btn = tk.Button(toolbar, text="▶ 播放音频", command=self.play_audio_file)
        play_btn.pack(side=tk.LEFT, padx=2, pady=2)
        
        tone_btn = tk.Button(toolbar, text="♪ 播放音调", command=self.play_tone_sequence)
        tone_btn.pack(side=tk.LEFT, padx=2, pady=2)
        
        stop_btn = tk.Button(toolbar, text="■ 停止", command=self.stop_playback)
        stop_btn.pack(side=tk.LEFT, padx=2, pady=2)
        
        # 分隔符
        tk.Label(toolbar, text=" | ").pack(side=tk.LEFT, padx=5)
        
        # 添加音调按钮
