    def broadcast_message(self):
        """广播消息"""
        if not self.is_server_running:
            messagebox.showwarning("提示", "只有服务器可以广播消息")
            return
        
        broadcast_window = tk.Toplevel(self.root)
        broadcast_window.title("广播消息")
        broadcast_window.geometry("400x200")
        
        tk.Label(broadcast_window, text="广播消息:", font=("Unifont", 10)).pack(pady=10)
        
        broadcast_text = tk.Text(broadcast_window, height=5, font=self.current_font)
        broadcast_text.pack(fill=tk.BOTH, expand=True, padx=10, pady=5)
        
        def send_broadcast():
            content = broadcast_text.get("1.0", tk.END).strip()
            if content:
                self.broadcast_to_clients({
                    'type': MessageType.SYSTEM.value,
                    'content': f"[广播] {content}",
                    'timestamp': datetime.datetime.now().strftime("%H:%M:%S")
                })
                self.add_system_message(f"[广播] {content}")
