    def server_settings(self):
        """服务器设置"""
        settings_window = tk.Toplevel(self.root)
        settings_window.title("服务器设置")
        settings_window.geometry("400x250")
        
        tk.Label(settings_window, text="服务器设置", font=("Unifont", 12, "bold")).pack(pady=10)
        
        # 服务器地址
        addr_frame = tk.Frame(settings_window)
        addr_frame.pack(fill=tk.X, padx=20, pady=5)
        tk.Label(addr_frame, text="服务器地址:", width=12).pack(side=tk.LEFT)
        self.server_host_var = tk.StringVar(value=self.server_host)
        addr_entry = tk.Entry(addr_frame, textvariable=self.server_host_var)
        addr_entry.pack(side=tk.LEFT, fill=tk.X, expand=True)
        
        # 服务器端口
        port_frame = tk.Frame(settings_window)
        port_frame.pack(fill=tk.X, padx=20, pady=5)
        tk.Label(port_frame, text="服务器端口:", width=12).pack(side=tk.LEFT)
        self.server_port_var = tk.StringVar(value=str(self.server_port))
        port_entry = tk.Entry(port_frame, textvariable=self.server_port_var)
        port_entry.pack(side=tk.LEFT, fill=tk.X, expand=True)
        
        # 最大连接数
        max_frame = tk.Frame(settings_window)
        max_frame.pack(fill=tk.X, padx=20, pady=5)
        tk.Label(max_frame, text="最大连接数:", width=12).pack(side=tk.LEFT)
        self.max_clients_var = tk.StringVar(value="10")
        max_spin = tk.Spinbox(max_frame, from_=1, to=100, textvariable=self.max_clients_var, width=10)
        max_spin.pack(side=tk.LEFT)
        
        def apply_settings():
            try:
                if self.is_server_running:
                    messagebox.showwarning("提示", "请先停止服务器再修改设置")
                    return
                
                self.server_host = self.server_host_var.get()
                self.server_port = int(self.server_port_var.get())
                
                self.update_server_info()
                settings_window.destroy()
                messagebox.showinfo("成功", "服务器设置已更新")
                
            except ValueError:
                messagebox.showerror("错误", "端口必须是数字")
        
        tk.Button(settings_window, text="应用设置", command=apply_settings,
                 bg="#4CAF50", fg="white", width=15).pack(pady=20)
    
    def change_username(self):
        """更改用户名"""
        username_window = tk.Toplevel(self.root)
        username_window.title("更改用户名")
        username_window.geometry("300x150")
        
        tk.Label(username_window, text="新用户名:", font=("Unifont", 10)).pack(pady=20)
        
        username_var = tk.StringVar(value=self.username)
        username_entry = tk.Entry(username_window, textvariable=username_var, font=("Unifont", 10))
        username_entry.pack(pady=5, padx=20, fill=tk.X)
        username_entry.select_range(0, tk.END)
        username_entry.focus()
        
        def apply_username():
            new_username = username_var.get().strip()
            if new_username and new_username != self.username:
                old_username = self.username
                self.username = new_username
                self.username_label.config(text=f"用户: {self.username}")
                
                # 如果是服务器，更新所有客户端
                if self.is_server_running:
                    # 在实际应用中更新服务器上的用户名
                    pass
                
                self.add_system_message(f"用户名已从 '{old_username}' 更改为 '{self.username}'")
                
            username_window.destroy()
        
        btn_frame = tk.Frame(username_window)
        btn_frame.pack(pady=10)
        
        tk.Button(btn_frame, text="确定", command=apply_username, width=10).pack(side=tk.LEFT, padx=5)
        tk.Button(btn_frame, text="取消", command=username_window.destroy, width=10).pack(side=tk.LEFT, padx=5)
    
