        font_window.geometry("300x200")
        
        tk.Label(font_window, text="字体大小:", font=("Unifont", 10)).pack(pady=10)
        
        sizes = ["8", "9", "10", "11", "12", "14", "16", "18", "20", "22", "24"]
        size_var = tk.StringVar(value=str(self.message_font.actual()['size']))
        
        size_listbox = tk.Listbox(font_window, font=("Unifont", 10), height=8)
        size_listbox.pack(fill=tk.BOTH, expand=True, padx=20, pady=5)
        
        for size in sizes:
            size_listbox.insert(tk.END, size)
        
        # 滚动到当前大小
        current_index = sizes.index(str(self.message_font.actual()['size'])) if str(self.message_font.actual()['size']) in sizes else 0
        size_listbox.selection_set(current_index)
