        self.connections = []
        
        # 默认颜色
        self.node_bg_color = "#E3F2FD"
        self.node_fg_color = "#1565C0"
        self.line_color = "#424242"
        
        # 当前绘制状态
        self.drawing_line = False
        self.line_start = None
        self.current_shape = "rectangle"  # rectangle, circle, diamond
        
        # 默认路径
        self.default_dir = "C:/SNO"
        
