class SNOGridEditor:
    def __init__(self, master=None):
        if master is None:
            self.root = tk.Tk()               # 独立运行时创建 Tk
        else:
            self.root = tk.Toplevel(master)
        self.root.title("SNO 表格")
        self.root.geometry("1200x800")
        
        # 当前文件路径
        self.current_file = None
        # 默认路径
        self.default_dir = "C:/SNO/"
        
        # 表格数据
        self.table_data = []
        # 公式数据
        self.formula_data = {}
        # 公式缓存结果
        self.formula_cache = {}
        
        # 当前列数
        self.columns = 5
        # 当前行数
        self.rows = 10
        
        # 支持的公式函数
        self.supported_functions = {
            'SUM': self.calculate_sum,
            'AVG': self.calculate_average,
            'MAX': self.calculate_max,
            'MIN': self.calculate_min,
            'COUNT': self.calculate_count,
            'PRODUCT': self.calculate_product,
            'SQRT': math.sqrt,
            'ABS': abs,
            'POWER': math.pow,
            'ROUND': round,
            'CEIL': math.ceil,
            'FLOOR': math.floor
        }
        
        # 单元格默认配置
        self.default_font = ("Unifont", 10)
        self.cell_bg_color = "#FFFFFF"
        self.cell_text_color = "#000000"
        
        # 确保默认目录存在
        self.ensure_default_directory()
        
        # 创建菜单栏
        self.create_menu()
        
        # 创建工具栏
        self.create_toolbar()
        
        # 创建公式工具栏
        self.create_formula_toolbar()
        
        # 创建状态栏
        self.create_statusbar()
        
        # 创建主表格区域
        self.create_table_widget()
        
        # 绑定快捷键
        self.bind_shortcuts()
        
        # 更新状态栏
        self.update_statusbar()
        
        # 初始化表格
        self.initialize_table()
        
        root.mainloop()
    
    def create_menu(self):
        """创建菜单栏"""
        menubar = tk.Menu(self.root)
        self.root.config(menu=menubar)
        
        # 文件菜单
        file_menu = tk.Menu(menubar, tearoff=0)
        menubar.add_cascade(label="文件", menu=file_menu)
        file_menu.add_command(label="新建", command=self.new_file, accelerator="Ctrl+N")
        file_menu.add_command(label="打开", command=self.open_file, accelerator="Ctrl+O")
        file_menu.add_command(label="保存", command=self.save_file, accelerator="Ctrl+S")
        file_menu.add_command(label="另存为", command=self.save_as_file, accelerator="Ctrl+Shift+S")
        file_menu.add_separator()
        file_menu.add_command(label="导入CSV", command=self.import_csv)
        file_menu.add_command(label="导出CSV", command=self.export_csv)
        file_menu.add_separator()
        file_menu.add_command(label="退出", command=self.root.quit)
        
        # 编辑菜单
        edit_menu = tk.Menu(menubar, tearoff=0)
        menubar.add_cascade(label="编辑", menu=edit_menu)
        edit_menu.add_command(label="插入行", command=self.insert_row, accelerator="Ctrl+I")
        edit_menu.add_command(label="删除行", command=self.delete_row, accelerator="Ctrl+D")
        edit_menu.add_command(label="插入列", command=self.insert_column, accelerator="Ctrl+Shift+I")
        edit_menu.add_command(label="删除列", command=self.delete_column, accelerator="Ctrl+Shift+D")
        edit_menu.add_separator()
        edit_menu.add_command(label="清空表格", command=self.clear_table)
        
        # 公式菜单
        formula_menu = tk.Menu(menubar, tearoff=0)
        menubar.add_cascade(label="公式", menu=formula_menu)
        formula_menu.add_command(label="插入公式", command=self.insert_formula, accelerator="Ctrl+F")
        formula_menu.add_command(label="重新计算所有公式", command=self.recalculate_all_formulas, accelerator="F9")
        formula_menu.add_separator()
        formula_menu.add_command(label="函数列表", command=self.show_function_list)
        
        # 格式菜单
        format_menu = tk.Menu(menubar, tearoff=0)
        menubar.add_cascade(label="格式", menu=format_menu)
        format_menu.add_command(label="设置字体", command=self.set_font)
        format_menu.add_command(label="单元格背景", command=self.set_cell_bg_color)
        format_menu.add_command(label="文本颜色", command=self.set_text_color)
        format_menu.add_command(label="对齐方式", command=self.set_alignment)
        
        # 帮助菜单
        help_menu = tk.Menu(menubar, tearoff=0)
        menubar.add_cascade(label="帮助", menu=help_menu)
        help_menu.add_command(label="公式帮助", command=self.show_formula_help)
        help_menu.add_command(label="关于", command=self.show_about)
    
    def create_toolbar(self):
        """创建工具栏"""
        toolbar = tk.Frame(self.root, bd=1, relief=tk.RAISED)
        toolbar.pack(side=tk.TOP, fill=tk.X)
        
        # 新建按钮
        new_btn = tk.Button(toolbar, text="新建", command=self.new_file)
        new_btn.pack(side=tk.LEFT, padx=2, pady=2)
        
        # 打开按钮
        open_btn = tk.Button(toolbar, text="打开", command=self.open_file)
        open_btn.pack(side=tk.LEFT, padx=2, pady=2)
        
        # 保存按钮
        save_btn = tk.Button(toolbar, text="保存", command=self.save_file)
        save_btn.pack(side=tk.LEFT, padx=2, pady=2)
        
        # 分隔符
        tk.Label(toolbar, text=" | ").pack(side=tk.LEFT, padx=5)
        
